fn main() {
    let runtime = tokio::runtime::Builder::new_multi_thread()
        .enable_all()
        // The compatibility dispatcher contains a large, intentionally
        // explicit match for the frozen controller surface.  Keep live HTTP
        // requests from overflowing Tokio's default worker stack before an
        // early branch (including a real 404) can return.
        .thread_stack_size(8 * 1024 * 1024)
        .build()
        .expect("build slskr runtime");
    if let Err(error) = runtime.block_on(run()) {
        eprintln!("{error}");
        std::process::exit(1);
    }
}

async fn run() -> Result<(), String> {
    let args = env::args_os().skip(1).collect::<Vec<_>>();
    if let Some(invocation) = parse_serve_args(&args)? {
        return serve(invocation).await;
    }

    cli::run_from_args(args).await
}

fn frozen_obfuscation_startup_error(config: &AppConfig) -> Option<&'static str> {
    (!config.current_upstream_behavior
        && config.controller_compatibility_target == ControllerCompatibilityTarget::Slskdn
        && config.obfuscation_enabled
        && !config.obfuscation_advertise_regular_port)
        .then_some(
            "Application terminated unexpectedly\nSystem.ArgumentException: The regular peer port must be advertised when peer obfuscation is enabled (Parameter 'advertiseRegularPort')",
        )
}

#[derive(Clone, Debug, Default, Eq, PartialEq)]
struct ServeInvocation {
    once: bool,
    config_environment: BTreeMap<String, String>,
}

struct ControllerCliEnv<'a> {
    values: &'a BTreeMap<String, String>,
}

impl ConfigEnv for ControllerCliEnv<'_> {
    fn var(&self, name: &str) -> Option<String> {
        self.values
            .get(name)
            .cloned()
            .or_else(|| ProcessEnv.var(name))
    }

    fn command_line_var(&self, name: &str) -> Option<String> {
        self.values.get(name).cloned()
    }
}

