#[derive(Clone, Debug, PartialEq, Eq)]
struct UserRecord {
    username: String,
    watched: bool,
    status: Option<String>,
    privileged: bool,
    average_speed: Option<u32>,
    upload_count: Option<u32>,
    file_count: Option<u32>,
    directory_count: Option<u32>,
    updated_at: u64,
}

impl UserRecord {
    fn json(&self) -> String {
        format!(
            "{{\"username\":\"{}\",\"watched\":{},\"status\":{},\"average_speed\":{},\"upload_count\":{},\"file_count\":{},\"directory_count\":{},\"updated_at\":{}}}",
            json_escape(&self.username),
            self.watched,
            json_option(self.status.as_deref()),
            json_u32_option(self.average_speed),
            json_u32_option(self.upload_count),
            json_u32_option(self.file_count),
            json_u32_option(self.directory_count),
            self.updated_at
        )
    }

    fn slskd_status_json(&self) -> serde_json::Value {
        let presence = match self.status.as_deref() {
            Some("online") | Some("Online") => "Online",
            Some("away") | Some("Away") => "Away",
            _ => "Offline",
        };
        serde_json::json!({
            "username": self.username,
            "presence": presence,
            "isPrivileged": self.privileged,
        })
    }

    fn slskd_info_json(&self) -> serde_json::Value {
        serde_json::json!({
            "description": "",
            "hasFreeUploadSlot": true,
            "hasPicture": false,
            "picture": null,
            "queueLength": 0,
            "uploadSlots": 0,
            "uploadSpeed": self.average_speed.unwrap_or(0),
            "uploadCount": self.upload_count.unwrap_or(0),
            "fileCount": self.file_count.unwrap_or(0),
            "directoryCount": self.directory_count.unwrap_or(0),
        })
    }
}

#[derive(Debug)]
struct UserStore {
    records: Vec<UserRecord>,
    updated_at: u64,
    max_records: usize,
}

impl UserStore {
    fn new() -> Self {
        Self::with_max_records(MAX_USER_RECORDS)
    }

    fn with_max_records(max_records: usize) -> Self {
        Self {
            records: Vec::new(),
            updated_at: unix_timestamp(),
            max_records: max_records.max(1),
        }
    }

    fn from_persisted(records: Vec<crate::persistence::UserProjectionRecord>) -> Self {
        let mut updated_at = unix_timestamp();
        let mut seen_usernames = HashSet::new();
        let records = records
            .into_iter()
            .map(|mut record| {
                record.username = bounded_user_username(&record.username);
                record
            })
            .filter(|record| seen_usernames.insert(record.username.clone()))
            .take(MAX_USER_RECORDS)
            .map(|record| {
                updated_at = updated_at.max(record.updated_at as u64);
                UserRecord {
                    username: record.username,
                    watched: record.watched,
                    status: record.status,
                    privileged: false,
                    average_speed: record.average_speed.and_then(|value| value.try_into().ok()),
                    upload_count: record.upload_count.and_then(|value| value.try_into().ok()),
                    file_count: record.file_count.and_then(|value| value.try_into().ok()),
                    directory_count: record
                        .directory_count
                        .and_then(|value| value.try_into().ok()),
                    updated_at: record.updated_at as u64,
                }
            })
            .collect();
        Self {
            records,
            updated_at,
            max_records: MAX_USER_RECORDS,
        }
    }

    fn watch(&mut self, username: String) -> Option<UserRecord> {
        let username = bounded_user_username(&username);
        let now = unix_timestamp();
        if let Some(record) = self
            .records
            .iter_mut()
            .find(|record| record.username == username)
        {
            record.watched = true;
            record.updated_at = now;
            self.updated_at = now;
            return Some(record.clone());
        }
        if self.records.len() >= self.max_records {
            return None;
        }
        let record = UserRecord {
            username,
            watched: true,
            status: None,
            privileged: false,
            average_speed: None,
            upload_count: None,
            file_count: None,
            directory_count: None,
            updated_at: now,
        };
        self.records.push(record.clone());
        self.updated_at = now;
        Some(record)
    }

    fn unwatch(&mut self, username: &str) -> Option<UserRecord> {
        let username = bounded_user_username(username);
        let now = unix_timestamp();
        let record = self
            .records
            .iter_mut()
            .find(|record| record.username == username)?;
        record.watched = false;
        record.updated_at = now;
        self.updated_at = now;
        Some(record.clone())
    }

    fn apply_watched_user(&mut self, user: &WatchedUser) -> Option<UserRecord> {
        let username = bounded_user_username(&user.username);
        let now = unix_timestamp();
        let status = user.status.map(|status| status.to_string());
        if let Some(record) = self
            .records
            .iter_mut()
            .find(|record| record.username == username)
        {
            record.status = status;
            if let Some(stats) = user.stats.as_ref() {
                record.average_speed = Some(stats.average_speed);
                record.upload_count = Some(stats.upload_count);
                record.file_count = Some(stats.file_count);
                record.directory_count = Some(stats.directory_count);
            }
            record.updated_at = now;
            self.updated_at = now;
            return Some(record.clone());
        }
        if self.records.len() >= self.max_records {
            return None;
        }
        let record = UserRecord {
            username,
            watched: true,
            status,
            privileged: false,
            average_speed: user.stats.as_ref().map(|stats| stats.average_speed),
            upload_count: user.stats.as_ref().map(|stats| stats.upload_count),
            file_count: user.stats.as_ref().map(|stats| stats.file_count),
            directory_count: user.stats.as_ref().map(|stats| stats.directory_count),
            updated_at: now,
        };
        self.records.push(record.clone());
        self.updated_at = now;
        Some(record)
    }

    fn apply_status(&mut self, status: &UserStatus) -> Option<UserRecord> {
        let username = bounded_user_username(&status.username);
        let now = unix_timestamp();
        if let Some(record) = self
            .records
            .iter_mut()
            .find(|record| record.username == username)
        {
            record.status = Some(status.status.to_string());
            record.privileged = status.privileged;
            record.updated_at = now;
            self.updated_at = now;
            return Some(record.clone());
        }
        if self.records.len() >= self.max_records {
            return None;
        }
        let record = UserRecord {
            username,
            watched: false,
            status: Some(status.status.to_string()),
            privileged: status.privileged,
            average_speed: None,
            upload_count: None,
            file_count: None,
            directory_count: None,
            updated_at: now,
        };
        self.records.push(record.clone());
        self.updated_at = now;
        Some(record)
    }

    fn apply_stats(&mut self, username: String, stats: &UserStats) -> Option<UserRecord> {
        let username = bounded_user_username(&username);
        let now = unix_timestamp();
        if let Some(record) = self
            .records
            .iter_mut()
            .find(|record| record.username == username)
        {
            record.average_speed = Some(stats.average_speed);
            record.upload_count = Some(stats.upload_count);
            record.file_count = Some(stats.file_count);
            record.directory_count = Some(stats.directory_count);
            record.updated_at = now;
            self.updated_at = now;
            return Some(record.clone());
        }
        if self.records.len() >= self.max_records {
            return None;
        }
        let record = UserRecord {
            username,
            watched: false,
            status: None,
            privileged: false,
            average_speed: Some(stats.average_speed),
            upload_count: Some(stats.upload_count),
            file_count: Some(stats.file_count),
            directory_count: Some(stats.directory_count),
            updated_at: now,
        };
        self.records.push(record.clone());
        self.updated_at = now;
        Some(record)
    }

    fn json(&self) -> String {
        let records = self
            .records
            .iter()
            .map(UserRecord::json)
            .collect::<Vec<_>>()
            .join(",");
        format!(
            "{{\"entries\":[{}],\"count\":{},\"updated_at\":{}}}",
            records,
            self.records.len(),
            self.updated_at
        )
    }

    fn summary_json(&self) -> String {
        let watched = self.records.iter().filter(|record| record.watched).count();
        format!(
            "{{\"total\":{},\"watched\":{},\"updated_at\":{}}}",
            self.records.len(),
            watched,
            self.updated_at
        )
    }
}

fn bounded_user_username(username: &str) -> String {
    truncate_utf8_bytes(username.to_owned(), MAX_USER_USERNAME_BYTES)
}

#[derive(Debug)]
struct MeshState {
    rendezvous: MeshRendezvous,
    enabled: bool,
    capability_handshake_enabled: bool,
    soulseek_rendezvous_enabled: bool,
    capability_records: Vec<PeerCapabilityDescriptor>,
    sync_invalid_entries: BTreeMap<String, (u64, u32)>,
    sync_rate_violations: BTreeMap<String, (u64, u32)>,
    sync_quarantined_until: BTreeMap<String, u64>,
    sync_rejected_messages: u64,
    sync_quarantine_events: u64,
    /// Real counters backing `/api/mesh/stats`'s `MeshSyncStats`
    /// contract, incremented at the one real merge call site
    /// (`POST /api/mesh/merge`) instead of being hardcoded to 0.
    sync_merge_total: u64,
    sync_merge_successful: u64,
    sync_merge_failed: u64,
    sync_entries_received: u64,
    sync_entries_sent: u64,
    sync_skipped_entries: u64,
    sync_rate_limit_violations: u64,
    sync_entries_merged: u64,
    updated_at: u64,
}

impl MeshState {
    #[cfg(any(test, feature = "bounded-differential"))]
    fn new() -> Self {
        Self::with_settings(true, true, true, true)
    }

    fn from_settings(settings: &crate::config::MeshRuntimeSettings) -> Self {
        Self::with_settings(
            settings.enabled,
            settings.enable_soulseek_capability_handshake,
            settings.enable_soulseek_rendezvous,
            settings.probe_soulseek_rendezvous_capabilities,
        )
    }

    fn with_settings(
        enabled: bool,
        capability_handshake_enabled: bool,
        soulseek_rendezvous_enabled: bool,
        active_probe: bool,
    ) -> Self {
        Self {
            rendezvous: MeshRendezvous::new(MeshRendezvousOptions {
                interest_tag: MESH_RENDEZVOUS_INTEREST_TAG.to_owned(),
                active_probe: enabled && soulseek_rendezvous_enabled && active_probe,
            }),
            enabled,
            capability_handshake_enabled,
            soulseek_rendezvous_enabled,
            capability_records: Vec::new(),
            sync_invalid_entries: BTreeMap::new(),
            sync_rate_violations: BTreeMap::new(),
            sync_quarantined_until: BTreeMap::new(),
            sync_rejected_messages: 0,
            sync_quarantine_events: 0,
            sync_merge_total: 0,
            sync_merge_successful: 0,
            sync_merge_failed: 0,
            sync_entries_received: 0,
            sync_entries_sent: 0,
            sync_skipped_entries: 0,
            sync_rate_limit_violations: 0,
            sync_entries_merged: 0,
            updated_at: unix_timestamp(),
        }
    }

    fn sync_is_quarantined(&mut self, username: &str, now: u64) -> bool {
        self.sync_quarantined_until
            .retain(|_, expires_at| *expires_at > now);
        self.sync_quarantined_until
            .get(&username.to_ascii_lowercase())
            .is_some_and(|expires_at| *expires_at > now)
    }

    fn record_invalid_sync_entries(
        &mut self,
        username: &str,
        invalid: u32,
        settings: &crate::config::MeshSyncSecuritySettings,
        now: u64,
    ) -> bool {
        let key = username.to_ascii_lowercase();
        let window = settings.rate_limit_window.as_secs();
        let entry = self
            .sync_invalid_entries
            .entry(key.clone())
            .or_insert((now, 0));
        if now.saturating_sub(entry.0) >= window {
            *entry = (now, 0);
        }
        entry.1 = entry.1.saturating_add(invalid);
        if entry.1 <= settings.max_invalid_entries_per_window {
            return false;
        }
        self.sync_rejected_messages = self.sync_rejected_messages.saturating_add(1);
        let violations = self
            .sync_rate_violations
            .entry(key.clone())
            .or_insert((now, 0));
        if now.saturating_sub(violations.0) >= window {
            *violations = (now, 0);
        }
        violations.1 = violations.1.saturating_add(1);
        if violations.1 >= settings.quarantine_violation_threshold {
            self.sync_quarantined_until.insert(
                key,
                now.saturating_add(settings.quarantine_duration.as_secs()),
            );
            self.sync_quarantine_events = self.sync_quarantine_events.saturating_add(1);
            violations.1 = 0;
        }
        true
    }

    fn mesh_capability_usernames(&self) -> Vec<&str> {
        self.capability_records
            .iter()
            .filter(|descriptor| MeshRendezvous::accepts_descriptor(descriptor))
            .map(|descriptor| descriptor.username.as_str())
            .collect()
    }

    fn update_capability(
        &mut self,
        mut descriptor: PeerCapabilityDescriptor,
    ) -> Result<(), String> {
        descriptor
            .verify(std::time::SystemTime::now())
            .map_err(|error| format!("peer capability descriptor rejected: {error}"))?;
        let now = unix_timestamp();
        self.capability_records
            .retain(|record| record.expires_at_unix > now);
        if self.capability_records.iter().any(|record| {
            record.peer_id.eq_ignore_ascii_case(&descriptor.peer_id)
                && !record.username.eq_ignore_ascii_case(&descriptor.username)
        }) {
            return Err(
                "peer capability descriptor peer ID is already registered to another username"
                    .to_owned(),
            );
        }
        descriptor.issued_at_unix = now;
        descriptor.expires_at_unix = descriptor
            .expires_at_unix
            .min(now.saturating_add(PEER_CAPABILITY_LEASE_SECONDS));
        if let Some(existing) = self
            .capability_records
            .iter_mut()
            .find(|record| record.username.eq_ignore_ascii_case(&descriptor.username))
        {
            *existing = descriptor;
        } else {
            if self.capability_records.len() >= MAX_PEER_CAPABILITY_RECORDS {
                return Err(format!(
                    "peer capability registry is full (maximum {MAX_PEER_CAPABILITY_RECORDS} records)"
                ));
            }
            self.capability_records.push(descriptor);
        }
        self.updated_at = now;
        Ok(())
    }

    fn restore_capability(&mut self, descriptor: PeerCapabilityDescriptor) -> bool {
        if descriptor.verify(SystemTime::now()).is_err()
            || self.capability_records.len() >= MAX_PEER_CAPABILITY_RECORDS
            || self.capability_records.iter().any(|record| {
                record.peer_id.eq_ignore_ascii_case(&descriptor.peer_id)
                    || record.username.eq_ignore_ascii_case(&descriptor.username)
            })
        {
            return false;
        }
        self.capability_records.push(descriptor);
        true
    }

    fn restore_persisted_capabilities(&mut self, records: &[serde_json::Value]) {
        for record in records.iter().take(MAX_PEER_CAPABILITY_RECORDS) {
            if let Some(descriptor) = persisted_capability_descriptor(record) {
                let _ = self.restore_capability(descriptor);
            }
        }
    }

    fn persisted_capability_projection(&self) -> Vec<serde_json::Value> {
        self.capability_records
            .iter()
            .map(|descriptor| {
                serde_json::json!({
                    "peerId": descriptor.peer_id,
                    "username": descriptor.username,
                    "features": descriptor.features,
                    "endpoints": descriptor.endpoints,
                    "overlayPort": descriptor.overlay_port,
                    "maxPayloadLength": descriptor.max_payload_length,
                    "issuedAtUnix": descriptor.issued_at_unix,
                    "expiresAtUnix": descriptor.expires_at_unix,
                    "publicKey": STANDARD.encode(descriptor.public_key),
                    "signature": descriptor.signature.map(|value| STANDARD.encode(value)),
                })
            })
            .collect()
    }

    fn candidate_usernames(&self, users: &UserStore) -> Vec<String> {
        self.rendezvous.candidate_usernames(
            users.records.iter().map(|user| user.username.as_str()),
            self.mesh_capability_usernames(),
        )
    }

    fn status_json(&self, users: &UserStore) -> String {
        let candidates = self.candidate_usernames(users);
        serde_json::json!({
            "enabled": self.enabled,
            "capabilityHandshakeEnabled": self.capability_handshake_enabled,
            "soulseekRendezvousEnabled": self.soulseek_rendezvous_enabled,
            "activeProbe": self.rendezvous.active_probe_enabled(),
            "interestTag": self.rendezvous.interest_tag(),
            "publishedInterestTags": self.rendezvous.publish_interest_tags(),
            "candidateCount": candidates.len(),
            "capabilityRecords": self.capability_records.len(),
            "meshCapableRecords": self.mesh_capability_usernames().len(),
            "privacy": "Soulseek mesh rendezvous is passive unless active probing is explicitly enabled.",
            "updated_at": self.updated_at,
        })
        .to_string()
    }

    fn users_json(&self, users: &UserStore) -> String {
        let candidates = self
            .candidate_usernames(users)
            .into_iter()
            .map(|username| {
                let has_capability = self.capability_records.iter().any(|descriptor| {
                    descriptor.username.eq_ignore_ascii_case(&username)
                        && MeshRendezvous::accepts_descriptor(descriptor)
                });
                serde_json::json!({
                    "username": username,
                    "source": if has_capability { "capability" } else { "similar-user" },
                    "meshCapable": has_capability,
                })
            })
            .collect::<Vec<_>>();
        let count = candidates.len();
        serde_json::json!({
            "users": candidates,
            "count": count,
            "interestTag": self.rendezvous.interest_tag(),
            "updated_at": self.updated_at,
        })
        .to_string()
    }

    fn versioned_similar_users_json(&self, users: &UserStore) -> String {
        let candidates = self
            .candidate_usernames(users)
            .into_iter()
            .map(|username| {
                serde_json::json!({
                    "username": username,
                    "rating": 0,
                })
            })
            .collect::<Vec<_>>();
        serde_json::Value::Array(candidates).to_string()
    }

    fn capability_records_json(&self) -> Vec<serde_json::Value> {
        self.capability_records
            .iter()
            .map(|descriptor| {
                serde_json::json!({
                    "peerId": descriptor.peer_id,
                    "username": descriptor.username,
                    "features": descriptor.features,
                    "endpoints": descriptor.endpoints,
                    "overlayPort": descriptor.overlay_port,
                    "maxPayloadLength": descriptor.max_payload_length,
                    "issuedAt": descriptor.issued_at_unix,
                    "expiresAt": descriptor.expires_at_unix,
                    "meshCapable": MeshRendezvous::accepts_descriptor(descriptor),
                })
            })
            .collect()
    }

    fn capability_service_peers_json(&self) -> Vec<serde_json::Value> {
        let mut records = self.capability_records.iter().collect::<Vec<_>>();
        records.sort_by_key(|record| std::cmp::Reverse(record.issued_at_unix));
        records
            .into_iter()
            .map(capability_service_peer_json)
            .collect()
    }

    fn capability_service_mesh_peers_json(&self) -> Vec<serde_json::Value> {
        self.capability_service_peers_json()
            .into_iter()
            .filter(|record| record["canMeshSync"] == true)
            .map(|record| {
                serde_json::json!({
                    "username": record["username"],
                    "lastSeen": record["lastSeen"],
                    "meshSeqId": record["meshSeqId"],
                })
            })
            .collect()
    }

    fn discover_json(&self, users: &UserStore) -> String {
        let user_json = self
            .candidate_usernames(users)
            .into_iter()
            .map(|username| serde_json::json!({ "username": username }))
            .collect::<Vec<_>>();
        let capability_records = self.capability_records_json();
        let user_count = user_json.len();
        let capability_record_count = capability_records.len();
        serde_json::json!({
            "users": user_json,
            "count": user_count,
            "capabilityRecords": capability_records,
            "capabilityRecordCount": capability_record_count,
            "interestTag": self.rendezvous.interest_tag(),
            "activeProbe": self.rendezvous.active_probe_enabled(),
            "updated_at": self.updated_at,
        })
        .to_string()
    }
}

async fn discover_mesh_range_sources(
    state: &AppState,
    expected_hash: &str,
    file_size: u64,
) -> Vec<multisource::RangeSource> {
    let (recording_ids, peer_ids) = {
        let discovery = state.content_discovery.read().await;
        let recording_ids = discovery.recording_ids_for_hash(expected_hash, file_size);
        let peer_ids = discovery.peer_ids_for_recordings(&recording_ids);
        (recording_ids, peer_ids)
    };
    if peer_ids.is_empty() {
        return Vec::new();
    }
    let peer_ids = peer_ids
        .into_iter()
        .map(|peer_id| peer_id.to_ascii_lowercase())
        .collect::<HashSet<_>>();
    let mut usernames = HashSet::new();
    let mut sources = state
        .config
        .trusted_mesh_peers
        .iter()
        .filter(|peer| peer_ids.contains(&peer.peer_id.to_ascii_lowercase()))
        .filter_map(|peer| {
            let endpoint = peer.range_url(
                expected_hash,
                file_size,
                recording_ids.first().map(String::as_str),
            )?;
            usernames
                .insert(peer.username.to_ascii_lowercase())
                .then_some(multisource::RangeSource {
                    username: peer.username.clone(),
                    url: endpoint,
                    authorization: None,
                })
        })
        .collect::<Vec<_>>();
    let mesh = state.mesh.read().await;
    sources.extend(
        mesh.capability_records
            .iter()
            .filter(|descriptor| {
                peer_ids.contains(&descriptor.peer_id.to_ascii_lowercase())
                    && MeshRendezvous::accepts_descriptor(descriptor)
            })
            .filter_map(|descriptor| {
                let endpoint = descriptor.endpoints.iter().find(|endpoint| {
                    endpoint.starts_with("https://") || endpoint.starts_with("http://")
                })?;
                usernames
                    .insert(descriptor.username.to_ascii_lowercase())
                    .then_some(multisource::RangeSource {
                        username: descriptor.username.clone(),
                        url: endpoint.clone(),
                        authorization: None,
                    })
            }),
    );
    sources
}

fn swarm_analytics_dashboard(
    store: &multisource::SwarmStore,
    time_window_hours: u64,
    ranking_limit: usize,
) -> serde_json::Value {
    let cutoff = unix_timestamp().saturating_sub(time_window_hours.saturating_mul(3_600));
    let jobs = store
        .list()
        .into_iter()
        .filter(|job| job.created_at >= cutoff)
        .collect::<Vec<_>>();
    let total_downloads = jobs.len() as u64;
    let successful_downloads = jobs.iter().filter(|job| job.status == "completed").count() as u64;
    let failed_downloads = jobs.iter().filter(|job| job.status == "failed").count() as u64;
    let completed = jobs
        .iter()
        .filter_map(|job| job.result.as_ref().filter(|result| result.success))
        .collect::<Vec<_>>();
    let total_bytes = completed
        .iter()
        .map(|result| result.bytes_downloaded)
        .sum::<u64>();
    let total_chunks = completed
        .iter()
        .map(|result| result.chunks.len() as u64)
        .sum::<u64>();
    let attempted_chunks = jobs.iter().map(|job| job.total_chunks).sum::<u64>();
    let average_duration =
        average_u64(completed.iter().map(|result| result.total_time_ms)) / 1_000.0;
    let average_sources = average_u64(completed.iter().map(|result| result.sources_used as u64));
    let average_speed = if completed.is_empty() {
        0.0
    } else {
        completed
            .iter()
            .map(|result| {
                result.bytes_downloaded as f64 / (result.total_time_ms.max(1) as f64 / 1_000.0)
            })
            .sum::<f64>()
            / completed.len() as f64
    };
    let success_rate = ratio(successful_downloads, total_downloads);
    let chunk_success_rate = ratio(total_chunks, attempted_chunks);

    let mut peers = BTreeMap::<String, (String, u64, u64, u64)>::new();
    let mut available_peers = HashSet::new();
    for job in &jobs {
        available_peers.extend(job.sources.iter().map(|source| source.to_ascii_lowercase()));
        if let Some(result) = job.result.as_ref() {
            for chunk in &result.chunks {
                let entry = peers
                    .entry(chunk.username.to_ascii_lowercase())
                    .or_insert_with(|| (chunk.username.clone(), 0, 0, 0));
                entry.1 = entry.1.saturating_add(1);
                entry.2 = entry.2.saturating_add(chunk.bytes_downloaded);
                entry.3 = entry.3.saturating_add(chunk.time_ms);
            }
        }
    }
    let mut peer_rows = peers
        .into_values()
        .map(|(peer_id, chunks, bytes, time_ms)| {
            let average_rtt = if chunks == 0 {
                0.0
            } else {
                time_ms as f64 / chunks as f64
            };
            let throughput = bytes as f64 / (time_ms.max(1) as f64 / 1_000.0);
            (peer_id, chunks, bytes, average_rtt, throughput)
        })
        .collect::<Vec<_>>();
    peer_rows.sort_by(|left, right| {
        right.2.cmp(&left.2).then_with(|| {
            left.0
                .to_ascii_lowercase()
                .cmp(&right.0.to_ascii_lowercase())
        })
    });
    let active_peer_count = peer_rows.len() as u64;
    let peer_rankings = peer_rows
        .into_iter()
        .take(ranking_limit)
        .enumerate()
        .map(
            |(index, (peer_id, chunks, bytes, average_rtt, throughput))| {
                serde_json::json!({
                    "peerId": peer_id,
                    "source": "overlay",
                    "reputationScore": 1.0,
                    "averageRttMs": average_rtt,
                    "averageThroughputBytesPerSecond": throughput,
                    "chunksCompleted": chunks,
                    "chunksFailed": 0,
                    "chunkSuccessRate": 1.0,
                    "totalBytesTransferred": bytes,
                    "rank": index + 1,
                })
            },
        )
        .collect::<Vec<_>>();
    let peer_utilization = ratio(active_peer_count, available_peers.len() as u64);
    let rescue_count = jobs
        .iter()
        .filter(|job| job.output_path.starts_with("rescue/"))
        .count() as u64;
    let first_byte_samples = completed
        .iter()
        .filter_map(|result| result.chunks.iter().map(|chunk| chunk.time_ms).min())
        .collect::<Vec<_>>();
    let efficiency = serde_json::json!({
        "chunkUtilization": ratio(total_chunks, attempted_chunks),
        "peerUtilization": peer_utilization,
        "redundancyFactor": if total_chunks == 0 { 0.0 } else { 1.0 },
        "averageTimeToFirstByteMs": average_u64(first_byte_samples.into_iter()),
        "averageReassignmentRate": 0.0,
        "averageRescueRate": ratio(rescue_count, total_downloads),
    });
    let performance = serde_json::json!({
        "totalDownloads": total_downloads,
        "successfulDownloads": successful_downloads,
        "failedDownloads": failed_downloads,
        "successRate": success_rate,
        "averageDurationSeconds": average_duration,
        "averageSpeedBytesPerSecond": average_speed,
        "averageSourcesUsed": average_sources,
        "totalBytesDownloaded": total_bytes,
        "totalChunksCompleted": total_chunks,
        "chunkSuccessRate": chunk_success_rate,
        "timeWindow": format_dotnet_hours(time_window_hours),
    });
    let mut recommendations = Vec::new();
    if success_rate < 0.8 {
        let description = format!(
            "Current success rate is {}. Consider improving peer selection criteria.",
            format_percent_one(success_rate)
        );
        recommendations.push(swarm_recommendation(
            "PeerSelection",
            "High",
            "Low Success Rate",
            &description,
            "Review peer reputation thresholds and increase minimum reputation score for peer selection.",
            0.3,
        ));
    }
    if chunk_success_rate < 0.9 {
        let description = format!(
            "Chunk success rate is {}. Consider adjusting chunk size.",
            format_percent_one(chunk_success_rate)
        );
        recommendations.push(swarm_recommendation(
            "ChunkSize",
            "Medium",
            "High Chunk Failure Rate",
            &description,
            "Try reducing chunk size to improve reliability, or increase timeout values.",
            0.2,
        ));
    }
    if peer_utilization < 0.5 {
        let description = format!(
            "Only {} of available peers are being utilized.",
            format_percent_one(peer_utilization)
        );
        recommendations.push(swarm_recommendation(
            "SourceCount",
            "Low",
            "Low Peer Utilization",
            &description,
            "Consider increasing the number of sources per download to improve redundancy.",
            0.15,
        ));
    }
    if average_speed / (1024.0 * 1024.0) < 0.5 {
        let description = format!(
            "Average download speed is {:.2} MB/s. This may indicate network or peer issues.",
            average_speed / (1024.0 * 1024.0)
        );
        recommendations.push(swarm_recommendation(
            "NetworkConfig",
            "High",
            "Low Download Speed",
            &description,
            "Check network connectivity, firewall settings, and consider using more sources per download.",
            0.4,
        ));
    }
    recommendations.sort_by(|left, right| {
        recommendation_priority(right)
            .cmp(&recommendation_priority(left))
            .then_with(|| {
                right["estimatedImpact"]
                    .as_f64()
                    .partial_cmp(&left["estimatedImpact"].as_f64())
                    .unwrap_or(std::cmp::Ordering::Equal)
            })
    });
    serde_json::json!({
        "performanceMetrics": performance,
        "peerRankings": peer_rankings,
        "efficiencyMetrics": efficiency,
        "recommendations": recommendations,
    })
}

fn ratio(numerator: u64, denominator: u64) -> f64 {
    if denominator == 0 {
        0.0
    } else {
        numerator as f64 / denominator as f64
    }
}

fn average_u64(values: impl Iterator<Item = u64>) -> f64 {
    let (total, count) = values.fold((0_u128, 0_u64), |(total, count), value| {
        (total.saturating_add(u128::from(value)), count + 1)
    });
    if count == 0 {
        0.0
    } else {
        total as f64 / count as f64
    }
}

fn format_dotnet_hours(hours: u64) -> String {
    if hours < 24 {
        format!("{hours:02}:00:00")
    } else {
        format!("{}.{:02}:00:00", hours / 24, hours % 24)
    }
}

fn format_percent_one(value: f64) -> String {
    format!("{:.1}%", value * 100.0)
}

fn swarm_recommendation(
    kind: &str,
    priority: &str,
    title: &str,
    description: &str,
    action: &str,
    estimated_impact: f64,
) -> serde_json::Value {
    serde_json::json!({
        "type": kind,
        "priority": priority,
        "title": title,
        "description": description,
        "action": action,
        "estimatedImpact": estimated_impact,
    })
}

fn recommendation_priority(value: &serde_json::Value) -> u8 {
    match value["priority"].as_str() {
        Some("Critical") => 4,
        Some("High") => 3,
        Some("Medium") => 2,
        Some("Low") => 1,
        _ => 0,
    }
}

async fn content_discovery_error_response(state: &AppState, error: String) -> HttpResponse {
    if error.starts_with("content discovery state ") {
        update_session(state, |snapshot| {
            snapshot.last_error = Some(error);
        })
        .await;
        routing::service_unavailable_response("content discovery storage is unavailable")
    } else {
        routing::bad_request_response(&error)
    }
}

fn persisted_hash_db_record(entry: &content_discovery::HashDbEntry) -> persistence::HashDbRecord {
    persistence::HashDbRecord {
        flac_key: entry.flac_key.clone(),
        byte_hash: entry.byte_hash.clone(),
        size: i64::try_from(entry.size).unwrap_or(i64::MAX),
        first_seen_at: i64::try_from(entry.first_seen_at).unwrap_or(i64::MAX),
        last_updated_at: i64::try_from(entry.last_updated_at).unwrap_or(i64::MAX),
        seq_id: i64::try_from(entry.seq_id).unwrap_or(i64::MAX),
        use_count: i64::from(entry.use_count),
        full_file_hash: entry.full_file_hash.clone(),
        musicbrainz_id: entry.music_brainz_id.clone(),
        file_sha256: entry.file_sha256.clone(),
    }
}

#[derive(Debug, Deserialize)]
#[serde(rename_all = "camelCase")]
struct HashDbVerificationRequest {
    filename: Option<String>,
    size: Option<i64>,
    byte_hash: Option<String>,
    #[allow(dead_code)]
    sample_rate: Option<i32>,
    #[allow(dead_code)]
    channels: Option<i32>,
    #[allow(dead_code)]
    bit_depth: Option<i32>,
}

fn hashdb_verification_entry_from_body(
    body: &str,
) -> Result<content_discovery::HashDbEntry, String> {
    let request = serde_json::from_str::<HashDbVerificationRequest>(body)
        .map_err(|_| "filename, size, and byteHash are required".to_owned())?;
    let filename = request
        .filename
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "filename, size, and byteHash are required".to_owned())?;
    let size = request
        .size
        .filter(|value| *value > 0)
        .and_then(|value| u64::try_from(value).ok())
        .ok_or_else(|| "filename, size, and byteHash are required".to_owned())?;
    let byte_hash = request
        .byte_hash
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "filename, size, and byteHash are required".to_owned())?;
    Ok(content_discovery::HashDbEntry {
        flac_key: content_discovery::generate_flac_key(filename, size),
        byte_hash: byte_hash.to_owned(),
        size,
        ..Default::default()
    })
}

fn hash_db_entry_from_persistence(
    record: persistence::HashDbRecord,
) -> Result<content_discovery::HashDbEntry, String> {
    Ok(content_discovery::HashDbEntry {
        flac_key: record.flac_key,
        byte_hash: record.byte_hash,
        size: u64::try_from(record.size).map_err(|_| "HashDb size is invalid".to_owned())?,
        full_file_hash: record.full_file_hash,
        music_brainz_id: record.musicbrainz_id,
        file_sha256: record.file_sha256,
        first_seen_at: u64::try_from(record.first_seen_at)
            .map_err(|_| "HashDb firstSeenAt is invalid".to_owned())?,
        last_updated_at: u64::try_from(record.last_updated_at)
            .map_err(|_| "HashDb lastUpdatedAt is invalid".to_owned())?,
        seq_id: u64::try_from(record.seq_id).map_err(|_| "HashDb seqId is invalid".to_owned())?,
        use_count: u32::try_from(record.use_count)
            .map_err(|_| "HashDb useCount is invalid".to_owned())?,
    })
}

async fn persist_hash_db_snapshot(
    state: &AppState,
    entries: &[content_discovery::HashDbEntry],
    latest_seq: u64,
) -> Result<(), String> {
    let Some(db) = state.db.as_ref() else {
        return Ok(());
    };
    let records = entries
        .iter()
        .map(persisted_hash_db_record)
        .collect::<Vec<_>>();
    db.replace_hash_db_snapshot(&records, i64::try_from(latest_seq).unwrap_or(i64::MAX))
        .await
        .map_err(|error| format!("hash database storage unavailable: {error}"))
}

async fn read_hash_db_state_json(
    state: &AppState,
    key: &str,
) -> Result<Option<serde_json::Value>, String> {
    if let Some(db) = state.db.as_ref() {
        let record = db
            .get_hash_db_state(key)
            .await
            .map_err(|error| format!("hash database state unavailable: {error}"))?;
        let Some(record) = record else {
            return Ok(None);
        };
        let Some(value) = record.value else {
            return Ok(None);
        };
        return serde_json::from_str(&value)
            .map(Some)
            .map_err(|error| format!("HashDbState value is invalid: {error}"));
    }
    Ok(state.controller_features.read().await.get(key).cloned())
}

async fn write_hash_db_state_json(
    state: &AppState,
    key: &str,
    value: Option<serde_json::Value>,
) -> Result<(), String> {
    if let Some(db) = state.db.as_ref() {
        let value = value
            .map(|value| value.to_string())
            .filter(|value| !value.is_empty());
        db.upsert_hash_db_state(&persistence::HashDbStateRecord {
            key: key.to_owned(),
            value,
        })
        .await
        .map_err(|error| format!("hash database state unavailable: {error}"))?;
        return Ok(());
    }
    let mut features = state.controller_features.write().await;
    if let Some(value) = value {
        features.upsert(key.to_owned(), value)
    } else {
        features.remove(key).map(|_| ())
    }
}

fn new_capability_signing_key() -> Result<SigningKey, String> {
    let mut secret = [0_u8; 32];
    SysRng
        .try_fill_bytes(&mut secret)
        .map_err(|_| "secure randomness unavailable for peer capability identity".to_owned())?;
    Ok(SigningKey::from_bytes(&secret))
}

fn load_or_create_capability_signing_key(state_dir: &Path) -> Result<SigningKey, String> {
    let path = state_dir.join("peer-capability-key.bin");
    match fs::symlink_metadata(&path) {
        Ok(metadata) => {
            if metadata.file_type().is_symlink() || !metadata.is_file() {
                return Err("peer capability key must be a regular file".to_owned());
            }
            let mut options = fs::OpenOptions::new();
            options.read(true);
            #[cfg(unix)]
            {
                use std::os::unix::fs::OpenOptionsExt;
                options.custom_flags(libc::O_CLOEXEC | libc::O_NOFOLLOW | libc::O_NONBLOCK);
            }
            let mut file = options
                .open(&path)
                .map_err(|error| format!("peer capability key read failed: {error}"))?;
            let opened_metadata = file
                .metadata()
                .map_err(|error| format!("peer capability key metadata failed: {error}"))?;
            if !opened_metadata.is_file() {
                return Err("peer capability key must be a regular file".to_owned());
            }
            let mut bytes = Vec::with_capacity(33);
            let mut limited = std::io::Read::take(&mut file, 33);
            std::io::Read::read_to_end(&mut limited, &mut bytes)
                .map_err(|error| format!("peer capability key read failed: {error}"))?;
            let secret: [u8; 32] = bytes
                .try_into()
                .map_err(|_| "peer capability key must contain exactly 32 bytes".to_owned())?;
            #[cfg(unix)]
            {
                use std::os::unix::fs::PermissionsExt;
                file.set_permissions(fs::Permissions::from_mode(0o600))
                    .map_err(|error| format!("peer capability key permissions failed: {error}"))?;
            }
            Ok(SigningKey::from_bytes(&secret))
        }
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => {
            let signing_key = new_capability_signing_key()?;
            let temporary = path.with_extension(format!("tmp-{}", uuid::Uuid::new_v4().simple()));
            let mut options = fs::OpenOptions::new();
            options.write(true).create_new(true);
            #[cfg(unix)]
            {
                use std::os::unix::fs::OpenOptionsExt;
                options.mode(0o600);
            }
            let mut file = options
                .open(&temporary)
                .map_err(|error| format!("peer capability key creation failed: {error}"))?;
            std::io::Write::write_all(&mut file, &signing_key.to_bytes())
                .map_err(|error| format!("peer capability key write failed: {error}"))?;
            file.sync_all()
                .map_err(|error| format!("peer capability key sync failed: {error}"))?;
            fs::rename(&temporary, &path)
                .map_err(|error| format!("peer capability key publish failed: {error}"))?;
            Ok(signing_key)
        }
        Err(error) => Err(format!("peer capability key metadata failed: {error}")),
    }
}

async fn local_capability_descriptor(state: &AppState) -> Result<PeerCapabilityDescriptor, String> {
    let mut features = vec![FEATURE_CAPABILITIES_V1.to_owned()];
    let publish_availability = state
        .media_services
        .read()
        .await
        .features
        .mesh_publish_availability;
    if publish_availability && state.private_gateway.is_some() {
        features.push("mesh_sync".to_owned());
    }
    PeerCapabilityDescriptor::unsigned(
        pod_request_peer_id(state)
            .await
            .unwrap_or_else(|| "slskr".to_owned()),
        features,
        Vec::new(),
        std::time::Duration::from_secs(24 * 60 * 60),
        &state.capability_signing_key,
        std::time::SystemTime::now(),
    )
    .map(|descriptor| {
        descriptor.with_overlay_port(if publish_availability {
            state
                .private_gateway
                .as_ref()
                .map(|gateway| gateway.bind().port())
        } else {
            None
        })
    })
    .and_then(|descriptor| descriptor.sign(&state.capability_signing_key))
    .map_err(|error| format!("local peer capability descriptor failed: {error}"))
}

fn local_profile_peer_id(state: &AppState) -> String {
    mesh_dht::peer_id(&state.capability_signing_key)
}

fn profile_friend_code(peer_id: &str) -> String {
    const ALPHABET: &[u8; 32] = b"abcdefghijklmnopqrstuvwxyz234567";
    let digest = Sha256::digest(peer_id.as_bytes());
    let mut encoded = String::with_capacity(16);
    let mut bits = 0_u16;
    let mut bit_count = 0_u8;
    for byte in digest.iter().take(10) {
        bits = (bits << 8) | u16::from(*byte);
        bit_count += 8;
        while bit_count >= 5 {
            bit_count -= 5;
            encoded.push(ALPHABET[((bits >> bit_count) & 31) as usize] as char);
        }
    }
    if bit_count > 0 {
        encoded.push(ALPHABET[((bits << (5 - bit_count)) & 31) as usize] as char);
    }
    format!(
        "{}-{}-{}-{}",
        &encoded[..5],
        &encoded[5..9],
        &encoded[9..13],
        &encoded[13..16]
    )
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct BrowseEntry {
    filename: String,
    size: u64,
    extension: String,
    path_encoding: ProtocolTextEncoding,
}

impl BrowseEntry {
    fn from_json_file(file: &serde_json::Value, directory: Option<&str>) -> Option<Self> {
        let raw_filename = file
            .get("filename")
            .or_else(|| file.get("name"))?
            .as_str()?
            .to_owned();
        let filename = match directory {
            Some(directory) if !raw_filename.contains('/') && !raw_filename.contains('\\') => {
                join_virtual_path(directory.trim_matches('/'), &raw_filename)
            }
            _ => raw_filename,
        };
        let extension = file
            .get("extension")
            .and_then(serde_json::Value::as_str)
            .map(str::to_owned)
            .unwrap_or_else(|| filename.split('.').next_back().unwrap_or("").to_owned());
        Some(Self {
            filename: truncate_utf8_bytes(filename, MAX_BROWSE_FILENAME_BYTES),
            size: file
                .get("size")
                .and_then(serde_json::Value::as_u64)
                .unwrap_or(0),
            extension: truncate_utf8_bytes(extension, MAX_BROWSE_EXTENSION_BYTES),
            path_encoding: ProtocolTextEncoding::Utf8,
        })
    }

    fn json(&self) -> String {
        format!(
            "{{\"filename\":\"{}\",\"size\":{},\"extension\":\"{}\"}}",
            json_escape(&self.filename),
            self.size,
            json_escape(&self.extension)
        )
    }
}

#[derive(Debug, Default)]
struct RemotePathEncodingRegistry {
    entries: BTreeMap<(String, String), ProtocolTextEncoding>,
}

impl RemotePathEncodingRegistry {
    fn remember(&mut self, username: &str, path: &str, encoding: ProtocolTextEncoding) {
        if username.is_empty() || path.is_empty() {
            return;
        }
        let key = (username.to_owned(), path.to_owned());
        if self.entries.len() >= MAX_REMOTE_PATH_ENCODINGS && !self.entries.contains_key(&key) {
            if let Some(oldest_key) = self.entries.keys().next().cloned() {
                self.entries.remove(&oldest_key);
            }
        }
        self.entries.insert(key, encoding);
    }

    fn encoding_for(&self, username: &str, path: &str) -> ProtocolTextEncoding {
        self.entries
            .get(&(username.to_owned(), path.to_owned()))
            .copied()
            .unwrap_or_default()
    }

    fn remember_browse_entries(&mut self, username: &str, entries: &[BrowseEntry]) {
        for entry in entries {
            self.remember(username, &entry.filename, entry.path_encoding);
            let mut folder = virtual_folder(&entry.filename);
            while !folder.is_empty() {
                self.remember(username, folder, entry.path_encoding);
                folder = virtual_folder(folder);
            }
        }
    }

    fn remember_search_response(&mut self, response: &FileSearchResponse) {
        for entry in response.results.iter().chain(&response.private_results) {
            self.remember(&response.username, &entry.filename, entry.filename_encoding);
        }
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct BrowseRecord {
    username: String,
    status: &'static str,
    entries: Vec<BrowseEntry>,
    reason: Option<String>,
    folder: Option<String>,
    indirect_token: Option<u32>,
    requested_at: Option<u64>,
    updated_at: u64,
}

impl BrowseRecord {
    fn json(&self) -> String {
        let entries = self
            .entries
            .iter()
            .map(BrowseEntry::json)
            .collect::<Vec<_>>()
            .join(",");
        let total_bytes = self.entries.iter().map(|entry| entry.size).sum::<u64>();
        format!(
            "{{\"username\":\"{}\",\"status\":\"{}\",\"entries\":[{}],\"count\":{},\"total_bytes\":{},\"reason\":{},\"folder\":{},\"indirect_token\":{},\"requested_at\":{},\"updated_at\":{}}}",
            json_escape(&self.username),
            self.status,
            entries,
            self.entries.len(),
            total_bytes,
            json_option(public_browse_reason(self.status, self.reason.as_deref())),
            json_option(self.folder.as_deref()),
            json_u32_option(self.indirect_token),
            json_u64_option(self.requested_at),
            self.updated_at
        )
    }

    fn slskd_status_json(&self) -> String {
        let size = self.entries.iter().map(|entry| entry.size).sum::<u64>();
        let complete = matches!(self.status, "ready" | "partial");
        let percent_complete = if complete { 100.0 } else { 0.0 };
        let directory_count = group_browse_entries(&self.entries).len();
        serde_json::json!({
            "username": self.username,
            "status": self.status,
            "state": browse_slskd_state(self.status),
            "size": size,
            "bytesTransferred": if complete { size } else { 0 },
            "bytesRemaining": if complete { 0 } else { size },
            "percentComplete": percent_complete,
            "fileCount": self.entries.len(),
            "directoryCount": directory_count,
            "isComplete": complete,
            "reason": public_browse_reason(self.status, self.reason.as_deref()),
            "folder": self.folder,
            "indirectToken": self.indirect_token,
            "requestedAt": self.requested_at,
            "updatedAt": self.updated_at,
        })
        .to_string()
    }
}

fn public_browse_reason(status: &str, reason: Option<&str>) -> Option<&'static str> {
    reason.map(|_| match status {
        "failed" => "browse failed",
        "cancelled" => "browse cancelled",
        "indirect_pending" => "direct browse failed; indirect request pending",
        _ => "browse operation unavailable",
    })
}

fn browse_slskd_state(status: &str) -> &'static str {
    match status {
        "ready" | "partial" => "Completed",
        "failed" => "Failed",
        "cancelled" => "Cancelled",
        "indirect_pending" => "Pending",
        _ => "InProgress",
    }
}

fn persisted_browse_status(status: &str) -> &'static str {
    match status {
        "requested" => "requested",
        "ready" => "ready",
        "partial" => "partial",
        "failed" => "failed",
        "cancelled" => "cancelled",
        "indirect_pending" => "indirect_pending",
        _ => "failed",
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct BrowseStore {
    records: Vec<BrowseRecord>,
    next_indirect_token: u32,
    updated_at: u64,
    max_records: usize,
    max_entries_per_user: usize,
}

impl BrowseStore {
    fn new() -> Self {
        Self::with_limits(MAX_BROWSE_RECORDS, MAX_BROWSE_ENTRIES_PER_USER)
    }

    fn with_limits(max_records: usize, max_entries_per_user: usize) -> Self {
        Self {
            records: Vec::new(),
            next_indirect_token: 1,
            updated_at: unix_timestamp(),
            max_records: max_records.max(1),
            max_entries_per_user: max_entries_per_user.max(1),
        }
    }

    #[allow(dead_code)]
    fn from_persisted(records: Vec<crate::persistence::BrowseRecord>) -> Self {
        let mut next_indirect_token = 1_u32;
        let mut updated_at = unix_timestamp();
        let mut seen_usernames = std::collections::HashSet::new();
        let mut total_entries = 0_usize;
        let records = records
            .into_iter()
            .map(|mut record| {
                record.username = bounded_browse_username(&record.username);
                record
            })
            .filter(|record| seen_usernames.insert(record.username.clone()))
            .take(MAX_BROWSE_RECORDS)
            .map(|record| {
                let remaining = MAX_TOTAL_BROWSE_ENTRIES.saturating_sub(total_entries);
                let entries = serde_json::from_str::<serde_json::Value>(&record.entries_json)
                    .ok()
                    .and_then(|value| value.as_array().cloned())
                    .unwrap_or_default()
                    .iter()
                    .filter_map(|entry| BrowseEntry::from_json_file(entry, None))
                    .take(MAX_BROWSE_ENTRIES_PER_USER.min(remaining))
                    .collect::<Vec<_>>();
                total_entries = total_entries.saturating_add(entries.len());
                let indirect_token = record
                    .indirect_token
                    .and_then(|token| u32::try_from(token).ok());
                if let Some(token) = indirect_token {
                    next_indirect_token = next_indirect_token.max(token.wrapping_add(1).max(1));
                }
                let requested_at = record
                    .requested_at
                    .and_then(|timestamp| u64::try_from(timestamp).ok());
                let record_updated_at =
                    u64::try_from(record.updated_at).unwrap_or_else(|_| unix_timestamp());
                updated_at = updated_at.max(record_updated_at);
                BrowseRecord {
                    username: record.username,
                    status: persisted_browse_status(&record.status),
                    entries,
                    reason: record
                        .reason
                        .map(|reason| truncate_utf8_bytes(reason, MAX_BROWSE_REASON_BYTES)),
                    folder: record
                        .folder
                        .map(|folder| truncate_utf8_bytes(folder, MAX_BROWSE_FOLDER_BYTES)),
                    indirect_token,
                    requested_at,
                    updated_at: record_updated_at,
                }
            })
            .collect();
        Self {
            records,
            next_indirect_token,
            updated_at,
            max_records: MAX_BROWSE_RECORDS,
            max_entries_per_user: MAX_BROWSE_ENTRIES_PER_USER,
        }
    }

    fn next_indirect_token(&mut self) -> u32 {
        let mut candidate = self.next_indirect_token.max(1);
        for _ in 0..=self.records.len() {
            if !self
                .records
                .iter()
                .any(|record| record.indirect_token == Some(candidate))
            {
                self.next_indirect_token = candidate.wrapping_add(1).max(1);
                return candidate;
            }
            candidate = candidate.wrapping_add(1).max(1);
        }
        unreachable!("bounded browse store must leave an available u32 token")
    }

    fn request(&mut self, username: String) -> Option<BrowseRecord> {
        let username = bounded_browse_username(&username);
        let now = unix_timestamp();
        if let Some(record) = self
            .records
            .iter_mut()
            .find(|record| record.username == username)
        {
            record.status = "requested";
            record.reason = None;
            record.folder = None;
            record.indirect_token = None;
            record.requested_at = Some(now);
            record.updated_at = now;
            self.updated_at = now;
            return Some(record.clone());
        }
        if self.records.len() >= self.max_records {
            return None;
        }
        let record = BrowseRecord {
            username,
            status: "requested",
            entries: Vec::new(),
            reason: None,
            folder: None,
            indirect_token: None,
            requested_at: Some(now),
            updated_at: now,
        };
        self.records.push(record.clone());
        self.updated_at = now;
        Some(record)
    }

    fn request_folder(&mut self, username: String, folder: String) -> Option<BrowseRecord> {
        let username = bounded_browse_username(&username);
        let folder = truncate_utf8_bytes(folder, MAX_BROWSE_FOLDER_BYTES);
        let now = unix_timestamp();
        if let Some(record) = self
            .records
            .iter_mut()
            .find(|record| record.username == username)
        {
            record.status = "requested";
            record.entries.clear();
            record.reason = None;
            record.folder = Some(folder);
            record.indirect_token = None;
            record.requested_at = Some(now);
            record.updated_at = now;
            self.updated_at = now;
            return Some(record.clone());
        }
        if self.records.len() >= self.max_records {
            return None;
        }
        let record = BrowseRecord {
            username,
            status: "requested",
            entries: Vec::new(),
            reason: None,
            folder: Some(folder),
            indirect_token: None,
            requested_at: Some(now),
            updated_at: now,
        };
        self.records.push(record.clone());
        self.updated_at = now;
        Some(record)
    }

    fn requested_folder(&self, username: &str) -> Option<Option<String>> {
        let username = bounded_browse_username(username);
        self.records
            .iter()
            .find(|record| record.username == username && record.status == "requested")
            .map(|record| record.folder.clone())
    }

    fn mark_indirect_pending(&mut self, username: &str, reason: String) -> Option<u32> {
        let username = bounded_browse_username(username);
        let reason = truncate_utf8_bytes(reason, MAX_BROWSE_REASON_BYTES);
        let index = self
            .records
            .iter()
            .position(|record| record.username == username && record.status == "requested")?;
        let token = self.next_indirect_token();
        let now = unix_timestamp();
        let record = &mut self.records[index];
        record.status = "indirect_pending";
        record.reason = Some(reason);
        record.indirect_token = Some(token);
        record.updated_at = now;
        self.updated_at = now;
        Some(token)
    }

    fn pending_indirect(&self, username: &str, token: u32) -> Option<Option<String>> {
        let username = bounded_browse_username(username);
        self.records
            .iter()
            .find(|record| {
                record.username == username
                    && record.status == "indirect_pending"
                    && record.indirect_token == Some(token)
            })
            .map(|record| record.folder.clone())
    }

    fn fail_indirect(&mut self, token: u32, reason: String) -> Option<BrowseRecord> {
        let reason = truncate_utf8_bytes(reason, MAX_BROWSE_REASON_BYTES);
        let now = unix_timestamp();
        let record = self.records.iter_mut().find(|record| {
            record.status == "indirect_pending" && record.indirect_token == Some(token)
        })?;
        record.status = "failed";
        record.reason = Some(reason);
        record.updated_at = now;
        self.updated_at = now;
        Some(record.clone())
    }

    fn add_entries(
        &mut self,
        username: String,
        entries: Vec<BrowseEntry>,
        complete: bool,
    ) -> Option<BrowseRecord> {
        let username = bounded_browse_username(&username);
        let total_entries = self.total_entries();
        let now = unix_timestamp();
        let status = if complete { "ready" } else { "partial" };
        if let Some(record) = self
            .records
            .iter_mut()
            .find(|record| record.username == username)
        {
            record.status = status;
            let per_user_remaining = self
                .max_entries_per_user
                .saturating_sub(record.entries.len());
            let aggregate_remaining = MAX_TOTAL_BROWSE_ENTRIES.saturating_sub(total_entries);
            record.entries.extend(
                entries
                    .into_iter()
                    .take(per_user_remaining.min(aggregate_remaining))
                    .map(bounded_browse_entry),
            );
            record.reason = None;
            record.indirect_token = None;
            record.updated_at = now;
            self.updated_at = now;
            return Some(record.clone());
        }
        if self.records.len() >= self.max_records {
            return None;
        }
        let entries = entries
            .into_iter()
            .take(
                self.max_entries_per_user
                    .min(MAX_TOTAL_BROWSE_ENTRIES.saturating_sub(total_entries)),
            )
            .map(bounded_browse_entry)
            .collect();
        let record = BrowseRecord {
            username,
            status,
            entries,
            reason: None,
            folder: None,
            indirect_token: None,
            requested_at: None,
            updated_at: now,
        };
        self.records.push(record.clone());
        self.updated_at = now;
        Some(record)
    }

    fn fail(&mut self, username: String, reason: String) -> Option<BrowseRecord> {
        let username = bounded_browse_username(&username);
        let reason = truncate_utf8_bytes(reason, MAX_BROWSE_REASON_BYTES);
        let now = unix_timestamp();
        if let Some(record) = self
            .records
            .iter_mut()
            .find(|record| record.username == username)
        {
            record.status = "failed";
            record.reason = Some(reason);
            record.indirect_token = None;
            record.updated_at = now;
            self.updated_at = now;
            return Some(record.clone());
        }
        if self.records.len() >= self.max_records {
            return None;
        }
        let record = BrowseRecord {
            username,
            status: "failed",
            entries: Vec::new(),
            reason: Some(reason),
            folder: None,
            indirect_token: None,
            requested_at: None,
            updated_at: now,
        };
        self.records.push(record.clone());
        self.updated_at = now;
        Some(record)
    }

    fn cancel(&mut self, username: String, reason: String) -> Option<BrowseRecord> {
        let username = bounded_browse_username(&username);
        let reason = truncate_utf8_bytes(reason, MAX_BROWSE_REASON_BYTES);
        let now = unix_timestamp();
        if let Some(record) = self
            .records
            .iter_mut()
            .find(|record| record.username == username)
        {
            record.status = "cancelled";
            record.reason = if reason.trim().is_empty() {
                None
            } else {
                Some(reason)
            };
            record.indirect_token = None;
            record.updated_at = now;
            self.updated_at = now;
            return Some(record.clone());
        }
        if self.records.len() >= self.max_records {
            return None;
        }
        let record = BrowseRecord {
            username,
            status: "cancelled",
            entries: Vec::new(),
            reason: if reason.trim().is_empty() {
                None
            } else {
                Some(reason)
            },
            folder: None,
            indirect_token: None,
            requested_at: None,
            updated_at: now,
        };
        self.records.push(record.clone());
        self.updated_at = now;
        Some(record)
    }

    fn get(&self, username: &str) -> Option<BrowseRecord> {
        let username = bounded_browse_username(username);
        self.records
            .iter()
            .find(|record| record.username == username)
            .cloned()
    }

    fn total_entries(&self) -> usize {
        self.records.iter().map(|record| record.entries.len()).sum()
    }

    fn json(&self, query: Option<&str>) -> String {
        let filter = RecordListFilter::from_query(query);
        let records = self
            .records
            .iter()
            .filter(|record| {
                filter
                    .status
                    .as_deref()
                    .is_none_or(|status| record.status == status)
            })
            .filter(|record| {
                filter
                    .q
                    .as_deref()
                    .is_none_or(|q| record.username.to_ascii_lowercase().contains(q))
            })
            .collect::<Vec<_>>();
        let filtered_count = records.len();
        let records = records
            .into_iter()
            .skip(filter.offset)
            .take(filter.limit.unwrap_or(usize::MAX))
            .map(BrowseRecord::json)
            .collect::<Vec<_>>()
            .join(",");
        format!(
            "{{\"entries\":[{}],\"count\":{},\"filtered_count\":{},\"offset\":{},\"limit\":{},\"updated_at\":{}}}",
            records,
            self.records.len(),
            filtered_count,
            filter.offset,
            json_usize_option(filter.limit),
            self.updated_at
        )
    }

    fn summary_json(&self) -> String {
        let requested = self
            .records
            .iter()
            .filter(|record| record.status == "requested")
            .count();
        let ready = self
            .records
            .iter()
            .filter(|record| record.status == "ready")
            .count();
        let partial = self
            .records
            .iter()
            .filter(|record| record.status == "partial")
            .count();
        let indirect_pending = self
            .records
            .iter()
            .filter(|record| record.status == "indirect_pending")
            .count();
        let failed = self
            .records
            .iter()
            .filter(|record| record.status == "failed")
            .count();
        let files = self
            .records
            .iter()
            .map(|record| record.entries.len())
            .sum::<usize>();
        let bytes = self
            .records
            .iter()
            .flat_map(|record| record.entries.iter())
            .map(|entry| entry.size)
            .sum::<u64>();
        format!(
            "{{\"total\":{},\"requested\":{},\"indirect_pending\":{},\"partial\":{},\"ready\":{},\"failed\":{},\"files\":{},\"bytes\":{},\"updated_at\":{}}}",
            self.records.len(),
            requested,
            indirect_pending,
            partial,
            ready,
            failed,
            files,
            bytes,
            self.updated_at
        )
    }
}

fn bounded_browse_username(username: &str) -> String {
    truncate_utf8_bytes(username.to_owned(), MAX_BROWSE_USERNAME_BYTES)
}

fn bounded_browse_entry(mut entry: BrowseEntry) -> BrowseEntry {
    entry.filename = truncate_utf8_bytes(entry.filename, MAX_BROWSE_FILENAME_BYTES);
    entry.extension = truncate_utf8_bytes(entry.extension, MAX_BROWSE_EXTENSION_BYTES);
    entry
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct MessageRecord {
    id: u64,
    username: String,
    direction: &'static str,
    body: String,
    acknowledged: bool,
    created_at: u64,
    created_at_ms: u64,
    updated_at: u64,
    source_id: Option<u32>,
    source_timestamp: Option<u32>,
    was_replayed: bool,
}

impl MessageRecord {
    fn json(&self) -> String {
        format!(
            "{{\"id\":{},\"username\":\"{}\",\"direction\":\"{}\",\"body\":\"{}\",\"acknowledged\":{},\"created_at\":{},\"updated_at\":{}}}",
            self.id,
            json_escape(&self.username),
            self.direction,
            json_escape(&self.body),
            self.acknowledged,
            self.created_at,
            self.updated_at
        )
    }

    fn slskd_json(&self) -> serde_json::Value {
        serde_json::json!({
            "timestamp": self.created_at.to_string(),
            "createdAtMs": self.created_at_ms,
            "id": self.id,
            "username": self.username,
            "direction": if self.direction == "inbound" { "In" } else { "Out" },
            "message": self.body,
            "isAcknowledged": self.acknowledged,
            "wasReplayed": self.was_replayed,
            "sourceId": self.source_id,
        })
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct MessageStore {
    records: Vec<MessageRecord>,
    next_id: u64,
    updated_at: u64,
    max_records: usize,
}

impl MessageStore {
    fn new() -> Self {
        Self::with_max_records(MAX_MESSAGE_RECORDS)
    }

    fn with_max_records(max_records: usize) -> Self {
        Self {
            records: Vec::new(),
            next_id: 1,
            updated_at: unix_timestamp(),
            max_records: max_records.max(1),
        }
    }

    fn from_persisted(records: Vec<crate::persistence::MessageRecord>) -> Self {
        let mut store = Self::new();
        store.records = records
            .into_iter()
            .filter_map(|record| {
                let id = record.id.parse::<u64>().ok()?;
                Some(MessageRecord {
                    id,
                    username: truncate_utf8_bytes(record.username, MAX_MESSAGE_USERNAME_BYTES),
                    direction: match record.direction.as_str() {
                        "inbound" | "incoming" | "In" => "inbound",
                        _ => "outbound",
                    },
                    body: truncate_utf8_bytes(record.content, MAX_MESSAGE_BODY_BYTES),
                    acknowledged: record.read,
                    created_at: u64::try_from(record.created_at).unwrap_or_default(),
                    created_at_ms: u64::try_from(record.created_at)
                        .unwrap_or_default()
                        .saturating_mul(1_000),
                    updated_at: u64::try_from(record.created_at).unwrap_or_default(),
                    source_id: record.source_id.and_then(|value| u32::try_from(value).ok()),
                    source_timestamp: record
                        .source_timestamp
                        .and_then(|value| u32::try_from(value).ok()),
                    was_replayed: record.was_replayed,
                })
            })
            .collect();
        store.records.sort_by_key(|record| record.id);
        store.records.dedup_by_key(|record| record.id);
        let mut previous_created_at_ms = 0_u64;
        for record in &mut store.records {
            record.created_at_ms = record
                .created_at_ms
                .max(previous_created_at_ms.saturating_add(1));
            previous_created_at_ms = record.created_at_ms;
        }
        if store.records.len() > store.max_records {
            let excess = store.records.len() - store.max_records;
            store.records.drain(0..excess);
        }
        store.next_id = store
            .records
            .iter()
            .map(|record| record.id)
            .max()
            .unwrap_or(0)
            .saturating_add(1);
        store.updated_at = store
            .records
            .iter()
            .map(|record| record.updated_at)
            .max()
            .unwrap_or_else(unix_timestamp);
        store
    }

    fn add(&mut self, username: String, direction: &'static str, body: String) -> MessageRecord {
        let now = unix_timestamp();
        let now_ms = unix_timestamp_millis().max(
            self.records
                .iter()
                .map(|record| record.created_at_ms)
                .max()
                .unwrap_or(0)
                .saturating_add(1),
        );
        let id = self.allocate_id();
        let record = MessageRecord {
            id,
            username: truncate_utf8_bytes(username, MAX_MESSAGE_USERNAME_BYTES),
            direction,
            body: truncate_utf8_bytes(body, MAX_MESSAGE_BODY_BYTES),
            acknowledged: false,
            created_at: now,
            created_at_ms: now_ms,
            updated_at: now,
            source_id: None,
            source_timestamp: None,
            was_replayed: false,
        };
        self.records.push(record.clone());
        if self.records.len() > self.max_records {
            let excess = self.records.len() - self.max_records;
            self.records.drain(0..excess);
        }
        self.updated_at = now;
        record
    }

    fn allocate_id(&mut self) -> u64 {
        let mut candidate = self.next_id.max(1);
        for _ in 0..=self.records.len() {
            if !self.records.iter().any(|record| record.id == candidate) {
                self.next_id = candidate.wrapping_add(1).max(1);
                return candidate;
            }
            candidate = candidate.wrapping_add(1).max(1);
        }
        unreachable!("bounded message history must leave an available u64 id")
    }

    fn ack(&mut self, id: u64) -> Option<MessageRecord> {
        let now = unix_timestamp();
        let record = self.records.iter_mut().find(|record| record.id == id)?;
        record.acknowledged = true;
        record.updated_at = now;
        self.updated_at = now;
        Some(record.clone())
    }

    fn json(&self, query: Option<&str>) -> String {
        self.json_filtered(None, query)
    }

    fn json_for_user(&self, username: &str, query: Option<&str>) -> String {
        self.json_filtered(Some(username), query)
    }

    fn json_filtered(&self, username: Option<&str>, query: Option<&str>) -> String {
        let filter = RecordListFilter::from_query(query);
        let records = self
            .records
            .iter()
            .filter(|record| username.is_none_or(|username| record.username == username))
            .filter(|record| {
                filter
                    .username
                    .as_deref()
                    .is_none_or(|username| record.username == username)
            })
            .filter(|record| {
                filter
                    .direction
                    .as_deref()
                    .is_none_or(|direction| record.direction == direction)
            })
            .filter(|record| {
                filter.q.as_deref().is_none_or(|q| {
                    record.username.to_ascii_lowercase().contains(q)
                        || record.body.to_ascii_lowercase().contains(q)
                })
            })
            .collect::<Vec<_>>();
        let filtered_count = records.len();
        let records = records
            .into_iter()
            .skip(filter.offset)
            .take(filter.limit.unwrap_or(usize::MAX))
            .map(MessageRecord::json)
            .collect::<Vec<_>>()
            .join(",");
        format!(
            "{{\"entries\":[{}],\"count\":{},\"filtered_count\":{},\"offset\":{},\"limit\":{},\"updated_at\":{}}}",
            records,
            self.records.len(),
            filtered_count,
            filter.offset,
            json_usize_option(filter.limit),
            self.updated_at
        )
    }

    fn summary_json(&self) -> String {
        let inbound = self
            .records
            .iter()
            .filter(|record| record.direction == "inbound")
            .count();
        let outbound = self
            .records
            .iter()
            .filter(|record| record.direction == "outbound")
            .count();
        let acknowledged = self
            .records
            .iter()
            .filter(|record| record.acknowledged)
            .count();
        format!(
            "{{\"total\":{},\"inbound\":{},\"outbound\":{},\"acknowledged\":{},\"unacknowledged\":{},\"updated_at\":{}}}",
            self.records.len(),
            inbound,
            outbound,
            acknowledged,
            self.records.len().saturating_sub(acknowledged),
            self.updated_at
        )
    }

    fn slskd_conversations_json(&self, query: Option<&str>) -> String {
        let filter = RecordListFilter::from_query(query);
        let mut grouped: BTreeMap<String, Vec<&MessageRecord>> = BTreeMap::new();
        for record in &self.records {
            if filter.q.as_deref().is_some_and(|q| {
                !record.username.to_ascii_lowercase().contains(q)
                    && !record.body.to_ascii_lowercase().contains(q)
            }) {
                continue;
            }
            grouped
                .entry(record.username.clone())
                .or_default()
                .push(record);
        }
        let conversations = grouped
            .into_iter()
            .map(|(username, messages)| slskd_conversation_json(username, messages, true))
            .collect::<Vec<_>>();
        serde_json::Value::Array(conversations).to_string()
    }

    fn slskd_conversation_json(
        &self,
        username: &str,
        include_messages: bool,
        since: Option<u64>,
    ) -> String {
        let messages = self
            .records
            .iter()
            .filter(|record| record.username == username)
            .collect::<Vec<_>>();
        let mut conversation =
            slskd_conversation_json(username.to_owned(), messages.clone(), false);
        if include_messages {
            conversation["messages"] = serde_json::Value::Array(
                messages
                    .into_iter()
                    .filter(|record| since.is_none_or(|since| record.created_at_ms > since))
                    .map(MessageRecord::slskd_json)
                    .collect(),
            );
        }
        conversation.to_string()
    }

    fn slskd_messages_json(&self, username: &str, unacknowledged_only: bool) -> String {
        let messages = self
            .records
            .iter()
            .filter(|record| record.username == username)
            .filter(|record| !unacknowledged_only || !record.acknowledged)
            .map(MessageRecord::slskd_json)
            .collect::<Vec<_>>();
        serde_json::Value::Array(messages).to_string()
    }

    fn ack_all_for_user(&mut self, username: &str) -> usize {
        let now = unix_timestamp();
        let mut updated = 0;
        for record in self
            .records
            .iter_mut()
            .filter(|record| record.username == username && !record.acknowledged)
        {
            record.acknowledged = true;
            record.updated_at = now;
            updated += 1;
        }
        if updated > 0 {
            self.updated_at = now;
        }
        updated
    }

    fn has_unacknowledged_messages(&self) -> bool {
        self.records.iter().any(|record| !record.acknowledged)
    }
}

#[derive(Debug, Default)]
struct PrivateMessageAutoResponseTracker {
    sent_at: BTreeMap<String, u64>,
}

impl PrivateMessageAutoResponseTracker {
    fn should_respond(&mut self, username: &str, now: u64, cooldown_seconds: u64) -> bool {
        self.sent_at
            .retain(|_, sent_at| now.saturating_sub(*sent_at) < cooldown_seconds);
        let key = truncate_utf8_bytes(
            username.trim().to_ascii_lowercase(),
            MAX_MESSAGE_USERNAME_BYTES,
        );
        if key.is_empty()
            || self
                .sent_at
                .get(&key)
                .is_some_and(|sent_at| now.saturating_sub(*sent_at) < cooldown_seconds)
        {
            return false;
        }
        if self.sent_at.len() >= MAX_PRIVATE_MESSAGE_AUTO_RESPONSE_PEERS {
            if let Some(oldest) = self
                .sent_at
                .iter()
                .min_by_key(|(_, sent_at)| **sent_at)
                .map(|(username, _)| username.clone())
            {
                self.sent_at.remove(&oldest);
            }
        }
        self.sent_at.insert(key, now);
        true
    }

    fn release(&mut self, username: &str) {
        let key = truncate_utf8_bytes(
            username.trim().to_ascii_lowercase(),
            MAX_MESSAGE_USERNAME_BYTES,
        );
        self.sent_at.remove(&key);
    }
}

const MANAGED_BLACKLIST_DECISION_TTL_SECONDS: u64 = 10 * 60;
const MAX_MANAGED_BLACKLIST_DECISIONS: usize = 1_000;

#[derive(Debug)]
struct ManagedBlacklistRuntime {
    settings: crate::config::ManagedBlacklistSettings,
    patterns: Vec<ControllerRegex>,
    target: ControllerCompatibilityTarget,
    decisions: BTreeMap<String, (bool, u64)>,
}

#[derive(Clone, Debug)]
struct ControllerRegex {
    expression: String,
    matcher: crate::dotnet_regex::DotNetRegex,
    match_timeout: Option<Duration>,
}

impl ControllerRegex {
    fn compile_with_timeout(
        expression: &str,
        case_sensitive: bool,
        match_timeout: Option<Duration>,
    ) -> Result<Self, String> {
        let matcher = crate::dotnet_regex::DotNetRegex::compile(expression, case_sensitive)
            .map_err(|error| format!("invalid regular expression {expression:?}: {error}"))?;
        Ok(Self {
            expression: expression.to_owned(),
            matcher,
            match_timeout,
        })
    }

    fn is_match(&self, value: &str) -> bool {
        match self.match_timeout {
            Some(timeout) => self
                .matcher
                .is_match_with_timeout(value, timeout)
                .unwrap_or(false),
            None => self.matcher.is_match(value).unwrap_or(false),
        }
    }
}

const SLSKDN_REGEX_MATCH_TIMEOUT: Duration = Duration::from_millis(250);

fn controller_regex_timeout(target: ControllerCompatibilityTarget) -> Option<Duration> {
    (target == ControllerCompatibilityTarget::Slskdn).then_some(SLSKDN_REGEX_MATCH_TIMEOUT)
}

fn compile_controller_regexes(
    expressions: &[String],
    case_sensitive: bool,
    target: ControllerCompatibilityTarget,
) -> Result<Vec<ControllerRegex>, String> {
    let match_timeout = controller_regex_timeout(target);
    expressions
        .iter()
        .map(|expression| {
            ControllerRegex::compile_with_timeout(expression, case_sensitive, match_timeout)
        })
        .collect()
}

fn compile_controller_regexes_for_request(
    expressions: Vec<String>,
    case_sensitive: bool,
    target: ControllerCompatibilityTarget,
) -> Result<Vec<ControllerRegex>, String> {
    std::thread::Builder::new()
        .name("slskr-regex-compile".to_owned())
        .stack_size(16 * 1024 * 1024)
        .spawn(move || compile_controller_regexes(&expressions, case_sensitive, target))
        .map_err(|error| format!("failed to start regular-expression compilation: {error}"))?
        .join()
        .map_err(|_| "regular-expression compilation panicked".to_owned())?
}

impl ManagedBlacklistRuntime {
    fn username_is_blacklisted(&self, username: &str) -> bool {
        let member_match = match self.target {
            ControllerCompatibilityTarget::Slskd => self
                .settings
                .members
                .iter()
                .any(|member| member == username),
            ControllerCompatibilityTarget::Slskdn => self
                .settings
                .members
                .iter()
                .any(|member| member.eq_ignore_ascii_case(username)),
        };
        member_match
            || self
                .patterns
                .iter()
                .any(|pattern| pattern.is_match(username))
    }

    fn new(
        settings: crate::config::ManagedBlacklistSettings,
        target: ControllerCompatibilityTarget,
        case_sensitive_regex: bool,
    ) -> Self {
        let pattern_case_sensitive = case_sensitive_regex;
        let patterns =
            compile_controller_regexes(&settings.patterns, pattern_case_sensitive, target)
                .expect("validated blacklist patterns must compile");
        Self {
            settings,
            patterns,
            target,
            decisions: BTreeMap::new(),
        }
    }

    fn replace(
        &mut self,
        settings: crate::config::ManagedBlacklistSettings,
        target: ControllerCompatibilityTarget,
        case_sensitive_regex: bool,
    ) {
        let pattern_case_sensitive = case_sensitive_regex;
        self.patterns =
            compile_controller_regexes(&settings.patterns, pattern_case_sensitive, target)
                .expect("validated blacklist patterns must compile");
        self.settings = settings;
        self.target = target;
        self.decisions.clear();
    }

    fn is_blacklisted(
        &mut self,
        username: Option<&str>,
        address: Option<IpAddr>,
        now: u64,
    ) -> bool {
        self.decisions.retain(|_, (_, decided_at)| {
            now.saturating_sub(*decided_at) < MANAGED_BLACKLIST_DECISION_TTL_SECONDS
        });
        let key = username
            .map(str::trim)
            .filter(|username| !username.is_empty())
            .map(str::to_owned);
        if let Some(cached) = key
            .as_ref()
            .and_then(|username| self.decisions.get(username))
            .map(|(blacklisted, _)| *blacklisted)
        {
            return cached;
        }
        let blacklisted = username.is_some_and(|username| self.username_is_blacklisted(username))
            || address.is_some_and(|address| self.settings.contains(address));
        if let Some(key) = key {
            if self.decisions.len() >= MAX_MANAGED_BLACKLIST_DECISIONS {
                if let Some(oldest) = self
                    .decisions
                    .iter()
                    .min_by_key(|(_, (_, decided_at))| *decided_at)
                    .map(|(username, _)| username.clone())
                {
                    self.decisions.remove(&oldest);
                }
            }
            self.decisions.insert(key, (blacklisted, now));
        }
        blacklisted
    }
}

fn is_private_message_auto_response_candidate(message: &str) -> bool {
    if message.trim().is_empty() || message.len() > MAX_MESSAGE_BODY_BYTES {
        return false;
    }
    let normalized = message
        .split_whitespace()
        .collect::<Vec<_>>()
        .join(" ")
        .to_ascii_lowercase();
    let direct_human_check = [
        "are you human",
        "are you a human",
        "are u human",
        "are u a human",
        "r u human",
        "are you real",
        "are u real",
        "are you a bot",
        "are u a bot",
        "you human?",
        "u human?",
        "bot?",
        "human?",
    ]
    .iter()
    .any(|phrase| normalized.contains(phrase));
    if direct_human_check {
        return true;
    }

    let tokens = normalized
        .split(|character: char| !character.is_ascii_alphanumeric())
        .filter(|token| !token.is_empty())
        .collect::<HashSet<_>>();
    let has_intent = [
        "prove", "verify", "confirm", "show", "tell", "say", "reply", "respond", "answer", "type",
        "write", "pass", "solve",
    ]
    .iter()
    .any(|token| tokens.contains(token));
    let has_identity = [
        "human",
        "person",
        "real",
        "bot",
        "robot",
        "automated",
        "automation",
        "script",
        "client",
        "captcha",
    ]
    .iter()
    .any(|token| tokens.contains(token));
    let named_check = [
        "check",
        "test",
        "verification",
        "gate",
        "screen",
        "challenge",
    ]
    .iter()
    .any(|token| tokens.contains(token))
        && has_identity;
    let share_gate = [
        "not sharing",
        "no sharing",
        "share something",
        "share more",
        "share files",
        "empty share",
        "empty shares",
        "no leechers",
        "anti-leech",
        "anti leech",
    ]
    .iter()
    .any(|phrase| normalized.contains(phrase));
    named_check || (has_intent && has_identity) || share_gate
}

fn slskd_conversation_json(
    username: String,
    messages: Vec<&MessageRecord>,
    include_messages: bool,
) -> serde_json::Value {
    let unacknowledged = messages
        .iter()
        .filter(|message| !message.acknowledged)
        .count();
    let messages_json = include_messages.then(|| {
        messages
            .into_iter()
            .map(MessageRecord::slskd_json)
            .collect::<Vec<_>>()
    });
    let mut value = serde_json::json!({
        "username": username,
        "isActive": true,
        "unAcknowledgedMessageCount": unacknowledged,
        "hasUnAcknowledgedMessages": unacknowledged > 0,
    });
    if let Some(messages) = messages_json {
        value["messages"] = serde_json::Value::Array(messages);
    }
    value
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct RoomMessageRecord {
    id: u64,
    username: String,
    body: String,
    created_at: u64,
    created_at_ms: u64,
}

impl RoomMessageRecord {
    fn json(&self) -> String {
        format!(
            "{{\"id\":{},\"username\":\"{}\",\"body\":\"{}\",\"created_at\":{},\"created_at_ms\":{}}}",
            self.id,
            json_escape(&self.username),
            json_escape(&self.body),
            self.created_at,
            self.created_at_ms
        )
    }

    fn slskd_json(&self, room_name: &str) -> serde_json::Value {
        serde_json::json!({
            "id": self.id.to_string(),
            "timestamp": self.created_at.to_string(),
            "createdAtMs": self.created_at_ms,
            "username": self.username,
            "message": self.body,
            "roomName": room_name,
        })
    }
}

/// Mirrors the oracle's real `UserDataResponse` fields for a room member,
/// sourced from the server's real `JoinedRoom` roster snapshot rather than
/// a placeholder.
#[derive(Clone, Debug, PartialEq, Eq)]
struct RoomRosterEntry {
    username: String,
    status: u32,
    average_speed: u32,
    upload_count: u64,
    file_count: u32,
    directory_count: u32,
    slots_free: u32,
    country_code: String,
}

impl RoomRosterEntry {
    /// `status` matches the wire protocol's numeric UserPresence codes
    /// (0=offline, 1=away, 2=online), which the oracle serializes by enum
    /// name via a global `JsonStringEnumConverter`.
    fn slskd_json(&self, local_username: &str) -> serde_json::Value {
        serde_json::json!({
            "username": self.username,
            "status": match self.status {
                1 => "Away",
                2 => "Online",
                _ => "Offline",
            },
            "averageSpeed": self.average_speed,
            "uploadCount": self.upload_count,
            "fileCount": self.file_count,
            "directoryCount": self.directory_count,
            "slotsFree": self.slots_free,
            "countryCode": self.country_code,
            // Matches the oracle's real `Self = self ? self : (bool?)null`:
            // present-and-true only for the caller's own username, absent
            // (never `false`) otherwise.
            "self": if self.username.eq_ignore_ascii_case(local_username) {
                serde_json::Value::Bool(true)
            } else {
                serde_json::Value::Null
            },
        })
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct RoomRecord {
    name: String,
    joined: bool,
    kind: &'static str,
    user_count: Option<u32>,
    operated: bool,
    last_error: Option<String>,
    ticker: Option<String>,
    members: Vec<String>,
    roster: Vec<RoomRosterEntry>,
    messages: Vec<RoomMessageRecord>,
    updated_at: u64,
}

impl RoomRecord {
    fn json(&self) -> String {
        let messages = self
            .messages
            .iter()
            .map(RoomMessageRecord::json)
            .collect::<Vec<_>>()
            .join(",");
        format!(
            "{{\"name\":\"{}\",\"joined\":{},\"kind\":\"{}\",\"user_count\":{},\"operated\":{},\"last_error\":{},\"ticker\":{},\"members\":{},\"messages\":[{}],\"message_count\":{},\"updated_at\":{}}}",
            json_escape(&self.name),
            self.joined,
            self.kind,
            json_u32_option(self.user_count),
            self.operated,
            json_option(self.last_error.as_deref()),
            json_option(self.ticker.as_deref()),
            serde_json::to_string(&self.members).unwrap_or_else(|_| "[]".to_owned()),
            messages,
            self.messages.len(),
            self.updated_at
        )
    }

    fn slskd_info_json(&self) -> serde_json::Value {
        serde_json::json!({
            "name": self.name,
            "userCount": self.user_count.unwrap_or(0),
            "isPrivate": self.kind != "public",
            "isOwned": self.operated,
            "isModerated": self.operated,
            "lastError": self.last_error,
            "ticker": self.ticker,
            "memberCount": self.members.len(),
        })
    }

    fn slskd_room_json(&self) -> serde_json::Value {
        serde_json::json!({
            "name": self.name,
            "isPrivate": self.kind != "public",
            "users": self.members,
            "messages": self.messages.iter().map(|message| message.slskd_json(&self.name)).collect::<Vec<_>>(),
            "ticker": self.ticker,
            "lastError": self.last_error,
        })
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct RoomStore {
    records: Vec<RoomRecord>,
    next_message_id: u64,
    updated_at: u64,
    max_records: usize,
    max_members_per_room: usize,
}

impl RoomStore {
    fn new() -> Self {
        Self::with_limits(MAX_ROOM_RECORDS, MAX_ROOM_MEMBERS_PER_ROOM)
    }

    fn with_limits(max_records: usize, max_members_per_room: usize) -> Self {
        Self {
            records: Vec::new(),
            next_message_id: 1,
            updated_at: unix_timestamp(),
            max_records: max_records.max(1),
            max_members_per_room: max_members_per_room.max(1),
        }
    }

    fn from_persisted(records: Vec<crate::persistence::RoomRecord>) -> Self {
        let mut store = Self::new();
        store.records = records
            .into_iter()
            .take(store.max_records)
            .map(|record| RoomRecord {
                name: bounded_room_name(&record.name),
                joined: record.subscribed,
                kind: if record.owner.is_some() {
                    "private"
                } else {
                    "local"
                },
                user_count: None,
                operated: false,
                last_error: None,
                ticker: None,
                members: Vec::new(),
                roster: Vec::new(),
                messages: Vec::new(),
                updated_at: u64::try_from(record.last_activity).unwrap_or_default(),
            })
            .collect();
        store.updated_at = store
            .records
            .iter()
            .map(|record| record.updated_at)
            .max()
            .unwrap_or_else(unix_timestamp);
        store
    }

    fn merge_configured(&mut self, rooms: &[String]) {
        for room in rooms {
            let _ = self.join(room.clone());
        }
    }

    fn join(&mut self, name: String) -> Option<RoomRecord> {
        let name = bounded_room_name(&name);
        let now = unix_timestamp();
        if let Some(record) = self.records.iter_mut().find(|record| record.name == name) {
            record.joined = true;
            record.last_error = None;
            record.updated_at = now;
            self.updated_at = now;
            return Some(record.clone());
        }
        if self.records.len() >= self.max_records {
            return None;
        }
        let record = RoomRecord {
            name,
            joined: true,
            kind: "local",
            user_count: None,
            operated: false,
            last_error: None,
            ticker: None,
            members: Vec::new(),
            roster: Vec::new(),
            messages: Vec::new(),
            updated_at: now,
        };
        self.records.push(record.clone());
        self.updated_at = now;
        Some(record)
    }

    fn leave(&mut self, name: &str) -> Option<RoomRecord> {
        let name = bounded_room_name(name);
        let now = unix_timestamp();
        let record = self.records.iter_mut().find(|record| record.name == name)?;
        record.joined = false;
        record.updated_at = now;
        self.updated_at = now;
        Some(record.clone())
    }

    fn fail_join(&mut self, name: &str, reason: String) -> Option<RoomRecord> {
        let name = bounded_room_name(name);
        let reason = truncate_utf8_bytes(reason, MAX_ROOM_ERROR_BYTES);
        let now = unix_timestamp();
        if let Some(record) = self.records.iter_mut().find(|record| record.name == name) {
            record.joined = false;
            record.last_error = Some(reason);
            record.updated_at = now;
            self.updated_at = now;
            return Some(record.clone());
        }
        if self.records.len() >= self.max_records {
            return None;
        }
        let record = RoomRecord {
            name,
            joined: false,
            kind: "local",
            user_count: None,
            operated: false,
            last_error: Some(reason),
            ticker: None,
            members: Vec::new(),
            roster: Vec::new(),
            messages: Vec::new(),
            updated_at: now,
        };
        self.records.push(record.clone());
        self.updated_at = now;
        Some(record)
    }

    fn apply_room_list(&mut self, room_list: &RoomList) {
        for entry in &room_list.public_rooms {
            self.upsert_room_list_entry(entry, "public", false);
        }
        for entry in &room_list.owned_private_rooms {
            self.upsert_room_list_entry(entry, "owned_private", true);
        }
        for entry in &room_list.private_rooms {
            let operated = room_list
                .operated_private_rooms
                .iter()
                .any(|room| room == &entry.name);
            self.upsert_room_list_entry(entry, "private", operated);
        }
        for room in &room_list.operated_private_rooms {
            let room = bounded_room_name(room);
            if self.records.len() < self.max_records
                && !self.records.iter().any(|record| record.name == room)
            {
                let now = unix_timestamp();
                self.records.push(RoomRecord {
                    name: room,
                    joined: false,
                    kind: "operated_private",
                    user_count: None,
                    operated: true,
                    last_error: None,
                    ticker: None,
                    members: Vec::new(),
                    roster: Vec::new(),
                    messages: Vec::new(),
                    updated_at: now,
                });
                self.updated_at = now;
            }
        }
    }

    fn upsert_room_list_entry(
        &mut self,
        entry: &RoomListEntry,
        kind: &'static str,
        operated: bool,
    ) -> Option<RoomRecord> {
        let name = bounded_room_name(&entry.name);
        let now = unix_timestamp();
        if let Some(record) = self.records.iter_mut().find(|record| record.name == name) {
            record.kind = kind;
            record.user_count = Some(entry.user_count);
            record.operated = operated;
            record.last_error = None;
            record.updated_at = now;
            self.updated_at = now;
            return Some(record.clone());
        }
        if self.records.len() >= self.max_records {
            return None;
        }
        let record = RoomRecord {
            name,
            joined: false,
            kind,
            user_count: Some(entry.user_count),
            operated,
            last_error: None,
            ticker: None,
            members: Vec::new(),
            roster: Vec::new(),
            messages: Vec::new(),
            updated_at: now,
        };
        self.records.push(record.clone());
        self.updated_at = now;
        Some(record)
    }

    fn add_message(&mut self, room: &str, username: String, body: String) -> Option<RoomRecord> {
        let room = bounded_room_name(room);
        let record_index = self.records.iter().position(|record| record.name == room)?;
        while self.total_messages() >= MAX_TOTAL_ROOM_MESSAGES {
            self.evict_oldest_message()?;
        }
        let now = unix_timestamp();
        let now_ms = unix_timestamp_millis().max(
            self.records
                .iter()
                .flat_map(|record| record.messages.iter())
                .map(|message| message.created_at_ms)
                .max()
                .unwrap_or(0)
                .saturating_add(1),
        );
        let id = self.allocate_message_id();
        let record = &mut self.records[record_index];
        record.messages.push(RoomMessageRecord {
            id,
            username: truncate_utf8_bytes(username, MAX_ROOM_USERNAME_BYTES),
            body: truncate_utf8_bytes(body, MAX_ROOM_MESSAGE_BODY_BYTES),
            created_at: now,
            created_at_ms: now_ms,
        });
        if record.messages.len() > MAX_ROOM_MESSAGES_PER_ROOM {
            let excess = record.messages.len() - MAX_ROOM_MESSAGES_PER_ROOM;
            record.messages.drain(0..excess);
        }
        record.updated_at = now;
        self.updated_at = now;
        Some(record.clone())
    }

    fn allocate_message_id(&mut self) -> u64 {
        let mut candidate = self.next_message_id.max(1);
        for _ in 0..=self.total_messages() {
            if !self
                .records
                .iter()
                .flat_map(|room| room.messages.iter())
                .any(|message| message.id == candidate)
            {
                self.next_message_id = candidate.wrapping_add(1).max(1);
                return candidate;
            }
            candidate = candidate.wrapping_add(1).max(1);
        }
        unreachable!("bounded room message history must leave an available u64 id")
    }

    fn activity_json(&self, local_username: &str) -> String {
        let activity = self
            .records
            .iter()
            .filter(|room| room.joined)
            .filter_map(|room| {
                room.messages
                    .iter()
                    .rev()
                    .find(|message| message.username != local_username)
                    .map(|message| {
                        (
                            room.name.clone(),
                            serde_json::Value::from(message.created_at.saturating_mul(1_000)),
                        )
                    })
            })
            .collect::<serde_json::Map<String, serde_json::Value>>();
        serde_json::Value::Object(activity).to_string()
    }

    fn set_ticker(&mut self, room: &str, ticker: String) -> Option<RoomRecord> {
        let room = bounded_room_name(room);
        let now = unix_timestamp();
        let record = self.records.iter_mut().find(|record| record.name == room)?;
        record.ticker = Some(truncate_utf8_bytes(ticker, MAX_ROOM_TICKER_BYTES));
        record.updated_at = now;
        self.updated_at = now;
        Some(record.clone())
    }

    /// Applies the real roster snapshot from the server's `JoinedRoom`
    /// message -- matches the oracle's `IRoomTracker`, which populates the
    /// room's user list from this same message rather than leaving it
    /// empty until someone happens to join/leave afterward.
    fn apply_roster(&mut self, room: &str, roster: Vec<RoomRosterEntry>) -> Option<RoomRecord> {
        let room = bounded_room_name(room);
        let now = unix_timestamp();
        let cap = self.max_members_per_room;
        let record = self.records.iter_mut().find(|record| record.name == room)?;
        record.roster = roster.into_iter().take(cap).collect();
        record.members = record
            .roster
            .iter()
            .map(|user| user.username.clone())
            .collect();
        record.user_count = Some(u32::try_from(record.roster.len()).unwrap_or(u32::MAX));
        record.updated_at = now;
        self.updated_at = now;
        Some(record.clone())
    }

    fn add_member(&mut self, room: &str, username: String) -> Result<Option<RoomRecord>, ()> {
        let room = bounded_room_name(room);
        let now = unix_timestamp();
        let username = truncate_utf8_bytes(username.trim().to_owned(), MAX_ROOM_USERNAME_BYTES);
        if username.is_empty() {
            return Ok(None);
        }
        let total_members = self.total_members();
        let record = match self.records.iter_mut().find(|record| record.name == room) {
            Some(record) => record,
            None => return Ok(None),
        };
        if !record
            .members
            .iter()
            .any(|member| member.eq_ignore_ascii_case(&username))
        {
            if record.members.len() >= self.max_members_per_room
                || total_members >= MAX_TOTAL_ROOM_MEMBERS
            {
                return Err(());
            }
            record.members.push(username);
        }
        record.user_count = Some(u32::try_from(record.members.len()).unwrap_or(u32::MAX));
        record.updated_at = now;
        self.updated_at = now;
        Ok(Some(record.clone()))
    }

    fn remove_member(&mut self, room: &str, username: &str) -> Option<RoomRecord> {
        let room = bounded_room_name(room);
        let now = unix_timestamp();
        let record = self.records.iter_mut().find(|record| record.name == room)?;
        let member = record
            .members
            .iter()
            .position(|member| member.eq_ignore_ascii_case(username))?;
        record.members.remove(member);
        record.user_count = Some(u32::try_from(record.members.len()).unwrap_or(u32::MAX));
        record.updated_at = now;
        self.updated_at = now;
        Some(record.clone())
    }

    fn total_messages(&self) -> usize {
        self.records
            .iter()
            .map(|record| record.messages.len())
            .sum()
    }

    fn total_members(&self) -> usize {
        self.records.iter().map(|record| record.members.len()).sum()
    }

    fn evict_oldest_message(&mut self) -> Option<()> {
        let room_index = self
            .records
            .iter()
            .enumerate()
            .filter_map(|(index, record)| {
                record
                    .messages
                    .first()
                    .map(|message| (index, message.created_at))
            })
            .min_by_key(|(index, created_at)| (*created_at, *index))?
            .0;
        self.records[room_index].messages.remove(0);
        Some(())
    }

    fn json(&self, query: Option<&str>) -> String {
        let filter = RecordListFilter::from_query(query);
        let filtered_count = self
            .records
            .iter()
            .filter(|record| filter.joined.is_none_or(|joined| record.joined == joined))
            .filter(|record| {
                filter
                    .q
                    .as_deref()
                    .is_none_or(|q| record.name.to_ascii_lowercase().contains(q))
            })
            .count();
        format!(
            "{{\"entries\":{},\"count\":{},\"filtered_count\":{},\"offset\":{},\"limit\":{},\"updated_at\":{}}}",
            self.json_array(query),
            self.records.len(),
            filtered_count,
            filter.offset,
            json_usize_option(filter.limit),
            self.updated_at
        )
    }

    fn json_array(&self, query: Option<&str>) -> String {
        let filter = RecordListFilter::from_query(query);
        let records = self
            .records
            .iter()
            .filter(|record| filter.joined.is_none_or(|joined| record.joined == joined))
            .filter(|record| {
                filter
                    .q
                    .as_deref()
                    .is_none_or(|q| record.name.to_ascii_lowercase().contains(q))
            })
            .skip(filter.offset)
            .take(filter.limit.unwrap_or(usize::MAX))
            .map(RoomRecord::json)
            .collect::<Vec<_>>()
            .join(",");
        format!("[{}]", records)
    }

    fn joined_names_json(&self) -> String {
        let records = self
            .records
            .iter()
            .filter(|record| record.joined)
            .map(|record| json_option(Some(record.name.as_str())))
            .collect::<Vec<_>>()
            .join(",");
        format!("[{}]", records)
    }

    fn slskd_available_json(&self) -> String {
        serde_json::Value::Array(
            self.records
                .iter()
                .map(RoomRecord::slskd_info_json)
                .collect::<Vec<_>>(),
        )
        .to_string()
    }

    fn summary_json(&self) -> String {
        let joined = self.records.iter().filter(|record| record.joined).count();
        let messages = self
            .records
            .iter()
            .map(|record| record.messages.len())
            .sum::<usize>();
        format!(
            "{{\"total\":{},\"joined\":{},\"messages\":{},\"updated_at\":{}}}",
            self.records.len(),
            joined,
            messages,
            self.updated_at
        )
    }
}

fn bounded_room_name(name: &str) -> String {
    truncate_utf8_bytes(name.to_owned(), MAX_ROOM_NAME_BYTES)
}

// Collection Models
fn unix_seconds_rfc3339(timestamp: u64) -> String {
    chrono::DateTime::<chrono::Utc>::from_timestamp(i64::try_from(timestamp).unwrap_or(i64::MAX), 0)
        .unwrap_or(chrono::DateTime::<chrono::Utc>::UNIX_EPOCH)
        .to_rfc3339_opts(chrono::SecondsFormat::Secs, true)
}

fn bridge_started_at_string(timestamp: u64) -> String {
    chrono::DateTime::<chrono::Utc>::from_timestamp(i64::try_from(timestamp).unwrap_or(i64::MAX), 0)
        .unwrap_or(chrono::DateTime::<chrono::Utc>::UNIX_EPOCH)
        .to_rfc3339()
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct CollectionItem {
    id: String,
    content_id: String,
    artist: String,
    title: String,
    kind: String,
    file_name: String,
    album: String,
    content_hash: String,
    added_at: u64,
}

impl CollectionItem {
    fn json(&self) -> String {
        format!(
            "{{\"id\":\"{}\",\"contentId\":\"{}\",\"content_id\":\"{}\",\"artist\":\"{}\",\"title\":\"{}\",\"fileName\":\"{}\",\"mediaKind\":\"{}\",\"kind\":\"{}\",\"addedAt\":{},\"added_at\":{}}}",
            json_escape(&self.id),
            json_escape(&self.content_id),
            json_escape(&self.content_id),
            json_escape(&self.artist),
            json_escape(&self.title),
            json_escape(if self.file_name.is_empty() { &self.title } else { &self.file_name }),
            json_escape(&self.kind),
            json_escape(&self.kind),
            self.added_at,
            self.added_at
        )
    }

    fn slskdn_json(&self, collection_id: &str, ordinal: usize) -> String {
        serde_json::json!({
            "id": self.id,
            "collectionId": collection_id,
            "ordinal": ordinal,
            "contentId": self.content_id,
            "mediaKind": (!self.kind.is_empty()).then_some(self.kind.as_str()),
            "fileName": (!self.file_name.is_empty()).then_some(self.file_name.as_str()),
            "title": (!self.title.is_empty()).then_some(self.title.as_str()),
            "artist": (!self.artist.is_empty()).then_some(self.artist.as_str()),
            "album": (!self.album.is_empty()).then_some(self.album.as_str()),
            "contentHash": (!self.content_hash.is_empty()).then_some(self.content_hash.as_str()),
        })
        .to_string()
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct CollectionRecord {
    id: String,
    owner_user_id: String,
    name: String,
    description: String,
    collection_type: String,
    items: Vec<CollectionItem>,
    created_at: u64,
    updated_at: u64,
}

impl CollectionRecord {
    fn json(&self) -> String {
        let items = self
            .items
            .iter()
            .map(CollectionItem::json)
            .collect::<Vec<_>>()
            .join(",");
        format!(
            "{{\"id\":\"{}\",\"title\":\"{}\",\"name\":\"{}\",\"type\":\"ShareList\",\"description\":\"{}\",\"items\":[{}],\"itemCount\":{},\"item_count\":{},\"createdAt\":{},\"created_at\":{},\"updatedAt\":{},\"updated_at\":{}}}",
            json_escape(&self.id),
            json_escape(&self.name),
            json_escape(&self.name),
            json_escape(&self.description),
            items,
            self.items.len(),
            self.items.len(),
            self.created_at,
            self.created_at,
            self.updated_at,
            self.updated_at
        )
    }

    fn slskdn_json(&self) -> String {
        serde_json::json!({
            "id": self.id,
            "ownerUserId": self.owner_user_id,
            "title": self.name,
            "description": (!self.description.is_empty()).then_some(self.description.as_str()),
            "type": self.collection_type,
            "createdAt": unix_seconds_rfc3339(self.created_at),
            "updatedAt": unix_seconds_rfc3339(self.updated_at),
        })
        .to_string()
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct CollectionStore {
    records: Vec<CollectionRecord>,
    next_id: u64,
    next_item_id: u64,
    updated_at: u64,
    max_records: usize,
    max_items_per_collection: usize,
}

#[allow(dead_code)]
impl CollectionStore {
    fn new() -> Self {
        Self::with_limits(MAX_COLLECTIONS, MAX_COLLECTION_ITEMS)
    }

    fn with_limits(max_records: usize, max_items_per_collection: usize) -> Self {
        Self {
            records: Vec::new(),
            next_id: 1,
            next_item_id: 1,
            updated_at: unix_timestamp(),
            max_records: max_records.max(1),
            max_items_per_collection: max_items_per_collection.max(1),
        }
    }

    fn from_persisted(
        collections: Vec<crate::persistence::CollectionRecord>,
        items: Vec<crate::persistence::CollectionItemRecord>,
    ) -> Self {
        let mut next_id = 1;
        let mut next_item_id = 1;
        let mut updated_at = unix_timestamp();
        let mut records = Vec::new();
        let mut retained_items = 0_usize;
        let mut seen_collection_ids = HashSet::new();
        for record in collections {
            if let Some(number) = record
                .id
                .strip_prefix("col-")
                .and_then(|value| value.parse::<u64>().ok())
            {
                next_id = next_id.max(number.saturating_add(1));
            }
            if records.len() < MAX_COLLECTIONS && seen_collection_ids.insert(record.id.clone()) {
                let created_at = u64::try_from(record.created_at).unwrap_or(0);
                let record_updated_at = u64::try_from(record.updated_at).unwrap_or(created_at);
                updated_at = updated_at.max(record_updated_at);
                records.push(CollectionRecord {
                    id: record.id,
                    owner_user_id: record.owner_user_id,
                    name: truncate_utf8_bytes(record.name, MAX_LIST_NAME_BYTES),
                    description: truncate_utf8_bytes(
                        record.description,
                        MAX_LIST_DESCRIPTION_BYTES,
                    ),
                    collection_type: record.collection_type,
                    items: Vec::new(),
                    created_at,
                    updated_at: record_updated_at,
                });
            }
        }
        let mut items = items;
        items.sort_by_key(|item| (item.collection_id.clone(), item.position, item.added_at));
        let mut seen_item_ids = HashSet::new();
        for item in items {
            if let Some(number) = item
                .id
                .strip_prefix("item-")
                .and_then(|value| value.parse::<u64>().ok())
            {
                next_item_id = next_item_id.max(number.saturating_add(1));
            }
            if !seen_item_ids.insert(item.id.clone()) {
                continue;
            }
            let Some(collection) = records
                .iter_mut()
                .find(|record| record.id == item.collection_id)
            else {
                continue;
            };
            if collection.items.len() >= MAX_COLLECTION_ITEMS
                || retained_items >= MAX_TOTAL_COLLECTION_ITEMS
            {
                continue;
            }
            collection
                .items
                .push(bounded_collection_item(CollectionItem {
                    id: item.id,
                    content_id: item.content_id,
                    artist: item.artist,
                    title: item.title,
                    kind: item.kind,
                    file_name: item.file_name,
                    album: item.album,
                    content_hash: item.content_hash,
                    added_at: u64::try_from(item.added_at).unwrap_or(0),
                }));
            retained_items = retained_items.saturating_add(1);
        }
        Self {
            records,
            next_id,
            next_item_id,
            updated_at,
            max_records: MAX_COLLECTIONS,
            max_items_per_collection: MAX_COLLECTION_ITEMS,
        }
    }

    fn create(
        &mut self,
        owner_user_id: String,
        name: String,
        description: String,
    ) -> Option<CollectionRecord> {
        let id = format!("col-{}", self.allocate_id());
        self.create_with_contract(id, owner_user_id, name, description, "ShareList".to_owned())
    }

    fn create_with_contract(
        &mut self,
        id: String,
        owner_user_id: String,
        name: String,
        description: String,
        collection_type: String,
    ) -> Option<CollectionRecord> {
        if self.records.len() >= self.max_records {
            return None;
        }
        let now = unix_timestamp();
        let record = CollectionRecord {
            id,
            owner_user_id: truncate_utf8_bytes(owner_user_id, MAX_LIST_NAME_BYTES),
            name: truncate_utf8_bytes(name, MAX_LIST_NAME_BYTES),
            description: truncate_utf8_bytes(description, MAX_LIST_DESCRIPTION_BYTES),
            collection_type,
            items: Vec::new(),
            created_at: now,
            updated_at: now,
        };
        self.records.push(record.clone());
        self.updated_at = now;
        Some(record)
    }

    fn get(&self, id: &str) -> Option<CollectionRecord> {
        self.records.iter().find(|r| r.id == id).cloned()
    }

    fn update(&mut self, id: &str, name: String, description: String) -> Option<CollectionRecord> {
        let now = unix_timestamp();
        let record = self.records.iter_mut().find(|r| r.id == id)?;
        record.name = truncate_utf8_bytes(name, MAX_LIST_NAME_BYTES);
        record.description = truncate_utf8_bytes(description, MAX_LIST_DESCRIPTION_BYTES);
        record.updated_at = now;
        self.updated_at = now;
        Some(record.clone())
    }

    fn update_contract(
        &mut self,
        id: &str,
        name: Option<String>,
        description: Option<String>,
        collection_type: Option<String>,
    ) -> Option<CollectionRecord> {
        let now = unix_timestamp();
        let record = self.records.iter_mut().find(|record| record.id == id)?;
        if let Some(name) = name {
            record.name = truncate_utf8_bytes(name, MAX_LIST_NAME_BYTES);
        }
        if let Some(description) = description {
            record.description = truncate_utf8_bytes(description, MAX_LIST_DESCRIPTION_BYTES);
        }
        if let Some(collection_type) = collection_type {
            record.collection_type = collection_type;
        }
        record.updated_at = now;
        self.updated_at = now;
        Some(record.clone())
    }

    fn delete(&mut self, id: &str) -> bool {
        if let Some(pos) = self.records.iter().position(|r| r.id == id) {
            self.records.remove(pos);
            self.updated_at = unix_timestamp();
            true
        } else {
            false
        }
    }

    #[cfg(any(test, feature = "bounded-differential"))]
    fn add_item(
        &mut self,
        collection_id: &str,
        content_id: String,
        artist: String,
        title: String,
        kind: String,
    ) -> Result<Option<CollectionItem>, ()> {
        self.add_item_with_contract(
            collection_id,
            None,
            content_id,
            artist,
            title,
            kind,
            String::new(),
            String::new(),
            String::new(),
        )
    }

    #[allow(clippy::too_many_arguments)]
    fn add_item_with_contract(
        &mut self,
        collection_id: &str,
        id: Option<String>,
        content_id: String,
        artist: String,
        title: String,
        kind: String,
        file_name: String,
        album: String,
        content_hash: String,
    ) -> Result<Option<CollectionItem>, ()> {
        let now = unix_timestamp();
        let Some(index) = self.records.iter().position(|r| r.id == collection_id) else {
            return Ok(None);
        };
        if self.records[index].items.len() >= self.max_items_per_collection
            || self.total_items() >= MAX_TOTAL_COLLECTION_ITEMS
        {
            return Err(());
        }
        let id = id.unwrap_or_else(|| format!("item-{}", self.allocate_item_id()));
        let item = bounded_collection_item(CollectionItem {
            id,
            content_id,
            artist,
            title,
            kind,
            file_name,
            album,
            content_hash,
            added_at: now,
        });
        let record = &mut self.records[index];
        record.items.push(item.clone());
        record.updated_at = now;
        self.updated_at = now;
        Ok(Some(item))
    }

    fn allocate_id(&mut self) -> u64 {
        let mut candidate = self.next_id.max(1);
        for _ in 0..=self.records.len() {
            let id = format!("col-{candidate}");
            if !self.records.iter().any(|record| record.id == id) {
                self.next_id = candidate.wrapping_add(1).max(1);
                return candidate;
            }
            candidate = candidate.wrapping_add(1).max(1);
        }
        unreachable!("bounded collection store must leave an available u64 id")
    }

    fn allocate_item_id(&mut self) -> u64 {
        let retained_items = self
            .records
            .iter()
            .map(|record| record.items.len())
            .sum::<usize>();
        let mut candidate = self.next_item_id.max(1);
        for _ in 0..=retained_items {
            let id = format!("item-{candidate}");
            if !self
                .records
                .iter()
                .flat_map(|record| &record.items)
                .any(|item| item.id == id)
            {
                self.next_item_id = candidate.wrapping_add(1).max(1);
                return candidate;
            }
            candidate = candidate.wrapping_add(1).max(1);
        }
        unreachable!("bounded collection items must leave an available u64 id")
    }

    fn update_item(
        &mut self,
        item_id: &str,
        artist: Option<String>,
        title: Option<String>,
        kind: Option<String>,
    ) -> Option<CollectionItem> {
        let now = unix_timestamp();
        for record in &mut self.records {
            if let Some(item) = record.items.iter_mut().find(|item| item.id == item_id) {
                if let Some(artist) = artist {
                    item.artist = truncate_utf8_bytes(artist, MAX_LIST_ARTIST_BYTES);
                }
                if let Some(title) = title {
                    item.title = truncate_utf8_bytes(title, MAX_LIST_TITLE_BYTES);
                }
                if let Some(kind) = kind {
                    item.kind = truncate_utf8_bytes(kind, MAX_LIST_KIND_BYTES);
                }
                record.updated_at = now;
                self.updated_at = now;
                return Some(item.clone());
            }
        }
        None
    }

    #[allow(clippy::too_many_arguments)]
    fn update_item_contract(
        &mut self,
        item_id: &str,
        content_id: Option<String>,
        artist: Option<String>,
        title: Option<String>,
        kind: Option<String>,
        file_name: Option<String>,
        album: Option<String>,
        content_hash: Option<String>,
    ) -> Option<CollectionItem> {
        let now = unix_timestamp();
        for record in &mut self.records {
            if let Some(item) = record.items.iter_mut().find(|item| item.id == item_id) {
                if let Some(content_id) = content_id {
                    if content_id.trim().is_empty() {
                        return None;
                    }
                    item.content_id = truncate_utf8_bytes(content_id, MAX_LIST_CONTENT_ID_BYTES);
                }
                if let Some(artist) = artist {
                    item.artist = truncate_utf8_bytes(artist, MAX_LIST_ARTIST_BYTES);
                }
                if let Some(title) = title {
                    item.title = truncate_utf8_bytes(title, MAX_LIST_TITLE_BYTES);
                }
                if let Some(kind) = kind {
                    item.kind = truncate_utf8_bytes(kind, MAX_LIST_KIND_BYTES);
                }
                if let Some(file_name) = file_name {
                    item.file_name = truncate_utf8_bytes(file_name, MAX_LIST_TITLE_BYTES);
                }
                if let Some(album) = album {
                    item.album = truncate_utf8_bytes(album, MAX_LIST_TITLE_BYTES);
                }
                if let Some(content_hash) = content_hash {
                    item.content_hash =
                        truncate_utf8_bytes(content_hash, MAX_LIST_CONTENT_ID_BYTES);
                }
                record.updated_at = now;
                self.updated_at = now;
                return Some(item.clone());
            }
        }
        None
    }

    fn remove_item(&mut self, item_id: &str) -> Option<CollectionItem> {
        let now = unix_timestamp();
        for record in &mut self.records {
            if let Some(pos) = record.items.iter().position(|item| item.id == item_id) {
                let item = record.items.remove(pos);
                record.updated_at = now;
                self.updated_at = now;
                return Some(item);
            }
        }
        None
    }

    fn collection_id_for_item(&self, item_id: &str) -> Option<String> {
        self.records
            .iter()
            .find(|record| record.items.iter().any(|item| item.id == item_id))
            .map(|record| record.id.clone())
    }

    fn total_items(&self) -> usize {
        self.records.iter().map(|record| record.items.len()).sum()
    }

    fn reorder_items(&mut self, collection_id: &str, body: &str) -> Option<CollectionRecord> {
        let now = unix_timestamp();
        let record = self
            .records
            .iter_mut()
            .find(|record| record.id == collection_id)?;
        let payload = serde_json::from_str::<serde_json::Value>(body).ok();
        let ids = payload
            .as_ref()
            .and_then(|value| {
                value
                    .get("item_ids")
                    .or_else(|| value.get("itemIds"))
                    .or_else(|| value.get("items"))
            })
            .and_then(serde_json::Value::as_array)
            .map(|array| {
                array
                    .iter()
                    .filter_map(serde_json::Value::as_str)
                    .map(str::to_owned)
                    .collect::<Vec<_>>()
            })
            .unwrap_or_default();
        if !ids.is_empty() {
            let mut ordered = Vec::new();
            for id in &ids {
                if let Some(pos) = record.items.iter().position(|item| item.id == *id) {
                    ordered.push(record.items.remove(pos));
                }
            }
            ordered.append(&mut record.items);
            record.items = ordered;
        }
        record.updated_at = now;
        self.updated_at = now;
        Some(record.clone())
    }

    #[allow(dead_code)]
    fn json(&self, query: Option<&str>) -> String {
        let filter = RecordListFilter::from_query(query);
        let filtered_count = self
            .records
            .iter()
            .filter(|record| {
                filter
                    .q
                    .as_deref()
                    .is_none_or(|q| record.name.to_ascii_lowercase().contains(q))
            })
            .count();
        format!(
            "{{\"entries\":{},\"count\":{},\"filtered_count\":{},\"offset\":{},\"limit\":{},\"updated_at\":{}}}",
            self.json_array(query, None),
            self.records.len(),
            filtered_count,
            filter.offset,
            json_usize_option(filter.limit),
            self.updated_at
        )
    }

    /// `caller_id` matches the oracle's real `GetCollectionsByOwnerAsync`
    /// scoping: when a real per-caller identity is resolvable, only that
    /// caller's own collections are visible. `None` (no resolvable
    /// identity, e.g. the common single-operator `auth_required=false`
    /// deployment) preserves the unrestricted behavior every collection
    /// visible to every caller.
    fn json_array(&self, query: Option<&str>, caller_id: Option<&str>) -> String {
        let filter = RecordListFilter::from_query(query);
        let records = self
            .records
            .iter()
            .filter(|record| !collection_owner_forbids(caller_id, &record.owner_user_id))
            .filter(|record| {
                filter
                    .q
                    .as_deref()
                    .is_none_or(|q| record.name.to_ascii_lowercase().contains(q))
            })
            .skip(filter.offset)
            .take(filter.limit.unwrap_or(usize::MAX))
            .map(CollectionRecord::json)
            .collect::<Vec<_>>()
            .join(",");
        format!("[{}]", records)
    }
}

/// Matches the oracle's real per-owner Collections/Share-Grants scoping:
/// a caller with a real resolvable identity (`Some`) may not see/mutate a
/// resource owned by a *different* real identity. An empty
/// `owner_user_id` (legacy data, or created before any per-caller
/// identity existed) and a `None` caller (no resolvable identity at all)
/// both preserve today's unrestricted behavior.
fn collection_owner_forbids(caller_id: Option<&str>, owner_user_id: &str) -> bool {
    caller_id.is_some_and(|caller_id| !owner_user_id.is_empty() && owner_user_id != caller_id)
}

/// Matches the oracle's real Share-Grants ownership gate (SharesController.cs):
/// a share grant is owned transitively through its collection, so every
/// grant action checks `collection.OwnerUserId == currentUserId`, treating
/// a mismatch identically to the collection/grant not existing (`NotFound`).
async fn share_grant_collection_forbids(
    state: &AppState,
    collection_id: &str,
    caller_id: Option<&str>,
) -> bool {
    state
        .collections
        .read()
        .await
        .get(collection_id)
        .is_some_and(|collection| collection_owner_forbids(caller_id, &collection.owner_user_id))
}

fn bounded_collection_item(mut item: CollectionItem) -> CollectionItem {
    item.content_id = truncate_utf8_bytes(item.content_id, MAX_LIST_CONTENT_ID_BYTES);
    item.artist = truncate_utf8_bytes(item.artist, MAX_LIST_ARTIST_BYTES);
    item.title = truncate_utf8_bytes(item.title, MAX_LIST_TITLE_BYTES);
    item.kind = truncate_utf8_bytes(item.kind, MAX_LIST_KIND_BYTES);
    item.file_name = truncate_utf8_bytes(item.file_name, MAX_LIST_TITLE_BYTES);
    item.album = truncate_utf8_bytes(item.album, MAX_LIST_TITLE_BYTES);
    item.content_hash = truncate_utf8_bytes(item.content_hash, MAX_LIST_CONTENT_ID_BYTES);
    item
}

fn collection_items_id(path: &str) -> Option<&str> {
    let path = path.strip_prefix("/api/collections/")?;
    let id = path.strip_suffix("/items")?;
    (!id.is_empty() && !id.contains('/')).then_some(id)
}

/// Accept both slskR's historical flat item action path and the current
/// upstream contract's collection-scoped item action path. The optional
/// collection id is checked by the dispatcher after resolving the item so a
/// valid item cannot be mutated through the wrong collection URL.
fn collection_item_action_ids(path: &str) -> Option<(&str, Option<&str>)> {
    let path = path.strip_prefix("/api/collections/")?;
    if let Some(item_id) = path.strip_prefix("items/") {
        return (!item_id.is_empty() && !item_id.contains('/')).then_some((item_id, None));
    }
    let (collection_id, item_id) = path.split_once("/items/")?;
    if collection_id.is_empty()
        || item_id.is_empty()
        || collection_id.contains('/')
        || item_id.contains('/')
    {
        return None;
    }
    Some((item_id, Some(collection_id)))
}

