async fn controller_slskd_user_read_failure_response(
    state: &AppState,
    route_path: &str,
    username: &str,
    browse: bool,
) -> Option<HttpResponse> {
    if state.config.controller_compatibility_target != ControllerCompatibilityTarget::Slskd
        || !route_path.starts_with("/api/v0/")
        || state.session.read().await.state == "connected"
    {
        return None;
    }

    let tracked = if browse {
        state
            .browse
            .read()
            .await
            .records
            .iter()
            .any(|record| record.username == username)
    } else {
        state
            .users
            .read()
            .await
            .records
            .iter()
            .any(|record| record.username == username)
    };
    tracked.then(|| routing::internal_server_error_response("user service unavailable"))
}

