fn slskdn_adversarial_yaml_update(
    current: &str,
    payload: &serde_json::Value,
) -> Result<String, String> {
    let object = payload
        .as_object()
        .ok_or_else(|| "Settings cannot be null".to_owned())?;
    let default_yaml = SLSKDN_DEFAULT_ADVERSARIAL_YAML.replace("__SLSKDN_EMPTY__", "");
    let mut rendered = default_yaml
        .trim_end_matches(['\r', '\n'])
        .strip_suffix("...")
        .unwrap_or(&default_yaml)
        .trim_end_matches(['\r', '\n'])
        .lines()
        .map(str::to_owned)
        .collect::<Vec<_>>();
    apply_slskdn_adversarial_json_object(
        &mut rendered,
        &["security".to_owned(), "adversarial".to_owned()],
        object,
    );

    let mut current_lines = current
        .trim_end_matches(['\r', '\n'])
        .lines()
        .map(str::to_owned)
        .collect::<Vec<_>>();
    if current_lines
        .last()
        .is_some_and(|line| line.trim() == "...")
    {
        current_lines.pop();
    }
    while current_lines.last().is_some_and(|line| line.is_empty()) {
        current_lines.pop();
    }

    let security_index = current_lines.iter().position(|line| line == "security:");
    let rendered_adversarial = rendered.iter().skip(1).cloned().collect::<Vec<_>>();
    match security_index {
        None => {
            current_lines.extend(rendered);
        }
        Some(security_index) => {
            let security_end = current_lines
                .iter()
                .enumerate()
                .skip(security_index + 1)
                .find(|(_, line)| !line.is_empty() && yaml_indentation(line) == 0)
                .map(|(index, _)| index)
                .unwrap_or(current_lines.len());
            let adversarial_index = current_lines
                .iter()
                .enumerate()
                .take(security_end)
                .skip(security_index + 1)
                .find(|(_, line)| *line == "  adversarial:")
                .map(|(index, _)| index);
            if let Some(adversarial_index) = adversarial_index {
                let adversarial_end = current_lines
                    .iter()
                    .enumerate()
                    .take(security_end)
                    .skip(adversarial_index + 1)
                    .find(|(_, line)| !line.is_empty() && yaml_indentation(line) <= 2)
                    .map(|(index, _)| index)
                    .unwrap_or(security_end);
                current_lines.splice(adversarial_index..adversarial_end, rendered_adversarial);
            } else {
                current_lines.splice(security_end..security_end, rendered_adversarial);
            }
        }
    }
    let mut output = current_lines.join("\n");
    output.push_str("\n...\n");
    Ok(output)
}

fn yaml_indentation(line: &str) -> usize {
    line.bytes().take_while(|byte| *byte == b' ').count()
}

fn apply_slskdn_adversarial_json_object(
    lines: &mut Vec<String>,
    parent_path: &[String],
    object: &serde_json::Map<String, serde_json::Value>,
) {
    for (key, value) in object {
        let mut path = parent_path.to_vec();
        path.push(camel_to_snake_case(key));
        match value {
            serde_json::Value::Object(nested) if nested.is_empty() => {}
            serde_json::Value::Object(nested) => {
                if !replace_slskdn_yaml_value(lines, &path, value) {
                    apply_slskdn_adversarial_json_object(lines, &path, nested);
                }
            }
            _ => {
                replace_slskdn_yaml_value(lines, &path, value);
            }
        }
    }
}

fn replace_slskdn_yaml_value(
    lines: &mut Vec<String>,
    target_path: &[String],
    value: &serde_json::Value,
) -> bool {
    let mut stack = Vec::<(usize, String)>::new();
    for index in 0..lines.len() {
        let line = &lines[index];
        let trimmed = line.trim_start();
        if trimmed.is_empty() || trimmed.starts_with('-') || matches!(trimmed, "---" | "...") {
            continue;
        }
        let Some((key, _)) = trimmed.split_once(':') else {
            continue;
        };
        let indentation = yaml_indentation(line);
        while stack
            .last()
            .is_some_and(|(ancestor_indentation, _)| *ancestor_indentation >= indentation)
        {
            stack.pop();
        }
        let mut path = stack.iter().map(|(_, key)| key.clone()).collect::<Vec<_>>();
        path.push(key.to_owned());
        if path == target_path {
            if value.is_object()
                && lines
                    .iter()
                    .skip(index + 1)
                    .find(|candidate| !candidate.trim().is_empty())
                    .is_some_and(|candidate| yaml_indentation(candidate) > indentation)
            {
                return false;
            }
            let end = lines
                .iter()
                .enumerate()
                .skip(index + 1)
                .find(|(_, candidate)| {
                    let candidate = candidate.as_str();
                    !candidate.trim().is_empty()
                        && !candidate.trim_start().starts_with('-')
                        && yaml_indentation(candidate) <= indentation
                })
                .map(|(end, _)| end)
                .unwrap_or(lines.len());
            let replacement = slskdn_yaml_value_lines(key, indentation, target_path, value);
            lines.splice(index..end, replacement);
            return true;
        }
        stack.push((indentation, key.to_owned()));
    }
    false
}

fn slskdn_yaml_value_lines(
    key: &str,
    indentation: usize,
    path: &[String],
    value: &serde_json::Value,
) -> Vec<String> {
    let prefix = " ".repeat(indentation);
    match value {
        serde_json::Value::Array(values) if values.is_empty() => {
            vec![format!("{prefix}{key}: []")]
        }
        serde_json::Value::Array(values) => {
            let mut output = vec![format!("{prefix}{key}:")];
            output.extend(values.iter().map(|value| {
                format!(
                    "{prefix}- {}",
                    slskdn_yaml_scalar(path, value).unwrap_or_default()
                )
            }));
            output
        }
        serde_json::Value::Object(object) if object.is_empty() => {
            vec![format!("{prefix}{key}: {{}}")]
        }
        serde_json::Value::Object(object) => {
            let mut output = vec![format!("{prefix}{key}:")];
            for (child_key, child_value) in object {
                let child_key = camel_to_snake_case(child_key);
                let child_path = path
                    .iter()
                    .cloned()
                    .chain(std::iter::once(child_key.clone()))
                    .collect::<Vec<_>>();
                output.extend(slskdn_yaml_value_lines(
                    &child_key,
                    indentation + 2,
                    &child_path,
                    child_value,
                ));
            }
            output
        }
        _ => vec![format!(
            "{prefix}{key}: {}",
            slskdn_yaml_scalar(path, value).unwrap_or_default()
        )],
    }
}

fn slskdn_yaml_scalar(path: &[String], value: &serde_json::Value) -> Option<String> {
    match value {
        serde_json::Value::Null => Some(String::new()),
        serde_json::Value::Bool(value) => Some(value.to_string()),
        serde_json::Value::Number(value) => Some(value.to_string()),
        serde_json::Value::String(value) => {
            let enum_value = if path.last().is_some_and(|key| {
                matches!(
                    key.as_str(),
                    "profile" | "mode" | "primary_transport" | "isolation_method"
                )
            }) || path.last().is_some_and(|key| key == "preference_order")
            {
                [
                    "Disabled",
                    "Standard",
                    "Enhanced",
                    "Maximum",
                    "Custom",
                    "Direct",
                    "Tor",
                    "I2P",
                    "RelayOnly",
                    "Auto",
                    "WebSocket",
                    "HttpTunnel",
                    "Obfs4",
                    "Meek",
                    "DirectQuic",
                    "TorOnionQuic",
                    "I2PQuic",
                    "SocksAuth",
                ]
                .into_iter()
                .find(|candidate| candidate.eq_ignore_ascii_case(value))
                .unwrap_or(value)
            } else {
                value
            };
            if enum_value.is_empty() {
                Some("''".to_owned())
            } else if enum_value.starts_with([
                '-', '?', ':', '!', '&', '*', '#', '{', '}', '[', ']', ',', '|', '>', '@', '`',
            ]) || enum_value.ends_with(char::is_whitespace)
                || enum_value.starts_with(char::is_whitespace)
                || enum_value.contains(": ")
                || enum_value.contains(" #")
                || matches!(
                    enum_value.to_ascii_lowercase().as_str(),
                    "true" | "false" | "null" | "~"
                )
                || enum_value.parse::<f64>().is_ok()
            {
                Some(format!("'{}'", enum_value.replace('\'', "''")))
            } else {
                Some(enum_value.to_owned())
            }
        }
        serde_json::Value::Array(_) | serde_json::Value::Object(_) => None,
    }
}

fn validate_slskdn_adversarial_settings(payload: &serde_json::Value) -> Result<(), &'static str> {
    let bucket_sizes = payload
        .pointer("/privacy/padding/bucketSizes")
        .or_else(|| payload.pointer("/privacy/padding/bucket_sizes"));
    if bucket_sizes
        .and_then(serde_json::Value::as_array)
        .is_some_and(|values| values.iter().any(|value| value.as_i64().unwrap_or(0) <= 0))
    {
        return Err("Bucket sizes must be positive");
    }
    Ok(())
}

async fn apply_controller_yaml_upload(body: &str, state: &AppState) -> HttpResponse {
    let text = match slskd_options_config_body(body) {
        Ok(text) => text,
        Err(error) => return routing::bad_request_response(&error),
    };
    if text.len() > MAX_CONTROLLER_YAML_BYTES {
        return HttpResponse {
            status: "413 Payload Too Large",
            content_type: "application/json",
            body: serde_json::json!("YAML is too large").to_string(),
        };
    }
    let parsed = match parse_controller_yaml(&text) {
        Ok(parsed) => parsed,
        Err(error) => return routing::bad_request_response(&error),
    };
    if let Some(error) = controller_yaml_target_validation_error(
        &parsed,
        state.config.controller_compatibility_target,
    ) {
        return HttpResponse {
            status: "400 Bad Request",
            content_type: "application/json; charset=utf-8",
            body: serde_json::Value::String(error).to_string(),
        };
    }
    if let Err(error) = write_controller_compatibility_yaml(&state.config, &text) {
        eprintln!("configuration update failed: {error}");
        return routing::internal_server_error_response("Failed to update configuration file");
    }
    apply_watched_controller_configuration(state, Some(&text), &state.controller_cli_environment)
        .await;
    if effective_controller_no_config_watch(state) {
        state.runtime.write().await.set_restart_requested(true);
    }
    record_event(
        state,
        "options.yaml.updated",
        "options/yaml",
        Some(format!("bytes={}", text.len())),
    )
    .await;
    HttpResponse {
        status: "200 OK",
        content_type: "",
        body: String::new(),
    }
}

fn slskd_options_config_validate_response(
    body: &str,
    target: ControllerCompatibilityTarget,
) -> Result<HttpResponse, String> {
    let text = slskd_options_config_body(body)?;
    let parsed = parse_controller_yaml(&text);
    let parse_failed = parsed.is_err();
    let validation = parsed
        .as_ref()
        .err()
        .cloned()
        .or_else(|| controller_yaml_target_validation_error(parsed.as_ref().ok()?, target));
    let (content_type, body) = match validation {
        None => ("", String::new()),
        Some(error) => {
            let error = if target == ControllerCompatibilityTarget::Slskd
                && parse_failed
                && text.trim_start().starts_with("web:")
            {
                "No node deserializer was able to deserialize the node into type slskd.Options+WebOptions, slskd, Version=1.0.0.0, Culture=neutral, PublicKeyToken=null".to_owned()
            } else {
                error
            };
            (
                "application/json; charset=utf-8",
                serde_json::Value::String(error).to_string(),
            )
        }
    };
    Ok(HttpResponse {
        status: "200 OK",
        content_type,
        body,
    })
}

fn json_object_field_ci<'a>(
    object: &'a serde_json::Map<String, serde_json::Value>,
    name: &str,
) -> Option<&'a serde_json::Value> {
    object
        .iter()
        .find(|(key, _)| key.eq_ignore_ascii_case(name))
        .map(|(_, value)| value)
}

fn options_model_binding_problem_response() -> HttpResponse {
    HttpResponse {
        status: "400 Bad Request",
        content_type: "application/json; charset=utf-8",
        body: r#"{"title":"One or more validation errors occurred.","status":400,"detail":"The request is invalid.","errors":{}}"#.to_owned(),
    }
}

fn normalize_controller_options_overlay(
    body: &str,
    target: ControllerCompatibilityTarget,
) -> Result<serde_json::Value, String> {
    let payload = serde_json::from_str::<serde_json::Value>(body)
        .map_err(|_| "Invalid options overlay".to_owned())?;
    let object = payload
        .as_object()
        .ok_or_else(|| "Options overlay is required".to_owned())?;
    let mut normalized = serde_json::Map::new();

    if let Some(soulseek) = json_object_field_ci(object, "soulseek") {
        let soulseek = soulseek
            .as_object()
            .ok_or_else(|| "Invalid options overlay".to_owned())?;
        let mut normalized_soulseek = serde_json::Map::new();
        if let Some(address) = json_object_field_ci(soulseek, "listenIpAddress") {
            let address = address
                .as_str()
                .filter(|value| value.parse::<IpAddr>().is_ok())
                .ok_or_else(|| "Invalid options overlay".to_owned())?;
            normalized_soulseek.insert(
                "listenIpAddress".to_owned(),
                serde_json::Value::String(address.to_owned()),
            );
        }
        if let Some(port) = json_object_field_ci(soulseek, "listenPort") {
            let port = port
                .as_u64()
                .filter(|port| (1024..=65535).contains(port))
                .ok_or_else(|| "Invalid options overlay".to_owned())?;
            normalized_soulseek.insert("listenPort".to_owned(), serde_json::json!(port));
        }
        if target == ControllerCompatibilityTarget::Slskdn {
            if let Some(auto_response) =
                json_object_field_ci(soulseek, "privateMessageAutoResponse")
            {
                let auto_response = auto_response
                    .as_object()
                    .ok_or_else(|| "Invalid options overlay".to_owned())?;
                if let Some(enabled) = json_object_field_ci(auto_response, "enabled") {
                    let enabled = enabled
                        .as_bool()
                        .ok_or_else(|| "Invalid options overlay".to_owned())?;
                    normalized_soulseek.insert(
                        "privateMessageAutoResponse".to_owned(),
                        serde_json::json!({"enabled": enabled}),
                    );
                }
            }
        }
        if !normalized_soulseek.is_empty() {
            normalized.insert(
                "soulseek".to_owned(),
                serde_json::Value::Object(normalized_soulseek),
            );
        }
    }

    if target == ControllerCompatibilityTarget::Slskdn {
        if let Some(integration) = json_object_field_ci(object, "integration") {
            if !integration.is_object() {
                return Err("Invalid options overlay".to_owned());
            }
            normalized.insert(
                "integration".to_owned(),
                controller_yaml_api_projection(integration.clone()),
            );
        }
    }
    Ok(serde_json::Value::Object(normalized))
}

async fn apply_controller_options_overlay(body: &str, state: &AppState) -> HttpResponse {
    let overlay = match normalize_controller_options_overlay(
        body,
        state.config.controller_compatibility_target,
    ) {
        Ok(overlay) => overlay,
        Err(error) => return routing::bad_request_response(&error),
    };
    let listen_changed = overlay
        .get("soulseek")
        .and_then(serde_json::Value::as_object)
        .is_some_and(|soulseek| {
            soulseek.contains_key("listenIpAddress") || soulseek.contains_key("listenPort")
        });
    if let Some(enabled) = overlay
        .pointer("/soulseek/privateMessageAutoResponse/enabled")
        .and_then(serde_json::Value::as_bool)
    {
        state
            .private_message_auto_response_settings
            .write()
            .await
            .enabled = enabled;
        if !enabled {
            *state.private_message_auto_responses.write().await =
                PrivateMessageAutoResponseTracker::default();
        }
    }
    state.options_overlay.write().await.apply(overlay.clone());
    if listen_changed
        && state.config.controller_compatibility_target == ControllerCompatibilityTarget::Slskdn
        && state.session.read().await.state == "connected"
    {
        state.runtime.write().await.set_reconnect_pending(true);
    }
    record_event(
        state,
        "options.updated",
        "options",
        Some("volatile=true".to_owned()),
    )
    .await;
    HttpResponse {
        status: "200 OK",
        content_type: "application/json; charset=utf-8",
        body: overlay.to_string(),
    }
}

fn slskd_options_mutation_response(
    body: &str,
    acknowledgements: u64,
    acknowledgement_persistence_enabled: bool,
) -> Result<String, String> {
    let payload = serde_json::from_str::<serde_json::Value>(body)
        .map_err(|error| format!("invalid options JSON: {error}"))?;
    let Some(object) = payload.as_object() else {
        return Err("options payload must be a JSON object".to_owned());
    };
    let accepted_keys = object.keys().cloned().collect::<Vec<_>>();
    Ok(serde_json::json!({
        "status": "accepted",
        "persisted": acknowledgement_persistence_enabled,
        "configPersisted": false,
        "restart_required": false,
        "runtimeMutationEnabled": false,
        "acceptedKeys": accepted_keys,
        "acknowledgements": acknowledgements,
        "note": "runtime option mutation is not enabled",
        "message": if acknowledgement_persistence_enabled {
            "persisted compatibility acknowledgement"
        } else {
            "non-persisted compatibility acknowledgement"
        },
        "compatibility": {
            "surface": "slskd-options",
            "mutationPersistence": if acknowledgement_persistence_enabled {
                "runtime_compat_state"
            } else {
                "none"
            },
        },
    })
    .to_string())
}

fn slskd_server_state_json(
    session: &SessionSnapshot,
    config: &AppConfig,
    runtime_credentials_configured: bool,
    connected_endpoint: Option<&str>,
) -> serde_json::Value {
    let connected = session.state == "connected";
    let state = match session.state {
        "connected" => "Connected, LoggedIn",
        "connecting" => "Connecting",
        "disconnecting" => "Disconnecting",
        "error" => "Error",
        _ => "Disconnected",
    };
    let config_credentials_configured = config.credentials().is_some();
    let credential_source = if runtime_credentials_configured {
        "runtime"
    } else if config_credentials_configured {
        "config"
    } else {
        "none"
    };
    let connected_endpoint = connected.then_some(connected_endpoint).flatten();
    let connected_address = connected_endpoint.and_then(|endpoint| {
        endpoint
            .rsplit_once(':')
            .map(|(address, _)| address.trim_matches(['[', ']']))
    });
    if config.controller_compatibility_target == ControllerCompatibilityTarget::Slskd {
        let mut response = serde_json::json!({
            "state": state,
            "isConnected": connected,
            "isLoggedIn": connected,
            "isTransitioning": session.state == "connecting" || session.state == "disconnecting",
        });
        if connected {
            response["address"] = serde_json::json!(connected_address);
            response["ipEndPoint"] = serde_json::json!(connected_endpoint);
        }
        return response;
    }
    let mut response = serde_json::json!({
        "credentialsConfigured": runtime_credentials_configured || config_credentials_configured,
        "credentialSource": credential_source,
        "credentialStore": config.credential_store.as_str(),
        "credentialStoreModes": credential_store::supported_store_modes(),
        "writableCredentialStoreModes": credential_store::writable_store_modes(),
        "state": state,
        "isConnected": connected,
        "isConnecting": session.state == "connecting",
        "isDisconnecting": session.state == "disconnecting",
        "isLoggedIn": connected,
        "isLoggingIn": session.state == "connecting",
        "isTransitioning": session.state == "connecting" || session.state == "disconnecting",
        "lastError": public_session_error(session.last_error.as_deref()),
        "runtimeCredentialsConfigured": runtime_credentials_configured,
    });
    let object = response
        .as_object_mut()
        .expect("server compatibility response must be an object");
    if connected {
        object.insert("address".to_owned(), serde_json::json!(connected_address));
        object.insert(
            "ipEndPoint".to_owned(),
            serde_json::json!(connected_endpoint),
        );
    } else if config.controller_compatibility_target == ControllerCompatibilityTarget::Slskdn {
        object.insert("address".to_owned(), serde_json::json!(""));
        object.insert(
            "ipEndPoint".to_owned(),
            serde_json::json!("255.255.255.255:0"),
        );
    }
    response
}

#[expect(
    clippy::too_many_arguments,
    reason = "application state intentionally aggregates independent runtime stores"
)]
fn slskd_application_state_json(
    session: &SessionSnapshot,
    share_lifecycle: &ShareLifecycleState,
    rooms: &RoomStore,
    users: &UserStore,
    relay: &RelayState,
    runtime: &RuntimeCompatState,
    distributed_network: &DistributedRuntime,
    distributed_settings: crate::config::SoulseekDistributedSettings,
    config: &AppConfig,
    runtime_credentials_configured: bool,
    connected_endpoint: Option<&str>,
    version: serde_json::Value,
) -> String {
    let mut vpn = serde_json::json!({
        "isReady": runtime.vpn.is_ready,
        "isConnected": runtime.vpn.is_connected,
        "publicIPAddress": runtime.vpn.public_ip_address.map(|value| value.to_string()),
        "location": runtime.vpn.location,
        "forwardedPort": runtime.vpn.forwarded_port,
    });
    if let Some(relay_status) = runtime.vpn.relay.as_ref() {
        vpn["relay"] = relay_status.json();
    }
    if config.controller_compatibility_target == ControllerCompatibilityTarget::Slskdn {
        vpn["portForwards"] = serde_json::Value::Array(
            runtime
                .vpn
                .port_forwards
                .iter()
                .map(vpn::PortForward::json)
                .collect(),
        );
    }
    let compatibility_target = if config.current_upstream_behavior {
        serde_json::Value::Null
    } else {
        serde_json::json!(config.controller_compatibility_target.as_str())
    };
    serde_json::json!({
        "product": "slskR",
        "compatibilityTarget": compatibility_target,
        "version": version,
        "pendingReconnect": runtime.application_reconnect_pending,
        "pendingRestart": runtime.application_restart_requested,
        "server": slskd_server_state_json(
            session,
            config,
            runtime_credentials_configured,
            connected_endpoint,
        ),
        "connectionWatchdog": {
            "enabled": config.reconnect,
            "reconnectDelaySeconds": config.reconnect_delay.as_secs(),
        },
        "vpn": vpn,
        "health": {
            "search": {"incoming": {"latency": 0, "queueDepth": 0, "dropRate": 0}},
        },
        "relay": {
            "enabled": relay.enabled,
            "agentEnabled": runtime.relay_agent_enabled,
            "updated_at": relay.updated_at,
        },
        "bridge": {
            "enabled": config.integrations.bridge.enabled,
            "running": runtime.bridge_running,
            "configUpdates": runtime.bridge_config_updates,
            "host": null,
            "port": null,
            "endpointConfigured": config.integrations.bridge.endpoint_configured(),
        },
        "operations": {
            "profileInvitesCreated": runtime.profile_invites_created,
            "cacheWarmRuns": runtime.cache_warm_runs,
            "backfillRuns": runtime.backfill_runs,
            "songidRuns": runtime.songid_runs,
            "lidarrSyncRuns": runtime.lidarr_sync_runs,
            "lidarrManualImports": runtime.lidarr_manual_imports,
        },
        "runtime": runtime.json_value(),
        "user": {
            "username": session.username,
            "privilegesSeconds": session.privileges_seconds,
        },
        "distributedNetwork": distributed_network.application_json(
            distributed_settings,
            session.state == "connected",
            config.controller_compatibility_target,
        ),
        "shares": share_lifecycle.json(config.controller_compatibility_target),
        "rooms": rooms.records.iter().map(|room| room.name.clone()).collect::<Vec<_>>(),
        "users": users.records.iter().map(|user| user.username.clone()).collect::<Vec<_>>(),
    })
    .to_string()
}

async fn slskdn_capabilities_response(state: &AppState) -> HttpResponse {
    let media = state.media_services.read().await;
    let mut features = vec![
        "mbid_jobs",
        "discography_jobs",
        "label_crate_jobs",
        "canonical_scoring",
        "rescue_mode",
        "library_health",
        "warm_cache",
        "job_manifests",
        "session_traces",
        "playback_aware",
        "soulseek_type1_obfuscation_options",
        "soulseek_type1_obfuscated_distributed_messages",
        "soulseek_type1_obfuscated_file_transfers",
    ];
    if media.features.scene_pod_bridge {
        features.push("scene_pod_bridge");
    }
    let config = &state.config;
    let requested_listen_port =
        (config.obfuscation_listen_port > 0).then_some(config.obfuscation_listen_port);
    let effective_listen_port = config.obfuscated_advertised_port;
    let mode = config.obfuscation_mode.as_str();
    let limitations = vec![
        "Type-1 obfuscation is a compatibility/privacy posture, not transport security or meaningful encryption.",
        "Current runtime support covers peer-message (P), distributed-message (D), and file-transfer (F) streams.",
        "Regular transfer paths remain advertised and available for legacy-client compatibility.",
    ];
    let summary = if config.obfuscation_enabled {
        if mode == "prefer" && config.obfuscation_prefer_outbound {
            "Prefer mode uses obfuscated peer/distributed/transfer dials when peers advertise type-1 metadata and keeps regular fallback."
        } else {
            "Compatibility mode keeps regular outbound peer/distributed/transfer dials first and adds obfuscated reachability."
        }
    } else {
        "Soulseek type-1 peer/distributed/transfer obfuscation is disabled."
    };
    let body = serde_json::json!({
        "impl": "slskdn",
        "compat": "slskd",
        "version": APP_VERSION,
        "features": features,
        "obfuscation": {
            "enabled": config.obfuscation_enabled,
            "mode": mode,
            "type": 1,
            "regularListenPort": config.listen_port,
            "requestedListenPort": requested_listen_port,
            "effectiveListenPort": effective_listen_port,
            "advertiseRegularPort": config.obfuscation_advertise_regular_port,
            "preferOutbound": mode == "prefer" && config.obfuscation_prefer_outbound,
            "supportedConnectionTypes": ["P", "D", "F"],
            "runtimeSupported": true,
            "runtimeState": if config.obfuscation_enabled { "active" } else { "disabled" },
            "summary": summary,
            "limitations": limitations,
        },
        "feature": {
            "scenePodBridge": media.features.scene_pod_bridge,
        },
    });
    drop(media);
    routing::ok_response(body.to_string())
}

async fn slskdn_capability_controller_response(state: &AppState) -> HttpResponse {
    #[derive(Serialize)]
    struct CapabilityFile {
        client: &'static str,
        version: &'static str,
        features: [&'static str; 6],
        protocol_version: i32,
        capabilities: i32,
        mesh_seq_id: u64,
    }

    #[derive(Serialize)]
    struct CapabilityResponse {
        version: &'static str,
        tag: &'static str,
        json: String,
    }

    let mesh_seq_id = state.content_discovery.read().await.latest_seq();
    let capability_json = CapabilityFile {
        client: "slskdn",
        version: "1.0.0",
        features: [
            "dht",
            "hash_exchange",
            "mesh_sync",
            "flac_hash_db",
            "swarm_download",
            "partial_download",
        ],
        protocol_version: 1,
        capabilities: 63,
        mesh_seq_id,
    };
    let response = CapabilityResponse {
        version: "slskdn/1.0.0+dht+mesh+swarm",
        tag: "slskdn_caps:v1;dht=1;mesh=1;swarm=1;hashx=1;flacdb=1",
        json: serde_json::to_string_pretty(&capability_json).unwrap_or_else(|_| "{}".to_owned()),
    };
    routing::ok_response(serde_json::to_string(&response).unwrap_or_else(|_| "{}".to_owned()))
}

fn capabilities_response() -> HttpResponse {
    let capability_json = serde_json::json!({
        "client": "slskr",
        "version": APP_VERSION,
        "features": ["dht", "hash_exchange", "mesh_sync", "flac_hash_db", "swarm_download", "partial_download"],
        "protocol_version": 1,
        "capabilities": 63,
        "mesh_seq_id": 0,
    });
    HttpResponse {
        status: "200 OK",
        content_type: "application/json",
        body: serde_json::json!({
        "version": format!("slskr/{APP_VERSION}+dht+mesh+swarm"),
            "impl": "slskr",
            "compat": "slskdn-v1",
            "features": capability_json["features"].clone(),
            "obfuscation": {"type1": true, "mode": "compatibility"},
            "feature": {"dht": true, "mesh": true, "swarm": true},
            "tag": "slskr_caps:v1;dht=1;mesh=1;swarm=1;hashx=1;flacdb=1",
            "json": serde_json::to_string_pretty(&capability_json).unwrap_or_else(|_| "{}".to_owned()),
            "api_version": "v0",
            "client_version": APP_VERSION,
            "supports": ["login","peers","shares","searches","transfers","users","messages","rooms","room-list-sync","browser-session-auth"],
        }).to_string(),
    }
}

async fn network_stats_value(state: &AppState, include_peers: bool) -> serde_json::Value {
    let searches = state.searches.read().await;
    let search_count = searches.records.len();
    let search_result_count = searches
        .records
        .iter()
        .map(|record| record.results.len())
        .sum::<usize>();
    drop(searches);

    let shares = state.shares.read().await;
    let shared_file_count = shares.entries.len();
    let shared_bytes = shares.entries.iter().map(|entry| entry.size).sum::<u64>();
    drop(shares);

    let events = state.events.read().await;
    let completed_backfills = events
        .records
        .iter()
        .filter(|event| event.kind.contains("backfill") || event.kind.contains("hashdb"))
        .count();
    drop(events);

    let users = state.users.read().await;
    let mesh = state.mesh.read().await;
    let candidate_usernames = mesh.candidate_usernames(&users);
    let discovered_peers = if include_peers {
        mesh.capability_records_json()
    } else {
        Vec::new()
    };
    let mesh_peers = if include_peers {
        candidate_usernames
            .iter()
            .map(|username| {
                serde_json::json!({
                    "username": username,
                    "meshCapable": mesh.capability_records.iter().any(|descriptor| {
                        descriptor.username.eq_ignore_ascii_case(username)
                            && MeshRendezvous::accepts_descriptor(descriptor)
                    }),
                })
            })
            .collect::<Vec<_>>()
    } else {
        Vec::new()
    };
    let capability_record_count = mesh.capability_records.len();
    drop(mesh);
    drop(users);

    let transfers = state.transfers.read().await;
    let swarm_jobs = transfers
        .entries
        .iter()
        .filter(|entry| entry.status == "in_progress")
        .map(|entry| {
            let total_bytes = entry.size.unwrap_or_default();
            let progress_percent = if total_bytes == 0 {
                0.0
            } else {
                entry.bytes_transferred as f64 * 100.0 / total_bytes as f64
            };
            serde_json::json!({
                "activeSources": usize::from(entry.peer_username.is_some()),
                "downloadedBytes": entry.bytes_transferred,
                "filename": entry.filename,
                "jobId": format!("transfer-{}", entry.id),
                "progressPercent": progress_percent,
                "totalBytes": total_bytes,
            })
        })
        .collect::<Vec<_>>();
    drop(transfers);

    let queued_backfills = search_count + search_result_count + shared_file_count;
    let now = unix_timestamp();
    serde_json::json!({
        "backfill": {
            "isActive": queued_backfills > 0,
            "isRunning": false,
            "queued": queued_backfills,
            "completed": completed_backfills,
            "searches": search_count,
            "searchResults": search_result_count,
            "sharedFiles": shared_file_count,
        },
        "capabilitiesJson": capabilities_response().body,
        "capabilitiesVersion": APP_VERSION,
        "dht": {
            "dhtNodeCount": 0,
            "isLanOnly": false,
            "lanOnly": false,
            "isBeaconCapable": false,
            "isDhtRunning": false,
            "verifiedBeaconCount": 0,
        },
        "discoveredPeers": discovered_peers,
        "hashDb": {
            "currentSeqId": now,
            "totalHashEntries": shared_file_count,
            "totalEntries": shared_file_count,
            "totalBytes": shared_bytes,
        },
        "mesh": {
            "currentSeqId": now,
            "localSeqId": now,
            "isSyncing": false,
            "knownMeshPeers": candidate_usernames.len(),
            "connectedPeerCount": 0,
            "capabilityRecords": capability_record_count,
            "interestTag": MESH_RENDEZVOUS_INTEREST_TAG,
            "warnings": [],
        },
        "meshPeers": mesh_peers,
        "swarmJobs": swarm_jobs,
        "transport": {
            "status": "Healthy",
            "health": "Healthy",
            "description": "Mesh transport unavailable in this runtime",
            "transportPreference": "Auto",
            "connectedPeers": 0,
            "totalPeers": 0,
            "activeCircuits": 0,
            "activeStreams": 0,
            "bootstrapPeers": [],
            "isolatedPeers": 0,
            "quorumPeers": 0,
            "relayedPeers": 0,
            "natType": "Unknown",
            "publicEndpoint": null,
            "lastDhtError": null,
            "lastDhtPublishUtc": null,
        },
    })
}

fn capabilities_negotiate_response(body: &str) -> HttpResponse {
    let server_capabilities = ["shares", "telemetry"];

    // Parse requested capabilities from body
    let requested = extract_json_string_array_field(body, "capabilities").unwrap_or_default();

    // Compute intersection
    let mut accepted = Vec::new();
    let mut unsupported = Vec::new();

    for req_cap in requested {
        if server_capabilities.contains(&req_cap.as_str()) {
            accepted.push(req_cap);
        } else {
            unsupported.push(req_cap);
        }
    }

    let response_body = serde_json::json!({
        "accepted": accepted,
        "unsupported": unsupported,
        "server_capabilities": server_capabilities,
    })
    .to_string();

    HttpResponse {
        status: "200 OK",
        content_type: "application/json",
        body: response_body,
    }
}

#[derive(Clone, Debug, PartialEq, Eq)]
struct ParsedCapabilityDescription {
    flags: i32,
    client_version: String,
    protocol_version: i32,
}

const CAPABILITY_SUPPORTS_DHT: i32 = 1 << 0;
const CAPABILITY_SUPPORTS_HASH_EXCHANGE: i32 = 1 << 1;
const CAPABILITY_SUPPORTS_PARTIAL_DOWNLOAD: i32 = 1 << 2;
const CAPABILITY_SUPPORTS_MESH_SYNC: i32 = 1 << 3;
const CAPABILITY_SUPPORTS_FLAC_HASH_DB: i32 = 1 << 4;
const CAPABILITY_SUPPORTS_SWARM: i32 = 1 << 5;

fn capability_flag_value(name: &str) -> i32 {
    match name.to_ascii_lowercase().as_str() {
        "dht" => CAPABILITY_SUPPORTS_DHT,
        "hashx" => CAPABILITY_SUPPORTS_HASH_EXCHANGE,
        "partial" => CAPABILITY_SUPPORTS_PARTIAL_DOWNLOAD,
        "mesh" => CAPABILITY_SUPPORTS_MESH_SYNC,
        "flacdb" => CAPABILITY_SUPPORTS_FLAC_HASH_DB,
        "swarm" => CAPABILITY_SUPPORTS_SWARM,
        _ => 0,
    }
}

fn capability_flags_from_features(features: &[String]) -> i32 {
    features.iter().fold(0, |flags, feature| {
        let flag = match feature.to_ascii_lowercase().as_str() {
            "dht" | "dht_hash_db" => CAPABILITY_SUPPORTS_DHT,
            "hashx" | "hash_exchange" => CAPABILITY_SUPPORTS_HASH_EXCHANGE,
            "partial" | "partial_download" => CAPABILITY_SUPPORTS_PARTIAL_DOWNLOAD,
            "mesh" | "mesh_sync" | slskr_client::capabilities::FEATURE_MESH_V1 => {
                CAPABILITY_SUPPORTS_MESH_SYNC
            }
            "flacdb" | "flac_hash_db" => CAPABILITY_SUPPORTS_FLAC_HASH_DB,
            "swarm" | "swarm_download" => CAPABILITY_SUPPORTS_SWARM,
            _ => 0,
        };
        flags | flag
    })
}

fn capability_flags_from_tag(flags: &str) -> i32 {
    flags
        .split(';')
        .filter_map(|part| {
            let mut fields = part.split('=');
            let name = fields.next()?;
            let value = fields.next()?;
            (fields.next().is_none() && value == "1").then(|| capability_flag_value(name))
        })
        .fold(0, |flags, flag| flags | flag)
}

fn capability_flags_from_version(tokens: &str) -> i32 {
    tokens
        .split('+')
        .filter(|token| !token.is_empty())
        .map(capability_flag_value)
        .fold(0, |flags, flag| flags | flag)
}

fn capability_flags_string(flags: i32) -> String {
    let names = [
        (CAPABILITY_SUPPORTS_DHT, "SupportsDHT"),
        (CAPABILITY_SUPPORTS_HASH_EXCHANGE, "SupportsHashExchange"),
        (
            CAPABILITY_SUPPORTS_PARTIAL_DOWNLOAD,
            "SupportsPartialDownload",
        ),
        (CAPABILITY_SUPPORTS_MESH_SYNC, "SupportsMeshSync"),
        (CAPABILITY_SUPPORTS_FLAC_HASH_DB, "SupportsFlacHashDb"),
        (CAPABILITY_SUPPORTS_SWARM, "SupportsSwarm"),
    ];
    if flags == 0 {
        return "None".to_owned();
    }
    names
        .into_iter()
        .filter_map(|(flag, name)| (flags & flag != 0).then_some(name))
        .collect::<Vec<_>>()
        .join(", ")
}

fn capability_service_peer_json(
    descriptor: &slskr_client::capabilities::PeerCapabilityDescriptor,
) -> serde_json::Value {
    let flags = capability_flags_from_features(&descriptor.features);
    serde_json::json!({
        "username": descriptor.username,
        "flags": capability_flags_string(flags),
        "flagsValue": flags,
        // slskdN's SoulseekCapabilityBridgeService records every binary
        // capability-envelope observation as its runtime capability client;
        // this is the stable DTO value exposed by CapabilitiesController,
        // not the unrelated UserInfo version-string parser.
        "clientVersion": "slskdn/runtime-capability-v1",
        "protocolVersion": 1,
        "canSwarm": flags & CAPABILITY_SUPPORTS_SWARM != 0,
        "canMeshSync": flags & CAPABILITY_SUPPORTS_MESH_SYNC != 0,
        "lastSeen": unix_seconds_rfc3339(descriptor.issued_at_unix),
        "meshSeqId": 0,
    })
}

fn persisted_capability_descriptor(value: &serde_json::Value) -> Option<PeerCapabilityDescriptor> {
    let decode = |name: &str| STANDARD.decode(value.get(name)?.as_str()?.as_bytes()).ok();
    let public_key = <[u8; 32]>::try_from(decode("publicKey")?.as_slice()).ok()?;
    let signature = value
        .get("signature")
        .and_then(serde_json::Value::as_str)
        .filter(|value| !value.is_empty())
        .and_then(|_| <[u8; 64]>::try_from(decode("signature")?.as_slice()).ok());
    let features = value
        .get("features")?
        .as_array()?
        .iter()
        .filter_map(serde_json::Value::as_str)
        .map(str::to_owned)
        .collect();
    let endpoints = value
        .get("endpoints")?
        .as_array()?
        .iter()
        .filter_map(serde_json::Value::as_str)
        .map(str::to_owned)
        .collect();
    Some(PeerCapabilityDescriptor {
        peer_id: value.get("peerId")?.as_str()?.to_owned(),
        username: value.get("username")?.as_str()?.to_owned(),
        features,
        endpoints,
        overlay_port: value
            .get("overlayPort")
            .and_then(serde_json::Value::as_u64)
            .and_then(|port| u16::try_from(port).ok()),
        max_payload_length: value
            .get("maxPayloadLength")
            .and_then(serde_json::Value::as_u64)
            .and_then(|length| u32::try_from(length).ok())?,
        issued_at_unix: value.get("issuedAtUnix")?.as_u64()?,
        expires_at_unix: value.get("expiresAtUnix")?.as_u64()?,
        public_key,
        signature,
    })
}

fn parse_capability_tag(description: &str) -> Option<ParsedCapabilityDescription> {
    let matcher = fancy_regex::Regex::new(r"(?i)slskdn_caps:v(\d+);?(.*)").ok()?;
    let captures = matcher.captures(description).ok()??;
    let protocol_version = captures.get(1)?.as_str().parse::<i32>().ok()?;
    let flags = captures
        .get(2)
        .map(|value| capability_flags_from_tag(value.as_str()))
        .unwrap_or_default();
    Some(ParsedCapabilityDescription {
        flags,
        client_version: String::new(),
        protocol_version,
    })
}

fn parse_capability_version(version: &str) -> Option<ParsedCapabilityDescription> {
    let matcher = fancy_regex::Regex::new(r"(?i)slskdn/([^+\s]+)(\+.*)?").ok()?;
    let captures = matcher.captures(version).ok()??;
    let client_version = captures.get(1)?.as_str().to_owned();
    let flags = captures
        .get(2)
        .map(|value| capability_flags_from_version(value.as_str()))
        .unwrap_or_default();
    Some(ParsedCapabilityDescription {
        flags,
        client_version,
        protocol_version: 1,
    })
}

fn capabilities_parse_response(body: &str) -> HttpResponse {
    let payload = match serde_json::from_str::<serde_json::Value>(body) {
        Ok(payload) => payload,
        Err(_) => return routing::bad_request_response("invalid JSON body"),
    };
    let description = payload
        .get("description")
        .or_else(|| payload.get("Description"))
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .unwrap_or_default();
    let version = payload
        .get("versionString")
        .or_else(|| payload.get("VersionString"))
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .unwrap_or_default();
    let parsed = (!description.is_empty())
        .then(|| parse_capability_tag(description))
        .flatten()
        .or_else(|| {
            (!version.is_empty())
                .then(|| parse_capability_version(version))
                .flatten()
        });
    let Some(parsed) = parsed else {
        return routing::ok_response(serde_json::json!({"isSlskdn": false}).to_string());
    };
    routing::ok_response(
        serde_json::json!({
            "isSlskdn": true,
            "flags": capability_flags_string(parsed.flags),
            "flagsValue": parsed.flags,
            "protocolVersion": parsed.protocol_version,
            "clientVersion": parsed.client_version,
            "canSwarm": parsed.flags & CAPABILITY_SUPPORTS_SWARM != 0,
            "canMeshSync": parsed.flags & CAPABILITY_SUPPORTS_MESH_SYNC != 0,
        })
        .to_string(),
    )
}

fn url_encode(value: &str) -> String {
    let mut encoded = String::new();
    for byte in value.bytes() {
        match byte {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                encoded.push(byte as char);
            }
            _ => encoded.push_str(&format!("%{byte:02X}")),
        }
    }
    encoded
}

fn secure_oauth_state() -> Option<String> {
    secure_oauth_state_with(|bytes| SysRng.try_fill_bytes(bytes).is_ok())
}

fn secure_oauth_state_with(fill: impl FnOnce(&mut [u8; 32]) -> bool) -> Option<String> {
    let mut bytes = [0_u8; 32];
    fill(&mut bytes).then(|| format!("slskr-{}", hex::encode(bytes)))
}

fn secure_spotify_code_verifier() -> Option<String> {
    const ALPHABET: &[u8] = b"ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789-._~";
    let mut bytes = [0_u8; 64];
    SysRng.try_fill_bytes(&mut bytes).ok()?;
    Some(
        bytes
            .into_iter()
            .map(|byte| char::from(ALPHABET[usize::from(byte) % ALPHABET.len()]))
            .collect(),
    )
}

fn secure_share_grant_token() -> Option<String> {
    secure_share_grant_token_with(|bytes| SysRng.try_fill_bytes(bytes).is_ok())
}

fn secure_share_grant_token_with(fill: impl FnOnce(&mut [u8; 32]) -> bool) -> Option<String> {
    let mut bytes = [0_u8; 32];
    fill(&mut bytes).then(|| format!("share-{}", hex::encode(bytes)))
}

fn request_share_token(
    authorization: Option<&str>,
    headers: &RequestSecurityHeaders,
) -> Option<String> {
    if let Some(token) = headers
        .x_share_token
        .as_deref()
        .map(str::trim)
        .filter(|token| !token.is_empty())
    {
        return Some(token.to_owned());
    }

    let authorization = authorization?.trim();
    let (scheme, value) = authorization.split_once(' ')?;
    if !scheme.eq_ignore_ascii_case("bearer") {
        return None;
    }
    let (prefix, token) = value.trim().split_once(':')?;
    let token = token.trim();
    (prefix.eq_ignore_ascii_case("share") && !token.is_empty()).then(|| token.to_owned())
}

fn query_parameter(query: Option<&str>, name: &str) -> Option<String> {
    query?.split('&').find_map(|pair| {
        let (key, value) = pair.split_once('=').unwrap_or((pair, ""));
        percent_decode_component(key)
            .eq_ignore_ascii_case(name)
            .then(|| percent_decode_component(value))
    })
}

fn webhook_from_persisted(record: crate::persistence::WebhookRecord) -> Option<webhooks::Webhook> {
    let events = record
        .events
        .split(',')
        .filter_map(webhooks::WebhookEvent::from_wire)
        .collect::<Vec<_>>();
    if events.is_empty() {
        return None;
    }
    Some(webhooks::Webhook {
        id: record.id,
        url: record.url,
        events,
        secret: record.secret,
        active: record.active,
        created_at: record.created_at,
        last_triggered: record.last_triggered,
        retry_count: u32::try_from(record.retry_count).unwrap_or(0),
        max_retries: u32::try_from(record.max_retries).unwrap_or(3),
        timeout_seconds: u32::try_from(record.timeout_seconds).unwrap_or(30),
    })
}

fn webhook_persistence_record(webhook: &webhooks::Webhook) -> crate::persistence::WebhookRecord {
    crate::persistence::WebhookRecord {
        id: webhook.id.clone(),
        url: webhook.url.clone(),
        events: webhook
            .events
            .iter()
            .map(ToString::to_string)
            .collect::<Vec<_>>()
            .join(","),
        secret: webhook.secret.clone(),
        active: webhook.active,
        created_at: webhook.created_at,
        last_triggered: webhook.last_triggered,
        retry_count: i32::try_from(webhook.retry_count).unwrap_or(i32::MAX),
        max_retries: i32::try_from(webhook.max_retries).unwrap_or(i32::MAX),
        timeout_seconds: i32::try_from(webhook.timeout_seconds).unwrap_or(i32::MAX),
    }
}

fn spotify_redirect_uri(state: &AppState, spotify: &config::SpotifyIntegrationSettings) -> String {
    spotify.redirect_uri.clone().unwrap_or_else(|| {
        let host = if state.config.http_bind.ip().is_unspecified() {
            format!("127.0.0.1:{}", state.config.http_bind.port())
        } else {
            state.config.http_bind.to_string()
        };
        format!("http://{host}/api/v0/integrations/spotify/callback")
    })
}

const SPOTIFY_CONNECTION_AAD: &[u8] = b"slskr.source-feeds.spotify-token-store.v1";

fn spotify_connection_path(state_dir: &Path) -> PathBuf {
    state_dir
        .join("source-feeds")
        .join("spotify-connection.json")
}

fn spotify_connection_key(signing_key: &SigningKey) -> [u8; 32] {
    let mut digest = Sha256::new();
    digest.update(SPOTIFY_CONNECTION_AAD);
    digest.update(signing_key.to_bytes());
    digest.finalize().into()
}

fn load_spotify_connection_store(
    state_dir: &Path,
    signing_key: &SigningKey,
) -> SpotifyConnectionStore {
    use std::io::Read as _;

    let path = spotify_connection_path(state_dir);
    let Ok(metadata) = fs::symlink_metadata(&path) else {
        return SpotifyConnectionStore::default();
    };
    if metadata.file_type().is_symlink() || !metadata.is_file() || metadata.len() > 1024 * 1024 {
        return SpotifyConnectionStore::default();
    }
    let mut options = fs::OpenOptions::new();
    options.read(true);
    #[cfg(unix)]
    {
        use std::os::unix::fs::OpenOptionsExt;
        options.custom_flags(libc::O_CLOEXEC | libc::O_NOFOLLOW | libc::O_NONBLOCK);
    }
    let Ok(mut file) = options.open(path) else {
        return SpotifyConnectionStore::default();
    };
    let Ok(opened) = file.metadata() else {
        return SpotifyConnectionStore::default();
    };
    if !opened.is_file() || opened.len() > 1024 * 1024 {
        return SpotifyConnectionStore::default();
    }
    let mut encoded = String::new();
    if std::io::Read::take(&mut file, 1024 * 1024 + 1)
        .read_to_string(&mut encoded)
        .is_err()
        || encoded.len() > 1024 * 1024
    {
        return SpotifyConnectionStore::default();
    }
    let Ok(envelope) = serde_json::from_str::<ProtectedSpotifyConnection>(&encoded) else {
        return SpotifyConnectionStore::default();
    };
    if envelope.version != 1 {
        return SpotifyConnectionStore::default();
    }
    let Ok(nonce) = URL_SAFE_NO_PAD.decode(envelope.nonce) else {
        return SpotifyConnectionStore::default();
    };
    let Ok(nonce): Result<[u8; 12], _> = nonce.try_into() else {
        return SpotifyConnectionStore::default();
    };
    let Ok(mut ciphertext) = URL_SAFE_NO_PAD.decode(envelope.ciphertext) else {
        return SpotifyConnectionStore::default();
    };
    let Ok(unbound) = ring::aead::UnboundKey::new(
        &ring::aead::AES_256_GCM,
        &spotify_connection_key(signing_key),
    ) else {
        return SpotifyConnectionStore::default();
    };
    let key = ring::aead::LessSafeKey::new(unbound);
    let Ok(plaintext) = key.open_in_place(
        ring::aead::Nonce::assume_unique_for_key(nonce),
        ring::aead::Aad::from(SPOTIFY_CONNECTION_AAD),
        &mut ciphertext,
    ) else {
        return SpotifyConnectionStore::default();
    };
    serde_json::from_slice(plaintext).unwrap_or_default()
}

fn persist_spotify_connection_store(
    state: &AppState,
    store: &SpotifyConnectionStore,
) -> Result<(), String> {
    let path = spotify_connection_path(&state.config.state_dir);
    let directory = path.parent().expect("Spotify connection path has a parent");
    ensure_private_storage_dir(directory, "Spotify connection state")?;
    let mut nonce = [0_u8; 12];
    SysRng
        .try_fill_bytes(&mut nonce)
        .map_err(|_| "secure randomness unavailable for Spotify connection state".to_owned())?;
    let unbound = ring::aead::UnboundKey::new(
        &ring::aead::AES_256_GCM,
        &spotify_connection_key(&state.capability_signing_key),
    )
    .map_err(|_| "Spotify connection encryption key is invalid".to_owned())?;
    let key = ring::aead::LessSafeKey::new(unbound);
    let mut ciphertext = serde_json::to_vec(store)
        .map_err(|error| format!("Spotify connection encode failed: {error}"))?;
    key.seal_in_place_append_tag(
        ring::aead::Nonce::assume_unique_for_key(nonce),
        ring::aead::Aad::from(SPOTIFY_CONNECTION_AAD),
        &mut ciphertext,
    )
    .map_err(|_| "Spotify connection encryption failed".to_owned())?;
    let envelope = ProtectedSpotifyConnection {
        version: 1,
        nonce: URL_SAFE_NO_PAD.encode(nonce),
        ciphertext: URL_SAFE_NO_PAD.encode(ciphertext),
    };
    let body = serde_json::to_vec(&envelope)
        .map_err(|error| format!("Spotify connection envelope encode failed: {error}"))?;
    write_file_atomic(&path, body)
        .map_err(|error| format!("Spotify connection persistence failed: {error}"))?;
    #[cfg(unix)]
    {
        use std::os::unix::fs::PermissionsExt;
        fs::set_permissions(&path, fs::Permissions::from_mode(0o600))
            .map_err(|error| format!("Spotify connection permissions failed: {error}"))?;
    }
    Ok(())
}

fn delete_spotify_connection_store(state: &AppState) -> Result<(), String> {
    let path = spotify_connection_path(&state.config.state_dir);
    match fs::remove_file(path) {
        Ok(()) => Ok(()),
        Err(error) if error.kind() == std::io::ErrorKind::NotFound => Ok(()),
        Err(error) => Err(format!("Spotify connection delete failed: {error}")),
    }
}

async fn spotify_token_request(
    spotify: &config::SpotifyIntegrationSettings,
    token_url: &str,
    form: &[(&str, String)],
) -> Result<serde_json::Value, String> {
    let response = reqwest::Client::builder()
        .timeout(Duration::from_secs(spotify.timeout_seconds))
        .redirect(reqwest::redirect::Policy::none())
        .build()
        .map_err(|error| format!("failed to build Spotify client: {error}"))?
        .post(token_url)
        .form(form)
        .send()
        .await
        .map_err(|error| format!("Spotify token request failed: {error}"))?;
    if !response.status().is_success() {
        return Err(format!("Spotify returned HTTP {}", response.status()));
    }
    read_bounded_integration_json(response, "Spotify token").await
}

async fn spotify_profile_request(
    spotify: &config::SpotifyIntegrationSettings,
    profile_url: &str,
    access_token: &str,
) -> Result<serde_json::Value, String> {
    let response = reqwest::Client::builder()
        .timeout(Duration::from_secs(spotify.timeout_seconds))
        .redirect(reqwest::redirect::Policy::none())
        .build()
        .map_err(|error| format!("failed to build Spotify client: {error}"))?
        .get(profile_url)
        .bearer_auth(access_token)
        .send()
        .await
        .map_err(|error| format!("Spotify profile request failed: {error}"))?;
    if !response.status().is_success() {
        return Err(format!("Spotify returned HTTP {}", response.status()));
    }
    read_bounded_integration_json(response, "Spotify profile").await
}

async fn complete_spotify_authorization(
    state: &AppState,
    spotify: &config::SpotifyIntegrationSettings,
    pending: &OAuthStateRecord,
    code: &str,
    token_url: &str,
    profile_url: &str,
) -> Result<serde_json::Value, String> {
    let client_id = spotify.client_id.as_deref().unwrap_or_default();
    let verifier = pending
        .code_verifier
        .as_deref()
        .ok_or_else(|| "Spotify authorization state is invalid or expired".to_owned())?;
    let token = spotify_token_request(
        spotify,
        token_url,
        &[
            ("client_id", client_id.to_owned()),
            ("grant_type", "authorization_code".to_owned()),
            ("code", code.to_owned()),
            ("redirect_uri", pending.redirect_uri.clone()),
            ("code_verifier", verifier.to_owned()),
        ],
    )
    .await?;
    let access_token = token
        .get("access_token")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default();
    let refresh_token = token
        .get("refresh_token")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default();
    if access_token.trim().is_empty() || refresh_token.trim().is_empty() {
        return Err("Spotify token response was incomplete".to_owned());
    }
    let profile = spotify_profile_request(spotify, profile_url, access_token).await?;
    let expires_in = token
        .get("expires_in")
        .and_then(serde_json::Value::as_i64)
        .unwrap_or_default();
    let store = SpotifyConnectionStore {
        access_token: access_token.to_owned(),
        refresh_token: refresh_token.to_owned(),
        scope: token
            .get("scope")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default()
            .to_owned(),
        expires_at: i64::try_from(unix_timestamp())
            .unwrap_or(i64::MAX)
            .saturating_add(expires_in.saturating_sub(30).max(30)),
        display_name: profile
            .get("display_name")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default()
            .to_owned(),
        spotify_user_id: profile
            .get("id")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default()
            .to_owned(),
    };
    persist_spotify_connection_store(state, &store)?;
    let status = store.status_json(spotify.configured());
    *state.spotify_connection.write().await = store;
    Ok(status)
}

fn normalize_spotify_source_target(kind: &str, id: &str) -> SpotifySourceTarget {
    let kind = match kind.trim().to_ascii_lowercase().as_str() {
        "collection" | "liked" | "saved-tracks" => "saved-tracks",
        "saved-albums" => "saved-albums",
        "followed-artists" => "followed-artists",
        "playlists" => "playlists",
        other => other,
    }
    .to_owned();
    let (requires_user_token, scope_hint) = match kind.as_str() {
        "saved-tracks" | "saved-albums" => (true, "user-library-read"),
        "followed-artists" => (true, "user-follow-read"),
        "playlists" => (true, "playlist-read-private playlist-read-collaborative"),
        _ => (false, ""),
    };
    SpotifySourceTarget {
        kind,
        id: id.trim().to_owned(),
        requires_user_token,
        scope_hint: scope_hint.to_owned(),
    }
}

fn parse_spotify_source_target(source_text: &str) -> SpotifySourceTarget {
    let trimmed = source_text.trim();
    let lower = trimmed.to_ascii_lowercase();
    if lower.starts_with("spotify:") {
        let mut parts = trimmed.split(':');
        let _ = parts.next();
        let kind = parts.next().unwrap_or_default();
        let id = parts.next().unwrap_or_default();
        return normalize_spotify_source_target(kind, id);
    }
    if let Ok(url) = reqwest::Url::parse(trimmed) {
        if url
            .host_str()
            .is_some_and(|host| host.eq_ignore_ascii_case("open.spotify.com"))
        {
            let parts = url
                .path_segments()
                .map(|segments| segments.filter(|part| !part.is_empty()).collect::<Vec<_>>())
                .unwrap_or_default();
            let kind = parts.first().copied().unwrap_or_default();
            let id = parts.get(1).copied().unwrap_or_default();
            if kind.eq_ignore_ascii_case("collection") {
                let path = url.path().to_ascii_lowercase();
                return if path.contains("albums") {
                    normalize_spotify_source_target("saved-albums", "")
                } else if path.contains("following") || path.contains("artists") {
                    normalize_spotify_source_target("followed-artists", "")
                } else {
                    normalize_spotify_source_target("saved-tracks", "")
                };
            }
            return normalize_spotify_source_target(kind, id);
        }
    }
    normalize_spotify_source_target(&lower, "")
}

fn looks_like_spotify_source(source_text: &str, source_kind: &str) -> bool {
    source_kind.eq_ignore_ascii_case("spotify")
        || source_text
            .trim_start()
            .to_ascii_lowercase()
            .starts_with("spotify:")
        || reqwest::Url::parse(source_text.trim()).is_ok_and(|url| {
            url.host_str()
                .is_some_and(|host| host.eq_ignore_ascii_case("open.spotify.com"))
        })
}

async fn refresh_spotify_user_access_token(
    state: &AppState,
    spotify: &config::SpotifyIntegrationSettings,
    token_url: &str,
) -> Result<String, String> {
    let _permit = state
        .spotify_token_gate
        .acquire()
        .await
        .map_err(|_| "Spotify token gate is unavailable".to_owned())?;
    let current = state.spotify_connection.read().await.clone();
    let now = i64::try_from(unix_timestamp()).unwrap_or(i64::MAX);
    if !current.access_token.trim().is_empty() && current.expires_at > now.saturating_add(60) {
        return Ok(current.access_token);
    }
    if current.refresh_token.trim().is_empty() {
        return Ok(String::new());
    }
    let token = spotify_token_request(
        spotify,
        token_url,
        &[
            (
                "client_id",
                spotify.client_id.as_deref().unwrap_or_default().to_owned(),
            ),
            ("grant_type", "refresh_token".to_owned()),
            ("refresh_token", current.refresh_token.clone()),
        ],
    )
    .await?;
    let access_token = token
        .get("access_token")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default()
        .trim();
    if access_token.is_empty() {
        return Err("Spotify refresh response was incomplete".to_owned());
    }
    let expires_in = token
        .get("expires_in")
        .and_then(serde_json::Value::as_i64)
        .unwrap_or_default();
    let mut refreshed = current;
    refreshed.access_token = access_token.to_owned();
    if let Some(value) = token
        .get("refresh_token")
        .and_then(serde_json::Value::as_str)
        .filter(|value| !value.trim().is_empty())
    {
        refreshed.refresh_token = value.to_owned();
    }
    if let Some(value) = token
        .get("scope")
        .and_then(serde_json::Value::as_str)
        .filter(|value| !value.trim().is_empty())
    {
        refreshed.scope = value.to_owned();
    }
    refreshed.expires_at = now.saturating_add(expires_in.saturating_sub(30).max(30));
    persist_spotify_connection_store(state, &refreshed)?;
    *state.spotify_connection.write().await = refreshed;
    Ok(access_token.to_owned())
}

async fn spotify_app_access_token(
    spotify: &config::SpotifyIntegrationSettings,
    token_url: &str,
) -> Result<String, String> {
    let client_id = spotify.client_id.as_deref().unwrap_or_default().trim();
    let client_secret = spotify.client_secret.as_deref().unwrap_or_default().trim();
    if !spotify.enabled || client_id.is_empty() || client_secret.is_empty() {
        return Ok(String::new());
    }
    use base64::Engine as _;
    let credentials =
        base64::engine::general_purpose::STANDARD.encode(format!("{client_id}:{client_secret}"));
    let response = reqwest::Client::builder()
        .timeout(Duration::from_secs(spotify.timeout_seconds))
        .redirect(reqwest::redirect::Policy::none())
        .build()
        .map_err(|error| format!("failed to build Spotify client: {error}"))?
        .post(token_url)
        .header("Authorization", format!("Basic {credentials}"))
        .form(&[("grant_type", "client_credentials")])
        .send()
        .await
        .map_err(|error| format!("Spotify token request failed: {error}"))?;
    if !response.status().is_success() {
        return Err(format!("Spotify returned HTTP {}", response.status()));
    }
    let token = read_bounded_integration_json(response, "Spotify token").await?;
    Ok(token
        .get("access_token")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default()
        .to_owned())
}

async fn spotify_source_access_token(
    state: &AppState,
    spotify: &config::SpotifyIntegrationSettings,
    target: &SpotifySourceTarget,
    provided: &str,
    token_url: &str,
) -> Result<String, String> {
    if !provided.trim().is_empty() {
        return Ok(provided.trim().to_owned());
    }
    if target.requires_user_token {
        return refresh_spotify_user_access_token(state, spotify, token_url).await;
    }
    let app_token = spotify_app_access_token(spotify, token_url).await?;
    if !app_token.trim().is_empty() {
        return Ok(app_token);
    }
    refresh_spotify_user_access_token(state, spotify, token_url).await
}

async fn spotify_get_json(
    spotify: &config::SpotifyIntegrationSettings,
    url: String,
    token: &str,
) -> Result<serde_json::Value, String> {
    let token = token.trim();
    let token = token
        .get(..7)
        .filter(|prefix| prefix.eq_ignore_ascii_case("Bearer "))
        .map(|_| &token[7..])
        .unwrap_or(token)
        .trim();
    let response = reqwest::Client::builder()
        .timeout(Duration::from_secs(spotify.timeout_seconds))
        .redirect(reqwest::redirect::Policy::none())
        .build()
        .map_err(|error| format!("failed to build Spotify client: {error}"))?
        .get(url)
        .bearer_auth(token)
        .send()
        .await
        .map_err(|error| format!("Spotify API request failed: {error}"))?;
    if !response.status().is_success() {
        return Err(format!("Spotify returned HTTP {}", response.status()));
    }
    read_bounded_integration_json(response, "Spotify API").await
}

fn spotify_track_row(
    track: &serde_json::Value,
    source: &str,
    source_id: &str,
    album_override: Option<&str>,
) -> Option<SpotifySourceRow> {
    if !track.is_object() {
        return None;
    }
    let title = track
        .get("name")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default()
        .to_owned();
    let artist = track
        .get("artists")
        .and_then(serde_json::Value::as_array)
        .map(|artists| {
            artists
                .iter()
                .filter_map(|artist| artist.get("name").and_then(serde_json::Value::as_str))
                .filter(|name| !name.trim().is_empty())
                .collect::<Vec<_>>()
                .join(" ")
        })
        .unwrap_or_default();
    let album = album_override
        .map(str::to_owned)
        .or_else(|| {
            track
                .pointer("/album/name")
                .and_then(serde_json::Value::as_str)
                .map(str::to_owned)
        })
        .unwrap_or_default();
    Some(SpotifySourceRow {
        raw_text: title.clone(),
        title,
        artist,
        album,
        source: source.to_owned(),
        source_id: source_id.to_owned(),
        provider_url: track
            .pointer("/external_urls/spotify")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default()
            .to_owned(),
    })
}

fn spotify_page_done(page: &serde_json::Value, item_count: usize, offset: usize) -> bool {
    item_count == 0
        || page.get("next").is_none_or(serde_json::Value::is_null)
        || page
            .get("total")
            .and_then(serde_json::Value::as_u64)
            .is_some_and(|total| offset.saturating_add(item_count) >= total as usize)
}

async fn fetch_spotify_playlist_tracks(
    spotify: &config::SpotifyIntegrationSettings,
    api_base: &str,
    token: &str,
    playlist_id: &str,
    rows: &mut Vec<SpotifySourceRow>,
    limit: usize,
) -> Result<u64, String> {
    let mut requests = 0_u64;
    let mut offset = 0_usize;
    while rows.len() < limit {
        let page_limit = 50_usize.min(limit - rows.len());
        let page = spotify_get_json(
            spotify,
            format!(
                "{}/playlists/{}/items?limit={page_limit}&offset={offset}&additional_types=track",
                api_base.trim_end_matches('/'),
                url_encode(playlist_id)
            ),
            token,
        )
        .await?;
        requests += 1;
        let items = page
            .get("items")
            .and_then(serde_json::Value::as_array)
            .cloned()
            .unwrap_or_default();
        for item in &items {
            if let Some(row) = spotify_track_row(
                item.get("track").unwrap_or(&serde_json::Value::Null),
                "spotify:playlist",
                playlist_id,
                None,
            ) {
                rows.push(row);
            }
        }
        if spotify_page_done(&page, items.len(), offset) {
            break;
        }
        offset = offset.saturating_add(items.len());
    }
    Ok(requests)
}

async fn fetch_spotify_track_pages(
    spotify: &config::SpotifyIntegrationSettings,
    api_base: &str,
    token: &str,
    path: &str,
    source: &str,
    rows: &mut Vec<SpotifySourceRow>,
    limit: usize,
) -> Result<u64, String> {
    let mut requests = 0_u64;
    let mut offset = 0_usize;
    while rows.len() < limit {
        let page_limit = 50_usize.min(limit - rows.len());
        let page = spotify_get_json(
            spotify,
            format!(
                "{}{path}?limit={page_limit}&offset={offset}",
                api_base.trim_end_matches('/')
            ),
            token,
        )
        .await?;
        requests += 1;
        let items = page
            .get("items")
            .and_then(serde_json::Value::as_array)
            .cloned()
            .unwrap_or_default();
        for item in &items {
            let track = item.get("track").unwrap_or(&serde_json::Value::Null);
            let source_id = track
                .get("id")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default();
            if let Some(row) = spotify_track_row(track, source, source_id, None) {
                rows.push(row);
            }
        }
        if spotify_page_done(&page, items.len(), offset) {
            break;
        }
        offset = offset.saturating_add(items.len());
    }
    Ok(requests)
}

async fn fetch_spotify_playlist_collection(
    spotify: &config::SpotifyIntegrationSettings,
    api_base: &str,
    token: &str,
    path: &str,
    rows: &mut Vec<SpotifySourceRow>,
    limit: usize,
) -> Result<u64, String> {
    let mut requests = 0_u64;
    let mut offset = 0_usize;
    while rows.len() < limit {
        let page = spotify_get_json(
            spotify,
            format!(
                "{}{path}?limit=20&offset={offset}",
                api_base.trim_end_matches('/')
            ),
            token,
        )
        .await?;
        requests += 1;
        let items = page
            .get("items")
            .and_then(serde_json::Value::as_array)
            .cloned()
            .unwrap_or_default();
        for playlist in &items {
            let playlist_id = playlist
                .get("id")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default();
            requests +=
                fetch_spotify_playlist_tracks(spotify, api_base, token, playlist_id, rows, limit)
                    .await?;
            if rows.len() >= limit {
                break;
            }
        }
        if spotify_page_done(&page, items.len(), offset) {
            break;
        }
        offset = offset.saturating_add(items.len());
    }
    Ok(requests)
}

fn build_spotify_source_result(
    target: &SpotifySourceTarget,
    rows: Vec<SpotifySourceRow>,
    network_request_count: u64,
) -> serde_json::Value {
    let mut seen = HashSet::new();
    let mut suggestions = Vec::new();
    let mut skipped_rows = Vec::new();
    let mut duplicate_count = 0_u64;
    let mut skipped_count = 0_u64;
    for (index, row) in rows.iter().enumerate() {
        let parts = [row.artist.trim(), row.title.trim(), row.album.trim()]
            .into_iter()
            .filter(|part| !part.is_empty())
            .collect::<Vec<_>>();
        let search_text = if parts.len() >= 2 || row.artist.trim().is_empty() {
            parts.join(" ")
        } else {
            String::new()
        };
        if search_text.is_empty() {
            skipped_count += 1;
            skipped_rows.push(serde_json::json!({
                "rowNumber": index + 1,
                "reason": "Missing artist/title metadata",
                "rawText": row.raw_text,
            }));
            continue;
        }
        let normalized = search_text
            .split_whitespace()
            .collect::<Vec<_>>()
            .join(" ")
            .to_ascii_lowercase();
        let evidence_key = format!("spotify:{}:{normalized}", row.source);
        if !seen.insert(evidence_key.clone()) {
            duplicate_count += 1;
            continue;
        }
        suggestions.push(serde_json::json!({
            "title": if row.title.trim().is_empty() { search_text.as_str() } else { row.title.as_str() },
            "artist": row.artist,
            "album": row.album,
            "searchText": search_text,
            "source": row.source,
            "sourceId": row.source_id,
            "sourceItemId": row.source_id,
            "providerUrl": row.provider_url,
            "evidenceKey": evidence_key,
            "reason": format!("Imported from spotify {}.", target.kind),
        }));
    }
    serde_json::json!({
        "provider": "spotify",
        "sourceKind": target.kind,
        "sourceId": target.id,
        "totalRows": rows.len(),
        "suggestionCount": suggestions.len(),
        "duplicateCount": duplicate_count,
        "skippedCount": skipped_count,
        "networkRequestCount": network_request_count,
        "requiresAccessToken": false,
        "requiredScopeHint": "",
        "suggestions": suggestions,
        "skippedRows": skipped_rows,
    })
}

async fn preview_spotify_source_feed(
    state: &AppState,
    source_text: &str,
    provider_access_token: &str,
    limit: usize,
    token_url: &str,
    api_base: &str,
) -> Result<serde_json::Value, String> {
    let target = parse_spotify_source_target(source_text);
    let spotify = state.integration_settings.read().await.spotify.clone();
    let token =
        spotify_source_access_token(state, &spotify, &target, provider_access_token, token_url)
            .await?;
    if token.trim().is_empty() {
        let scope = if target.requires_user_token {
            target.scope_hint.as_str()
        } else {
            "Configure integrations.spotify.client_id/client_secret, connect a Spotify account, or provide a Spotify bearer token."
        };
        return Ok(serde_json::json!({
            "provider": "spotify",
            "sourceKind": target.kind,
            "sourceId": target.id,
            "totalRows": 0,
            "suggestionCount": 0,
            "duplicateCount": 0,
            "skippedCount": 0,
            "networkRequestCount": 0,
            "requiresAccessToken": true,
            "requiredScopeHint": scope,
            "suggestions": [],
            "skippedRows": [],
        }));
    }

    let base = api_base.trim_end_matches('/');
    let mut rows = Vec::new();
    let mut requests = 0_u64;
    match target.kind.as_str() {
        "playlist" => {
            requests +=
                fetch_spotify_playlist_tracks(&spotify, base, &token, &target.id, &mut rows, limit)
                    .await?;
        }
        "album" => {
            let album = spotify_get_json(
                &spotify,
                format!("{base}/albums/{}", url_encode(&target.id)),
                &token,
            )
            .await?;
            requests += 1;
            let album_name = album
                .get("name")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default();
            for track in album
                .pointer("/tracks/items")
                .and_then(serde_json::Value::as_array)
                .into_iter()
                .flatten()
            {
                if let Some(row) =
                    spotify_track_row(track, "spotify:album", &target.id, Some(album_name))
                {
                    rows.push(row);
                }
            }
        }
        "track" => {
            let track = spotify_get_json(
                &spotify,
                format!("{base}/tracks/{}", url_encode(&target.id)),
                &token,
            )
            .await?;
            requests += 1;
            if let Some(row) = spotify_track_row(&track, "spotify:track", &target.id, None) {
                rows.push(row);
            }
        }
        "artist" => {
            let top = spotify_get_json(
                &spotify,
                format!(
                    "{base}/artists/{}/top-tracks?market={}",
                    url_encode(&target.id),
                    url_encode(&spotify.market)
                ),
                &token,
            )
            .await?;
            requests += 1;
            for track in top
                .get("tracks")
                .and_then(serde_json::Value::as_array)
                .into_iter()
                .flatten()
                .take(limit)
            {
                if let Some(row) =
                    spotify_track_row(track, "spotify:artist-top-tracks", &target.id, None)
                {
                    rows.push(row);
                }
            }
        }
        "saved-tracks" => {
            requests += fetch_spotify_track_pages(
                &spotify,
                base,
                &token,
                "/me/tracks",
                "spotify:liked",
                &mut rows,
                limit,
            )
            .await?;
        }
        "saved-albums" => {
            let mut offset = 0_usize;
            while rows.len() < limit {
                let page_limit = 20_usize.min(limit - rows.len());
                let page = spotify_get_json(
                    &spotify,
                    format!("{base}/me/albums?limit={page_limit}&offset={offset}"),
                    &token,
                )
                .await?;
                requests += 1;
                let items = page
                    .get("items")
                    .and_then(serde_json::Value::as_array)
                    .cloned()
                    .unwrap_or_default();
                for item in &items {
                    let album = item.get("album").unwrap_or(&serde_json::Value::Null);
                    let name = album
                        .get("name")
                        .and_then(serde_json::Value::as_str)
                        .unwrap_or_default()
                        .to_owned();
                    let artist = album
                        .get("artists")
                        .and_then(serde_json::Value::as_array)
                        .map(|artists| {
                            artists
                                .iter()
                                .filter_map(|artist| {
                                    artist.get("name").and_then(serde_json::Value::as_str)
                                })
                                .collect::<Vec<_>>()
                                .join(" ")
                        })
                        .unwrap_or_default();
                    rows.push(SpotifySourceRow {
                        title: name.clone(),
                        artist,
                        album: name.clone(),
                        source: "spotify:saved-albums".to_owned(),
                        source_id: album
                            .get("id")
                            .and_then(serde_json::Value::as_str)
                            .unwrap_or_default()
                            .to_owned(),
                        provider_url: album
                            .pointer("/external_urls/spotify")
                            .and_then(serde_json::Value::as_str)
                            .unwrap_or_default()
                            .to_owned(),
                        raw_text: name,
                    });
                }
                if spotify_page_done(&page, items.len(), offset) {
                    break;
                }
                offset = offset.saturating_add(items.len());
            }
        }
        "followed-artists" => {
            let mut after = String::new();
            while rows.len() < limit {
                let page_limit = 50_usize.min(limit - rows.len());
                let after_query = if after.is_empty() {
                    String::new()
                } else {
                    format!("&after={}", url_encode(&after))
                };
                let page = spotify_get_json(
                    &spotify,
                    format!("{base}/me/following?type=artist&limit={page_limit}{after_query}"),
                    &token,
                )
                .await?;
                requests += 1;
                let artists = page
                    .pointer("/artists/items")
                    .and_then(serde_json::Value::as_array)
                    .cloned()
                    .unwrap_or_default();
                for artist in &artists {
                    let name = artist
                        .get("name")
                        .and_then(serde_json::Value::as_str)
                        .unwrap_or_default()
                        .to_owned();
                    rows.push(SpotifySourceRow {
                        title: name.clone(),
                        artist: name.clone(),
                        album: String::new(),
                        source: "spotify:followed-artists".to_owned(),
                        source_id: artist
                            .get("id")
                            .and_then(serde_json::Value::as_str)
                            .unwrap_or_default()
                            .to_owned(),
                        provider_url: artist
                            .pointer("/external_urls/spotify")
                            .and_then(serde_json::Value::as_str)
                            .unwrap_or_default()
                            .to_owned(),
                        raw_text: name,
                    });
                }
                after = page
                    .pointer("/artists/cursors/after")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_default()
                    .to_owned();
                if artists.is_empty() || after.is_empty() {
                    break;
                }
            }
        }
        "playlists" => {
            requests += fetch_spotify_playlist_collection(
                &spotify,
                base,
                &token,
                "/me/playlists",
                &mut rows,
                limit,
            )
            .await?;
        }
        "user" => {
            requests += fetch_spotify_playlist_collection(
                &spotify,
                base,
                &token,
                &format!("/users/{}/playlists", url_encode(&target.id)),
                &mut rows,
                limit,
            )
            .await?;
        }
        _ => {}
    }
    Ok(build_spotify_source_result(&target, rows, requests))
}

fn source_provider(source_text: &str, source_kind: &str) -> Option<&'static str> {
    let normalized = source_kind.replace('.', "").to_ascii_lowercase();
    if normalized != "auto" {
        return match normalized.as_str() {
            "youtube" => Some("youtube"),
            "lastfm" => Some("lastfm"),
            "apple" | "itunes" => Some("apple"),
            "listenbrainz" => Some("listenbrainz"),
            _ => None,
        };
    }
    let url = reqwest::Url::parse(source_text.trim()).ok()?;
    let host = url.host_str()?.to_ascii_lowercase();
    if host == "youtube.com" || host.ends_with(".youtube.com") || host == "youtu.be" {
        Some("youtube")
    } else if host == "last.fm" || host.ends_with(".last.fm") {
        Some("lastfm")
    } else if host == "music.apple.com" || host == "itunes.apple.com" {
        Some("apple")
    } else if host == "bandcamp.com" || host.ends_with(".bandcamp.com") {
        Some("bandcamp")
    } else if host == "listenbrainz.org" || host.ends_with(".listenbrainz.org") {
        Some("listenbrainz")
    } else {
        None
    }
}

fn loose_source_row(text: &str, source: &str, row_number: usize) -> SpotifySourceRow {
    let text = text.trim();
    let (artist, title) = text
        .split_once(" - ")
        .map(|(artist, title)| (artist.trim(), title.trim()))
        .unwrap_or(("", text));
    SpotifySourceRow {
        title: title.to_owned(),
        artist: artist.to_owned(),
        source: source.to_owned(),
        source_id: row_number.to_string(),
        raw_text: text.to_owned(),
        ..Default::default()
    }
}

fn build_provider_source_result(
    provider: &str,
    source_text: &str,
    rows: Vec<SpotifySourceRow>,
    network_request_count: u64,
) -> serde_json::Value {
    let mut result = build_spotify_source_result(
        &SpotifySourceTarget {
            kind: "url".to_owned(),
            id: source_text.to_owned(),
            requires_user_token: false,
            scope_hint: String::new(),
        },
        rows,
        network_request_count,
    );
    result["provider"] = serde_json::json!(provider);
    result["sourceKind"] = serde_json::json!("url");
    result["sourceId"] = serde_json::json!(source_text);
    if let Some(suggestions) = result["suggestions"].as_array_mut() {
        for suggestion in suggestions {
            let source = suggestion["source"].as_str().unwrap_or_default();
            let normalized = suggestion["searchText"]
                .as_str()
                .unwrap_or_default()
                .split_whitespace()
                .collect::<Vec<_>>()
                .join(" ")
                .to_ascii_lowercase();
            suggestion["evidenceKey"] =
                serde_json::json!(format!("{provider}:{source}:{normalized}"));
            suggestion["reason"] = serde_json::json!(format!("Imported from {provider} url."));
        }
    }
    result
}

async fn provider_get_json(
    timeout_seconds: u64,
    url: String,
    label: &str,
) -> Result<serde_json::Value, String> {
    let response = reqwest::Client::builder()
        .timeout(Duration::from_secs(timeout_seconds))
        .redirect(reqwest::redirect::Policy::none())
        .build()
        .map_err(|error| format!("failed to build provider client: {error}"))?
        .get(url)
        .header("User-Agent", "slskdN-source-feed-import/1.0")
        .send()
        .await
        .map_err(|error| format!("{label} request failed: {error}"))?;
    if !response.status().is_success() {
        return Err(format!("{label} returned HTTP {}", response.status()));
    }
    read_bounded_source_provider_json(response, label).await
}

async fn read_bounded_source_provider_bytes(
    response: reqwest::Response,
    label: &str,
) -> Result<Vec<u8>, String> {
    if response
        .content_length()
        .is_some_and(|length| length > MAX_SOURCE_PROVIDER_RESPONSE_BYTES as u64)
    {
        return Err(format!(
            "{label} response exceeds {MAX_SOURCE_PROVIDER_RESPONSE_BYTES} bytes"
        ));
    }
    let mut body = Vec::new();
    let mut stream = response.bytes_stream();
    while let Some(chunk) = stream.next().await {
        let chunk = chunk.map_err(|error| format!("{label} response read failed: {error}"))?;
        if body.len().saturating_add(chunk.len()) > MAX_SOURCE_PROVIDER_RESPONSE_BYTES {
            return Err(format!(
                "{label} response exceeds {MAX_SOURCE_PROVIDER_RESPONSE_BYTES} bytes"
            ));
        }
        body.extend_from_slice(&chunk);
    }
    Ok(body)
}

async fn read_bounded_source_provider_json(
    response: reqwest::Response,
    label: &str,
) -> Result<serde_json::Value, String> {
    let body = read_bounded_source_provider_bytes(response, label).await?;
    serde_json::from_slice(&body).map_err(|error| format!("invalid {label} JSON: {error}"))
}

fn decode_markup_entities(value: &str) -> String {
    let mut decoded = String::with_capacity(value.len());
    let mut remaining = value;
    while let Some(ampersand) = remaining.find('&') {
        decoded.push_str(&remaining[..ampersand]);
        remaining = &remaining[ampersand..];
        let Some(semicolon) = remaining.find(';') else {
            decoded.push_str(remaining);
            return decoded.trim().to_owned();
        };
        let entity = &remaining[1..semicolon];
        let replacement = match entity {
            "amp" => Some('&'),
            "apos" => Some('\''),
            "gt" => Some('>'),
            "lt" => Some('<'),
            "quot" => Some('"'),
            _ if entity.starts_with("#x") || entity.starts_with("#X") => {
                u32::from_str_radix(&entity[2..], 16)
                    .ok()
                    .and_then(char::from_u32)
            }
            _ if entity.starts_with('#') => {
                entity[1..].parse::<u32>().ok().and_then(char::from_u32)
            }
            _ => None,
        };
        if let Some(replacement) = replacement {
            decoded.push(replacement);
        } else {
            decoded.push_str(&remaining[..=semicolon]);
        }
        remaining = &remaining[semicolon + 1..];
    }
    decoded.push_str(remaining);
    decoded.trim().to_owned()
}

fn markup_tag_attributes(tag: &str) -> Vec<(String, String)> {
    let bytes = tag.as_bytes();
    let mut index = 0_usize;
    while index < bytes.len() && !bytes[index].is_ascii_whitespace() {
        index += 1;
    }
    let mut attributes = Vec::new();
    while index < bytes.len() {
        while index < bytes.len()
            && (bytes[index].is_ascii_whitespace() || matches!(bytes[index], b'/' | b'>'))
        {
            index += 1;
        }
        let name_start = index;
        while index < bytes.len()
            && !bytes[index].is_ascii_whitespace()
            && !matches!(bytes[index], b'=' | b'/' | b'>')
        {
            index += 1;
        }
        if name_start == index {
            break;
        }
        let name = tag[name_start..index].to_owned();
        while index < bytes.len() && bytes[index].is_ascii_whitespace() {
            index += 1;
        }
        if bytes.get(index) != Some(&b'=') {
            attributes.push((name, String::new()));
            continue;
        }
        index += 1;
        while index < bytes.len() && bytes[index].is_ascii_whitespace() {
            index += 1;
        }
        let quote = bytes
            .get(index)
            .copied()
            .filter(|byte| matches!(byte, b'\'' | b'"'));
        if quote.is_some() {
            index += 1;
        }
        let value_start = index;
        while index < bytes.len()
            && quote.map_or_else(
                || !bytes[index].is_ascii_whitespace() && !matches!(bytes[index], b'/' | b'>'),
                |quote| bytes[index] != quote,
            )
        {
            index += 1;
        }
        attributes.push((name, decode_markup_entities(&tag[value_start..index])));
        if quote.is_some() && index < bytes.len() {
            index += 1;
        }
    }
    attributes
}

fn metadata_value(html: &str, property: &str) -> String {
    let lower = html.to_ascii_lowercase();
    let mut offset = 0_usize;
    while let Some(relative) = lower[offset..].find("<meta") {
        let start = offset + relative;
        let Some(end_relative) = lower[start..].find('>') else {
            break;
        };
        let end = start + end_relative + 1;
        let attributes = markup_tag_attributes(&html[start + 1..end - 1]);
        let matches_property = attributes.iter().any(|(name, value)| {
            (name.eq_ignore_ascii_case("property") || name.eq_ignore_ascii_case("name"))
                && value.eq_ignore_ascii_case(property)
        });
        if matches_property {
            if let Some((_, value)) = attributes
                .iter()
                .find(|(name, _)| name.eq_ignore_ascii_case("content"))
            {
                return value.clone();
            }
        }
        offset = end;
    }
    String::new()
}

fn metadata_title(html: &str) -> String {
    let lower = html.to_ascii_lowercase();
    let Some(start) = lower.find("<title") else {
        return String::new();
    };
    let Some(open_end_relative) = lower[start..].find('>') else {
        return String::new();
    };
    let content_start = start + open_end_relative + 1;
    let Some(close_relative) = lower[content_start..].find("</title>") else {
        return String::new();
    };
    decode_markup_entities(
        &html[content_start..content_start + close_relative]
            .split_whitespace()
            .collect::<Vec<_>>()
            .join(" "),
    )
}

fn clean_provider_title(title: &str, provider: &str) -> String {
    let mut cleaned = title.trim().to_owned();
    let suffixes: &[&str] = match provider {
        "youtube" => &[" - YouTube"],
        "bandcamp" => &[" | Bandcamp"],
        "lastfm" => &[" | Last.fm", " — Last.fm"],
        "apple" => &[" by Apple Music", " on Apple Music"],
        _ => &[],
    };
    for suffix in suffixes {
        if cleaned
            .get(cleaned.len().saturating_sub(suffix.len())..)
            .is_some_and(|tail| tail.eq_ignore_ascii_case(suffix))
        {
            cleaned.truncate(cleaned.len() - suffix.len());
            cleaned = cleaned.trim().to_owned();
        }
    }
    cleaned.trim_matches('"').to_owned()
}

fn provider_metadata_row(
    provider: &str,
    source_text: &str,
    html: &str,
) -> Option<SpotifySourceRow> {
    let title = [
        metadata_value(html, "music:song"),
        metadata_value(html, "og:title"),
        metadata_value(html, "twitter:title"),
        metadata_title(html),
    ]
    .into_iter()
    .find(|value| !value.trim().is_empty())
    .unwrap_or_default();
    let title = clean_provider_title(&title, provider);
    if title.trim().is_empty() {
        return None;
    }
    let artist = [
        metadata_value(html, "music:musician:description"),
        metadata_value(html, "byl"),
        metadata_value(html, "article:author"),
    ]
    .into_iter()
    .find(|value| !value.trim().is_empty())
    .unwrap_or_default();
    let mut row = loose_source_row(&title, provider, 1);
    if !artist.trim().is_empty() {
        row.artist = artist;
    }
    row.provider_url = source_text.to_owned();
    Some(row)
}

fn validate_provider_metadata_url(
    url: &str,
) -> Result<(reqwest::Url, ResolvedIntegrationTarget), String> {
    let parsed =
        reqwest::Url::parse(url).map_err(|error| format!("provider URL is invalid: {error}"))?;
    if !matches!(parsed.scheme(), "http" | "https") {
        return Err("provider URL scheme must be http or https".to_owned());
    }
    if !parsed.username().is_empty() || parsed.password().is_some() {
        return Err("provider URL must not contain embedded credentials".to_owned());
    }
    if parsed.fragment().is_some() {
        return Err("provider URL must not contain a fragment".to_owned());
    }
    if source_provider(url, "auto").is_none() {
        return Err("provider URL host is not supported".to_owned());
    }
    let host = parsed
        .host_str()
        .ok_or_else(|| "provider URL must include a host".to_owned())?
        .to_owned();
    let port = parsed
        .port_or_known_default()
        .ok_or_else(|| "provider URL port is unknown".to_owned())?;
    let addrs = (host.as_str(), port)
        .to_socket_addrs()
        .map_err(|error| format!("provider URL resolution failed: {error}"))?
        .collect::<Vec<_>>();
    if addrs.is_empty() {
        return Err("provider URL did not resolve".to_owned());
    }
    if addrs
        .iter()
        .any(|address| is_blocked_integration_ip(address.ip()))
    {
        return Err("provider URL resolves to a private address".to_owned());
    }
    Ok((parsed, ResolvedIntegrationTarget { host, addrs }))
}

async fn fetch_provider_metadata_page(
    provider: &str,
    source_text: &str,
    timeout_seconds: u64,
) -> Result<Option<SpotifySourceRow>, String> {
    let (url, resolved) = validate_provider_metadata_url(source_text)?;
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(timeout_seconds))
        .redirect(reqwest::redirect::Policy::none())
        .resolve_to_addrs(&resolved.host, &resolved.addrs)
        .build()
        .map_err(|error| format!("failed to build provider client: {error}"))?;
    let response = client
        .get(url)
        .header("User-Agent", "slskdN-source-feed-import/1.0")
        .send()
        .await
        .map_err(|error| format!("provider metadata request failed: {error}"))?;
    if !response.status().is_success() {
        return Err(format!(
            "provider metadata returned HTTP {}",
            response.status()
        ));
    }
    let body = read_bounded_source_provider_bytes(response, "provider metadata").await?;
    let html = String::from_utf8_lossy(&body);
    Ok(provider_metadata_row(provider, source_text, &html))
}

async fn send_ntfy_notification(
    options: &config::NtfyIntegrationSettings,
    title: &str,
    body: &str,
) -> Result<(), String> {
    let resolved = validate_integration_base_url(&options.url)?;
    send_ntfy_notification_to(options, title, body, &options.url, &resolved).await
}

async fn send_ntfy_notification_to(
    options: &config::NtfyIntegrationSettings,
    title: &str,
    body: &str,
    endpoint: &str,
    resolved: &ResolvedIntegrationTarget,
) -> Result<(), String> {
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(30))
        .redirect(reqwest::redirect::Policy::none())
        .resolve_to_addrs(&resolved.host, &resolved.addrs)
        .build()
        .map_err(|error| format!("failed to build Ntfy client: {error}"))?;
    let mut request = client
        .post(endpoint)
        .header("Title", format!("{}: {title}", options.notification_prefix))
        .header("Content-Type", "text/plain; charset=utf-8")
        .body(body.to_owned());
    if !options.access_token.trim().is_empty() {
        request = request.bearer_auth(&options.access_token);
    }
    let response = request
        .send()
        .await
        .map_err(|error| format!("Ntfy request failed: {error}"))?;
    if !response.status().is_success() {
        return Err(format!("Ntfy returned HTTP {}", response.status()));
    }
    Ok(())
}

async fn send_pushover_notification(
    options: &config::PushoverIntegrationSettings,
    title: &str,
    body: &str,
    endpoint: &str,
) -> Result<(), String> {
    let prefixed_title = format!("{}: {title}", options.notification_prefix);
    let response = reqwest::Client::builder()
        .timeout(Duration::from_secs(30))
        .redirect(reqwest::redirect::Policy::none())
        .build()
        .map_err(|error| format!("failed to build Pushover client: {error}"))?
        .post(endpoint)
        .form(&[
            ("token", options.token.as_str()),
            ("user", options.user_key.as_str()),
            ("title", prefixed_title.as_str()),
            ("message", body),
        ])
        .send()
        .await
        .map_err(|error| format!("Pushover request failed: {error}"))?;
    if !response.status().is_success() {
        return Err(format!("Pushover returned HTTP {}", response.status()));
    }
    Ok(())
}

async fn send_pushbullet_notification(
    options: &config::PushbulletIntegrationSettings,
    title: &str,
    body: &str,
    endpoint: &str,
) -> Result<(), String> {
    let client = reqwest::Client::builder()
        .timeout(Duration::from_secs(30))
        .redirect(reqwest::redirect::Policy::none())
        .build()
        .map_err(|error| format!("failed to build Pushbullet client: {error}"))?;
    let payload = serde_json::json!({"title": format!("{} {title}", options.notification_prefix), "body": body, "type": "note"});
    let attempts = options.retry_attempts.max(1);
    let mut last_error = String::new();
    for _ in 0..attempts {
        match client
            .post(endpoint)
            .header("Access-Token", &options.access_token)
            .header("User-Agent", format!("slskR v{APP_VERSION}"))
            .json(&payload)
            .send()
            .await
        {
            Ok(response) if response.status().is_success() => return Ok(()),
            Ok(response) => last_error = format!("Pushbullet returned HTTP {}", response.status()),
            Err(error) => last_error = format!("Pushbullet request failed: {error}"),
        }
    }
    Err(last_error)
}

async fn send_private_message_notifications(state: &AppState, username: &str, message: &str) {
    let key = format!("notification:pm:{username}");
    if !state
        .private_message_auto_responses
        .write()
        .await
        .should_respond(&key, unix_timestamp(), 30)
    {
        return;
    }
    let integrations = state.integration_settings.read().await.clone();
    let title = format!("Private Message from {username}");
    if integrations.pushbullet.enabled && integrations.pushbullet.notify_on_private_message {
        if integrations.pushbullet.cooldown_time < 0 {
            record_daemon_log(
                state,
                logging::LogLevel::Warn,
                "pushbullet",
                "Pushbullet cooldown is negative".to_owned(),
            )
            .await;
            return;
        }
        let cooldown = u64::try_from(integrations.pushbullet.cooldown_time)
            .unwrap_or_default()
            .saturating_add(999)
            / 1_000;
        let push_key = format!("pushbullet:pm:{username}");
        if state
            .private_message_auto_responses
            .write()
            .await
            .should_respond(&push_key, unix_timestamp(), cooldown)
        {
            if let Err(error) = send_pushbullet_notification(
                &integrations.pushbullet,
                &title,
                message,
                "https://api.pushbullet.com/v2/pushes",
            )
            .await
            {
                record_daemon_log(state, logging::LogLevel::Warn, "pushbullet", error).await;
            }
        }
    }
    if integrations.ntfy.enabled && integrations.ntfy.notify_on_private_message {
        if let Err(error) = send_ntfy_notification(&integrations.ntfy, &title, message).await {
            record_daemon_log(state, logging::LogLevel::Error, "ntfy", error).await;
        }
    }
    if integrations.pushover.enabled && integrations.pushover.notify_on_private_message {
        if let Err(error) = send_pushover_notification(
            &integrations.pushover,
            &title,
            message,
            "https://api.pushover.net/1/messages.json",
        )
        .await
        {
            record_daemon_log(state, logging::LogLevel::Error, "pushover", error).await;
        }
    }
}

async fn send_room_mention_notifications(
    state: &AppState,
    room: &str,
    username: &str,
    message: &str,
) {
    let key = format!("notification:room:{room}:{username}");
    if !state
        .private_message_auto_responses
        .write()
        .await
        .should_respond(&key, unix_timestamp(), 30)
    {
        return;
    }
    let integrations = state.integration_settings.read().await.clone();
    let title = format!("Room Mention by {username} in {room}");
    if integrations.pushbullet.enabled && integrations.pushbullet.notify_on_room_mention {
        if integrations.pushbullet.cooldown_time < 0 {
            record_daemon_log(
                state,
                logging::LogLevel::Warn,
                "pushbullet",
                "Pushbullet cooldown is negative".to_owned(),
            )
            .await;
            return;
        }
        let cooldown = u64::try_from(integrations.pushbullet.cooldown_time)
            .unwrap_or_default()
            .saturating_add(999)
            / 1_000;
        let push_key = format!("pushbullet:room:{room}");
        if state
            .private_message_auto_responses
            .write()
            .await
            .should_respond(&push_key, unix_timestamp(), cooldown)
        {
            if let Err(error) = send_pushbullet_notification(
                &integrations.pushbullet,
                &title,
                message,
                "https://api.pushbullet.com/v2/pushes",
            )
            .await
            {
                record_daemon_log(state, logging::LogLevel::Warn, "pushbullet", error).await;
            }
        }
    }
    if integrations.ntfy.enabled && integrations.ntfy.notify_on_room_mention {
        if let Err(error) = send_ntfy_notification(&integrations.ntfy, &title, message).await {
            record_daemon_log(state, logging::LogLevel::Error, "ntfy", error).await;
        }
    }
    if integrations.pushover.enabled && integrations.pushover.notify_on_room_mention {
        if let Err(error) = send_pushover_notification(
            &integrations.pushover,
            &title,
            message,
            "https://api.pushover.net/1/messages.json",
        )
        .await
        {
            record_daemon_log(state, logging::LogLevel::Error, "pushover", error).await;
        }
    }
}

fn youtube_playlist_id(source_text: &str) -> String {
    reqwest::Url::parse(source_text.trim())
        .ok()
        .and_then(|url| {
            url.query_pairs()
                .find(|(key, _)| key == "list")
                .map(|(_, value)| value.into_owned())
        })
        .unwrap_or_default()
}

fn lastfm_target(source_text: &str) -> (String, &'static str, &'static str) {
    let Ok(url) = reqwest::Url::parse(source_text.trim()) else {
        return (String::new(), "", "");
    };
    let parts = url
        .path_segments()
        .map(|parts| parts.filter(|part| !part.is_empty()).collect::<Vec<_>>())
        .unwrap_or_default();
    let Some(user_index) = parts
        .iter()
        .position(|part| part.eq_ignore_ascii_case("user"))
    else {
        return (String::new(), "", "");
    };
    let user = parts.get(user_index + 1).copied().unwrap_or_default();
    let suffix = parts
        .iter()
        .skip(user_index + 2)
        .copied()
        .collect::<Vec<_>>()
        .join("/")
        .to_ascii_lowercase();
    if suffix.contains("loved") {
        (user.to_owned(), "user.getlovedtracks", "lastfm:loved")
    } else if suffix.contains("toptracks") {
        (user.to_owned(), "user.gettoptracks", "lastfm:top-tracks")
    } else {
        (
            user.to_owned(),
            "user.getrecenttracks",
            "lastfm:recent-tracks",
        )
    }
}

fn apple_source_ids(source_text: &str) -> Vec<String> {
    let Ok(url) = reqwest::Url::parse(source_text.trim()) else {
        return Vec::new();
    };
    if let Some(id) = url
        .query_pairs()
        .find(|(key, _)| key == "i")
        .map(|(_, value)| value.into_owned())
        .filter(|value| !value.trim().is_empty())
    {
        return vec![id];
    }
    url.path_segments()
        .into_iter()
        .flatten()
        .rev()
        .find(|segment| !segment.is_empty() && segment.bytes().all(|byte| byte.is_ascii_digit()))
        .map(|segment| vec![segment.to_owned()])
        .unwrap_or_default()
}

fn listenbrainz_user(source_text: &str) -> String {
    let Ok(url) = reqwest::Url::parse(source_text.trim()) else {
        return String::new();
    };
    let parts = url
        .path_segments()
        .map(|parts| parts.filter(|part| !part.is_empty()).collect::<Vec<_>>())
        .unwrap_or_default();
    parts
        .iter()
        .position(|part| part.eq_ignore_ascii_case("user"))
        .and_then(|index| parts.get(index + 1))
        .copied()
        .unwrap_or_default()
        .to_owned()
}

#[allow(clippy::too_many_arguments)]
async fn preview_configured_provider_source_feed(
    state: &AppState,
    source_text: &str,
    source_kind: &str,
    limit: usize,
    youtube_api_base: &str,
    lastfm_api_base: &str,
    apple_api_base: &str,
    listenbrainz_api_base: &str,
) -> Result<Option<serde_json::Value>, String> {
    let Some(provider) = source_provider(source_text, source_kind) else {
        return Ok(None);
    };
    let integrations = state.integration_settings.read().await.clone();
    let timeout = integrations.spotify.timeout_seconds;
    let mut rows = Vec::new();
    let mut requests = 0_u64;
    match provider {
        "youtube" => {
            let playlist_id = youtube_playlist_id(source_text);
            if integrations.youtube.configured() && !playlist_id.is_empty() {
                let api_key = integrations.youtube.api_key.as_deref().unwrap_or_default();
                let mut page_token = String::new();
                while rows.len() < limit {
                    let page_limit = 50_usize.min(limit - rows.len());
                    let page_query = if page_token.is_empty() {
                        String::new()
                    } else {
                        format!("&pageToken={}", url_encode(&page_token))
                    };
                    let page = provider_get_json(
                        timeout,
                        format!(
                            "{}?part=snippet&maxResults={page_limit}&playlistId={}&key={}{page_query}",
                            youtube_api_base.trim_end_matches('/'),
                            url_encode(&playlist_id),
                            url_encode(api_key),
                        ),
                        "YouTube",
                    )
                    .await?;
                    requests += 1;
                    let items = page
                        .get("items")
                        .and_then(serde_json::Value::as_array)
                        .cloned()
                        .unwrap_or_default();
                    let starting_row = rows.len();
                    for (index, item) in items.iter().enumerate() {
                        let title = item
                            .pointer("/snippet/title")
                            .and_then(serde_json::Value::as_str)
                            .unwrap_or_default();
                        let video_id = item
                            .pointer("/snippet/resourceId/videoId")
                            .and_then(serde_json::Value::as_str)
                            .unwrap_or_default();
                        let mut row =
                            loose_source_row(title, "youtube:playlist", starting_row + index + 1);
                        if !video_id.is_empty() {
                            row.source_id = video_id.to_owned();
                            row.provider_url =
                                format!("https://www.youtube.com/watch?v={}", url_encode(video_id));
                        } else {
                            row.provider_url = source_text.to_owned();
                        }
                        rows.push(row);
                    }
                    page_token = page
                        .get("nextPageToken")
                        .and_then(serde_json::Value::as_str)
                        .unwrap_or_default()
                        .to_owned();
                    if items.is_empty() || page_token.is_empty() {
                        break;
                    }
                }
            }
        }
        "lastfm" => {
            let (user, method, source) = lastfm_target(source_text);
            if integrations.lastfm.configured() && !user.is_empty() {
                let api_key = integrations.lastfm.api_key.as_deref().unwrap_or_default();
                let page = provider_get_json(
                    timeout,
                    format!(
                        "{}?method={method}&user={}&api_key={}&format=json&limit={}",
                        lastfm_api_base.trim_end_matches('/'),
                        url_encode(&user),
                        url_encode(api_key),
                        200_usize.min(limit),
                    ),
                    "Last.fm",
                )
                .await?;
                requests = 1;
                let tracks = page
                    .pointer("/recenttracks/track")
                    .or_else(|| page.pointer("/lovedtracks/track"))
                    .or_else(|| page.pointer("/toptracks/track"))
                    .and_then(serde_json::Value::as_array)
                    .cloned()
                    .unwrap_or_default();
                for (index, track) in tracks.iter().take(limit).enumerate() {
                    let title = track
                        .get("name")
                        .and_then(serde_json::Value::as_str)
                        .unwrap_or_default()
                        .to_owned();
                    rows.push(SpotifySourceRow {
                        title: title.clone(),
                        artist: track
                            .pointer("/artist/name")
                            .or_else(|| track.pointer("/artist/#text"))
                            .and_then(serde_json::Value::as_str)
                            .unwrap_or_default()
                            .to_owned(),
                        album: track
                            .pointer("/album/#text")
                            .and_then(serde_json::Value::as_str)
                            .unwrap_or_default()
                            .to_owned(),
                        source: source.to_owned(),
                        source_id: track
                            .get("mbid")
                            .and_then(serde_json::Value::as_str)
                            .filter(|value| !value.trim().is_empty())
                            .map(str::to_owned)
                            .unwrap_or_else(|| (index + 1).to_string()),
                        provider_url: track
                            .get("url")
                            .and_then(serde_json::Value::as_str)
                            .unwrap_or_default()
                            .to_owned(),
                        raw_text: title,
                    });
                }
            }
        }
        "apple" => {
            for id in apple_source_ids(source_text).into_iter().take(2) {
                let page = provider_get_json(
                    timeout,
                    format!(
                        "{}?id={}&entity=song&limit={}",
                        apple_api_base.trim_end_matches('/'),
                        url_encode(&id),
                        200_usize.min(limit),
                    ),
                    "Apple Music",
                )
                .await?;
                requests += 1;
                for item in page
                    .get("results")
                    .and_then(serde_json::Value::as_array)
                    .into_iter()
                    .flatten()
                    .filter(|item| {
                        item.get("trackName")
                            .and_then(serde_json::Value::as_str)
                            .is_some_and(|value| !value.trim().is_empty())
                    })
                {
                    let title = item
                        .get("trackName")
                        .and_then(serde_json::Value::as_str)
                        .unwrap_or_default()
                        .to_owned();
                    rows.push(SpotifySourceRow {
                        title: title.clone(),
                        artist: item
                            .get("artistName")
                            .and_then(serde_json::Value::as_str)
                            .unwrap_or_default()
                            .to_owned(),
                        album: item
                            .get("collectionName")
                            .and_then(serde_json::Value::as_str)
                            .unwrap_or_default()
                            .to_owned(),
                        source: "apple".to_owned(),
                        source_id: item
                            .get("trackId")
                            .and_then(serde_json::Value::as_i64)
                            .map(|value| value.to_string())
                            .unwrap_or_default(),
                        provider_url: item
                            .get("trackViewUrl")
                            .and_then(serde_json::Value::as_str)
                            .filter(|value| !value.trim().is_empty())
                            .unwrap_or(source_text)
                            .to_owned(),
                        raw_text: title,
                    });
                }
                if rows.len() >= limit {
                    break;
                }
            }
        }
        "listenbrainz" => {
            let user = listenbrainz_user(source_text);
            if !user.is_empty() {
                let page = provider_get_json(
                    timeout,
                    format!(
                        "{}/1/user/{}/listens?count={}",
                        listenbrainz_api_base.trim_end_matches('/'),
                        url_encode(&user),
                        100_usize.min(limit),
                    ),
                    "ListenBrainz",
                )
                .await?;
                requests = 1;
                for (index, listen) in page
                    .pointer("/payload/listens")
                    .and_then(serde_json::Value::as_array)
                    .into_iter()
                    .flatten()
                    .take(limit)
                    .enumerate()
                {
                    let metadata = listen
                        .get("track_metadata")
                        .unwrap_or(&serde_json::Value::Null);
                    let title = metadata
                        .get("track_name")
                        .and_then(serde_json::Value::as_str)
                        .unwrap_or_default()
                        .to_owned();
                    rows.push(SpotifySourceRow {
                        title: title.clone(),
                        artist: metadata
                            .get("artist_name")
                            .and_then(serde_json::Value::as_str)
                            .unwrap_or_default()
                            .to_owned(),
                        album: metadata
                            .get("release_name")
                            .and_then(serde_json::Value::as_str)
                            .unwrap_or_default()
                            .to_owned(),
                        source: "listenbrainz:listens".to_owned(),
                        source_id: metadata
                            .pointer("/additional_info/recording_msid")
                            .and_then(serde_json::Value::as_str)
                            .filter(|value| !value.trim().is_empty())
                            .map(str::to_owned)
                            .unwrap_or_else(|| (index + 1).to_string()),
                        provider_url: source_text.to_owned(),
                        raw_text: title,
                    });
                }
            }
        }
        "bandcamp" => {}
        _ => unreachable!(),
    }
    if rows.is_empty() {
        if let Some(row) = fetch_provider_metadata_page(provider, source_text, timeout).await? {
            rows.push(row);
        }
        requests += 1;
    }
    Ok(Some(build_provider_source_result(
        provider,
        source_text,
        rows.into_iter().take(limit).collect(),
        requests,
    )))
}

fn detect_local_source_kind(source_text: &str) -> &'static str {
    let trimmed = source_text.trim_start();
    if trimmed.to_ascii_lowercase().starts_with("#extm3u")
        || trimmed.to_ascii_lowercase().contains("#extinf")
    {
        "m3u"
    } else if trimmed.to_ascii_lowercase().starts_with("<rss")
        || trimmed.to_ascii_lowercase().starts_with("<feed")
        || trimmed.to_ascii_lowercase().starts_with("<opml")
    {
        "rss"
    } else {
        let first_line = source_text
            .lines()
            .find(|line| !line.trim().is_empty())
            .unwrap_or_default();
        if first_line.contains(',') && first_line.to_ascii_lowercase().contains("track") {
            "csv"
        } else {
            "text"
        }
    }
}

fn local_csv_rows(source_text: &str, include_album: bool) -> Vec<SpotifySourceRow> {
    let rows = parse_wishlist_csv_rows(source_text);
    let Some(first) = rows.first() else {
        return Vec::new();
    };
    let header_names = first
        .iter()
        .map(|value| normalized_wishlist_csv_header(value))
        .collect::<Vec<_>>();
    let has_header = header_names.iter().any(|value| {
        matches!(
            value.as_str(),
            "trackname"
                | "track"
                | "title"
                | "songname"
                | "song"
                | "artistname"
                | "artist"
                | "artists"
                | "albumname"
                | "album"
        )
    });
    let title_index = has_header
        .then(|| {
            wishlist_csv_column(
                first,
                &["trackname", "track", "title", "songname", "song", "name"],
            )
        })
        .flatten()
        .unwrap_or(0);
    let artist_index = has_header
        .then(|| wishlist_csv_column(first, &["artistname", "artistnames", "artists", "artist"]))
        .flatten()
        .unwrap_or(1);
    let album_index = has_header
        .then(|| wishlist_csv_column(first, &["albumname", "album", "release"]))
        .flatten()
        .unwrap_or(2);
    let url_index = has_header
        .then(|| wishlist_csv_column(first, &["url", "spotifyurl", "trackurl", "link"]))
        .flatten();
    rows.iter()
        .enumerate()
        .skip(usize::from(has_header))
        .map(|(index, row)| {
            let cell = |column: usize| {
                row.get(column)
                    .map(|value| value.trim())
                    .unwrap_or_default()
            };
            let title = cell(title_index).to_owned();
            SpotifySourceRow {
                title: title.clone(),
                artist: cell(artist_index).to_owned(),
                album: if include_album {
                    cell(album_index).to_owned()
                } else {
                    String::new()
                },
                source: "csv".to_owned(),
                source_id: (index + 1).to_string(),
                provider_url: url_index
                    .and_then(|column| row.get(column))
                    .map(|value| value.trim().to_owned())
                    .unwrap_or_default(),
                raw_text: row.join(","),
            }
        })
        .collect()
}

fn local_playlist_rows(source_text: &str) -> Vec<SpotifySourceRow> {
    source_text
        .lines()
        .enumerate()
        .filter_map(|(index, line)| {
            let line = line.trim();
            if !line
                .get(..8)
                .is_some_and(|prefix| prefix.eq_ignore_ascii_case("#EXTINF:"))
            {
                return None;
            }
            let title = line.rsplit_once(',')?.1;
            Some(loose_source_row(title, "m3u", index + 1))
        })
        .collect()
}

fn local_xml_values(source_text: &str, element: &str) -> Vec<String> {
    let lower = String::from_utf8(
        source_text
            .as_bytes()
            .iter()
            .map(u8::to_ascii_lowercase)
            .collect(),
    )
    .expect("ASCII case conversion preserves UTF-8");
    let mut values = Vec::new();
    let mut offset = 0_usize;
    while let Some(relative) = lower[offset..].find('<') {
        let start = offset + relative;
        let Some(tag_end_relative) = lower[start..].find('>') else {
            break;
        };
        let tag_end = start + tag_end_relative;
        let tag = source_text[start + 1..tag_end].trim();
        if tag.starts_with('/') || tag.starts_with('!') || tag.starts_with('?') {
            offset = tag_end + 1;
            continue;
        }
        let tag_name = tag
            .split_ascii_whitespace()
            .next()
            .unwrap_or_default()
            .trim_end_matches('/');
        if !tag_name
            .rsplit(':')
            .next()
            .is_some_and(|name| name.eq_ignore_ascii_case(element))
        {
            offset = tag_end + 1;
            continue;
        }
        let close = format!("</{}>", tag_name.to_ascii_lowercase());
        let content_start = start + tag_end_relative + 1;
        let Some(close_relative) = lower[content_start..].find(&close) else {
            offset = tag_end + 1;
            continue;
        };
        let content_end = content_start + close_relative;
        values.push(decode_markup_entities(
            source_text[content_start..content_end].trim(),
        ));
        offset = content_end + close.len();
    }
    values
}

fn local_xml_rows(source_text: &str) -> Vec<SpotifySourceRow> {
    let mut rows = Vec::new();
    let lower = source_text.to_ascii_lowercase();
    let mut offset = 0_usize;
    while let Some(relative) = lower[offset..].find('<') {
        let start = offset + relative;
        let Some(tag_end_relative) = lower[start..].find('>') else {
            break;
        };
        let tag_end = start + tag_end_relative;
        let tag = source_text[start + 1..tag_end].trim();
        let tag_name = tag
            .split_ascii_whitespace()
            .next()
            .unwrap_or_default()
            .trim_end_matches('/');
        let local_name = tag_name.rsplit(':').next().unwrap_or_default();
        if !tag.starts_with('/')
            && (local_name.eq_ignore_ascii_case("item") || local_name.eq_ignore_ascii_case("entry"))
        {
            let close = format!("</{}>", tag_name.to_ascii_lowercase());
            let content_start = tag_end + 1;
            if let Some(close_relative) = lower[content_start..].find(&close) {
                let content_end = content_start + close_relative;
                let container = &source_text[content_start..content_end];
                let title = local_xml_values(container, "title")
                    .into_iter()
                    .next()
                    .unwrap_or_default();
                rows.push(loose_source_row(&title, "rss", rows.len() + 1));
                offset = content_end + close.len();
                continue;
            }
        }
        offset = tag_end + 1;
    }

    let mut outline_index = 0_usize;
    let mut offset = 0_usize;
    while let Some(relative) = lower[offset..].find('<') {
        let start = offset + relative;
        let Some(tag_end_relative) = lower[start..].find('>') else {
            break;
        };
        let tag_end = start + tag_end_relative;
        let tag = source_text[start + 1..tag_end].trim();
        let tag_name = tag
            .split_ascii_whitespace()
            .next()
            .unwrap_or_default()
            .trim_end_matches('/');
        if !tag.starts_with('/')
            && tag_name
                .rsplit(':')
                .next()
                .is_some_and(|name| name.eq_ignore_ascii_case("outline"))
        {
            outline_index += 1;
            let attributes = markup_tag_attributes(tag);
            let text = attributes
                .iter()
                .find(|(name, _)| name == "text")
                .or_else(|| attributes.iter().find(|(name, _)| name == "title"))
                .map(|(_, value)| value.as_str())
                .unwrap_or_default();
            rows.push(loose_source_row(text, "opml", outline_index));
        }
        offset = tag_end + 1;
    }
    rows
}

fn preview_local_source_feed(
    source_text: &str,
    requested_kind: &str,
    include_album: bool,
    limit: usize,
) -> serde_json::Value {
    let kind = if requested_kind == "auto" {
        detect_local_source_kind(source_text)
    } else {
        requested_kind
    };
    let rows = match kind {
        "csv" => local_csv_rows(source_text, include_album),
        "m3u" | "pls" => local_playlist_rows(source_text),
        "rss" | "opml" => local_xml_rows(source_text),
        _ => source_text
            .lines()
            .filter(|line| !line.trim().is_empty())
            .enumerate()
            .map(|(index, line)| loose_source_row(line, "text", index + 1))
            .collect(),
    };
    let mut result =
        build_provider_source_result("local", "", rows.into_iter().take(limit).collect(), 0);
    result["sourceKind"] = serde_json::json!(kind);
    result["sourceId"] = serde_json::json!("");
    if let Some(suggestions) = result["suggestions"].as_array_mut() {
        for suggestion in suggestions {
            suggestion["reason"] = serde_json::json!(format!("Imported from local {kind}."));
        }
    }
    result
}

fn html_escape(value: &str) -> String {
    value
        .replace('&', "&amp;")
        .replace('<', "&lt;")
        .replace('>', "&gt;")
        .replace('"', "&quot;")
        .replace('\'', "&#39;")
}

fn spotify_callback_html(message: &str) -> String {
    format!(
        "<!doctype html>\n<html>\n  <head><title>Spotify Connection</title></head>\n  <body>\n    <p>{}</p>\n    <script>\n      if (window.opener) {{\n        window.opener.postMessage({{ type: 'slskdn:spotify-connected' }}, window.location.origin);\n      }}\n    </script>\n  </body>\n</html>",
        html_escape(message)
    )
}

async fn fetch_lidarr_system_status(
    lidarr: &config::LidarrIntegrationSettings,
) -> Result<serde_json::Value, String> {
    let base_url = lidarr
        .url
        .as_deref()
        .ok_or("Lidarr URL is not configured")?;
    let resolved = validate_lidarr_base_url(base_url)?;
    let api_key = lidarr
        .api_key
        .as_deref()
        .ok_or("Lidarr API key is not configured")?;
    let url = format!("{}/api/v1/system/status", base_url.trim_end_matches('/'));
    let mut client_builder = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(lidarr.timeout_seconds))
        .redirect(reqwest::redirect::Policy::none());
    for addr in &resolved.addrs {
        client_builder = client_builder.resolve(&resolved.host, *addr);
    }
    let client = client_builder
        .build()
        .map_err(|error| format!("failed to build Lidarr client: {error}"))?;
    let response = client
        .get(url)
        .header("X-Api-Key", api_key)
        .send()
        .await
        .map_err(|error| format!("Lidarr status request failed: {error}"))?;
    if !response.status().is_success() {
        return Err(format!("Lidarr returned HTTP {}", response.status()));
    }
    read_bounded_integration_json(response, "Lidarr status").await
}

async fn fetch_lidarr_wanted_missing(
    lidarr: &config::LidarrIntegrationSettings,
    page: u64,
    page_size: u64,
) -> Result<serde_json::Value, String> {
    let base_url = lidarr
        .url
        .as_deref()
        .ok_or("Lidarr URL is not configured")?;
    let resolved = validate_lidarr_base_url(base_url)?;
    let api_key = lidarr
        .api_key
        .as_deref()
        .ok_or("Lidarr API key is not configured")?;
    let url = format!(
        "{}/api/v1/wanted/missing?page={}&pageSize={}&includeArtist=true&monitored=true",
        base_url.trim_end_matches('/'),
        page.max(1),
        page_size.clamp(1, 250),
    );
    let mut client_builder = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(lidarr.timeout_seconds))
        .redirect(reqwest::redirect::Policy::none());
    for addr in &resolved.addrs {
        client_builder = client_builder.resolve(&resolved.host, *addr);
    }
    let client = client_builder
        .build()
        .map_err(|error| format!("failed to build Lidarr client: {error}"))?;
    let response = client
        .get(url)
        .header("X-Api-Key", api_key)
        .send()
        .await
        .map_err(|error| format!("Lidarr wanted request failed: {error}"))?;
    if !response.status().is_success() {
        return Err(format!("Lidarr returned HTTP {}", response.status()));
    }
    read_bounded_integration_json(response, "Lidarr wanted").await
}

/// Convert Lidarr's allowed quality tree into the same literal filter syntax
/// consumed by wishlist candidate selection. `None` means the profile is
/// intentionally unrestricted; `Some("")` means it contained no recognized
/// quality and therefore must not replace the operator's configured filter.
fn lidarr_quality_profile_filter(profile: &serde_json::Value) -> Option<String> {
    fn quality_name(item: &serde_json::Value) -> String {
        item.pointer("/quality/name")
            .or_else(|| item.get("name"))
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default()
            .trim()
            .to_ascii_lowercase()
    }
    fn visit(item: &serde_json::Value, filters: &mut Vec<String>, seen: &mut HashSet<String>) -> bool {
        let name = quality_name(item);
        let allowed = item
            .get("allowed")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false);
        if allowed && (name.contains("any") || name.contains("all")) {
            return true;
        }
        if allowed {
            let mut formats = Vec::new();
            let mut add = |format: &str| {
                if !formats.iter().any(|value: &String| value == format) {
                    formats.push(format.to_owned());
                }
            };
            if name.contains("lossless") {
                for format in ["flac", "alac", "m4a", "wav", "ape", "aiff", "aif"] {
                    add(format);
                }
            }
            if name.contains("lossy") {
                for format in ["mp3", "aac", "m4a", "ogg", "oga", "opus"] {
                    add(format);
                }
            }
            for (needle, format) in [
                ("mp3", "mp3"),
                ("flac", "flac"),
                ("alac", "alac"),
                ("aac", "aac"),
                ("vorbis", "ogg"),
                ("ogg", "ogg"),
                ("opus", "opus"),
                ("ape", "ape"),
                ("wav", "wav"),
                ("aiff", "aiff"),
                ("aif", "aif"),
                ("m4a", "m4a"),
            ] {
                if name.contains(needle) {
                    add(format);
                }
            }
            let bitrate = name
                .split(|character: char| !character.is_ascii_digit())
                .filter_map(|part| part.parse::<u32>().ok())
                .find(|value| (32..=1_000).contains(value));
            for format in formats {
                let filter = bitrate
                    .map(|value| format!("{format} minbr:{value}"))
                    .unwrap_or(format);
                if seen.insert(filter.clone()) {
                    filters.push(filter);
                }
            }
        }
        item.get("items")
            .and_then(serde_json::Value::as_array)
            .is_some_and(|items| items.iter().any(|child| visit(child, filters, seen)))
    }

    let mut filters = Vec::new();
    let mut seen = HashSet::new();
    let unrestricted = profile
        .get("items")
        .and_then(serde_json::Value::as_array)
        .is_some_and(|items| items.iter().any(|item| visit(item, &mut filters, &mut seen)));
    if unrestricted {
        None
    } else {
        Some(filters.join(" OR "))
    }
}

async fn sync_lidarr_wanted_to_wishlist(
    state: &AppState,
    lidarr: &config::LidarrIntegrationSettings,
) -> Result<serde_json::Value, String> {
    let mut wanted_count = 0_u64;
    let mut created_count = 0_u64;
    let mut duplicate_count = 0_u64;
    let mut skipped_count = 0_u64;
    if !lidarr.enabled {
        return Ok(serde_json::json!({
            "enabled": false,
            "wantedCount": wanted_count,
            "createdCount": created_count,
            "duplicateCount": duplicate_count,
            "skippedCount": skipped_count,
        }));
    }

    let mut existing = state
        .wishlist
        .read()
        .await
        .records
        .iter()
        .flat_map(|record| record.items.iter())
        .map(|item| {
            format!(
                "{}\u{1f}{}",
                item.search_text().trim().to_ascii_lowercase(),
                item.filter.trim().to_ascii_lowercase()
            )
        })
        .collect::<HashSet<_>>();
    let mut page = 1_u64;
    const PAGE_SIZE: u64 = 250;
    let mut quality_profiles: Option<Vec<serde_json::Value>> = None;
    let mut monitored_releases = BTreeMap::<i64, Option<serde_json::Value>>::new();

    loop {
        let response = fetch_lidarr_wanted_missing(lidarr, page, PAGE_SIZE).await?;
        wanted_count = response
            .get("totalRecords")
            .and_then(serde_json::Value::as_u64)
            .unwrap_or_default();
        let raw_records = response
            .get("records")
            .and_then(serde_json::Value::as_array)
            .cloned()
            .unwrap_or_default();
        if raw_records.is_empty() {
            break;
        }

        let mut records = Vec::with_capacity(raw_records.len());
        for mut album in raw_records {
            let album_id = album
                .get("id")
                .and_then(serde_json::Value::as_i64)
                .filter(|value| *value > 0);
            let quality_profile_id = album
                .get("profileId")
                .or_else(|| album.pointer("/artist/qualityProfileId"))
                .and_then(serde_json::Value::as_i64)
                .filter(|value| *value > 0);
            if quality_profile_id.is_some() && quality_profiles.is_none() {
                quality_profiles = Some(
                    fetch_lidarr_json_get(lidarr, "/api/v1/qualityprofile", "quality profiles")
                        .await?
                        .as_array()
                        .cloned()
                        .unwrap_or_default(),
                );
            }
            let mut selected_filter = lidarr.wishlist_filter.clone();
            if let Some(profile_id) = quality_profile_id {
                if let Some(profile) = quality_profiles.as_ref().and_then(|profiles| {
                    profiles.iter().find(|profile| {
                        profile.get("id").and_then(serde_json::Value::as_i64) == Some(profile_id)
                    })
                }) {
                    match lidarr_quality_profile_filter(profile) {
                        Some(filter) if !filter.is_empty() => selected_filter = filter,
                        None => selected_filter.clear(),
                        _ => {}
                    }
                }
            }
            let monitored_release = if let Some(album_id) = album_id {
                let needs_release_fetch = matches!(
                    monitored_releases.entry(album_id),
                    std::collections::btree_map::Entry::Vacant(_)
                );
                if needs_release_fetch {
                    let release = fetch_lidarr_json_get(
                        lidarr,
                        &format!("/api/v1/album/{album_id}"),
                        "album release detail",
                    )
                    .await
                    .ok()
                    .and_then(|detail| {
                        detail
                            .get("releases")
                            .and_then(serde_json::Value::as_array)
                            .and_then(|releases| {
                                releases
                                    .iter()
                                    .find(|release| {
                                        release
                                            .get("monitored")
                                            .and_then(serde_json::Value::as_bool)
                                            .unwrap_or(false)
                                    })
                                    .or_else(|| releases.first())
                                    .cloned()
                            })
                    });
                    monitored_releases.insert(album_id, release);
                }
                monitored_releases.get(&album_id).cloned().flatten()
            } else {
                None
            };
            let track_file_count = album
                .pointer("/statistics/trackFileCount")
                .and_then(serde_json::Value::as_i64)
                .unwrap_or_default();
            let total_track_count = album
                .pointer("/statistics/trackCount")
                .and_then(serde_json::Value::as_i64)
                .or_else(|| {
                    album
                        .pointer("/statistics/totalTrackCount")
                        .and_then(serde_json::Value::as_i64)
                })
                .unwrap_or_default();
            let partially_missing = album_id.is_some()
                && track_file_count > 0
                && total_track_count > track_file_count;
            let expected_track_count = monitored_release
                .as_ref()
                .and_then(|release| release.get("trackCount"))
                .and_then(serde_json::Value::as_i64)
                .filter(|value| *value > 0)
                .or_else(|| (total_track_count > 0).then_some(total_track_count));
            let release_duration_seconds = monitored_release
                .as_ref()
                .and_then(|release| release.get("duration"))
                .and_then(serde_json::Value::as_i64)
                .filter(|value| *value > 0)
                .map(|value| (value / 1_000).max(1));
            let release_disambiguation = monitored_release
                .as_ref()
                .and_then(|release| {
                    release
                        .get("disambiguation")
                        .or_else(|| release.get("title"))
                })
                .and_then(serde_json::Value::as_str)
                .map(str::trim)
                .filter(|value| !value.is_empty())
                .map(str::to_owned);
            album["__slskrSelectedFilter"] = serde_json::json!(selected_filter);
            album["__slskrExpectedTrackCount"] = expected_track_count
                .map(serde_json::Value::from)
                .unwrap_or(serde_json::Value::Null);
            album["__slskrReleaseDurationSeconds"] = release_duration_seconds
                .map(serde_json::Value::from)
                .unwrap_or(serde_json::Value::Null);
            album["__slskrReleaseDisambiguation"] = release_disambiguation
                .clone()
                .map(serde_json::Value::from)
                .unwrap_or(serde_json::Value::Null);
            if let Some(album_id) = album_id.filter(|_| partially_missing) {
                let tracks = fetch_lidarr_json_get(
                    lidarr,
                    &format!("/api/v1/track?albumId={album_id}"),
                    "album tracks",
                )
                .await?
                .as_array()
                .cloned()
                .unwrap_or_default();
                let album_title = album
                    .get("title")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_default()
                    .trim();
                let artist = album
                    .pointer("/artist/artistName")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_default()
                    .trim();
                let missing_tracks = tracks
                    .into_iter()
                    .filter(|track| {
                        !track
                            .get("hasFile")
                            .and_then(serde_json::Value::as_bool)
                            .unwrap_or(false)
                            && track
                                .get("trackFileId")
                                .and_then(serde_json::Value::as_i64)
                                .unwrap_or_default()
                                <= 0
                    })
                    .filter_map(|track| {
                        let track_id = track
                            .get("id")
                            .and_then(serde_json::Value::as_i64)
                            .filter(|value| *value > 0)?;
                        let track_title = track
                            .get("title")
                            .and_then(serde_json::Value::as_str)
                            .unwrap_or_default()
                            .trim();
                        if track_title.is_empty() {
                            return None;
                        }
                        let track_number = track
                            .get("trackNumber")
                            .map(|value| match value {
                                serde_json::Value::String(value) => value.clone(),
                                value => value.to_string(),
                            })
                            .unwrap_or_default();
                        let title = [album_title, track_number.trim(), track_title]
                            .into_iter()
                            .filter(|value| !value.is_empty())
                            .collect::<Vec<_>>()
                            .join(" ");
                        let search_text = [artist, title.as_str()]
                            .into_iter()
                            .filter(|value| !value.is_empty())
                            .collect::<Vec<_>>()
                            .join(" ");
                        let duration_seconds = track
                            .get("duration")
                            .and_then(serde_json::Value::as_i64)
                            .filter(|value| *value > 0)
                            .map(|value| (value / 1_000).max(1));
                        Some(serde_json::json!({
                            "id": track_id,
                            "artist": artist,
                            "title": title,
                            "searchText": search_text,
                            "durationSeconds": duration_seconds,
                            "releaseDisambiguation": release_disambiguation.clone(),
                        }))
                    })
                    .collect::<Vec<_>>();
                album["__slskrPartialAlbum"] = serde_json::json!(true);
                album["__slskrMissingTracks"] = serde_json::Value::Array(missing_tracks);
            }
            records.push(album);
        }

        let mut created = Vec::new();
        let mut updated = Vec::new();
        let mut reached_cap = false;
        {
            let mut wishlist = state.wishlist.write().await;
            for album in records {
                if created_count.saturating_add(created.len() as u64) >= lidarr.max_items_per_sync {
                    reached_cap = true;
                    break;
                }
                let title = album
                    .get("title")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_default()
                    .trim()
                    .to_owned();
                let artist = album
                    .pointer("/artist/artistName")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_default()
                    .trim()
                    .to_owned();
                let selected_filter = album
                    .get("__slskrSelectedFilter")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or(lidarr.wishlist_filter.as_str())
                    .to_owned();
                let lidarr_album_id = album
                    .get("id")
                    .and_then(serde_json::Value::as_i64)
                    .filter(|value| *value > 0);
                let lidarr_track_count = album
                    .pointer("/statistics/trackCount")
                    .and_then(serde_json::Value::as_i64)
                    .or_else(|| {
                        album
                            .pointer("/statistics/totalTrackCount")
                            .and_then(serde_json::Value::as_i64)
                    })
                    .filter(|value| *value > 0);
                let expected_track_count = album
                    .get("__slskrExpectedTrackCount")
                    .and_then(serde_json::Value::as_i64)
                    .filter(|value| *value > 0);
                let release_duration_seconds = album
                    .get("__slskrReleaseDurationSeconds")
                    .and_then(serde_json::Value::as_i64)
                    .filter(|value| *value > 0);
                let release_disambiguation = album
                    .get("__slskrReleaseDisambiguation")
                    .and_then(serde_json::Value::as_str)
                    .map(str::to_owned);
                let lidarr_track_count = expected_track_count.or(lidarr_track_count);
                let lidarr_duration_seconds = release_duration_seconds.or_else(|| {
                    album
                        .get("duration")
                        .and_then(serde_json::Value::as_i64)
                        .filter(|value| *value > 0)
                        .map(|value| (value / 1_000).max(1))
                });
                let lidarr_release_disambiguation = release_disambiguation.clone().or_else(|| {
                    album
                        .get("disambiguation")
                        .or_else(|| album.get("releaseDisambiguation"))
                        .and_then(serde_json::Value::as_str)
                        .map(str::trim)
                        .filter(|value| !value.is_empty())
                        .map(str::to_owned)
                });
                let search_text = match (artist.is_empty(), title.is_empty()) {
                    (true, true) => String::new(),
                    (true, false) => title.clone(),
                    (false, true) => artist.clone(),
                    (false, false) => format!("{artist} {title}"),
                };
                if search_text.is_empty() {
                    skipped_count = skipped_count.saturating_add(1);
                    continue;
                }

                if album
                    .get("__slskrPartialAlbum")
                    .and_then(serde_json::Value::as_bool)
                    .unwrap_or(false)
                {
                    if let Some(album_id) = lidarr_album_id {
                        let missing_track_ids = album
                            .get("__slskrMissingTracks")
                            .and_then(serde_json::Value::as_array)
                            .into_iter()
                            .flatten()
                            .filter_map(|track| track.get("id").and_then(serde_json::Value::as_i64))
                            .collect::<HashSet<_>>();
                        updated.extend(
                            wishlist.disable_lidarr_items_for_album(
                                album_id,
                                &missing_track_ids,
                            ),
                        );
                    }
                    let missing_tracks = album
                        .get("__slskrMissingTracks")
                        .and_then(serde_json::Value::as_array)
                        .cloned()
                        .unwrap_or_default();
                    if missing_tracks.is_empty() {
                        skipped_count = skipped_count.saturating_add(1);
                        continue;
                    }
                    for track in missing_tracks {
                        if created_count.saturating_add(created.len() as u64)
                            >= lidarr.max_items_per_sync
                        {
                            reached_cap = true;
                            break;
                        }
                        let track_id = track
                            .get("id")
                            .and_then(serde_json::Value::as_i64)
                            .filter(|value| *value > 0);
                        let artist = track
                            .get("artist")
                            .and_then(serde_json::Value::as_str)
                            .unwrap_or_default()
                            .to_owned();
                        let title = track
                            .get("title")
                            .and_then(serde_json::Value::as_str)
                            .unwrap_or_default()
                            .to_owned();
                        let search_text = track
                            .get("searchText")
                            .and_then(serde_json::Value::as_str)
                            .unwrap_or_default()
                            .trim()
                            .to_owned();
                        if search_text.is_empty() {
                            skipped_count = skipped_count.saturating_add(1);
                            continue;
                        }
                        let key = format!(
                            "{}\u{1f}{}",
                            search_text.to_ascii_lowercase(),
                            selected_filter.trim().to_ascii_lowercase()
                        );
                        if !existing.insert(key) {
                            duplicate_count = duplicate_count.saturating_add(1);
                            continue;
                        }
                        let item = wishlist.add_item_with_settings(
                            artist,
                            title,
                            "Audio".to_owned(),
                            selected_filter.clone(),
                            true,
                            lidarr.auto_download,
                            usize::try_from(lidarr.wishlist_max_results)
                                .unwrap_or(MAX_WISHLIST_RESULTS),
                            Some(1),
                        );
                        match item {
                            Ok(item) => {
                                let item = wishlist
                                .update_lidarr_metadata(
                                        &item.id,
                                        lidarr_album_id,
                                        track_id,
                                        None,
                                        track
                                            .get("durationSeconds")
                                            .and_then(serde_json::Value::as_i64),
                                        track
                                            .get("releaseDisambiguation")
                                            .and_then(serde_json::Value::as_str)
                                            .map(str::to_owned)
                                            .or_else(|| lidarr_release_disambiguation.clone()),
                                    )
                                    .unwrap_or(item);
                                created.push(item);
                            }
                            Err(()) => {
                                skipped_count = skipped_count.saturating_add(1);
                                reached_cap = true;
                                break;
                            }
                        }
                    }
                    if reached_cap {
                        break;
                    }
                    continue;
                }
                let key = format!(
                    "{}\u{1f}{}",
                    search_text.to_ascii_lowercase(),
                    selected_filter.trim().to_ascii_lowercase()
                );
                if !existing.insert(key) {
                    duplicate_count = duplicate_count.saturating_add(1);
                    continue;
                }
                match wishlist.add_item_with_settings(
                    artist,
                    title,
                    "Audio".to_owned(),
                    selected_filter.clone(),
                    true,
                    lidarr.auto_download,
                    usize::try_from(lidarr.wishlist_max_results).unwrap_or(MAX_WISHLIST_RESULTS),
                    None,
                ) {
                    Ok(item) => {
                        let item = wishlist
                            .update_lidarr_metadata(
                                &item.id,
                                lidarr_album_id,
                                None,
                                lidarr_track_count,
                                lidarr_duration_seconds,
                                lidarr_release_disambiguation,
                            )
                            .unwrap_or(item);
                        created.push(item);
                    }
                    Err(()) => {
                        skipped_count = skipped_count.saturating_add(1);
                        reached_cap = true;
                        break;
                    }
                }
            }
        }
        for item in created.iter().chain(updated.iter()) {
            persist_wishlist_item_checked(state, item).await?;
        }
        created_count = created_count.saturating_add(created.len() as u64);

        if reached_cap || page.saturating_mul(PAGE_SIZE) >= wanted_count {
            break;
        }
        page = page.saturating_add(1);
    }

    let result = serde_json::json!({
        "enabled": true,
        "wantedCount": wanted_count,
        "createdCount": created_count,
        "duplicateCount": duplicate_count,
        "skippedCount": skipped_count,
    });
    {
        let mut sync = state.lidarr_sync_state.write().await;
        sync.last_sync_at = Some(chrono::Utc::now().to_rfc3339());
        sync.last_error = None;
        sync.last_result = Some(result.clone());
    }
    Ok(result)
}

fn lidarr_map_import_path(path: &str, from_prefix: &str, to_prefix: &str) -> String {
    // Lidarr mappings may use POSIX virtual paths even when the daemon runs
    // on Windows; apply that mapping before host Path semantics rewrite them.
    let raw = path.replace('\\', "/");
    let from_virtual = from_prefix.trim_end_matches(['/', '\\']).replace('\\', "/");
    if !from_virtual.is_empty()
        && (raw == from_virtual
            || raw
                .strip_prefix(&from_virtual)
                .is_some_and(|suffix| suffix.starts_with('/')))
    {
        let relative = raw[from_virtual.len()..].trim_start_matches('/');
        let to = to_prefix.trim_end_matches(['/', '\\']);
        let windows_destination = to.contains('\\')
            || to
                .as_bytes()
                .get(1)
                .is_some_and(|separator| *separator == b':');
        return if relative.is_empty() {
            to.to_owned()
        } else if windows_destination {
            format!(r"{to}\{}", relative.replace('/', "\\"))
        } else {
            format!("{to}/{relative}")
        };
    }
    let absolute = if Path::new(path).is_absolute() {
        PathBuf::from(path)
    } else {
        std::env::current_dir()
            .unwrap_or_else(|_| PathBuf::from("/"))
            .join(path)
    };
    let normalized = absolute.to_string_lossy().to_string();
    if from_prefix.trim().is_empty() || to_prefix.trim().is_empty() {
        return normalized;
    }
    let from = from_prefix.trim_end_matches(['/', '\\']);
    let same = normalized == from;
    let child = normalized
        .strip_prefix(from)
        .is_some_and(|suffix| suffix.starts_with('/') || suffix.starts_with('\\'));
    if !same && !child {
        return normalized;
    }
    let relative = normalized[from.len()..].trim_start_matches(['/', '\\']);
    if to_prefix.contains('/') && !to_prefix.contains('\\') {
        let prefix = to_prefix.trim_end_matches(['/', '\\']);
        if relative.is_empty() {
            prefix.to_owned()
        } else {
            format!("{prefix}/{}", relative.replace('\\', "/"))
        }
    } else {
        Path::new(to_prefix)
            .join(relative)
            .to_string_lossy()
            .to_string()
    }
}

fn lidarr_safe_import_candidate(candidate: &serde_json::Value) -> bool {
    let valid_rejections = candidate
        .get("rejections")
        .and_then(serde_json::Value::as_array)
        .is_none_or(|rejections| {
            rejections.iter().all(|rejection| {
                rejection
                    .get("reason")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_default()
                    .to_ascii_lowercase()
                    .contains("missing tracks")
            })
        });
    candidate
        .get("id")
        .and_then(serde_json::Value::as_i64)
        .is_some_and(|value| value > 0)
        && candidate
            .get("path")
            .and_then(serde_json::Value::as_str)
            .is_some_and(|value| !value.trim().is_empty())
        && candidate
            .pointer("/artist/id")
            .and_then(serde_json::Value::as_i64)
            .is_some_and(|value| value > 0)
        && candidate
            .pointer("/album/id")
            .and_then(serde_json::Value::as_i64)
            .is_some_and(|value| value > 0)
        && candidate
            .get("albumReleaseId")
            .and_then(serde_json::Value::as_i64)
            .is_some_and(|value| value > 0)
        && candidate
            .get("tracks")
            .and_then(serde_json::Value::as_array)
            .is_some_and(|value| !value.is_empty())
        && candidate
            .get("quality")
            .is_some_and(|value| !value.is_null())
        && !candidate
            .get("additionalFile")
            .and_then(serde_json::Value::as_bool)
            .unwrap_or(false)
        && valid_rejections
}

fn lidarr_portable_file_name(path: &str) -> String {
    let normalized = path.replace('\\', "/").trim_end_matches('/').to_owned();
    normalized.rsplit('/').next().unwrap_or_default().to_owned()
}

async fn fetch_lidarr_json_get(
    lidarr: &config::LidarrIntegrationSettings,
    path: &str,
    label: &str,
) -> Result<serde_json::Value, String> {
    let base_url = lidarr
        .url
        .as_deref()
        .ok_or("Lidarr URL is not configured")?;
    let resolved = validate_lidarr_base_url(base_url)?;
    let api_key = lidarr
        .api_key
        .as_deref()
        .ok_or("Lidarr API key is not configured")?;
    let url = format!("{}{}", base_url.trim_end_matches('/'), path);
    let mut builder = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(lidarr.timeout_seconds))
        .redirect(reqwest::redirect::Policy::none());
    for addr in &resolved.addrs {
        builder = builder.resolve(&resolved.host, *addr);
    }
    let response = builder
        .build()
        .map_err(|error| format!("failed to build Lidarr client: {error}"))?
        .get(url)
        .header("X-Api-Key", api_key)
        .send()
        .await
        .map_err(|error| format!("Lidarr {label} request failed: {error}"))?;
    if !response.status().is_success() {
        return Err(format!("Lidarr returned HTTP {}", response.status()));
    }
    read_bounded_integration_json(response, &format!("Lidarr {label}"))
        .await
}

async fn lidarr_already_owned_skip_reason(
    lidarr: &config::LidarrIntegrationSettings,
    directory: &str,
) -> Result<Option<String>, String> {
    let release_title = lidarr_portable_file_name(directory);
    if release_title.trim().is_empty() {
        return Ok(None);
    }
    let parsed = fetch_lidarr_json_get(
        lidarr,
        &format!("/api/v1/parse?title={}", url_encode(&release_title)),
        "release parse",
    )
    .await?;
    let artist_id = parsed
        .pointer("/artist/id")
        .and_then(serde_json::Value::as_i64)
        .filter(|value| *value > 0);
    let album_title = parsed
        .pointer("/parsedAlbumInfo/albumTitle")
        .or_else(|| parsed.pointer("/album/albumTitle"))
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty());
    let (Some(artist_id), Some(album_title)) = (artist_id, album_title) else {
        return Ok(None);
    };
    let albums = fetch_lidarr_json_get(
        lidarr,
        &format!("/api/v1/album?artistId={artist_id}"),
        "artist albums",
    )
    .await?;
    let albums = albums.as_array().cloned().unwrap_or_default();
    let owned = albums.into_iter().find(|album| {
        album
            .get("title")
            .and_then(serde_json::Value::as_str)
            .is_some_and(|title| title.eq_ignore_ascii_case(album_title))
            && album
                .pointer("/statistics/totalTrackCount")
                .and_then(serde_json::Value::as_i64)
                .is_some_and(|total| {
                    total > 0
                        && album
                            .pointer("/statistics/trackFileCount")
                            .and_then(serde_json::Value::as_i64)
                            .is_some_and(|files| files >= total)
                })
    });
    Ok(owned.map(|_| {
        format!(
            "Already fully in Lidarr library ({album_title})"
        )
    }))
}

fn lidarr_rejected_filenames(candidates: &[serde_json::Value]) -> Vec<String> {
    let mut seen = HashSet::new();
    candidates
        .iter()
        .filter(|candidate| !lidarr_safe_import_candidate(candidate))
        .filter_map(|candidate| candidate.get("path").and_then(serde_json::Value::as_str))
        .map(lidarr_portable_file_name)
        .filter(|filename| !filename.trim().is_empty())
        .filter(|filename| seen.insert(filename.to_lowercase()))
        .collect()
}

fn delete_lidarr_rejected_files(directory: &str, filenames: &[String]) -> Result<usize, String> {
    let directory = Path::new(directory);
    if !directory.is_dir() {
        return Ok(0);
    }
    let directory = fs::canonicalize(directory)
        .map_err(|error| format!("failed to resolve Lidarr download directory: {error}"))?;
    let mut deleted = 0;
    for filename in filenames {
        let path = directory.join(filename);
        if path.parent() != Some(directory.as_path()) || !path.is_file() {
            continue;
        }
        fs::remove_file(&path).map_err(|error| {
            format!(
                "failed to delete rejected Lidarr file {}: {error}",
                path.display()
            )
        })?;
        deleted += 1;
    }
    Ok(deleted)
}

async fn fetch_lidarr_manual_import_candidates(
    lidarr: &config::LidarrIntegrationSettings,
    directory: &str,
) -> Result<Vec<serde_json::Value>, String> {
    let base_url = lidarr
        .url
        .as_deref()
        .ok_or("Lidarr URL is not configured")?;
    let resolved = validate_lidarr_base_url(base_url)?;
    let api_key = lidarr
        .api_key
        .as_deref()
        .ok_or("Lidarr API key is not configured")?;
    let url = format!(
        "{}/api/v1/manualimport?folder={}&filterExistingFiles=false&replaceExistingFiles={}",
        base_url.trim_end_matches('/'),
        url_encode(directory),
        lidarr.import_replace_existing_files,
    );
    let mut builder = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(lidarr.timeout_seconds))
        .redirect(reqwest::redirect::Policy::none());
    for addr in &resolved.addrs {
        builder = builder.resolve(&resolved.host, *addr);
    }
    let response = builder
        .build()
        .map_err(|error| format!("failed to build Lidarr client: {error}"))?
        .get(url)
        .header("X-Api-Key", api_key)
        .send()
        .await
        .map_err(|error| format!("Lidarr manual import request failed: {error}"))?;
    if !response.status().is_success() {
        return Err(format!("Lidarr returned HTTP {}", response.status()));
    }
    read_bounded_integration_json(response, "Lidarr manual import")
        .await?
        .as_array()
        .cloned()
        .ok_or_else(|| "Lidarr manual import response was not an array".to_owned())
}

async fn import_lidarr_completed_directory_once(
    state: &AppState,
    lidarr: &config::LidarrIntegrationSettings,
    directory: &str,
    bypass_debounce: bool,
) -> Result<serde_json::Value, String> {
    let empty_result = |enabled: bool, auto_import_enabled: bool| {
        serde_json::json!({
            "enabled": enabled,
            "autoImportEnabled": auto_import_enabled,
            "directory": "",
            "candidateCount": 0,
            "safeCandidateCount": 0,
            "rejectedCandidateCount": 0,
            "rejectedFilenames": [],
            "commandId": 0,
            "importMode": "",
            "skippedReason": "",
        })
    };
    if !lidarr.enabled || !lidarr.auto_import_completed {
        return Ok(empty_result(lidarr.enabled, lidarr.auto_import_completed));
    }
    if directory.trim().is_empty() {
        let mut result = empty_result(true, true);
        result["skippedReason"] = serde_json::json!("Directory is empty");
        return Ok(result);
    }

    let mapped_directory =
        lidarr_map_import_path(directory, &lidarr.import_path_from, &lidarr.import_path_to);
    let now = unix_timestamp();
    if !bypass_debounce {
        let mut recent = state.lidarr_recent_imports.write().await;
        recent.retain(|_, processed_at| now.saturating_sub(*processed_at) <= 60 * 60);
        if recent.insert(mapped_directory.clone(), now).is_some() {
            let mut result = empty_result(true, true);
            result["directory"] = serde_json::json!(mapped_directory);
            result["skippedReason"] = serde_json::json!("Recently processed");
            return Ok(result);
        }
    }

    if lidarr.skip_already_owned_albums && !lidarr.import_replace_existing_files {
        match lidarr_already_owned_skip_reason(lidarr, &mapped_directory).await {
            Ok(Some(reason)) => {
                let mut result = empty_result(true, true);
                result["directory"] = serde_json::json!(mapped_directory);
                result["skippedReason"] = serde_json::json!(reason);
                return Ok(result);
            }
            Ok(None) => {}
            Err(error) => {
                record_daemon_log(
                    state,
                    logging::LogLevel::Debug,
                    "lidarr",
                    format!("Lidarr ownership pre-check unavailable: {error}"),
                )
                .await;
            }
        }
    }

    let _permit = state
        .lidarr_import_gate
        .acquire()
        .await
        .map_err(|_| "Lidarr import gate is unavailable".to_owned())?;
    let candidates = fetch_lidarr_manual_import_candidates(lidarr, &mapped_directory).await?;
    let candidate_count = candidates.len();
    let rejected_filenames = lidarr_rejected_filenames(&candidates);
    let mut safe = candidates
        .into_iter()
        .filter(lidarr_safe_import_candidate)
        .collect::<Vec<_>>();
    for candidate in &mut safe {
        candidate["replaceExistingFiles"] = serde_json::json!(lidarr.import_replace_existing_files);
        if candidate
            .pointer("/artist/foreignArtistId")
            .and_then(serde_json::Value::as_str)
            .is_none()
        {
            candidate["artist"]["foreignArtistId"] = serde_json::Value::String(String::new());
        }
    }
    let safe_count = safe.len();
    let rejected_count = candidate_count.saturating_sub(safe_count);
    if safe.is_empty() {
        return Ok(serde_json::json!({
            "enabled": true,
            "autoImportEnabled": true,
            "directory": mapped_directory,
            "candidateCount": candidate_count,
            "safeCandidateCount": 0,
            "rejectedCandidateCount": rejected_count,
            "rejectedFilenames": rejected_filenames,
            "commandId": 0,
            "importMode": "",
            "skippedReason": if candidate_count == 0 {
                "Lidarr found no import candidates"
            } else {
                "Lidarr candidates had rejections or ambiguous matches"
            },
        }));
    }
    let import_mode = if lidarr.import_mode.eq_ignore_ascii_case("copy") {
        "Copy"
    } else {
        "Move"
    };
    let command_id = start_lidarr_manual_import(lidarr, safe, import_mode).await?;
    Ok(serde_json::json!({
        "enabled": true,
        "autoImportEnabled": true,
        "directory": mapped_directory,
        "candidateCount": candidate_count,
        "safeCandidateCount": safe_count,
        "rejectedCandidateCount": rejected_count,
        "rejectedFilenames": rejected_filenames,
        "commandId": command_id,
        "importMode": import_mode,
        "skippedReason": "",
    }))
}

async fn import_lidarr_completed_directory(
    state: &AppState,
    lidarr: &config::LidarrIntegrationSettings,
    directory: &str,
) -> Result<serde_json::Value, String> {
    // Manual imports are explicit user actions: they bypass the automatic
    // completion debounce and do not inherit the automatic delay/retry loop.
    import_lidarr_completed_directory_once(state, lidarr, directory, true).await
}

async fn import_lidarr_completed_directory_automatic(
    state: &AppState,
    lidarr: &config::LidarrIntegrationSettings,
    directory: &str,
) -> Result<serde_json::Value, String> {
    if lidarr.import_delay_seconds > 0 {
        time::sleep(std::time::Duration::from_secs(lidarr.import_delay_seconds)).await;
    }

    let max_attempts = lidarr.import_retry_max_attempts.saturating_add(1).max(1);
    let mut retry_delay = std::time::Duration::from_secs(lidarr.import_retry_delay_seconds);
    let mut last_error = None;
    for attempt in 0..max_attempts {
        // The first attempt participates in the completion debounce. Retries
        // are already part of that same history item and must not turn into a
        // false "recently processed" skip.
        match import_lidarr_completed_directory_once(
            state,
            lidarr,
            directory,
            attempt > 0,
        )
        .await
        {
            Ok(result) => return Ok(result),
            Err(error) => {
                last_error = Some(error);
                if attempt + 1 < max_attempts {
                    time::sleep(retry_delay).await;
                    retry_delay = retry_delay.saturating_mul(2);
                }
            }
        }
    }
    Err(last_error.unwrap_or_else(|| "Lidarr import retry loop exhausted".to_owned()))
}

const LIDARR_IMPORT_HISTORY_PREFIX: &str = "integrations/lidarr/import-history/";

fn lidarr_import_history_key(id: &str) -> String {
    format!("{LIDARR_IMPORT_HISTORY_PREFIX}{id}")
}

fn lidarr_import_history_status(result: &serde_json::Value) -> &'static str {
    if result
        .get("skippedReason")
        .and_then(serde_json::Value::as_str)
        .is_some_and(|reason| !reason.trim().is_empty())
    {
        "Skipped"
    } else if result
        .get("commandId")
        .and_then(serde_json::Value::as_i64)
        .is_some_and(|command_id| command_id > 0)
    {
        "Successful"
    } else {
        "Skipped"
    }
}

fn lidarr_import_history_record(
    id: &str,
    source_directory: &str,
    result: Option<&serde_json::Value>,
    error: Option<&str>,
    retry_of_id: Option<&str>,
) -> serde_json::Value {
    let now = chrono::Utc::now().to_rfc3339();
    let result = result.cloned().unwrap_or_default();
    let status = error
        .map(|_| "Failed")
        .unwrap_or_else(|| lidarr_import_history_status(&result));
    serde_json::json!({
        "id": id,
        "sourceDirectory": source_directory,
        "directory": result.get("directory").cloned().unwrap_or_else(|| serde_json::json!(source_directory)),
        "status": status,
        "errorMessage": error.unwrap_or_default(),
        "skippedReason": result.get("skippedReason").and_then(serde_json::Value::as_str).unwrap_or_default(),
        "candidateCount": result.get("candidateCount").and_then(serde_json::Value::as_u64).unwrap_or_default(),
        "safeCandidateCount": result.get("safeCandidateCount").and_then(serde_json::Value::as_u64).unwrap_or_default(),
        "rejectedCandidateCount": result.get("rejectedCandidateCount").and_then(serde_json::Value::as_u64).unwrap_or_default(),
        "commandId": result.get("commandId").cloned().unwrap_or(serde_json::Value::Null),
        "importMode": result.get("importMode").and_then(serde_json::Value::as_str).unwrap_or_default(),
        "startedAt": now,
        "completedAt": chrono::Utc::now().to_rfc3339(),
        "retryOfId": retry_of_id,
    })
}

fn public_lidarr_import_history_record(mut record: serde_json::Value) -> serde_json::Value {
    if let Some(object) = record.as_object_mut() {
        object.remove("sourceDirectory");
    }
    record
}

async fn persist_lidarr_import_history(
    state: &AppState,
    record: serde_json::Value,
) -> Result<(), String> {
    let id = record
        .get("id")
        .and_then(serde_json::Value::as_str)
        .ok_or_else(|| "Lidarr import history record has no id".to_owned())?;
    state
        .controller_features
        .write()
        .await
        .upsert(lidarr_import_history_key(id), record)
}

async fn list_lidarr_import_history(
    state: &AppState,
    limit: usize,
) -> Vec<serde_json::Value> {
    let mut records = state
        .controller_features
        .read()
        .await
        .values_with_prefix(LIDARR_IMPORT_HISTORY_PREFIX);
    records.sort_by(|left, right| {
        right
            .get("startedAt")
            .and_then(serde_json::Value::as_str)
            .cmp(&left.get("startedAt").and_then(serde_json::Value::as_str))
    });
    records
        .into_iter()
        .take(limit)
        .map(public_lidarr_import_history_record)
        .collect()
}

async fn run_lidarr_import_with_history(
    state: &AppState,
    lidarr: &config::LidarrIntegrationSettings,
    directory: &str,
    retry_of_id: Option<&str>,
) -> Result<serde_json::Value, String> {
    run_lidarr_import_with_history_mode(state, lidarr, directory, retry_of_id, false).await
}

async fn run_lidarr_automatic_import_with_history(
    state: &AppState,
    lidarr: &config::LidarrIntegrationSettings,
    directory: &str,
) -> Result<serde_json::Value, String> {
    run_lidarr_import_with_history_mode(state, lidarr, directory, None, true).await
}

async fn run_lidarr_import_with_history_mode(
    state: &AppState,
    lidarr: &config::LidarrIntegrationSettings,
    directory: &str,
    retry_of_id: Option<&str>,
    automatic: bool,
) -> Result<serde_json::Value, String> {
    let id = uuid::Uuid::new_v4().to_string();
    let result = if automatic {
        import_lidarr_completed_directory_automatic(state, lidarr, directory).await
    } else {
        import_lidarr_completed_directory(state, lidarr, directory).await
    };
    match result {
        Ok(result) => {
            let record = lidarr_import_history_record(
                &id,
                directory,
                Some(&result),
                None,
                retry_of_id,
            );
            persist_lidarr_import_history(state, record).await?;
            Ok(result)
        }
        Err(error) => {
            let record = lidarr_import_history_record(
                &id,
                directory,
                None,
                Some(&error),
                retry_of_id,
            );
            persist_lidarr_import_history(state, record).await?;
            Err(error)
        }
    }
}

fn transfer_remote_directory(filename: &str) -> &str {
    filename
        .rfind(['/', '\\'])
        .map_or("", |separator| &filename[..separator])
}

async fn maybe_import_lidarr_completed_download(state: &AppState, transfer: &TransferEntry) {
    if transfer.direction != 0 || transfer.status != "succeeded" {
        return;
    }
    let Some(local_directory) = transfer
        .local_path
        .as_deref()
        .and_then(|path| Path::new(path).parent())
        .map(|path| path.to_string_lossy().to_string())
    else {
        return;
    };
    let remote_directory = transfer_remote_directory(&transfer.filename);
    let has_pending_file = state
        .transfers
        .read()
        .await
        .entries
        .iter()
        .any(|candidate| {
            candidate.id != transfer.id
                && candidate.direction == 0
                && candidate.peer_username == transfer.peer_username
                && transfer_remote_directory(&candidate.filename) == remote_directory
                && !matches!(
                    candidate.status.as_str(),
                    "succeeded" | "completed" | "cancelled" | "failed" | "rejected"
                )
        });
    if has_pending_file {
        return;
    }
    let lidarr = state.integration_settings.read().await.lidarr.clone();
    if !lidarr.enabled || !lidarr.auto_import_completed {
        return;
    }
    match run_lidarr_automatic_import_with_history(state, &lidarr, &local_directory).await {
        Ok(result) => {
            if result
                .get("rejectedCandidateCount")
                .and_then(serde_json::Value::as_u64)
                .is_some_and(|count| count > 0)
            {
                if let Err(error) =
                    apply_lidarr_rejection_policy(state, transfer, &local_directory, &result).await
                {
                    record_daemon_log(
                        state,
                        logging::LogLevel::Warn,
                        "lidarr",
                        format!(
                            "Lidarr rejected-download policy failed for {local_directory}: {error}"
                        ),
                    )
                    .await;
                }
            }
        }
        Err(error) => {
            record_daemon_log(
                state,
                logging::LogLevel::Warn,
                "lidarr",
                format!("Lidarr auto-import failed for {local_directory}: {error}"),
            )
            .await;
        }
    }
}

/// Issue the controller-side relay download tokens when a local download
/// completes.  The SignalR notification transport is still a separate
/// integration boundary, but token issuance must happen at completion so a
/// connected agent can retry the authenticated HTTP fetch without the old
/// token-passthrough shortcut.
async fn issue_relay_download_tokens(state: &AppState, transfer: &TransferEntry) {
    if transfer.direction != 0 || transfer.status != "succeeded" {
        return;
    }
    let Some(local_path) = transfer.local_path.as_deref() else {
        return;
    };
    let root = effective_downloads_dir(state);
    let Ok(local_path) = ensure_scoped_download_path(&root, local_path) else {
        return;
    };
    let Ok(filename) = local_path.strip_prefix(&root) else {
        return;
    };
    let filename = filename.to_string_lossy().replace('\\', "/");
    let settings = state.advanced_networking.read().await.relay.clone();
    if !settings.enabled || !matches!(settings.mode.as_str(), "controller" | "debug") {
        return;
    }
    let mut relay = state.relay.write().await;
    let issued = relay
        .protocol
        .issue_download_tokens(&filename, unix_timestamp());
    for (agent_name, token) in issued {
        let _ = relay::send_hub_invocation(
            &relay.protocol,
            &agent_name,
            "NotifyFileDownloadCompleted",
            vec![
                serde_json::Value::String(filename.clone()),
                serde_json::Value::String(token),
            ],
        );
    }
}

async fn apply_lidarr_rejection_policy(
    state: &AppState,
    transfer: &TransferEntry,
    local_directory: &str,
    result: &serde_json::Value,
) -> Result<(), String> {
    let options = state.integration_settings.read().await.lidarr.clone();
    let rejected_filenames = result
        .get("rejectedFilenames")
        .and_then(serde_json::Value::as_array)
        .map(|filenames| {
            filenames
                .iter()
                .filter_map(serde_json::Value::as_str)
                .map(str::to_owned)
                .collect::<Vec<_>>()
        })
        .unwrap_or_default();

    if options.blacklist_rejected_downloads {
        let Some(item_id) = transfer.wishlist_item_id.as_deref() else {
            return delete_lidarr_rejected_files_if_enabled(
                &options,
                local_directory,
                &rejected_filenames,
            );
        };
        let Some(username) = transfer
            .peer_username
            .as_deref()
            .filter(|username| !username.trim().is_empty())
        else {
            return delete_lidarr_rejected_files_if_enabled(
                &options,
                local_directory,
                &rejected_filenames,
            );
        };
        let remote_directory = transfer_remote_directory(&transfer.filename);
        if !remote_directory.trim().is_empty() {
            let ignored = {
                let mut wishlist = state.wishlist.write().await;
                let previous = wishlist.clone();
                let (rule, created) =
                    match wishlist.ignore_result(item_id, username, remote_directory) {
                        Ok(result) => result,
                        Err("not_found") => {
                            return delete_lidarr_rejected_files_if_enabled(
                                &options,
                                local_directory,
                                &rejected_filenames,
                            )
                        }
                        Err("capacity") => {
                            return Err("wishlist ignored-result capacity is full".to_owned())
                        }
                        Err(_) => return Err("invalid wishlist ignored-result inputs".to_owned()),
                    };
                let mutated = wishlist.clone();
                drop(wishlist);
                (previous, mutated, rule, created)
            };
            let (previous_wishlist, mutated_wishlist, rule, created) = ignored;
            if created {
                let (previous_searches, mutated_searches, changed_searches) = {
                    let mut searches = state.searches.write().await;
                    let previous = searches.clone();
                    let changed = searches.suppress_ignored_result(&rule);
                    let mutated = searches.clone();
                    (previous, mutated, changed)
                };
                if let Err(error) = persist_wishlist_ignored_result_and_searches_checked(
                    state,
                    &rule,
                    &changed_searches,
                )
                .await
                {
                    rollback_wishlist_if_unchanged(state, previous_wishlist, &mutated_wishlist)
                        .await;
                    let mut searches = state.searches.write().await;
                    if *searches == mutated_searches {
                        *searches = previous_searches;
                    }
                    return Err(error);
                }
            }
        }
    }

    delete_lidarr_rejected_files_if_enabled(&options, local_directory, &rejected_filenames)
}

fn delete_lidarr_rejected_files_if_enabled(
    options: &config::LidarrIntegrationSettings,
    local_directory: &str,
    filenames: &[String],
) -> Result<(), String> {
    if options.delete_rejected_downloads {
        let _ = delete_lidarr_rejected_files(local_directory, filenames)?;
    }
    Ok(())
}

async fn maybe_upload_ftp_completed_download(state: &AppState, transfer: &TransferEntry) {
    if transfer.direction != 0 || transfer.status != "succeeded" {
        return;
    }
    let Some(local_path) = transfer.local_path.as_deref() else {
        return;
    };
    let root = effective_downloads_dir(state);
    let Ok(local_path) = ensure_scoped_download_path(&root, local_path) else {
        return;
    };
    let options = state.integration_settings.read().await.ftp.clone();
    if !options.enabled {
        return;
    }
    let target = state.config.controller_compatibility_target;
    tokio::spawn(async move {
        if let Err(error) = ftp::upload_completed_file(&options, target, &local_path).await {
            eprintln!("[FTP] Completed-download upload failed: {error}");
        }
    });
}

async fn start_lidarr_manual_import(
    lidarr: &config::LidarrIntegrationSettings,
    files: Vec<serde_json::Value>,
    import_mode: &str,
) -> Result<i64, String> {
    let base_url = lidarr
        .url
        .as_deref()
        .ok_or("Lidarr URL is not configured")?;
    let resolved = validate_lidarr_base_url(base_url)?;
    let api_key = lidarr
        .api_key
        .as_deref()
        .ok_or("Lidarr API key is not configured")?;
    let mut builder = reqwest::Client::builder()
        .timeout(std::time::Duration::from_secs(lidarr.timeout_seconds))
        .redirect(reqwest::redirect::Policy::none());
    for addr in &resolved.addrs {
        builder = builder.resolve(&resolved.host, *addr);
    }
    let response = builder
        .build()
        .map_err(|error| format!("failed to build Lidarr client: {error}"))?
        .post(format!("{}/api/v1/command", base_url.trim_end_matches('/')))
        .header("X-Api-Key", api_key)
        .json(&serde_json::json!({
            "name": "ManualImport",
            "sendUpdatesToClient": false,
            "files": files,
            "importMode": import_mode,
            "replaceExistingFiles": lidarr.import_replace_existing_files,
        }))
        .send()
        .await
        .map_err(|error| format!("Lidarr command request failed: {error}"))?;
    if !response.status().is_success() {
        return Err(format!("Lidarr returned HTTP {}", response.status()));
    }
    let value = read_bounded_integration_json(response, "Lidarr command").await?;
    value
        .as_i64()
        .or_else(|| value.get("id").and_then(serde_json::Value::as_i64))
        .ok_or_else(|| "Lidarr command response did not include an id".to_owned())
}

async fn read_bounded_integration_json(
    response: reqwest::Response,
    label: &str,
) -> Result<serde_json::Value, String> {
    if response
        .content_length()
        .is_some_and(|length| length > MAX_INTEGRATION_RESPONSE_BYTES as u64)
    {
        return Err(format!(
            "{label} response exceeds {MAX_INTEGRATION_RESPONSE_BYTES} bytes"
        ));
    }

    let mut body = Vec::new();
    let mut stream = response.bytes_stream();
    while let Some(chunk) = stream.next().await {
        let chunk = chunk.map_err(|error| format!("{label} response read failed: {error}"))?;
        if body.len().saturating_add(chunk.len()) > MAX_INTEGRATION_RESPONSE_BYTES {
            return Err(format!(
                "{label} response exceeds {MAX_INTEGRATION_RESPONSE_BYTES} bytes"
            ));
        }
        body.extend_from_slice(&chunk);
    }

    serde_json::from_slice(&body).map_err(|error| format!("invalid {label} JSON: {error}"))
}

/// Resolves a MusicBrainz release id into a SongID-ready `(artist, title)`
/// pair, matching the oracle's `MusicBrainzClient.GetReleaseAsync` +
/// `MapToAlbumTarget`: `Ok(None)` when the release doesn't exist or has no
/// resolvable artist credit, `Err` only on a genuine transport/parse failure.
#[cfg(any(test, feature = "bounded-differential"))]
#[allow(dead_code)]
async fn musicbrainz_release_target(
    base_url: &str,
    release_id: &str,
) -> Result<Option<(String, String)>, String> {
    let settings = MusicBrainzIntegrationSettings {
        base_url: base_url.trim_end_matches('/').to_owned(),
        user_agent: format!("slskR v{APP_VERSION}"),
        timeout_seconds: 10.0,
        retry_attempts: 1,
    };
    musicbrainz_release_target_with_settings(&settings, release_id).await
}

async fn musicbrainz_release_target_with_settings(
    settings: &MusicBrainzIntegrationSettings,
    release_id: &str,
) -> Result<Option<(String, String)>, String> {
    let Some(value) = musicbrainz_json_request(
        settings,
        &format!(
            "/release/{}?fmt=json&inc=recordings+artists+labels+discids+isrcs",
            url_encode(release_id.trim())
        ),
    )
    .await?
    else {
        return Ok(None);
    };
    let artist_id = value
        .pointer("/artist-credit/0/artist/id")
        .and_then(serde_json::Value::as_str)
        .filter(|id| !id.trim().is_empty());
    if artist_id.is_none() {
        return Ok(None);
    }
    let title = value
        .get("title")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default()
        .to_owned();
    let artist_name = value
        .pointer("/artist-credit/0/name")
        .and_then(serde_json::Value::as_str)
        .unwrap_or_default()
        .to_owned();
    Ok(Some((artist_name, title)))
}

#[derive(Clone, Debug)]
struct MusicBrainzRecordingHit {
    recording_id: String,
    title: String,
    artist: String,
    artist_id: Option<String>,
}

#[derive(Clone, Debug)]
struct ParsedPodcoreContentId {
    domain: String,
    content_type: String,
    domain_lower: String,
    type_lower: String,
    id: String,
    full_id: String,
}

fn parse_podcore_content_id(content_id: &str) -> Option<ParsedPodcoreContentId> {
    let content_id = content_id.trim();
    let (prefix, remainder) = content_id.split_once(':')?;
    if !prefix.eq_ignore_ascii_case("content") {
        return None;
    }
    let (domain, remainder) = remainder.split_once(':')?;
    let (content_type, id) = remainder.split_once(':')?;
    if domain.trim().is_empty() || content_type.trim().is_empty() || id.trim().is_empty() {
        return None;
    }
    let domain = domain.to_owned();
    let content_type = content_type.to_owned();
    let id = id.to_owned();
    Some(ParsedPodcoreContentId {
        domain_lower: domain.to_ascii_lowercase(),
        type_lower: content_type.to_ascii_lowercase(),
        full_id: format!("content:{domain}:{content_type}:{id}"),
        domain,
        content_type,
        id,
    })
}

fn musicbrainz_query_encode(value: &str) -> String {
    let mut encoded = String::new();
    for byte in value.bytes() {
        match byte {
            b'A'..=b'Z' | b'a'..=b'z' | b'0'..=b'9' | b'-' | b'_' | b'.' | b'~' => {
                encoded.push(byte as char)
            }
            b' ' => encoded.push('+'),
            _ => encoded.push_str(&format!("%{byte:02X}")),
        }
    }
    encoded
}

async fn musicbrainz_json_request(
    settings: &MusicBrainzIntegrationSettings,
    path_and_query: &str,
) -> Result<Option<serde_json::Value>, String> {
    let timeout = Duration::try_from_secs_f64(settings.timeout_seconds)
        .map_err(|error| format!("MusicBrainz timeout is invalid: {error}"))?;
    let client = reqwest::Client::builder()
        .timeout(timeout)
        .redirect(reqwest::redirect::Policy::none())
        .build()
        .map_err(|error| format!("failed to build MusicBrainz client: {error}"))?;
    let url = format!(
        "{}{}",
        settings.base_url.trim_end_matches('/'),
        path_and_query
    );

    for attempt in 0..settings.retry_attempts {
        let response = client
            .get(&url)
            .header(reqwest::header::USER_AGENT, &settings.user_agent)
            .header(reqwest::header::ACCEPT, "application/json")
            .header(reqwest::header::ACCEPT_LANGUAGE, "en")
            .send()
            .await;
        let response = match response {
            Ok(response) => response,
            Err(_error) if attempt + 1 < settings.retry_attempts => {
                tokio::time::sleep(Duration::from_secs(1)).await;
                continue;
            }
            Err(error) => {
                return Err(format!("MusicBrainz API request failed: {error}"));
            }
        };
        if response.status() == reqwest::StatusCode::NOT_FOUND {
            return Ok(None);
        }
        if !response.status().is_success() {
            return Err(format!("MusicBrainz returned HTTP {}", response.status()));
        }
        return read_bounded_integration_json(response, "MusicBrainz API")
            .await
            .map(Some);
    }

    Err("MusicBrainz request did not run".to_owned())
}

fn musicbrainz_artist_credit(value: &serde_json::Value) -> String {
    value
        .get("artist-credit")
        .and_then(serde_json::Value::as_array)
        .map(|credits| {
            credits
                .iter()
                .map(|credit| {
                    let name = credit
                        .get("name")
                        .and_then(serde_json::Value::as_str)
                        .unwrap_or_default();
                    let join_phrase = credit
                        .get("joinphrase")
                        .and_then(serde_json::Value::as_str)
                        .unwrap_or_default();
                    format!("{name}{join_phrase}")
                })
                .collect::<String>()
                .trim()
                .to_owned()
        })
        .unwrap_or_default()
}

fn musicbrainz_artist_id(value: &serde_json::Value) -> Option<String> {
    value
        .pointer("/artist-credit/0/artist/id")
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|id| !id.is_empty())
        .map(str::to_owned)
}

async fn musicbrainz_search_recordings(
    settings: &MusicBrainzIntegrationSettings,
    query: &str,
    limit: usize,
) -> Result<Vec<MusicBrainzRecordingHit>, String> {
    let Some(value) = musicbrainz_json_request(
        settings,
        &format!(
            "/recording?query={}&fmt=json&limit={}",
            musicbrainz_query_encode(query.trim()),
            limit.clamp(1, 100)
        ),
    )
    .await?
    else {
        return Ok(Vec::new());
    };
    let Some(recordings) = value
        .get("recordings")
        .and_then(serde_json::Value::as_array)
    else {
        return Ok(Vec::new());
    };
    let mut seen = HashSet::new();
    let mut hits = Vec::new();
    for recording in recordings {
        let recording_id = recording
            .get("id")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default()
            .trim()
            .to_owned();
        let title = recording
            .get("title")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default()
            .trim()
            .to_owned();
        let artist = musicbrainz_artist_credit(recording);
        if recording_id.is_empty() && title.is_empty() && artist.is_empty() {
            continue;
        }
        let key = if recording_id.is_empty() {
            format!(
                "{}\u{1f}{}",
                artist.to_ascii_lowercase(),
                title.to_ascii_lowercase()
            )
        } else {
            recording_id.to_ascii_lowercase()
        };
        if !seen.insert(key) {
            continue;
        }
        hits.push(MusicBrainzRecordingHit {
            recording_id,
            title,
            artist,
            artist_id: musicbrainz_artist_id(recording),
        });
    }
    Ok(hits)
}

fn basic_podcore_metadata(
    parsed: &ParsedPodcoreContentId,
    title_override: Option<&str>,
    artist_override: Option<&str>,
    mut additional_info: BTreeMap<String, String>,
) -> serde_json::Value {
    additional_info.insert("id".to_owned(), parsed.id.clone());
    additional_info.insert("domain".to_owned(), parsed.domain.clone());
    additional_info.insert("type".to_owned(), parsed.content_type.clone());
    let default_title = format!("{}: {}", parsed.content_type, parsed.id);
    serde_json::json!({
        "contentId": parsed.full_id,
        "title": title_override.unwrap_or(&default_title),
        "artist": artist_override.unwrap_or("Unknown"),
        "type": parsed.content_type,
        "domain": parsed.domain,
        "additionalInfo": additional_info,
    })
}

fn fallback_podcore_metadata(parsed: &ParsedPodcoreContentId) -> serde_json::Value {
    let title = if parsed.domain_lower == "video" {
        parsed.id.clone()
    } else {
        format!("{}: {}", parsed.content_type, parsed.id)
    };
    basic_podcore_metadata(parsed, Some(&title), None, BTreeMap::new())
}

async fn podcore_audio_metadata(
    settings: &MusicBrainzIntegrationSettings,
    parsed: &ParsedPodcoreContentId,
) -> Result<serde_json::Value, String> {
    match parsed.type_lower.as_str() {
        "artist" => {
            let hits = musicbrainz_search_recordings(settings, &parsed.id, 10).await?;
            let matching = hits
                .iter()
                .find(|hit| {
                    hit.artist_id
                        .as_deref()
                        .is_some_and(|id| id.eq_ignore_ascii_case(&parsed.id))
                })
                .or_else(|| {
                    hits.iter()
                        .find(|hit| hit.artist.eq_ignore_ascii_case(parsed.id.trim()))
                });
            let title = matching
                .map(|hit| hit.artist.as_str())
                .unwrap_or(parsed.id.as_str());
            let mut additional_info = BTreeMap::new();
            additional_info.insert("musicbrainz_id".to_owned(), parsed.id.clone());
            additional_info.insert("type".to_owned(), "artist".to_owned());
            additional_info.insert(
                "musicbrainz_artist_id".to_owned(),
                matching
                    .and_then(|hit| hit.artist_id.as_deref())
                    .unwrap_or(parsed.id.as_str())
                    .to_owned(),
            );
            Ok(basic_podcore_metadata(
                parsed,
                Some(title),
                Some(title),
                additional_info,
            ))
        }
        "album" => {
            let Some(value) = musicbrainz_json_request(
                settings,
                &format!(
                    "/release/{}?fmt=json&inc=recordings+artists+labels+discids+isrcs",
                    url_encode(parsed.id.trim())
                ),
            )
            .await?
            else {
                return Ok(fallback_podcore_metadata(parsed));
            };
            let title = value
                .get("title")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default();
            let release_date = value
                .get("date")
                .and_then(serde_json::Value::as_str)
                .and_then(parse_musicbrainz_release_date)
                .unwrap_or_else(|| "Unknown".to_owned());
            let track_count = value
                .get("media")
                .and_then(serde_json::Value::as_array)
                .into_iter()
                .flat_map(|media| media.iter())
                .filter_map(|media| media.get("tracks"))
                .filter_map(serde_json::Value::as_array)
                .flat_map(|tracks| tracks.iter())
                .filter(|track| {
                    track
                        .get("recording")
                        .is_some_and(serde_json::Value::is_object)
                })
                .count();
            let label = value
                .get("label-info")
                .and_then(serde_json::Value::as_array)
                .into_iter()
                .flat_map(|labels| labels.iter())
                .filter_map(|entry| entry.pointer("/label/name"))
                .filter_map(serde_json::Value::as_str)
                .map(str::trim)
                .find(|name| !name.is_empty())
                .unwrap_or("Unknown");
            let mut additional_info = BTreeMap::new();
            additional_info.insert("musicbrainz_id".to_owned(), parsed.id.clone());
            additional_info.insert("release_date".to_owned(), release_date);
            additional_info.insert("track_count".to_owned(), track_count.to_string());
            additional_info.insert("label".to_owned(), label.to_owned());
            Ok(serde_json::json!({
                "contentId": parsed.full_id,
                "title": title,
                "artist": musicbrainz_artist_credit(&value),
                "type": parsed.content_type,
                "domain": parsed.domain,
                "additionalInfo": additional_info,
            }))
        }
        "track" => {
            let Some(value) = musicbrainz_json_request(
                settings,
                &format!(
                    "/recording/{}?fmt=json&inc=artists+isrcs",
                    url_encode(parsed.id.trim())
                ),
            )
            .await?
            else {
                return Ok(fallback_podcore_metadata(parsed));
            };
            let title = value
                .get("title")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default();
            let duration_ms = value
                .get("length")
                .and_then(serde_json::Value::as_i64)
                .unwrap_or(0);
            let mut additional_info = BTreeMap::new();
            additional_info.insert("musicbrainz_id".to_owned(), parsed.id.clone());
            additional_info.insert("duration_ms".to_owned(), duration_ms.to_string());
            additional_info.insert("album".to_owned(), "Unknown".to_owned());
            additional_info.insert("position".to_owned(), "0".to_owned());
            Ok(serde_json::json!({
                "contentId": parsed.full_id,
                "title": title,
                "artist": musicbrainz_artist_credit(&value),
                "type": parsed.content_type,
                "domain": parsed.domain,
                "additionalInfo": additional_info,
            }))
        }
        _ => Ok(fallback_podcore_metadata(parsed)),
    }
}

fn parse_musicbrainz_release_date(value: &str) -> Option<String> {
    let mut parts = value.split('-');
    let year = parts.next()?.parse::<i32>().ok()?;
    let month = parts
        .next()
        .and_then(|part| part.parse::<u32>().ok())
        .unwrap_or(1);
    let day = parts
        .next()
        .and_then(|part| part.parse::<u32>().ok())
        .unwrap_or(1);
    chrono::NaiveDate::from_ymd_opt(year, month, day)
        .map(|date| date.format("%Y-%m-%d").to_string())
}

struct ResolvedIntegrationTarget {
    host: String,
    addrs: Vec<SocketAddr>,
}

#[allow(dead_code)]
fn validate_integration_base_url(base_url: &str) -> Result<ResolvedIntegrationTarget, String> {
    let parsed = reqwest::Url::parse(base_url)
        .map_err(|error| format!("integration URL is invalid: {error}"))?;
    match parsed.scheme() {
        "http" | "https" => {}
        _ => return Err("integration URL scheme must be http or https".to_owned()),
    }
    let host = parsed
        .host_str()
        .ok_or_else(|| "integration URL must include a host".to_owned())?;
    if !parsed.username().is_empty() || parsed.password().is_some() {
        return Err("integration URL must not contain embedded credentials".to_owned());
    }
    if parsed.query().is_some() || parsed.fragment().is_some() {
        return Err("integration URL must not contain a query or fragment".to_owned());
    }
    let allow_private = matches!(
        env::var("SLSKR_ALLOW_PRIVATE_INTEGRATION_URLS")
            .unwrap_or_default()
            .to_ascii_lowercase()
            .as_str(),
        "1" | "true" | "yes"
    );
    if allow_private {
        let port = parsed
            .port_or_known_default()
            .ok_or_else(|| "integration URL port is unknown".to_owned())?;
        return Ok(ResolvedIntegrationTarget {
            host: host.to_owned(),
            addrs: (host, port)
                .to_socket_addrs()
                .map_err(|error| format!("integration URL resolution failed: {error}"))?
                .collect(),
        });
    }
    if host.eq_ignore_ascii_case("localhost") {
        return Err("integration URL host is private".to_owned());
    }
    if let Ok(ip) = host.parse::<IpAddr>() {
        if is_blocked_integration_ip(ip) {
            return Err("integration URL IP is private".to_owned());
        }
    }
    let port = parsed
        .port_or_known_default()
        .ok_or_else(|| "integration URL port is unknown".to_owned())?;
    let addrs = (host, port)
        .to_socket_addrs()
        .map_err(|error| format!("integration URL resolution failed: {error}"))?
        .collect::<Vec<_>>();
    if addrs.is_empty() {
        return Err("integration URL did not resolve".to_owned());
    }
    if addrs
        .iter()
        .any(|addr| is_blocked_integration_ip(addr.ip()))
    {
        return Err("integration URL resolves to a private address".to_owned());
    }
    Ok(ResolvedIntegrationTarget {
        host: host.to_owned(),
        addrs,
    })
}

fn validate_lidarr_base_url(base_url: &str) -> Result<ResolvedIntegrationTarget, String> {
    let parsed = reqwest::Url::parse(base_url)
        .map_err(|error| format!("integration URL is invalid: {error}"))?;
    if !matches!(parsed.scheme(), "http" | "https") {
        return Err("integration URL scheme must be http or https".to_owned());
    }
    let host = parsed
        .host_str()
        .ok_or_else(|| "integration URL must include a host".to_owned())?;
    if !parsed.username().is_empty() || parsed.password().is_some() {
        return Err("integration URL must not contain embedded credentials".to_owned());
    }
    if parsed.query().is_some() || parsed.fragment().is_some() {
        return Err("integration URL must not contain a query or fragment".to_owned());
    }
    let port = parsed
        .port_or_known_default()
        .ok_or_else(|| "integration URL port is unknown".to_owned())?;
    let addrs = (host, port)
        .to_socket_addrs()
        .map_err(|error| format!("integration URL resolution failed: {error}"))?
        .collect::<Vec<_>>();
    if addrs.is_empty() {
        return Err("integration URL did not resolve".to_owned());
    }
    if addrs
        .iter()
        .any(|address| address.ip().is_unspecified() || address.ip().is_multicast())
    {
        return Err("integration URL resolves to an unusable address".to_owned());
    }
    Ok(ResolvedIntegrationTarget {
        host: host.to_owned(),
        addrs,
    })
}

#[allow(dead_code)]
fn is_blocked_integration_ip(ip: IpAddr) -> bool {
    match ip {
        IpAddr::V4(ip) => is_blocked_outbound_ipv4(ip),
        IpAddr::V6(ip) => {
            if let Some(v4) = ip.to_ipv4_mapped().or_else(|| ip.to_ipv4()) {
                return is_blocked_integration_ip(IpAddr::V4(v4));
            }
            if let Some(v4) = nat64_embedded_ipv4(ip) {
                return is_blocked_outbound_ipv4(v4);
            }
            let segments = ip.segments();
            if segments[0] == 0x2002 || (segments[0] == 0x2001 && segments[1] == 0) {
                return true;
            }
            ip.is_loopback()
                || ip.is_unspecified()
                || ip.is_multicast()
                || (segments[0] == 0x2001 && segments[1] == 0x0db8)
                || (segments[0] & 0xfe00) == 0xfc00
                || (segments[0] & 0xffc0) == 0xfe80
                || (segments[0] & 0xffc0) == 0xfec0
                || is_non_global_special_use_ipv6(ip)
        }
    }
}

#[cfg(any(test, feature = "bounded-differential"))]
