fn rate_limit_user_key(authenticated_token: &str) -> String {
    use sha2::{Digest, Sha256};

    let digest = Sha256::digest(authenticated_token.as_bytes());
    format!("auth:{}", hex::encode(&digest[..16]))
}

fn authenticated_rate_limit_user_key(
    config: &AppConfig,
    authorization: Option<&str>,
    cookie: Option<&str>,
    remote_addr: Option<SocketAddr>,
) -> Option<String> {
    if !utils::is_authorized_from(config, authorization, cookie, remote_addr) {
        return None;
    }
    authorization
        .and_then(|value| {
            value
                .strip_prefix("Bearer ")
                .or_else(|| value.strip_prefix("ApiKey "))
        })
        .map(str::to_owned)
        .or_else(|| cookie_session_token(cookie))
        .map(|token| rate_limit_user_key(&token))
}

#[derive(Clone, Debug, Eq, PartialEq)]
struct ControllerRateLimitPolicy {
    partition: String,
    max_requests: u32,
    window_seconds: u64,
}

fn controller_rate_limit_policy(
    config: &AppConfig,
    method: &str,
    path: &str,
    authenticated_caller: Option<&str>,
    remote_addr: Option<SocketAddr>,
) -> Option<ControllerRateLimitPolicy> {
    if config.controller_compatibility_target != ControllerCompatibilityTarget::Slskdn
        || !config.controller_web_rate_limiting.enabled
    {
        return None;
    }

    let settings = config.controller_web_rate_limiting;
    let path = path.to_ascii_lowercase();
    let method_is_post = method.eq_ignore_ascii_case("POST");
    let policy = if path.starts_with("/mesh/") {
        ControllerRateLimitPolicy {
            partition: "mesh".to_owned(),
            max_requests: controller_rate_permit(settings.mesh_gateway_permit_limit),
            window_seconds: nonzero_controller_rate_window(settings.mesh_gateway_window_seconds),
        }
    } else if method_is_post && path.contains("/inbox") {
        ControllerRateLimitPolicy {
            partition: "fed".to_owned(),
            max_requests: controller_rate_permit(settings.federation_permit_limit),
            window_seconds: nonzero_controller_rate_window(settings.federation_window_seconds),
        }
    } else if method_is_post && path.starts_with("/api/") && path.contains("/events/") {
        ControllerRateLimitPolicy {
            partition: "event-injection".to_owned(),
            max_requests: controller_rate_permit(settings.api_permit_limit.min(10)),
            window_seconds: 60,
        }
    } else if method_is_post && path.starts_with("/api/") && path.contains("/warm-cache/hints") {
        let fallback_caller = remote_addr
            .map(|address| address.ip().to_string())
            .unwrap_or_else(|| "unknown".to_owned());
        ControllerRateLimitPolicy {
            partition: format!(
                "warm-cache:{}",
                authenticated_caller.unwrap_or(&fallback_caller)
            ),
            max_requests: controller_rate_permit(settings.api_permit_limit.min(10)),
            window_seconds: 60,
        }
    } else if authenticated_caller.is_some() || !path.starts_with("/api/") {
        return None;
    } else {
        ControllerRateLimitPolicy {
            partition: "api".to_owned(),
            max_requests: controller_rate_permit(settings.api_permit_limit),
            window_seconds: nonzero_controller_rate_window(settings.api_window_seconds),
        }
    };
    Some(policy)
}

fn controller_rate_permit(permit_limit: i32) -> u32 {
    u32::try_from(permit_limit).unwrap_or(0)
}

fn nonzero_controller_rate_window(window_seconds: i32) -> u64 {
    if window_seconds <= 0 {
        60
    } else {
        u64::try_from(window_seconds).unwrap_or(60)
    }
}

fn rate_limit_remote_addr(
    config: &AppConfig,
    remote_addr: Option<SocketAddr>,
    headers: &http_server::HttpHeaders,
) -> Option<SocketAddr> {
    let remote_addr = remote_addr?;
    if !config
        .trusted_proxy_cidrs
        .iter()
        .any(|cidr| cidr.contains(remote_addr.ip()))
    {
        return Some(remote_addr);
    }

    forwarded_client_ip(config, remote_addr.ip(), headers)
        .map(|ip| SocketAddr::new(ip, 0))
        .or(Some(remote_addr))
}

fn forwarded_client_ip(
    config: &AppConfig,
    remote_ip: IpAddr,
    headers: &http_server::HttpHeaders,
) -> Option<IpAddr> {
    let forwarded_ips = if let Some(value) = headers.forwarded.as_deref() {
        forwarded_header_client_ips(value)?
    } else {
        let value = headers.x_forwarded_for.as_deref()?;
        x_forwarded_for_client_ips(value)?
    };

    forwarded_ips
        .into_iter()
        .chain(std::iter::once(remote_ip))
        .rev()
        .find(|ip| {
            !config
                .trusted_proxy_cidrs
                .iter()
                .any(|cidr| cidr.contains(*ip))
        })
}

fn x_forwarded_for_client_ips(value: &str) -> Option<Vec<IpAddr>> {
    let ips = value
        .split(',')
        .map(parse_forwarded_ip_token)
        .collect::<Option<Vec<_>>>()?;
    (!ips.is_empty()).then_some(ips)
}

fn forwarded_header_client_ips(value: &str) -> Option<Vec<IpAddr>> {
    let ips = value
        .split(',')
        .map(parse_forwarded_element_ip)
        .collect::<Option<Vec<_>>>()?;
    (!ips.is_empty()).then_some(ips)
}

fn parse_forwarded_element_ip(entry: &str) -> Option<IpAddr> {
    let mut forwarded_ip = None;
    for part in entry.split(';') {
        let (name, value) = part.trim().split_once('=')?;
        if !name.trim().eq_ignore_ascii_case("for") {
            continue;
        }
        if forwarded_ip.is_some() {
            return None;
        }
        forwarded_ip = Some(parse_forwarded_ip_token(value)?);
    }
    forwarded_ip
}

fn parse_forwarded_ip_token(value: &str) -> Option<IpAddr> {
    let value = value.trim();
    let value = match (value.strip_prefix('"'), value.strip_suffix('"')) {
        (Some(without_prefix), Some(_)) => without_prefix.strip_suffix('"')?,
        (None, None) => value,
        _ => return None,
    };
    if value.is_empty() || value.contains(['"', '\\']) {
        return None;
    }
    if value.eq_ignore_ascii_case("unknown") || value.starts_with('_') {
        return None;
    }
    if let Some(bracketed) = value.strip_prefix('[') {
        let (host, suffix) = bracketed.split_once(']')?;
        if !suffix.is_empty()
            && suffix
                .strip_prefix(':')
                .and_then(|port| port.parse::<u16>().ok())
                .is_none()
        {
            return None;
        }
        return host.parse::<std::net::Ipv6Addr>().ok().map(IpAddr::V6);
    }
    if value.contains(['[', ']']) {
        return None;
    }
    if let Ok(ip) = value.parse::<IpAddr>() {
        return Some(ip);
    }
    let (host, port) = value.rsplit_once(':')?;
    port.parse::<u16>().ok()?;
    host.parse::<std::net::Ipv4Addr>().ok().map(IpAddr::V4)
}

fn websocket_auth_protocol(protocol_header: Option<&str>) -> Option<&str> {
    protocol_header?
        .split(',')
        .map(str::trim)
        .find(|protocol| decode_websocket_auth_protocol(protocol).is_some())
}

fn websocket_auth_protocol_count(protocol_header: Option<&str>) -> usize {
    protocol_header
        .into_iter()
        .flat_map(|header| header.split(','))
        .map(str::trim)
        .filter(|protocol| decode_websocket_auth_protocol(protocol).is_some())
        .take(2)
        .count()
}

fn websocket_protocol_authorization(protocol_header: Option<&str>) -> Option<String> {
    let protocol = websocket_auth_protocol(protocol_header)?;
    let token = decode_websocket_auth_protocol(protocol)?;
    Some(format!("Bearer {token}"))
}

fn mixed_websocket_auth_credentials(
    headers: &http_server::HttpHeaders,
    websocket_authorization: Option<&str>,
) -> bool {
    websocket_auth_protocol_count(headers.sec_websocket_protocol.as_deref()) > 1
        || (websocket_authorization.is_some()
            && (headers.authorization.is_some() || headers.x_api_key.is_some()))
}

fn decode_websocket_auth_protocol(protocol: &str) -> Option<String> {
    if !is_websocket_protocol_token(protocol) {
        return None;
    }
    let encoded = protocol.strip_prefix(WEBSOCKET_AUTH_PROTOCOL_PREFIX)?;
    let token = strict_percent_decode(encoded)?;
    (!token.is_empty()
        && !token
            .chars()
            .any(|character| character.is_control() || character == '\u{7f}'))
    .then_some(token)
}

fn strict_percent_decode(value: &str) -> Option<String> {
    let bytes = value.as_bytes();
    let mut decoded = Vec::with_capacity(bytes.len());
    let mut index = 0;
    while index < bytes.len() {
        if bytes[index] == b'%' {
            let high = strict_hex_value(*bytes.get(index + 1)?)?;
            let low = strict_hex_value(*bytes.get(index + 2)?)?;
            decoded.push((high << 4) | low);
            index += 3;
        } else {
            decoded.push(bytes[index]);
            index += 1;
        }
    }
    String::from_utf8(decoded).ok()
}

fn strict_hex_value(value: u8) -> Option<u8> {
    match value {
        b'0'..=b'9' => Some(value - b'0'),
        b'a'..=b'f' => Some(value - b'a' + 10),
        b'A'..=b'F' => Some(value - b'A' + 10),
        _ => None,
    }
}

fn is_websocket_protocol_token(value: &str) -> bool {
    !value.is_empty()
        && value.bytes().all(|byte| {
            byte.is_ascii_alphanumeric()
                || matches!(
                    byte,
                    b'!' | b'#'
                        | b'$'
                        | b'%'
                        | b'&'
                        | b'\''
                        | b'*'
                        | b'+'
                        | b'-'
                        | b'.'
                        | b'^'
                        | b'_'
                        | b'`'
                        | b'|'
                        | b'~'
                )
        })
}

fn slskd_transfer_user_path<'a>(path: &'a str, direction: &str) -> Option<&'a str> {
    let prefix = format!("/api/transfers/{direction}/");
    path.strip_prefix(&prefix)
        .filter(|username| !username.is_empty() && !username.contains('/'))
}

fn slskd_transfer_file_path<'a>(path: &'a str, direction: &str) -> Option<(&'a str, u64)> {
    let prefix = format!("/api/transfers/{direction}/");
    let rest = path.strip_prefix(&prefix)?;
    let (username, tail) = rest.split_once('/')?;
    let id = tail.split_once('/').map_or(
        tail,
        |(id, suffix)| {
            if suffix == "position" {
                id
            } else {
                ""
            }
        },
    );
    if username.is_empty() || username.contains('/') || id.is_empty() {
        return None;
    }
    Some((username, id.parse().ok()?))
}

fn slskd_transfer_position_path(path: &str) -> Option<(&str, u64)> {
    slskd_transfer_file_path(path, "downloads").filter(|_| path.ends_with("/position"))
}

fn transfer_resource_segment(path: &str) -> Option<&str> {
    path_segment_after(path, "/api/transfers/")
        .or_else(|| path_segment_after(path, "/api/v0/transfers/"))
}

fn slskd_file_storage_resource_path(path: &str) -> Option<(&str, &str, &str)> {
    let mut segments = path
        .strip_prefix("/api/files/")
        .or_else(|| path.strip_prefix("/api/v0/files/"))?
        .split('/');
    let storage = segments.next()?;
    let resource = segments.next()?;
    let encoded_name = segments.next()?;
    if segments.next().is_some()
        || !matches!(storage, "downloads" | "incomplete")
        || !matches!(resource, "directories" | "files")
        || encoded_name.is_empty()
    {
        return None;
    }
    Some((storage, resource, encoded_name))
}

fn file_storage_error_response(error: &str) -> HttpResponse {
    if error == STORAGE_DIRECTORY_NOT_FOUND_ERROR {
        routing::not_found_response()
    } else if matches!(
        error,
        STORAGE_DIRECTORY_ENTRY_LIMIT_ERROR
            | STORAGE_DIRECTORY_DELETE_ENTRY_LIMIT_ERROR
            | STORAGE_DIRECTORY_DELETE_TOTAL_LIMIT_ERROR
            | STORAGE_DIRECTORY_DELETE_DEPTH_ERROR
    ) {
        HttpResponse {
            status: "413 Payload Too Large",
            content_type: "application/json",
            body: if error == STORAGE_DIRECTORY_ENTRY_LIMIT_ERROR {
                "{\"error\":\"storage directory is too large to list\"}".to_owned()
            } else if matches!(
                error,
                STORAGE_DIRECTORY_DELETE_ENTRY_LIMIT_ERROR
                    | STORAGE_DIRECTORY_DELETE_TOTAL_LIMIT_ERROR
            ) {
                "{\"error\":\"storage directory is too large to delete\"}".to_owned()
            } else {
                "{\"error\":\"storage directory tree is too deep to delete\"}".to_owned()
            },
        }
    } else if error.contains("failed:") {
        eprintln!("file storage operation failed: {error}");
        routing::service_unavailable_response("file storage unavailable")
    } else {
        routing::bad_request_response(error)
    }
}

fn slskd_files_from_body(body: &str) -> Vec<serde_json::Value> {
    let Ok(payload) = serde_json::from_str::<serde_json::Value>(body) else {
        return Vec::new();
    };
    if let Some(files) = payload.get("files").and_then(serde_json::Value::as_array) {
        return files.clone();
    }
    if payload.get("filename").is_some() {
        return vec![payload];
    }
    payload.as_array().cloned().unwrap_or_default()
}

fn slskd_transfer_batch_id(body: &str) -> Option<String> {
    let payload = serde_json::from_str::<serde_json::Value>(body).ok()?;
    ["batchId", "batch_id", "id"]
        .iter()
        .find_map(|field| payload.get(field).and_then(serde_json::Value::as_str))
        .map(str::trim)
        .filter(|value| !value.is_empty() && uuid::Uuid::parse_str(value).is_ok())
        .map(str::to_owned)
}

fn transfer_batch_record_key(batch_id: &str) -> String {
    format!("slskd/transfer-batch/{batch_id}")
}

fn persisted_transfer_batch_record(
    batch: &serde_json::Value,
) -> Result<persistence::TransferBatchRecord, String> {
    let id = batch
        .get("id")
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .ok_or_else(|| "transfer batch is missing an id".to_owned())?;
    let username = batch
        .get("username")
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .unwrap_or_default()
        .to_owned();
    let direction = match batch
        .get("direction")
        .and_then(serde_json::Value::as_str)
        .unwrap_or("Download")
    {
        "Upload" | "upload" => 1,
        _ => 0,
    };
    let search_id = batch
        .get("searchId")
        .and_then(serde_json::Value::as_str)
        .map(str::to_owned);
    let created_at = batch
        .get("createdAt")
        .and_then(serde_json::Value::as_str)
        .map(str::to_owned)
        .ok_or_else(|| "transfer batch is missing createdAt".to_owned())?;
    let options_json = batch
        .get("options")
        .cloned()
        .unwrap_or_else(|| serde_json::json!({}));
    if !options_json.is_object() {
        return Err("transfer batch options must be an object".to_owned());
    }
    Ok(persistence::TransferBatchRecord {
        id: id.to_owned(),
        search_id,
        username,
        direction,
        created_at,
        options_json: Some(options_json.to_string()),
    })
}

fn transfer_batch_json_from_record(
    record: persistence::TransferBatchRecord,
) -> Result<serde_json::Value, String> {
    let options = record
        .options_json
        .as_deref()
        .map(serde_json::from_str::<serde_json::Value>)
        .transpose()
        .map_err(|error| format!("transfer batch options could not be decoded: {error}"))?
        .unwrap_or_else(|| serde_json::json!({}));
    if !options.is_object() {
        return Err("transfer batch options must be an object".to_owned());
    }
    let mut batch = serde_json::json!({
        "id": record.id,
        "username": record.username,
        "direction": if record.direction == 1 { "Upload" } else { "Download" },
        "createdAt": record.created_at,
        "transfers": [],
        "options": options,
    });
    if let Some(search_id) = record.search_id {
        batch["searchId"] = serde_json::Value::String(search_id);
    }
    Ok(batch)
}

async fn slskd_read_transfer_batch(
    state: &AppState,
    batch_id: &str,
) -> Result<Option<serde_json::Value>, String> {
    if let Some(db) = state.db.as_ref() {
        let record = db
            .get_transfer_batch(batch_id)
            .await
            .map_err(|error| format!("transfer batch storage unavailable: {error}"))?;
        return record.map(transfer_batch_json_from_record).transpose();
    }
    Ok(state
        .controller_features
        .read()
        .await
        .get(&transfer_batch_record_key(batch_id))
        .cloned())
}

async fn slskd_create_transfer_batch(
    state: &AppState,
    batch: &serde_json::Value,
) -> Result<(), String> {
    if let Some(db) = state.db.as_ref() {
        let record = persisted_transfer_batch_record(batch)?;
        return db
            .insert_transfer_batch(&record)
            .await
            .map_err(|error| format!("transfer batch storage unavailable: {error}"));
    }
    state.controller_features.write().await.upsert(
        transfer_batch_record_key(
            batch
                .get("id")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default(),
        ),
        batch.clone(),
    )
}

async fn slskd_delete_transfer_batch(state: &AppState, batch_id: &str) -> Result<(), String> {
    if let Some(db) = state.db.as_ref() {
        db.delete_transfer_batch(batch_id)
            .await
            .map_err(|error| format!("transfer batch storage unavailable: {error}"))?;
        return Ok(());
    }
    state
        .controller_features
        .write()
        .await
        .remove(&transfer_batch_record_key(batch_id))
        .map(|_| ())
}

fn slskd_transfer_batch_insert_is_duplicate(error: &str) -> bool {
    let error = error.to_ascii_lowercase();
    error.contains("unique constraint")
        || error.contains("constraint failed")
        || error.contains("primary key")
}

fn transfer_batch_with_entries(
    mut batch: serde_json::Value,
    entries: impl IntoIterator<Item = serde_json::Value>,
) -> serde_json::Value {
    batch["transfers"] = serde_json::Value::Array(entries.into_iter().collect());
    batch
}

async fn slskd_enqueue_download_batch(body: &str, state: &AppState) -> HttpResponse {
    let payload = match serde_json::from_str::<serde_json::Value>(body) {
        Ok(serde_json::Value::Object(payload)) => serde_json::Value::Object(payload),
        Ok(_) => return routing::bad_request_response("The request body must be an object"),
        Err(_) => return routing::bad_request_response("invalid JSON body"),
    };
    let username = payload
        .get("username")
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty() && value.len() <= MAX_TRANSFER_USERNAME_BYTES)
        .map(str::to_owned);
    let Some(username) = username else {
        return routing::bad_request_response("Username is required");
    };
    let Some(files) = payload
        .get("files")
        .and_then(serde_json::Value::as_array)
        .filter(|files| !files.is_empty())
    else {
        return routing::bad_request_response("At least one file is required");
    };
    if files.iter().any(serde_json::Value::is_null) {
        return routing::bad_request_response("One or more files in the request are null");
    }
    let exclusions = effective_download_exclusions(state).await;
    let parse_guid = |name: &str| -> Result<Option<String>, HttpResponse> {
        let Some(value) = payload.get(name) else {
            return Ok(None);
        };
        if value.is_null() {
            return Ok(None);
        }
        let value = value.as_str().map(str::trim).unwrap_or_default();
        if value.is_empty() {
            return Ok(None);
        }
        uuid::Uuid::parse_str(value)
            .map(|value| Some(value.to_string()))
            .map_err(|_| {
                routing::bad_request_response(
                    "One or more provided identifiers is not a valid GUID/UUID",
                )
            })
    };
    let batch_id = match parse_guid("id") {
        Ok(value) => value.unwrap_or_else(|| uuid::Uuid::new_v4().to_string()),
        Err(response) => return response,
    };
    let search_id = match parse_guid("searchId") {
        Ok(value) => value,
        Err(response) => return response,
    };
    let _request_permit = match Arc::clone(&state.download_batch_requests).try_acquire_owned() {
        Ok(permit) => permit,
        Err(_) => {
            return HttpResponse {
                status: "429 Too Many Requests",
                content_type: "application/json",
                body: serde_json::json!(
                    "Only one concurrent operation is permitted. Wait until the previous request completes"
                )
                .to_string(),
            }
        }
    };
    let options = payload
        .get("options")
        .filter(|value| value.is_object())
        .cloned()
        .unwrap_or_else(|| serde_json::json!({}));
    let destination = options
        .get("destination")
        .and_then(serde_json::Value::as_str)
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(str::to_owned);
    let downloads_dir = effective_downloads_dir(state);
    if destination.as_deref().is_some_and(|destination| {
        safe_download_path(
            &downloads_dir,
            &format!("{destination}/slskr-batch-path-validation"),
        )
        .is_err()
    }) {
        return routing::bad_request_response(
            "Destination must be relative and stay within the download root",
        );
    }
    let mut seen_filenames = HashSet::new();
    let mut requested_files = Vec::with_capacity(files.len());
    for file in files {
        let Some(filename) = file
            .get("filename")
            .and_then(serde_json::Value::as_str)
            .map(str::trim)
            .filter(|value| !value.is_empty())
        else {
            return routing::bad_request_response("Each file requires a filename");
        };
        if !seen_filenames.insert(filename.to_owned()) {
            return routing::bad_request_response("Two or more files in the request are repeated");
        }
        let Some(size) = file.get("size").and_then(serde_json::Value::as_u64) else {
            return routing::bad_request_response("Each file requires a non-negative size");
        };
        if safe_download_path(&downloads_dir, filename).is_err() {
            return routing::bad_request_response(
                "One or more files in the request contain a dangerous path traversal segment",
            );
        }
        requested_files.push((filename.to_owned(), size));
    }

    let blocked = requested_files
        .iter()
        .filter_map(|(filename, _)| {
            crate::download_filter::matching_exclusion(
                filename,
                &exclusions,
            )
            .map(|exclusion| serde_json::json!({
                "filename": filename,
                "exclusion": exclusion,
                "message": "Download blocked by global exclusion",
            }))
        })
        .collect::<Vec<_>>();
    if blocked.len() == requested_files.len() && !blocked.is_empty() {
        return HttpResponse {
            status: "403 Forbidden",
            content_type: "application/json",
            body: serde_json::json!({
                "type": "download_blocked",
                "title": "Download blocked",
                "detail": "Every requested file matched a configured global download exclusion.",
                "blocked": blocked,
            })
            .to_string(),
        };
    }
    requested_files.retain(|(filename, _)| {
        !crate::download_filter::is_excluded(filename, &exclusions)
    });

    if let Err(error) = request_peer_endpoint(state, &username).await {
        return HttpResponse {
            status: "404 Not Found",
            content_type: "application/json",
            body: serde_json::json!(error).to_string(),
        };
    }

    let existing_record = match slskd_read_transfer_batch(state, &batch_id).await {
        Ok(record) => record.is_some(),
        Err(error) => return routing::service_unavailable_response(&error),
    };
    let existing_transfer = state
        .transfers
        .read()
        .await
        .entries
        .iter()
        .any(|entry| entry.batch_id.as_deref() == Some(batch_id.as_str()));
    if existing_record || existing_transfer {
        return HttpResponse {
            status: "409 Conflict",
            content_type: "application/json",
            body: serde_json::json!(format!("A batch with ID {batch_id} already exists"))
                .to_string(),
        };
    }

    let mut public_options = serde_json::Map::new();
    if let Some(destination) = destination.as_ref() {
        public_options.insert(
            "destination".to_owned(),
            serde_json::Value::String(destination.clone()),
        );
    }
    // Frozen slskd accepts ExternalId in the request DTO but does not copy it
    // into the persisted BatchOptions record in EnqueueBatchAsync.
    let created_at = chrono::Utc::now().to_rfc3339_opts(chrono::SecondsFormat::AutoSi, true);
    let mut batch = serde_json::json!({
        "id": batch_id,
        "username": username,
        "direction": "Download",
        "createdAt": created_at,
        "transfers": [],
        "options": serde_json::Value::Object(public_options),
    });
    if let Some(search_id) = search_id.as_ref() {
        batch["searchId"] = serde_json::Value::String(search_id.clone());
    }
    if let Err(error) = slskd_create_transfer_batch(state, &batch).await {
        if slskd_transfer_batch_insert_is_duplicate(&error) {
            return HttpResponse {
                status: "409 Conflict",
                content_type: "application/json",
                body: serde_json::json!(format!("A batch with ID {batch_id} already exists"))
                    .to_string(),
            };
        }
        return routing::service_unavailable_response(&error);
    }

    let mut failures = blocked;
    let mut staged = Vec::new();
    let mut transfers = state.transfers.write().await;
    for (filename, size) in requested_files {
        let duplicate = transfers.entries.iter().any(|entry| {
            entry.direction == 0
                && entry
                    .peer_username
                    .as_deref()
                    .is_some_and(|peer| peer.eq_ignore_ascii_case(&username))
                && entry.filename == filename
                && !is_terminal_transfer_status(&entry.status)
        });
        if duplicate {
            failures.push(serde_json::json!({
                "filename": filename,
                "message": "Transfer is already queued or in progress",
            }));
            continue;
        }
        if !state.config.transfer_allow_outbound {
            failures.push(serde_json::json!({
                "filename": filename,
                "message": "Outbound transfers are disabled",
            }));
            continue;
        }
        let permit = match state.session_commands.clone().try_reserve_owned() {
            Ok(permit) => permit,
            Err(_) => {
                failures.push(serde_json::json!({
                    "filename": filename,
                    "message": "Transfer dispatch capacity is unavailable",
                }));
                continue;
            }
        };
        let details = TransferRequestDetails {
            destination_directory: destination.clone(),
            request_name: Some(virtual_basename(&filename).to_owned()),
            ..TransferRequestDetails::default()
        };
        let relative = if let Some(destination) = destination.as_deref() {
            format!(
                "{}/{}",
                destination.trim_matches(['/', '\\']),
                virtual_basename(&filename)
            )
        } else {
            match render_configured_completed_download_path(
                state,
                &username,
                &filename,
                Some(&batch_id),
                details.request_name.as_deref(),
                unix_timestamp(),
            )
            .await
            {
                Ok(relative) => relative,
                Err(error) => {
                    failures.push(serde_json::json!({"filename": filename, "message": error}));
                    continue;
                }
            }
        };
        let local_path = match configured_download_destination_path(state, &relative).await {
            Ok(path) => Some(path.display().to_string()),
            Err(error) => {
                failures.push(serde_json::json!({"filename": filename, "message": error}));
                continue;
            }
        };
        let entry = transfers.create_with_details(
            0,
            Some(username.clone()),
            filename,
            local_path,
            Some(size),
            Some(batch_id.clone()),
            details,
        );
        let entry = transfers
            .update_status(entry.id, "peer_lookup", None, None)
            .unwrap_or(entry);
        staged.push((entry, permit));
    }
    drop(transfers);

    let staged_entries = staged
        .iter()
        .map(|(entry, _)| entry.clone())
        .collect::<Vec<_>>();
    if let Err(error) = persist_transfer_records(state, &staged_entries).await {
        let ids = staged_entries
            .iter()
            .map(|entry| entry.id)
            .collect::<Vec<_>>();
        state.transfers.write().await.remove_entries(&ids);
        let _ = slskd_delete_transfer_batch(state, &batch_id).await;
        return routing::service_unavailable_response(&error);
    }
    let public_entries = staged_entries
        .iter()
        .map(TransferEntry::slskd_file_json)
        .collect::<Vec<_>>();
    batch = transfer_batch_with_entries(batch, public_entries);
    if state.db.is_none() {
        if let Err(error) = state
            .controller_features
            .write()
            .await
            .upsert(transfer_batch_record_key(&batch_id), batch.clone())
        {
            let ids = staged_entries
                .iter()
                .map(|entry| entry.id)
                .collect::<Vec<_>>();
            state.transfers.write().await.remove_entries(&ids);
            let _ = delete_persisted_transfers(state, &staged_entries).await;
            let _ = slskd_delete_transfer_batch(state, &batch_id).await;
            return routing::service_unavailable_response(&error);
        }
    }
    for (entry, permit) in staged {
        permit.send(SessionCommand::TransferPeer {
            id: entry.id,
            username: username.clone(),
        });
    }
    let status = if failures.len() == files.len() {
        "200 OK"
    } else if failures.is_empty() {
        "201 Created"
    } else {
        "207 Multi-Status"
    };
    HttpResponse {
        status,
        content_type: "application/json",
        body: serde_json::json!({"batch": batch, "failures": failures}).to_string(),
    }
}

fn transfer_request_details_from_json(
    value: &serde_json::Value,
    filename: &str,
) -> TransferRequestDetails {
    let text = |names: &[&str], max_bytes: usize| {
        names
            .iter()
            .find_map(|name| value.get(name).and_then(serde_json::Value::as_str))
            .map(str::trim)
            .filter(|value| !value.is_empty())
            .map(|value| truncate_utf8_bytes(value.to_owned(), max_bytes))
    };
    let number = |names: &[&str]| {
        names
            .iter()
            .find_map(|name| value.get(name).and_then(serde_json::Value::as_u64))
            .and_then(|value| u32::try_from(value).ok())
    };
    let request_id = text(&["requestId", "request_id"], MAX_TRANSFER_REQUEST_ID_BYTES)
        .filter(|value| uuid::Uuid::parse_str(value).is_ok())
        .or_else(|| Some(uuid::Uuid::new_v4().to_string()));
    TransferRequestDetails {
        request_id,
        wishlist_item_id: text(
            &["wishlistItemId", "wishlist_item_id"],
            MAX_TRANSFER_REQUEST_ID_BYTES,
        ),
        request_name: text(
            &["requestName", "request_name", "name"],
            MAX_TRANSFER_REQUEST_NAME_BYTES,
        )
        .or_else(|| Some(virtual_basename(filename).to_owned())),
        destination_directory: text(
            &[
                "destinationDirectory",
                "destination_directory",
                "destination",
            ],
            MAX_TRANSFER_LOCAL_PATH_BYTES,
        ),
        bit_rate: number(&["bitRate", "bit_rate", "bitrate"]),
        sample_rate: number(&["sampleRate", "sample_rate", "samplerate"]),
        bit_depth: number(&["bitDepth", "bit_depth", "bitdepth"]),
        length_seconds: number(&["length", "lengthSeconds", "length_seconds"]),
        artist: text(&["artist"], MAX_TRANSFER_METADATA_TEXT_BYTES),
        album: text(&["album"], MAX_TRANSFER_METADATA_TEXT_BYTES),
        title: text(&["title"], MAX_TRANSFER_METADATA_TEXT_BYTES),
        track_number: number(&["trackNumber", "track_number"]),
        year: number(&["year"]),
        attempts: number(&["attempts"]).unwrap_or(0),
        auto_replace_attempts: number(&["autoReplaceAttempts", "auto_replace_attempts"])
            .unwrap_or(0),
        next_attempt_at: value
            .get("nextAttemptAt")
            .or_else(|| value.get("next_attempt_at"))
            .and_then(serde_json::Value::as_u64),
    }
}

fn slskd_enqueue_request(body: &str) -> Option<(String, Vec<serde_json::Value>)> {
    let payload = serde_json::from_str::<serde_json::Value>(body).ok()?;
    let username = payload.get("username")?.as_str()?.to_owned();
    let files = payload
        .get("files")
        .and_then(serde_json::Value::as_array)
        .cloned()
        .unwrap_or_default();
    (!files.is_empty()).then_some((username, files))
}

fn json_body_string(body: &str) -> Option<String> {
    serde_json::from_str::<serde_json::Value>(body)
        .ok()
        .and_then(|value| value.as_str().map(str::to_owned))
}

fn path_segment_after<'a>(path: &'a str, prefix: &str) -> Option<&'a str> {
    path.strip_prefix(prefix)
        .filter(|segment| !segment.is_empty() && !segment.contains('/'))
}

fn download_request_path(path: &str) -> Option<(&str, Option<&str>)> {
    let rest = path
        .strip_prefix("/api/v0/downloads/requests/")
        .or_else(|| path.strip_prefix("/api/downloads/requests/"))?;
    let (id, action) = rest
        .split_once('/')
        .map_or((rest, None), |(id, action)| (id, Some(action)));
    (!id.is_empty()
        && !id.contains('/')
        && uuid::Uuid::parse_str(id).is_ok()
        && action.is_none_or(|action| !action.is_empty() && !action.contains('/')))
    .then_some((id, action))
}

fn path_segment_between<'a>(path: &'a str, prefix: &str, suffix: &str) -> Option<&'a str> {
    let segment = path.strip_prefix(prefix)?.strip_suffix(suffix)?;
    (!segment.is_empty() && !segment.contains('/')).then_some(segment)
}

fn pod_channel_messages_path(path: &str) -> Option<(String, String)> {
    let rest = path.strip_prefix("/api/pods/")?;
    let (pod_id, rest) = rest.split_once("/channels/")?;
    let channel_id = rest.strip_suffix("/messages")?;
    if pod_id.is_empty()
        || channel_id.is_empty()
        || pod_id.contains('/')
        || channel_id.contains('/')
    {
        return None;
    }
    let pod_id = decoded_path_segment(pod_id).trim().to_owned();
    let channel_id = decoded_path_segment(channel_id).trim().to_owned();
    (!pod_id.is_empty()
        && !channel_id.is_empty()
        && !pod_id.contains('/')
        && !channel_id.contains('/'))
    .then_some((pod_id, channel_id))
}

fn pod_resource_segments(path: &str) -> Option<Vec<String>> {
    let rest = path.strip_prefix("/api/pods/")?;
    let mut segments = Vec::new();
    for segment in rest.split('/') {
        if segment.is_empty() {
            return None;
        }
        let decoded = decoded_path_segment(segment).trim().to_owned();
        if decoded.is_empty() || decoded.contains('/') {
            return None;
        }
        segments.push(decoded);
    }
    (!segments.is_empty()).then_some(segments)
}

/// The frozen slskdN controller receives whitespace-only route values and
/// validates them inside the action, returning 400.  The compatibility
/// dispatcher normally rejects those values in its route-segment helper and
/// would otherwise expose a generic 404 before the controller contract runs.
fn versioned_pods_blank_segment_response(method: &str, path: &str) -> Option<HttpResponse> {
    let rest = path.strip_prefix("/api/v0/pods/")?;
    let segments = rest
        .split('/')
        .map(decoded_path_segment)
        .map(|segment| segment.trim().to_owned())
        .collect::<Vec<_>>();

    let blank_pod = segments.first().is_some_and(String::is_empty);
    let blank_channel = segments.len() >= 3
        && segments.get(1).is_some_and(|segment| segment == "channels")
        && segments.get(2).is_some_and(String::is_empty);
    if !blank_pod && !blank_channel {
        return None;
    }

    let error = if blank_channel {
        "PodId and ChannelId are required"
    } else {
        "PodId is required"
    };
    let _ = method;
    Some(routing::bad_request_response(error))
}

async fn pod_request_peer_id(state: &AppState) -> Option<String> {
    let runtime_peer = state
        .runtime_credentials
        .read()
        .await
        .as_ref()
        .map(|credentials| credentials.username.trim().to_owned())
        .filter(|value| !value.is_empty());
    let configured_peer = state
        .configured_credentials
        .read()
        .await
        .as_ref()
        .map(|credentials| credentials.username.trim().to_owned())
        .filter(|value| !value.is_empty());
    runtime_peer
        .or(configured_peer)
        .or_else(|| (!state.config.auth_required).then(|| "Anonymous".to_owned()))
}

fn gold_star_club_available(state: &AppState) -> bool {
    pods::gold_star_club_available_with_setting(
        &state.config.state_dir,
        state.config.advanced_networking.gold_star_club_autojoin,
    )
}

fn spawn_gold_star_club(state: Arc<AppState>) {
    if !gold_star_club_available(&state) {
        return;
    }
    tokio::spawn(async move {
        loop {
            if !gold_star_club_available(&state) {
                return;
            }
            let (connected, peer_id) = {
                let session = state.session.read().await;
                (
                    session.state == "connected",
                    session
                        .username
                        .clone()
                        .or_else(|| state.config.username.clone())
                        .filter(|value| !value.trim().is_empty()),
                )
            };
            if connected {
                let Some(peer_id) = peer_id else {
                    return;
                };
                let result = {
                    let mut pods = state.pods.write().await;
                    pods.ensure_gold_star_club()
                        .and_then(|_| pods.join(pods::GOLD_STAR_CLUB_POD_ID, peer_id.clone()))
                };
                match result {
                    Ok(Some(true)) => {
                        let member_count = state
                            .pods
                            .read()
                            .await
                            .members(pods::GOLD_STAR_CLUB_POD_ID)
                            .map_or(0, |members| members.len());
                        record_daemon_log(
                            &state,
                            logging::LogLevel::Info,
                            "podcore",
                            format!(
                                "auto-joined {peer_id} to Gold Star Club ({}/{})",
                                member_count,
                                pods::GOLD_STAR_CLUB_MAX_MEMBERS
                            ),
                        )
                        .await;
                    }
                    Ok(Some(false)) => {}
                    Ok(None) => {
                        record_daemon_log(
                            &state,
                            logging::LogLevel::Warn,
                            "podcore",
                            "Gold Star Club pod disappeared before auto-join".to_owned(),
                        )
                        .await;
                    }
                    Err(error) => {
                        record_daemon_log(
                            &state,
                            logging::LogLevel::Warn,
                            "podcore",
                            format!("Gold Star Club auto-join failed: {error}"),
                        )
                        .await;
                    }
                }
                return;
            }
            time::sleep(Duration::from_secs(1)).await;
        }
    });
}

/// True when this instance's own configured Soulseek identity
/// (`pod_request_peer_id`) holds owner/moderator role in `pod_id`.
async fn pod_local_peer_can_moderate(state: &AppState, pod_id: &str) -> bool {
    let acting_peer_id = pod_request_peer_id(state).await;
    let pods = state.pods.read().await;
    acting_peer_id
        .as_deref()
        .is_some_and(|acting| pods.can_moderate(pod_id, acting))
}

async fn versioned_get_failure_contract(
    path: &str,
    query: Option<&str>,
    state: &AppState,
) -> Option<HttpResponse> {
    if !path.starts_with("/api/v0/") {
        return None;
    }

    if state.config.controller_compatibility_target == ControllerCompatibilityTarget::Slskd
        && matches!(
            path,
            "/api/v0/mesh/health" | "/api/v0/signals/config" | "/api/v0/signals/status"
        )
    {
        return Some(HttpResponse {
            status: "400 Bad Request",
            content_type: "application/problem+json",
            body: serde_json::json!({
                "type": "https://docs.api-versioning.org/problems#unsupported",
                "title": "Unsupported API version",
                "status": 400,
                "detail": "The HTTP resource does not support API version 0.",
                "code": "UnsupportedApiVersion",
            })
            .to_string(),
        });
    }

    // FairnessController evaluates its durable TrafficStats row before it
    // builds the decision DTO.  Preserve the frozen slskdN 500 contract when
    // that SQLite dependency is present but unavailable; in-memory/no-DB
    // deployments retain the neutral zero-total response.
    if state.config.controller_compatibility_target == ControllerCompatibilityTarget::Slskdn
        && path == "/api/v0/fairness/summary"
    {
        if let Some(db) = state.db.as_ref() {
            if db.get_traffic_totals().await.is_err() {
                return Some(routing::internal_server_error_response(
                    "fairness storage unavailable",
                ));
            }
        }
    }

    if matches!(
        state.config.controller_compatibility_target,
        ControllerCompatibilityTarget::Slskd | ControllerCompatibilityTarget::Slskdn
    ) && path == "/api/v0/conversations"
        && (query_bool_is_invalid(query, "includeInactive")
            || query_bool_is_invalid(query, "unAcknowledgedOnly"))
    {
        return Some(routing::bad_request_response(
            "The query value must be a boolean",
        ));
    }

    if matches!(
        state.config.controller_compatibility_target,
        ControllerCompatibilityTarget::Slskd | ControllerCompatibilityTarget::Slskdn
    ) && ((path == "/api/v0/application/build"
        && query_bool_is_invalid(query, "checkForUpdates"))
        || (path == "/api/v0/application/version/latest"
            && query_bool_is_invalid(query, "forceCheck")))
    {
        return Some(routing::bad_request_response(
            "The query value must be a boolean",
        ));
    }

    if state.config.controller_compatibility_target == ControllerCompatibilityTarget::Slskdn
        && path == "/api/v0/network/stats"
        && query_bool_is_invalid(query, "includePeers")
    {
        return Some(routing::bad_request_response(
            "The query value must be a boolean",
        ));
    }

    if state.config.controller_compatibility_target == ControllerCompatibilityTarget::Slskdn
        && matches!(path, "/api/v0/opinions" | "/api/v0/opinions/summary")
    {
        let enum_query_is_invalid = |name: &str, max_numeric: i64, names: &[&str]| {
            query_parameter(query, name).is_some_and(|value| {
                let value = value.trim();
                value.parse::<i64>().map_or_else(
                    |_| !names.iter().any(|name| value.eq_ignore_ascii_case(name)),
                    |numeric| !(0..=max_numeric).contains(&numeric),
                )
            })
        };
        if enum_query_is_invalid(
            "subjectType",
            11,
            &[
                "Unknown",
                "User",
                "File",
                "ContentHash",
                "Artist",
                "Album",
                "Track",
                "Pod",
                "Source",
                "MeshPeer",
                "SearchTerm",
                "Other",
            ],
        ) || enum_query_is_invalid(
            "kind",
            9,
            &[
                "Unknown",
                "Like",
                "Hate",
                "Trust",
                "Distrust",
                "Block",
                "Recommend",
                "Quarantine",
                "VerifiedGood",
                "VerifiedBad",
            ],
        ) {
            return Some(routing::bad_request_response(
                "The query value is not valid.",
            ));
        }
        if path == "/api/v0/opinions"
            && (query_bool_is_invalid(query, "includeExpired")
                || query_parameter(query, "limit")
                    .is_some_and(|value| value.parse::<i32>().is_err()))
        {
            return Some(routing::bad_request_response(
                "The query value is not valid.",
            ));
        }
    }

    let relay_settings = state.advanced_networking.read().await.relay.clone();
    if (relay_versioned_route_known("GET", path)
        && !relay_versioned_route_allowed(&relay_settings, "GET", path))
        || matches!(
            path,
            "/api/v0/soulseek/mesh-rendezvous/discover" | "/api/v0/soulseek/mesh-rendezvous/users"
        )
    {
        return Some(routing::forbidden_response(
            "feature is disabled by configuration",
        ));
    }

    let uuid_prefixes = [
        "/api/v0/collections/",
        "/api/v0/contacts/",
        // Must precede the shorter "/api/v0/share-grants/" prefix below --
        // strip_prefix matches whichever prefix is checked first, so a
        // more specific nested prefix must always come before a shorter
        // one it is contained within, or the nested route's real id
        // segment (e.g. a collection UUID) never reaches its own check
        // and instead gets validated against the wrong path segment
        // ("by-collection").
        "/api/v0/share-grants/by-collection/",
        "/api/v0/share-grants/",
        "/api/v0/sharegroups/",
        "/api/v0/wishlist/",
        "/api/v0/multisource/jobs/",
    ];
    for prefix in uuid_prefixes {
        if let Some(value) = path.strip_prefix(prefix) {
            // `nearby` is a literal sibling action on ContactsController,
            // not a contact id.  It must reach the controller's nearby
            // handler instead of being rejected by the Guid route guard.
            if prefix == "/api/v0/contacts/"
                && value.split('/').next().unwrap_or_default() == "nearby"
            {
                continue;
            }
            if prefix == "/api/v0/share-grants/"
                && value.split('/').next().unwrap_or_default() == "announce"
            {
                continue;
            }
            let value = decoded_path_segment(value.split('/').next().unwrap_or_default());
            if uuid::Uuid::parse_str(&value).is_err() {
                return Some(routing::bad_request_response("The request is invalid"));
            }
            // Stop at the first (most specific, since nested prefixes are
            // ordered before the shorter prefixes they're contained
            // within) matching prefix -- otherwise a path validated
            // successfully here would keep matching shorter prefixes
            // later in the list and get re-validated against the wrong
            // path segment.
            break;
        }
    }

    for prefix in ["/api/v0/transfers/downloads/", "/api/v0/transfers/uploads/"] {
        if let Some(value) = path.strip_prefix(prefix) {
            let segments = value.split('/').collect::<Vec<_>>();
            let first = segments.first().copied().unwrap_or_default();
            let special = matches!(
                first,
                "accelerated" | "auto-replace" | "stuck" | "user-stats" | "diagnostics" | "stats"
            );
            if !special && segments.len() >= 2 {
                let valid_id = if first == "batches" {
                    uuid::Uuid::parse_str(segments[1]).is_ok()
                } else {
                    segments[1].parse::<u64>().is_ok()
                };
                if !valid_id {
                    return Some(routing::bad_request_response("The request is invalid"));
                }
            }
        }
    }

    if path.starts_with("/api/v0/mediacore/ipld/traverse/") {
        let content_id =
            decoded_path_segment(path.trim_start_matches("/api/v0/mediacore/ipld/traverse/"));
        if !content_id.starts_with("content:") {
            return Some(routing::bad_request_response("The request is invalid"));
        }
    }

    let has_only_api_version_query = query.is_none_or(|query| {
        query.split('&').all(|pair| {
            pair.split_once('=')
                .map(|(name, _)| name.eq_ignore_ascii_case("api-version"))
                .unwrap_or(false)
        })
    });
    let missing_required_query = matches!(
        path,
        "/api/v0/library/health/issues/by-type"
            | "/api/v0/multisource/search"
            | "/api/v0/multisource/users"
            | "/api/v0/opinions/summary"
            | "/api/v0/podcore/content/metadata"
            | "/api/v0/podcore/content/search"
            | "/api/v0/telemetry/reports/transfers/exceptions"
            | "/api/v0/telemetry/reports/transfers/exceptions/pareto"
            | "/api/v0/telemetry/reports/transfers/leaderboard"
    ) && has_only_api_version_query;
    if missing_required_query {
        return Some(routing::bad_request_response(
            "A required query value is missing",
        ));
    }

    if let Some(username) = path
        .strip_prefix("/api/v0/conversations/")
        .and_then(|value| value.split('/').next())
    {
        let username = decoded_path_segment(username);
        if username != "activity"
            && !username.trim().is_empty()
            && !state
                .messages
                .read()
                .await
                .records
                .iter()
                .any(|record| record.username.eq_ignore_ascii_case(&username))
        {
            return Some(routing::not_found_response());
        }
    }

    if let Some(job_id) = path.strip_prefix("/api/v0/jobs/") {
        if !job_id.contains('/')
            && state
                .searches
                .read()
                .await
                .get_by_identifier(&decoded_path_segment(job_id))
                .is_none()
        {
            return Some(routing::not_found_response());
        }
    }

    if let Some(search_id) = path
        .strip_prefix("/api/v0/searches/")
        .and_then(|value| value.strip_suffix("/responses"))
    {
        if state.config.controller_compatibility_target == ControllerCompatibilityTarget::Slskdn
            && uuid::Uuid::parse_str(search_id).is_err()
            && search_id.parse::<u32>().is_err()
        {
            // SearchResponsesController binds this route segment as a Guid.
            // Validate it before the missing-record check so malformed input
            // remains a 400 instead of being mistaken for an unknown search.
            return Some(routing::bad_request_response("The request is invalid"));
        }
        if state
            .searches
            .read()
            .await
            .get_by_identifier(&decoded_path_segment(search_id))
            .is_none()
        {
            return Some(routing::not_found_response());
        }
    }

    if let Some(segments) = decoded_segments_after(path, "/api/v0/listening-party/radio/") {
        if let [party_id, content_id] = segments.as_slice() {
            // Matches the oracle's real StreamListedParty gate: the party
            // referenced by partyId must actually be listed, must allow
            // mesh streaming, and must currently be playing exactly this
            // contentId -- otherwise NotFound(), evaluated before any
            // stream ticket is even considered. Previously this checked
            // the unrelated global content-discovery shadow-record index,
            // which neither matched the oracle's real per-party gate nor
            // scoped the check to the specific party being queried.
            let listed = state
                .controller_features
                .read()
                .await
                .values_with_prefix("listening-party/")
                .into_iter()
                .any(|event| {
                    event.get("partyId").and_then(serde_json::Value::as_str) == Some(party_id)
                        && event.get("listed").and_then(serde_json::Value::as_bool) == Some(true)
                        && event
                            .get("allowMeshStreaming")
                            .and_then(serde_json::Value::as_bool)
                            == Some(true)
                        && event.get("contentId").and_then(serde_json::Value::as_str)
                            == Some(content_id)
                });
            if !listed {
                return Some(routing::not_found_response());
            }
        }
    }

    for (prefix, suffix) in [
        ("/api/v0/musicbrainz/artist/", "/discography-coverage"),
        ("/api/v0/musicbrainz/overlays/artist/", "/release-graph"),
    ] {
        if let Some(artist_id) = path_segment_between(path, prefix, suffix) {
            let artist_id = decoded_path_segment(artist_id);
            let is_musicbrainz_artist = prefix == "/api/v0/musicbrainz/artist/";
            if !state
                .library
                .read()
                .await
                .records
                .iter()
                .any(|record| record.artist.eq_ignore_ascii_case(&artist_id))
                && !(is_musicbrainz_artist && uuid::Uuid::parse_str(&artist_id).is_ok())
            {
                return Some(routing::not_found_response());
            }
        }
    }

    if let Some(peer_id) = path.strip_prefix("/api/v0/profile/") {
        if peer_id != "me" && !peer_id.contains('/') {
            let peer_id = decoded_path_segment(peer_id).trim().to_owned();
            if peer_id.is_empty() {
                return Some(routing::bad_request_response("PeerId is required."));
            }
            let local_peer_id = local_profile_peer_id(state);
            let known_user = state
                .users
                .read()
                .await
                .records
                .iter()
                .any(|user| user.username.eq_ignore_ascii_case(&peer_id));
            if !peer_id.eq_ignore_ascii_case(&local_peer_id) && !known_user {
                return Some(routing::not_found_response());
            }
        }
    }

    if path == "/api/v0/security/adversarial"
        && state.config.controller_compatibility_target == ControllerCompatibilityTarget::Slskdn
    {
        // The frozen slskdN controller's direct settings GET remains
        // unregistered even after a successful PUT and persisted YAML update.
        // Keep the mutation/readback store available to its own management
        // flow, but preserve the externally observable GET contract.
        return Some(HttpResponse {
            status: "404 Not Found",
            content_type: "text/plain; charset=utf-8",
            body: "Adversarial features are not configured".to_owned(),
        });
    }

    if matches!(
        path,
        "/api/v0/security/canaries" | "/api/v0/security/tor/status"
    ) {
        let feature_key = if path.ends_with("/canaries") {
            "security/profile/security/canaries"
        } else {
            "security/profile/security/tor"
        };
        let configured = state
            .controller_features
            .read()
            .await
            .get(feature_key)
            .is_some();
        if !configured {
            return Some(routing::not_found_response());
        }
    }

    if let Some(share_id) = path.strip_prefix("/api/v0/shares/") {
        let share_id = decoded_path_segment(share_id.split('/').next().unwrap_or_default());
        if !matches!(share_id.as_str(), "catalog" | "contents") && {
            let shares = state.shares.read().await;
            !shares
                .roots
                .iter()
                .any(|root| share_root_id(&root.label) == share_id)
        } {
            return Some(HttpResponse {
                status: "404 Not Found",
                content_type: "",
                body: String::new(),
            });
        }
    }

    for (prefix, direction) in [
        ("/api/v0/transfers/downloads/", 0_u32),
        ("/api/v0/transfers/uploads/", 1_u32),
    ] {
        if let Some(value) = path.strip_prefix(prefix) {
            let raw_username = value.split('/').next().unwrap_or_default();
            if matches!(
                raw_username,
                "" | "accelerated"
                    | "auto-replace"
                    | "stuck"
                    | "user-stats"
                    | "diagnostics"
                    | "stats"
                    | "batches"
            ) {
                continue;
            }
            let username = decoded_path_segment(raw_username);
            if state.config.controller_compatibility_target == ControllerCompatibilityTarget::Slskdn
                && username.trim().is_empty()
            {
                return Some(routing::bad_request_response("The request is invalid"));
            }
            if !state.transfers.read().await.entries.iter().any(|entry| {
                entry.direction == direction
                    && entry
                        .peer_username
                        .as_deref()
                        .is_some_and(|peer| peer.eq_ignore_ascii_case(&username))
            }) {
                return Some(routing::not_found_response());
            }
        }
    }

    if let Some(username) = path
        .strip_prefix("/api/v0/users/")
        .and_then(|value| value.strip_suffix("/browse/status"))
    {
        if state
            .browse
            .read()
            .await
            .get(&decoded_path_segment(username))
            .is_none()
        {
            return Some(routing::not_found_response());
        }
    }

    if let Some(username) = path
        .strip_prefix("/api/v0/multisource/users/")
        .and_then(|value| value.strip_suffix("/files"))
    {
        let username = decoded_path_segment(username).trim().to_owned();
        if username.is_empty() {
            return Some(routing::bad_request_response("Username is required"));
        }
        if !state
            .searches
            .read()
            .await
            .records
            .iter()
            .flat_map(|search| &search.results)
            .any(|result| {
                result
                    .peer_username
                    .as_deref()
                    .is_some_and(|peer| peer.eq_ignore_ascii_case(&username))
            })
        {
            return Some(routing::bad_request_response(
                "No search results. Call /users?searchText=... first",
            ));
        }
    }

    None
}

fn relay_versioned_route_allowed(
    settings: &config::RelaySettings,
    method: &str,
    path: &str,
) -> bool {
    if !relay_versioned_route_known(method, path) {
        return false;
    }
    if !settings.enabled {
        return false;
    }
    let mode = settings.mode.as_str();
    match method {
        "PUT" | "DELETE" => path == "/api/v0/relay/agent" && matches!(mode, "agent" | "debug"),
        "GET" => {
            (path.starts_with("/api/v0/relay/controller/downloads/")
                || path.starts_with("/api/v0/relay/streams/"))
                && matches!(mode, "controller" | "debug")
        }
        "POST" => {
            (path.starts_with("/api/v0/relay/controller/files/")
                || path.starts_with("/api/v0/relay/controller/shares/"))
                && matches!(mode, "controller" | "debug")
        }
        _ => false,
    }
}

fn relay_versioned_route_known(method: &str, path: &str) -> bool {
    let has_one_segment = |prefix: &str| {
        path.strip_prefix(prefix)
            .is_some_and(|value| !value.is_empty() && !value.contains('/'))
    };
    match method {
        "PUT" | "DELETE" => path == "/api/v0/relay/agent",
        "GET" => {
            has_one_segment("/api/v0/relay/controller/downloads/")
                || has_one_segment("/api/v0/relay/streams/")
        }
        "POST" => {
            has_one_segment("/api/v0/relay/controller/files/")
                || has_one_segment("/api/v0/relay/controller/shares/")
        }
        _ => false,
    }
}

fn relay_multipart_boundary(content_type: Option<&str>) -> Option<String> {
    let content_type = content_type?.trim();
    let mut parts = content_type.split(';');
    let media_type = parts.next()?.trim();
    if !media_type.eq_ignore_ascii_case("multipart/form-data") {
        return None;
    }
    parts.find_map(|part| {
        let (name, value) = part.trim().split_once('=')?;
        if !name.trim().eq_ignore_ascii_case("boundary") {
            return None;
        }
        let value = value.trim().trim_matches('"');
        (!value.is_empty()).then(|| value.to_owned())
    })
}

async fn versioned_relay_request(
    method: &str,
    path: &str,
    body: &str,
    headers: &RequestSecurityHeaders,
    state: &AppState,
) -> Option<HttpResponse> {
    versioned_relay_request_bytes(method, path, body.as_bytes(), headers, state).await
}

async fn versioned_relay_request_bytes(
    method: &str,
    path: &str,
    body: &[u8],
    headers: &RequestSecurityHeaders,
    state: &AppState,
) -> Option<HttpResponse> {
    if !path.starts_with("/api/v0/relay/") {
        return None;
    }

    if !relay_versioned_route_known(method, path) {
        return None;
    }

    let settings = state.advanced_networking.read().await.relay.clone();
    if !relay_versioned_route_allowed(&settings, method, path) {
        return Some(routing::forbidden_response(
            "feature is disabled by configuration",
        ));
    }

    if path == "/api/v0/relay/agent" && method == "PUT" {
        let result = mutate_runtime_compat_state(state, |runtime, relay| {
            relay.set_enabled(true);
            runtime.set_relay_agent(true).to_string()
        })
        .await;
        return Some(match result {
            Ok(_) => HttpResponse {
                status: "200 OK",
                content_type: "",
                body: String::new(),
            },
            Err(error) => routing::service_unavailable_response(&error),
        });
    }

    if path == "/api/v0/relay/agent" && method == "DELETE" {
        let result = mutate_runtime_compat_state(state, |runtime, _| {
            runtime.set_relay_agent(false).to_string()
        })
        .await;
        return Some(match result {
            Ok(_) => routing::no_content_response(),
            Err(error) => routing::service_unavailable_response(&error),
        });
    }

    if method == "GET" && path.starts_with("/api/v0/relay/controller/downloads/") {
        let token = path_segment_after(path, "/api/v0/relay/controller/downloads/")
            .map(decoded_path_segment)
            .unwrap_or_default();
        let Ok(token) = uuid::Uuid::parse_str(token.trim()) else {
            return Some(routing::bad_request_response(
                "Token is not in a valid format",
            ));
        };
        let Some(credential) = headers
            .x_relay_credential
            .as_deref()
            .map(str::trim)
            .filter(|credential| !credential.is_empty())
        else {
            return Some(routing::unauthorized_response());
        };
        let authorized = state.relay.write().await.protocol.validate_download(
            &settings,
            relay::credential_scheme(state.config.controller_compatibility_target),
            token,
            credential,
            unix_timestamp(),
        );
        return Some(match authorized {
            Some(_) => HttpResponse {
                status: "200 OK",
                content_type: "application/octet-stream",
                body: String::new(),
            },
            None => routing::unauthorized_response(),
        });
    }

    if method == "POST" && path.starts_with("/api/v0/relay/controller/files/") {
        let token = path_segment_after(path, "/api/v0/relay/controller/files/")
            .map(decoded_path_segment)
            .unwrap_or_default();
        let Ok(token) = uuid::Uuid::parse_str(token.trim()) else {
            return Some(routing::bad_request_response(
                "Token is not in a valid format",
            ));
        };
        if relay_multipart_boundary(headers.content_type.as_deref()).is_none() {
            return Some(HttpResponse {
                status: "415 Unsupported Media Type",
                content_type: "application/json",
                body: String::new(),
            });
        }
        let Some(credential) = headers
            .x_relay_credential
            .as_deref()
            .map(str::trim)
            .filter(|credential| !credential.is_empty())
        else {
            return Some(routing::unauthorized_response());
        };
        let parts = match relay::parse_multipart(body, headers.content_type.as_deref()) {
            Ok(parts) => parts,
            Err(_) => {
                return Some(routing::bad_request_response(
                    "Upload file section is missing",
                ));
            }
        };
        let Some(file_part) = parts.iter().find(|part| part.filename.is_some()) else {
            return Some(routing::bad_request_response(
                "Upload file section is missing",
            ));
        };
        let Some(filename) = file_part.filename.as_deref() else {
            return Some(routing::bad_request_response("Upload filename is missing"));
        };
        if filename.is_empty() || filename.contains("..") {
            return Some(routing::bad_request_response("Invalid filename"));
        }
        let authorized = state.relay.write().await.protocol.validate_file_upload(
            &settings,
            relay::credential_scheme(state.config.controller_compatibility_target),
            token,
            filename,
            credential,
            unix_timestamp(),
        );
        return Some(match authorized {
            Some(_) => match persist_relay_upload_part(state, token, filename, &file_part.data) {
                Ok(upload) => {
                    let _ = relay::RuntimeState::complete_file_stream(token, upload);
                    HttpResponse {
                        status: "200 OK",
                        content_type: "",
                        body: String::new(),
                    }
                }
                Err(error) => {
                    let _ = relay::RuntimeState::fail_file_stream_token(token, error.clone());
                    relay_upload_error_response(&error)
                }
            },
            None => routing::unauthorized_response(),
        });
    }

    if method == "POST" && path.starts_with("/api/v0/relay/controller/shares/") {
        let token = path_segment_after(path, "/api/v0/relay/controller/shares/")
            .map(decoded_path_segment)
            .unwrap_or_default();
        let Ok(token) = uuid::Uuid::parse_str(token.trim()) else {
            return Some(routing::bad_request_response("Token is not a valid Guid"));
        };
        if relay_multipart_boundary(headers.content_type.as_deref()).is_none() {
            return Some(HttpResponse {
                status: "415 Unsupported Media Type",
                content_type: "application/json",
                body: String::new(),
            });
        }
        let Some(credential) = headers
            .x_relay_credential
            .as_deref()
            .map(str::trim)
            .filter(|credential| !credential.is_empty())
        else {
            return Some(routing::unauthorized_response());
        };
        let parts = match relay::parse_multipart(body, headers.content_type.as_deref()) {
            Ok(parts) => parts,
            Err(_) => {
                return Some(routing::bad_request_response(
                    "Share multipart sections are missing",
                ));
            }
        };
        let authorized = state.relay.write().await.protocol.validate_share_upload(
            &settings,
            relay::credential_scheme(state.config.controller_compatibility_target),
            token,
            credential,
            unix_timestamp(),
        );
        return Some(match authorized {
            Some(authorized) => {
                let share_part = parts.iter().find(|part| part.name == "shares");
                let database_part = parts.iter().find(|part| part.filename.is_some());
                let Some(share_part) = share_part else {
                    return Some(routing::bad_request_response(
                        "Share metadata section is missing",
                    ));
                };
                let shares = match serde_json::from_slice::<serde_json::Value>(&share_part.data) {
                    Ok(value) if value.is_array() => value,
                    _ => {
                        return Some(routing::bad_request_response(
                            "Share metadata is not a JSON array",
                        ));
                    }
                };
                let metadata_shares = shares
                    .as_array()
                    .into_iter()
                    .flatten()
                    .filter_map(|share| {
                        let filename = share.get("filename")?.as_str()?.trim();
                        let size = share.get("size").and_then(serde_json::Value::as_u64)?;
                        (!filename.is_empty()).then(|| relay::RemoteShare {
                            filename: filename.to_owned(),
                            size,
                        })
                    })
                    .collect::<Vec<_>>();
                let Some(database_part) = database_part else {
                    return Some(routing::bad_request_response(
                        "Share database section is missing",
                    ));
                };
                match persist_relay_share_database(
                    state,
                    token,
                    database_part.filename.as_deref().unwrap_or("shares.db"),
                    &database_part.data,
                ) {
                    Ok(database_path) => match relay::read_share_database(
                        &database_path,
                        state.config.controller_compatibility_target,
                    )
                    .await
                    {
                        Ok(mut remote_shares) => {
                            // Older slskR agents sent file-shaped metadata while the
                            // frozen agents send share-root metadata.  Keep the former
                            // as a compatibility fallback, but always validate and
                            // extract the uploaded SQLite repository first.
                            if remote_shares.is_empty() && !metadata_shares.is_empty() {
                                remote_shares = metadata_shares;
                            }
                            match state.relay.write().await.protocol.record_share_upload(
                                token,
                                authorized.agent_name,
                                remote_shares.len(),
                                remote_shares,
                                database_path.clone(),
                                unix_timestamp(),
                            ) {
                                Ok(()) => HttpResponse {
                                    status: "200 OK",
                                    content_type: "",
                                    body: String::new(),
                                },
                                Err(error) => {
                                    let _ = fs::remove_file(&database_path);
                                    relay_upload_error_response(&error)
                                }
                            }
                        }
                        Err(error) => {
                            let _ = fs::remove_file(&database_path);
                            routing::bad_request_response(&error)
                        }
                    },
                    Err(error) => relay_upload_error_response(&error),
                }
            }
            None => routing::unauthorized_response(),
        });
    }

    None
}

fn relay_upload_directory(state: &AppState) -> Result<PathBuf, String> {
    let directory = state.config.state_dir.join("relay").join("incoming");
    fs::create_dir_all(&directory)
        .map_err(|error| format!("relay upload directory create failed: {error}"))?;
    Ok(directory)
}

fn relay_upload_error_response(error: &str) -> HttpResponse {
    eprintln!("relay upload operation failed: {error}");
    routing::service_unavailable_response("relay upload unavailable")
}

fn persist_relay_upload_part(
    state: &AppState,
    token: uuid::Uuid,
    filename: &str,
    data: &[u8],
) -> Result<relay::UploadedFile, String> {
    let directory = relay_upload_directory(state)?;
    let path = directory.join(format!("file-{}.part", token.simple()));
    fs::write(&path, data).map_err(|error| format!("relay file upload write failed: {error}"))?;
    Ok(relay::UploadedFile {
        filename: filename.to_owned(),
        path,
        length: data.len() as u64,
    })
}

fn persist_relay_share_database(
    state: &AppState,
    token: uuid::Uuid,
    filename: &str,
    data: &[u8],
) -> Result<PathBuf, String> {
    let directory = relay_upload_directory(state)?;
    let extension = Path::new(filename)
        .extension()
        .and_then(|value| value.to_str())
        .filter(|value| value.len() <= 16 && value.bytes().all(|byte| byte.is_ascii_alphanumeric()))
        .unwrap_or("db");
    let path = directory.join(format!("share-{}.{}", token.simple(), extension));
    fs::write(&path, data)
        .map_err(|error| format!("relay share database write failed: {error}"))?;
    Ok(path)
}

fn decoded_path_segment(segment: &str) -> String {
    percent_decode_component(segment)
}

async fn create_preview_stream_ticket(
    state: &AppState,
    family: &str,
    body: &str,
) -> Result<String, String> {
    let payload = serde_json::from_str::<serde_json::Value>(body).ok();
    let field = |name: &str| {
        payload
            .as_ref()
            .and_then(|value| value.get(name))
            .and_then(serde_json::Value::as_str)
            .map(ToOwned::to_owned)
    };
    let mesh_contract = family == "mesh";
    let content_id = if mesh_contract {
        let value = field("contentId").ok_or_else(|| "ContentId is required.".to_owned())?;
        let value = normalize_preview_identifier(value, "ContentId", 512)?;
        Some(value)
    } else {
        field("contentId")
            .or_else(|| field("content_id"))
            .or_else(|| field("id"))
    };
    let filename = if mesh_contract {
        let value = field("filename").ok_or_else(|| "Filename is required.".to_owned())?;
        normalize_preview_filename(value)?
    } else {
        let value = field("filename")
            .or_else(|| field("path"))
            .or_else(|| content_id.clone())
            .ok_or_else(|| "Filename is required.".to_owned())?;
        normalize_preview_filename(value)?
    };
    let peer_username = if mesh_contract {
        field("peerId")
            .filter(|value| !value.trim().is_empty())
            .map(|value| normalize_preview_identifier(value, "PeerId", 512))
            .transpose()?
    } else if matches!(family, "peer" | "soulseek") {
        let value = field("username")
            .or_else(|| field("peerUsername"))
            .or_else(|| field("peer_username"))
            .or_else(|| field("peerId"))
            .ok_or_else(|| "Username is required.".to_owned())?;
        let value = value.trim();
        if value.is_empty()
            || value.encode_utf16().count() > 256
            || value.chars().any(char::is_control)
        {
            return Err("Username is required.".to_owned());
        }
        Some(value.to_owned())
    } else {
        field("username")
            .or_else(|| field("peerUsername"))
            .or_else(|| field("peer_username"))
            .or_else(|| field("peerId"))
    };
    let requested_size = if mesh_contract {
        let value = payload
            .as_ref()
            .and_then(|payload| payload.get("expectedSize").or_else(|| payload.get("size")));
        match value {
            None | Some(serde_json::Value::Null) => 0,
            Some(value) => value
                .as_i64()
                .filter(|value| *value >= 0)
                .and_then(|value| u64::try_from(value).ok())
                .or_else(|| value.as_u64())
                .ok_or_else(|| "Expected size must be greater than or equal to zero.".to_owned())?,
        }
    } else {
        match payload.as_ref().and_then(|payload| payload.get("size")) {
            None | Some(serde_json::Value::Null) => 0,
            Some(value) => value
                .as_i64()
                .filter(|value| *value >= 0)
                .and_then(|value| u64::try_from(value).ok())
                .or_else(|| value.as_u64())
                .ok_or_else(|| "Size must be greater than or equal to zero.".to_owned())?,
        }
    };
    if requested_size > MAX_PREVIEW_STREAM_BYTES {
        return Err("preview stream size exceeds the 2 GiB limit".to_owned());
    }
    let source_url = extract_json_string_field(body, "sourceUrl")
        .or_else(|| extract_json_string_field(body, "source_url"));
    let source_authorization = extract_json_string_field(body, "sourceAuthorization")
        .or_else(|| extract_json_string_field(body, "source_authorization"));
    let expected_hash = field("expectedHash").or_else(|| field("expected_hash"));
    let expected_hash = expected_hash
        .as_deref()
        .map(str::trim)
        .filter(|value| !value.is_empty())
        .map(ToOwned::to_owned);
    if mesh_contract
        && expected_hash.as_deref().is_some_and(|hash| {
            hash.len() != 64 || !hash.bytes().all(|byte| byte.is_ascii_hexdigit())
        })
    {
        return Err("Expected hash must be a SHA-256 hex digest.".to_owned());
    }
    if mesh_contract && content_id.as_deref().is_none_or(str::is_empty) {
        return Err("contentId is required".to_owned());
    }
    let content_type = if mesh_contract {
        mesh_preview_stream_content_type(&filename).unwrap_or("application/octet-stream")
    } else {
        preview_stream_content_type(&filename)
    };
    if content_type == "application/octet-stream" {
        return Err(if mesh_contract {
            "Only audio files can be preview streamed from mesh peers.".to_owned()
        } else {
            "Only audio files can be preview streamed from peers.".to_owned()
        });
    }
    let content_type = content_type.to_owned();
    let remote_mesh = match source_url {
        Some(_) if family != "mesh" => {
            return Err("sourceUrl is supported only for mesh preview streams".to_owned());
        }
        Some(source_url) => {
            if requested_size == 0 {
                return Err("size is required for a remote mesh preview".to_owned());
            }
            if source_authorization
                .as_ref()
                .is_some_and(|value| value.contains(['\r', '\n']) || value.len() > 8 * 1024)
            {
                return Err("sourceAuthorization is invalid".to_owned());
            }
            let expected_hash = expected_hash
                .as_deref()
                .map(str::trim)
                .filter(|hash| {
                    hash.len() == 64 && hash.bytes().all(|byte| byte.is_ascii_hexdigit())
                })
                .ok_or_else(|| {
                    "expectedHash must be a SHA-256 digest for a remote mesh preview".to_owned()
                })?
                .to_ascii_lowercase();
            Some((source_url, source_authorization, expected_hash))
        }
        None => None,
    };

    let shares = state.shares.read().await;
    let transfers = state.transfers.read().await;
    let searches = state.searches.read().await;
    let share = shares.entries.iter().find(|entry| {
        let hash = stable_content_hash(&entry.filename, entry.size).to_string();
        entry.filename == filename
            || content_id.as_deref() == Some(entry.filename.as_str())
            || content_id.as_deref() == Some(hash.as_str())
    });
    let transfer = transfers.entries.iter().find(|entry| {
        entry.filename == filename
            || content_id
                .as_deref()
                .and_then(|id| id.strip_prefix("transfer-"))
                .and_then(|id| id.parse::<u64>().ok())
                == Some(entry.id)
    });
    let search_result = searches.records.iter().find_map(|record| {
        record.results.iter().find(|result| {
            (result.filename == filename || content_id.as_deref() == Some(result.filename.as_str()))
                && peer_username
                    .as_deref()
                    .is_none_or(|peer| result.peer_username.as_deref() == Some(peer))
        })
    });

    let resolved_filename = share
        .map(|entry| entry.filename.clone())
        .or_else(|| transfer.map(|entry| entry.filename.clone()))
        .or_else(|| search_result.map(|entry| entry.filename.clone()))
        .unwrap_or(filename);
    let resolved_size = share
        .map(|entry| entry.size)
        .or_else(|| transfer.and_then(|entry| entry.size))
        .or_else(|| search_result.map(|entry| entry.size))
        .unwrap_or(requested_size);
    let resolved_content_id = content_id
        .unwrap_or_else(|| stable_content_hash(&resolved_filename, resolved_size).to_string());
    let resolved_peer_username =
        peer_username.or_else(|| search_result.and_then(|entry| entry.peer_username.clone()));
    let source = if share.is_some() {
        "local-share"
    } else if transfer.is_some() {
        "transfer"
    } else if search_result.is_some() && family == "mesh" {
        "mesh-preview"
    } else if search_result.is_some() {
        "peer-preview"
    } else if family == "mesh" {
        "mesh-unresolved"
    } else {
        "peer-unresolved"
    };
    drop(searches);
    drop(transfers);
    drop(shares);

    let remote_overlay = if family == "mesh"
        && remote_mesh.is_none()
        && !matches!(source, "local-share" | "transfer")
    {
        if let Some(identity) = resolved_peer_username.as_deref() {
            let trusted = state
                .config
                .trusted_mesh_peers
                .iter()
                .find(|peer| peer.matches(identity));
            trusted
                .map(|peer| {
                    if resolved_size == 0 {
                        return Err("size is required for a trusted mesh preview".to_owned());
                    }
                    let expected_hash = expected_hash
                        .as_deref()
                        .map(str::trim)
                        .filter(|hash| {
                            hash.len() == 64 && hash.bytes().all(|byte| byte.is_ascii_hexdigit())
                        })
                        .ok_or_else(|| {
                            "expectedHash must be a SHA-256 digest for a trusted mesh preview"
                                .to_owned()
                        })?;
                    Ok((peer.peer_id.clone(), expected_hash.to_ascii_lowercase()))
                })
                .transpose()?
        } else {
            None
        }
    } else {
        None
    };

    let mut tickets = state.stream_tickets.write().await;
    let Some((token, ticket)) = tickets.issue(
        family,
        source,
        resolved_content_id,
        resolved_filename,
        resolved_peer_username,
        resolved_size,
        content_type,
        120,
    ) else {
        return Err("preview stream ticket capacity is full".to_owned());
    };
    if let Some((source_url, source_authorization, expected_hash)) = remote_mesh {
        if !tickets.configure_remote_mesh(&token, source_url, source_authorization, expected_hash) {
            return Err("preview stream ticket could not be configured".to_owned());
        }
    } else if let Some((peer_identity, expected_hash)) = remote_overlay {
        if !tickets.configure_remote_overlay(&token, peer_identity, expected_hash) {
            return Err("preview stream ticket could not be configured".to_owned());
        }
    }
    drop(tickets);

    let body = if mesh_contract {
        serde_json::json!({
            "ticket": token,
            "streamUrl": format!("/api/v0/mesh-streams/{}", url_encode(&token)),
            "expiresInSeconds": 120,
            "contentType": ticket.content_type,
            "source": "mesh",
        })
        .to_string()
    } else {
        serde_json::json!({
            "ticket": token,
            "streamUrl": format!("/api/v0/{family}-streams/{}", url_encode(&token)),
            "stream_url": format!("/api/v0/{family}-streams/{}", url_encode(&token)),
            "expiresInSeconds": 120,
            "contentType": ticket.content_type,
            "content_id": ticket.content_id,
            "filename": ticket.filename,
            "size": ticket.size,
            "source": ticket.source,
        })
        .to_string()
    };
    Ok(body)
}

fn normalize_preview_identifier(
    value: String,
    field_name: &str,
    max_utf16_units: usize,
) -> Result<String, String> {
    let value = value.trim();
    if value.is_empty()
        || value.encode_utf16().count() > max_utf16_units
        || value.chars().any(char::is_control)
    {
        return Err(format!("{field_name} is required."));
    }
    Ok(value.to_owned())
}

fn normalize_preview_filename(value: String) -> Result<String, String> {
    let value = value.trim();
    if value.is_empty()
        || value.encode_utf16().count() > 4_096
        || value.chars().any(char::is_control)
        || preview_filename_contains_traversal(value)
        || Path::new(value).is_absolute()
        || (value
            .as_bytes()
            .first()
            .is_some_and(|character| character.is_ascii_alphabetic())
            && value
                .as_bytes()
                .get(1)
                .is_some_and(|separator| *separator == b':'))
    {
        return Err("Filename is required.".to_owned());
    }
    Ok(value.to_owned())
}

fn preview_filename_contains_traversal(value: &str) -> bool {
    let mut decoded = value.to_owned();
    for _ in 0..5 {
        let next = percent_decode_component(&decoded);
        if next == decoded {
            break;
        }
        decoded = next;
    }
    value.contains("..") || decoded.contains("..")
}

async fn virtual_soulfind_catalogue(state: &AppState) -> Vec<virtual_soulfind_v2::CatalogueItem> {
    let shares = state.shares.read().await;
    shares
        .entries
        .iter()
        .filter(|entry| matches!(library_media_kind(&entry.extension), "Audio"))
        .map(|entry| {
            let (artist, title) = virtual_soulfind_file_metadata(&entry.filename);
            let local_path = shares
                .local_paths
                .get(&entry.filename)
                .map(|path| path.display().to_string());
            let source_id = format!(
                "share:{}",
                hex::encode(Sha256::digest(
                    format!("{}|{}", entry.filename, entry.size).as_bytes(),
                ))
            );
            virtual_soulfind_v2::CatalogueItem {
                source_id,
                artist,
                title,
                kind: "Album".to_owned(),
                created_at: unix_timestamp(),
                local_path,
                size: entry.size,
            }
        })
        .collect()
}

fn virtual_soulfind_file_metadata(filename: &str) -> (String, String) {
    let relative = filename.split_once('/').map_or(filename, |(_, path)| path);
    let components = relative.split('/').filter(|part| !part.is_empty()).collect::<Vec<_>>();
    let basename = components.last().copied().unwrap_or(relative);
    let title = basename
        .rsplit_once('.')
        .map_or(basename, |(stem, _)| stem)
        .trim();
    let (artist, title) = title
        .split_once(" - ")
        .map_or_else(
            || {
                (
                    components
                        .get(components.len().saturating_sub(2))
                        .copied()
                        .unwrap_or("Unknown Artist"),
                    title,
                )
            },
            |(artist, title)| (artist.trim(), title.trim()),
        );
    (
        if artist.is_empty() {
            "Unknown Artist".to_owned()
        } else {
            artist.to_owned()
        },
        if title.is_empty() {
            "Unknown Track".to_owned()
        } else {
            title.to_owned()
        },
    )
}

async fn route_virtual_soulfind_v2(
    method: &str,
    path: &str,
    query: Option<&str>,
    body: &str,
    state: &AppState,
) -> HttpResponse {
    if state.config.controller_compatibility_target == ControllerCompatibilityTarget::Slskd {
        return routing::not_found_response();
    }
    if !state.config.virtual_soulfind_v2_enabled {
        return routing::service_unavailable_string_response("VirtualSoulfind v2 is disabled");
    }
    let Some(suffix) = path.strip_prefix("/api/virtualsoulfind/v2") else {
        return routing::not_found_response();
    };
    let value = || {
        serde_json::from_str::<serde_json::Value>(body)
            .map_err(|_| routing::bad_request_response("invalid request body"))
    };

    // ASP.NET binds a present-but-blank route parameter and the controller
    // returns BadRequest after trimming it.  The generic route helpers reject
    // that shape as an unmatched route, which would incorrectly turn the
    // frozen 400 contract into 404.  Keep this correction local to the
    // VirtualSoulfind v2 dispatcher.
    if [
        ("/intents/tracks/", ""),
        ("/intents/releases/", ""),
        ("/catalogue/artists/", ""),
        ("/catalogue/releases/", ""),
        ("/executions/", ""),
    ]
    .iter()
    .any(|(prefix, _)| virtual_soulfind_blank_single_segment(suffix, prefix))
        || virtual_soulfind_blank_action_segment(suffix, "/intents/tracks/", "/process")
        || virtual_soulfind_blank_action_segment(suffix, "/catalogue/artists/", "/releases")
        || virtual_soulfind_blank_action_segment(suffix, "/catalogue/releases/", "/tracks")
    {
        return routing::bad_request_response("");
    }

    match (method, suffix) {
        ("POST", "/intents/tracks") => {
            let request = match value() {
                Ok(value) => value,
                Err(response) => return response,
            };
            let track_id = request
                .get("trackId")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default();
            let domain = request
                .get("domain")
                .cloned()
                .unwrap_or_else(|| serde_json::json!("Music"));
            let priority = request
                .get("priority")
                .cloned()
                .unwrap_or_else(|| serde_json::json!("Normal"));
            let parent = request
                .get("parentDesiredReleaseId")
                .and_then(serde_json::Value::as_str);
            match state
                .virtual_soulfind_v2
                .write()
                .await
                .enqueue_track(&domain, track_id, &priority, parent)
            {
                Ok(intent) => routing::created_response(intent.to_string()),
                Err(error) if error.contains("capacity") => {
                    routing::service_unavailable_response(&error)
                }
                Err(error) => routing::bad_request_response(&error),
            }
        }
        ("POST", "/intents/releases") => {
            let request = match value() {
                Ok(value) => value,
                Err(response) => return response,
            };
            let release_id = request
                .get("releaseId")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default();
            let priority = request
                .get("priority")
                .cloned()
                .unwrap_or_else(|| serde_json::json!("Normal"));
            let mode = request
                .get("mode")
                .cloned()
                .unwrap_or_else(|| serde_json::json!("Wanted"));
            let notes = request.get("notes").and_then(serde_json::Value::as_str);
            match state
                .virtual_soulfind_v2
                .write()
                .await
                .enqueue_release(release_id, &priority, &mode, notes)
            {
                Ok(intent) => routing::created_response(intent.to_string()),
                Err(error) if error.contains("capacity") => {
                    routing::service_unavailable_response(&error)
                }
                Err(error) => routing::bad_request_response(&error),
            }
        }
        ("GET", "/intents/tracks/pending") => {
            let limit = match query_bounded_usize(query, "limit", 0, 1_024) {
                Ok(limit) => limit.unwrap_or(100),
                Err(()) => return routing::bad_request_response("limit is invalid"),
            };
            routing::ok_response(
                state
                    .virtual_soulfind_v2
                    .read()
                    .await
                    .pending_tracks(limit)
                    .to_string(),
            )
        }
        ("GET", "/stats") => {
            routing::ok_response(state.virtual_soulfind_v2.read().await.stats().to_string())
        }
        ("GET", "/catalogue/artists/search") => {
            let Some(query_text) = query_parameter(query, "query")
                .map(|value| value.trim().to_owned())
                .filter(|value| !value.is_empty())
            else {
                return routing::bad_request_response("Query is required");
            };
            if query_text.len() > 512 || query_text.chars().any(char::is_control) {
                return routing::bad_request_response("Query is invalid");
            }
            let limit = match query_bounded_usize(query, "limit", 0, 100) {
                Ok(limit) => limit.unwrap_or(50),
                Err(()) => return routing::bad_request_response("limit is invalid"),
            };
            routing::ok_response(
                virtual_soulfind_v2::search_artists(
                    &virtual_soulfind_catalogue(state).await,
                    &query_text,
                    limit,
                )
                .to_string(),
            )
        }
        ("POST", "/plans") => {
            let request = match value() {
                Ok(value) => value,
                Err(response) => return response,
            };
            let track_id = request
                .get("trackId")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default();
            let domain = request
                .get("domain")
                .cloned()
                .unwrap_or_else(|| serde_json::json!("Music"));
            let mode = request
                .get("mode")
                .cloned()
                .unwrap_or_else(|| serde_json::json!("SoulseekFriendly"));
            let priority = request
                .get("priority")
                .cloned()
                .unwrap_or_else(|| serde_json::json!("Normal"));
            match virtual_soulfind_v2::create_plan(
                &virtual_soulfind_catalogue(state).await,
                &domain,
                track_id,
                &mode,
                &priority,
            ) {
                Ok(plan) => routing::ok_response(plan.to_string()),
                Err(error) => routing::bad_request_response(&error),
            }
        }
        _ => {
            if let Some(id) = single_route_segment(suffix, "/intents/tracks/") {
                return match method {
                    "GET" => state
                        .virtual_soulfind_v2
                        .read()
                        .await
                        .track(&decoded_path_segment(id))
                        .map_or_else(routing::not_found_response, |intent| {
                            routing::ok_response(intent.to_string())
                        }),
                    "PATCH" => {
                        let request = match value() {
                            Ok(value) => value,
                            Err(response) => return response,
                        };
                        let status = request
                            .get("status")
                            .cloned()
                            .unwrap_or(serde_json::Value::Null);
                        match state
                            .virtual_soulfind_v2
                            .write()
                            .await
                            .update_track_status(&decoded_path_segment(id), &status)
                        {
                            Ok(true) => routing::no_content_response(),
                            Ok(false) => routing::not_found_response(),
                            Err(error) => routing::bad_request_response(&error),
                        }
                    }
                    _ => routing::not_found_response(),
                };
            }
            if let Some(id) = single_route_segment(suffix, "/intents/releases/") {
                return if method == "GET" {
                    state
                        .virtual_soulfind_v2
                        .read()
                        .await
                        .release(&decoded_path_segment(id))
                        .map_or_else(routing::not_found_response, |intent| {
                            routing::ok_response(intent.to_string())
                        })
                } else {
                    routing::not_found_response()
                };
            }
            if let Some(id) = action_route_segment(suffix, "/intents/tracks/", "/process") {
                if method != "POST" {
                    return routing::not_found_response();
                }
                let id = decoded_path_segment(id);
                if state.virtual_soulfind_v2.read().await.track(&id).is_none() {
                    return routing::not_found_response();
                }
                let catalogue = virtual_soulfind_catalogue(state).await;
                let intents = Arc::clone(&state.virtual_soulfind_v2);
                let process_id = id.clone();
                tokio::spawn(async move {
                    intents.write().await.process_track(&process_id, &catalogue);
                });
                return routing::accepted_response(
                    serde_json::json!({
                        "message": "Processing started",
                        "intentId": id,
                    })
                    .to_string(),
                );
            }
            if let Some(id) = single_route_segment(suffix, "/catalogue/artists/") {
                if method != "GET" {
                    return routing::not_found_response();
                }
                return virtual_soulfind_v2::artist(
                    &virtual_soulfind_catalogue(state).await,
                    &decoded_path_segment(id),
                )
                .map_or_else(routing::not_found_response, |artist| {
                    routing::ok_response(artist.to_string())
                });
            }
            if let Some(id) = action_route_segment(suffix, "/catalogue/artists/", "/releases") {
                if method != "GET" {
                    return routing::not_found_response();
                }
                let limit = match query_bounded_usize(query, "limit", 0, 100) {
                    Ok(limit) => limit.unwrap_or(100),
                    Err(()) => return routing::bad_request_response("limit is invalid"),
                };
                return routing::ok_response(
                    virtual_soulfind_v2::artist_releases(
                        &virtual_soulfind_catalogue(state).await,
                        &decoded_path_segment(id),
                        limit,
                    )
                    .to_string(),
                );
            }
            if let Some(id) = action_route_segment(suffix, "/catalogue/releases/", "/tracks") {
                if method != "GET" {
                    return routing::not_found_response();
                }
                return routing::ok_response(
                    virtual_soulfind_v2::release_tracks(
                        &virtual_soulfind_catalogue(state).await,
                        &decoded_path_segment(id),
                    )
                    .to_string(),
                );
            }
            if let Some(id) = single_route_segment(suffix, "/executions/") {
                return if method == "GET" {
                    state
                        .virtual_soulfind_v2
                        .read()
                        .await
                        .execution(&decoded_path_segment(id))
                        .map_or_else(routing::not_found_response, |execution| {
                            routing::ok_response(execution.to_string())
                        })
                } else {
                    routing::not_found_response()
                };
            }
            routing::not_found_response()
        }
    }
}

fn single_route_segment<'a>(path: &'a str, prefix: &str) -> Option<&'a str> {
    let segment = path.strip_prefix(prefix)?;
    (!segment.is_empty() && !segment.contains('/')).then_some(segment)
}

fn action_route_segment<'a>(path: &'a str, prefix: &str, suffix: &str) -> Option<&'a str> {
    let segment = path.strip_prefix(prefix)?.strip_suffix(suffix)?;
    (!segment.is_empty() && !segment.contains('/')).then_some(segment)
}

fn virtual_soulfind_blank_single_segment(path: &str, prefix: &str) -> bool {
    let Some(segment) = path.strip_prefix(prefix) else {
        return false;
    };
    if segment.contains('/') {
        return false;
    }
    segment.is_empty() || decoded_path_segment(segment).trim().is_empty()
}

fn virtual_soulfind_blank_action_segment(path: &str, prefix: &str, suffix: &str) -> bool {
    let Some(segment) = path
        .strip_prefix(prefix)
        .and_then(|path| path.strip_suffix(suffix))
    else {
        return false;
    };
    segment.is_empty()
        || (!segment.contains('/') && decoded_path_segment(segment).trim().is_empty())
}

async fn open_preview_stream_ticket(state: &AppState, family: &str, token: &str) -> Option<String> {
    let mut tickets = state.stream_tickets.write().await;
    let ticket = tickets.get(token);
    drop(tickets);
    let ticket = ticket?;
    if ticket.family != family {
        return None;
    }
    Some(
        serde_json::json!({
            "ticket": token,
            "status": "available",
            "source": ticket.source,
            "content_id": ticket.content_id,
            "filename": ticket.filename,
            "peer_username": ticket.peer_username,
            "size": ticket.size,
            "contentType": ticket.content_type,
            "created_at": ticket.created_at,
            "expires_at": ticket.expires_at,
            "cacheControl": "no-store",
            "acceptRanges": "none",
        })
        .to_string(),
    )
}

fn preview_stream_content_type(path: &str) -> &'static str {
    match path
        .rsplit_once('.')
        .map(|(_, extension)| extension.to_ascii_lowercase())
    {
        Some(extension) if extension == "flac" => "audio/flac",
        Some(extension) if extension == "mp3" => "audio/mpeg",
        Some(extension) if extension == "ogg" || extension == "oga" => "audio/ogg",
        Some(extension) if extension == "opus" => "audio/opus",
        Some(extension) if extension == "aac" => "audio/aac",
        Some(extension) if extension == "wav" => "audio/wav",
        Some(extension) if extension == "m4a" || extension == "mp4" => "audio/mp4",
        _ => "application/octet-stream",
    }
}

/// The frozen MeshStreamTicketService intentionally accepts a narrower
/// extension set than the compatibility preview routes.  Keep that contract
/// separate so mesh tickets do not inherit peer/listening-party aliases such
/// as `.oga` or `.mp4`.
fn mesh_preview_stream_content_type(path: &str) -> Option<&'static str> {
    match path
        .rsplit_once('.')
        .map(|(_, extension)| extension.to_ascii_lowercase())
    {
        Some(extension) if extension == "flac" => Some("audio/flac"),
        Some(extension) if extension == "mp3" => Some("audio/mpeg"),
        Some(extension) if extension == "m4a" => Some("audio/mp4"),
        Some(extension) if extension == "aac" => Some("audio/aac"),
        Some(extension) if extension == "ogg" => Some("audio/ogg"),
        Some(extension) if extension == "opus" => Some("audio/opus"),
        Some(extension) if extension == "wav" => Some("audio/wav"),
        _ => None,
    }
}

async fn security_extended_response(
    path: &str,
    query: Option<&str>,
    state: &AppState,
) -> HttpResponse {
    let list_limit = if matches!(
        path,
        "/api/security/events"
            | "/api/security/anomalies"
            | "/api/security/reputation/suspicious"
            | "/api/security/reputation/trusted"
            | "/api/security/network/top"
    ) {
        let (name, error_message) =
            if matches!(path, "/api/security/events" | "/api/security/anomalies") {
                ("count", "count must be positive")
            } else {
                ("limit", "limit must be positive")
            };
        match query_bounded_usize(query, name, 1, 1_000) {
            Ok(Some(value)) => value,
            Ok(None) => 100,
            Err(()) => return routing::bad_request_response(error_message),
        }
    } else {
        1_000
    };
    match path {
        "/api/security/bans" => {
            let security = state.security.read().await;
            routing::ok_response(security.json_value().to_string())
        }
        "/api/security/events" | "/api/security/anomalies" => {
            let events = state.events.read().await;
            let rows = events
                .records
                .iter()
                .rev()
                .take(list_limit)
                .map(|event| {
                    serde_json::json!({
                        "eventId": event.id,
                        "eventType": event.kind,
                        "severity": if event.kind.contains("failed") || event.kind.contains("rejected") { "Warning" } else { "Info" },
                        "description": event.detail,
                        "source": event.resource,
                        "timestamp": event.created_at,
                    })
                })
                .collect::<Vec<_>>();
            routing::ok_response(serde_json::Value::Array(rows).to_string())
        }
        "/api/security/reputation/suspicious" | "/api/security/reputation/trusted" => {
            // Matches the oracle's real GetSuspiciousPeers/GetTrustedPeers:
            // real per-peer scores (SecurityState.reputation), sorted
            // worst/best-first, filtered by the oracle's real
            // Untrusted/Trusted thresholds -- not watch/online status,
            // which has nothing to do with reputation.
            let trusted = path.ends_with("/trusted");
            let security = state.security.read().await;
            let mut peers = security
                .reputation
                .iter()
                .map(|(username, score)| (username.clone(), *score))
                .collect::<Vec<_>>();
            peers.retain(|(_, score)| {
                if trusted {
                    *score >= SECURITY_REPUTATION_TRUSTED_THRESHOLD
                } else {
                    *score < SECURITY_REPUTATION_DEFAULT_SCORE
                }
            });
            if trusted {
                peers.sort_by_key(|peer| std::cmp::Reverse(peer.1));
            } else {
                peers.sort_by_key(|peer| peer.1);
            }
            peers.truncate(list_limit);
            let rows = peers
                .into_iter()
                .map(|(username, score)| {
                    let profile = security
                        .reputation_profiles
                        .get(&username)
                        .cloned()
                        .unwrap_or_else(|| {
                            SecurityReputationProfile::new(&username, unix_timestamp())
                        });
                    security_reputation_profile_value(&profile, score)
                })
                .collect::<Vec<_>>();
            routing::ok_response(serde_json::Value::Array(rows).to_string())
        }
        "/api/security/scanners" | "/api/security/threats" => {
            let feature_key = if path.ends_with("/scanners") {
                "security/profile/security/scanners"
            } else {
                "security/profile/security/threats"
            };
            let configured = state
                .controller_features
                .read()
                .await
                .get(feature_key)
                .and_then(|value| value.get("items"))
                .cloned();
            routing::ok_response(
                configured
                    .unwrap_or_else(|| serde_json::json!([]))
                    .to_string(),
            )
        }
        "/api/security/canaries" => {
            let configured = state
                .controller_features
                .read()
                .await
                .get("security/profile/security/canaries")
                .and_then(|value| value.get("settings"))
                .cloned();
            routing::ok_response(
                configured
                    .unwrap_or_else(|| {
                        serde_json::json!({
                            "totalAccesses": 0,
                            "uniqueAttackers": 0,
                            "activeTraps": 0,
                            "triggeredTraps": 0,
                            "trapsByType": {},
                        })
                    })
                    .to_string(),
            )
        }
        "/api/security/network" => {
            let listeners = state.listeners.read().await;
            let total_connections = listeners.regular_accepts + listeners.obfuscated_accepts;
            let policy = state
                .advanced_networking
                .read()
                .await
                .security
                .network_guard
                .clone();
            let (active_connections, tracked_ips) = {
                let active = state
                    .incoming_connection_ips
                    .lock()
                    .unwrap_or_else(std::sync::PoisonError::into_inner);
                (active.values().copied().sum::<usize>(), active.len())
            };
            routing::ok_response(
                serde_json::json!({
                    "activeConnections": active_connections,
                    "globalConnections": active_connections,
                    "trackedIps": tracked_ips,
                    "totalConnections": total_connections,
                    "totalMessages": state.events.read().await.records.len(),
                    "rateLimitHits": 0,
                    "maxConnectionsPerIp": policy.max_connections_per_ip,
                    "maxGlobalConnections": policy.max_global_connections,
                    "maxMessagesPerMinute": policy.max_messages_per_minute,
                    "blockedConnections": listeners.transfer_rejections,
                    "rateLimitedConnections": 0,
                    "errors": listeners.errors,
                    "updatedAt": listeners.updated_at,
                })
                .to_string(),
            )
        }
        "/api/security/network/top" | "/api/security/peers" => {
            let users = state.users.read().await;
            let rows = users
                .records
                .iter()
                .take(list_limit)
                .map(|user| {
                    serde_json::json!({
                        "username": user.username,
                        "status": user.status,
                        "watched": user.watched,
                        "averageSpeed": user.average_speed.unwrap_or(0),
                        "fileCount": user.file_count.unwrap_or(0),
                        "updatedAt": user.updated_at,
                    })
                })
                .collect::<Vec<_>>();
            routing::ok_response(serde_json::Value::Array(rows).to_string())
        }
        "/api/security/adversarial" => {
            let configured = state
                .controller_features
                .read()
                .await
                .get("security/profile/security/adversarial")
                .and_then(|value| value.get("settings"))
                .cloned();
            routing::ok_response(
                configured
                    .unwrap_or_else(|| {
                        serde_json::json!({
                            "enabled": false,
                            "injectLatency": false,
                            "dropMessages": false,
                            "corruptMessages": false,
                            "reorderMessages": false,
                            "partitionNetwork": false,
                        })
                    })
                    .to_string(),
            )
        }
        "/api/security/adversarial/stats" => routing::ok_response(
            serde_json::json!({
                "enabled": false,
                "profile": "Standard",
                "privacyEnabled": false,
                "anonymityEnabled": false,
                "transportEnabled": state.private_gateway.is_some(),
                "plausibleDeniabilityEnabled": false,
                "onionRoutingEnabled": false,
                "censorshipResistanceEnabled": false,
                "messagesProcessed": 0,
                "messagesDropped": 0,
                "messagesCorrupted": 0,
                "messagesReordered": 0,
                "latencyInjected": 0,
                "partitionsCreated": 0,
            })
            .to_string(),
        ),
        "/api/security/tor/status" => {
            let configured = state
                .controller_features
                .read()
                .await
                .get("security/profile/security/tor")
                .and_then(|value| value.get("settings"))
                .cloned();
            routing::ok_response(
                configured
                    .unwrap_or_else(|| {
                        serde_json::json!({
                            "type": "Tor",
                            "available": false,
                            "connected": false,
                            "healthy": false,
                            "errorMessage": "Tor transport is not configured",
                        })
                    })
                    .to_string(),
            )
        }
        "/api/security/transports/status" => {
            let mesh_enabled = state.private_gateway.is_some();
            routing::ok_response(
                serde_json::json!({
                    "selectedTransport": if mesh_enabled { "Direct" } else { "None" },
                    "availableTransports": if mesh_enabled { vec!["Direct"] } else { Vec::<&str>::new() },
                    "healthy": mesh_enabled,
                })
                .to_string(),
            )
        }
        "/api/security/transports" => {
            let mesh_enabled = state.private_gateway.is_some();
            let configured = state
                .controller_features
                .read()
                .await
                .get("security/profile/security/transports")
                .and_then(|value| value.get("items"))
                .cloned();
            routing::ok_response(
                configured
                    .unwrap_or_else(|| {
                        serde_json::json!({
                            "Direct": {
                                "type": "Direct",
                                "available": mesh_enabled,
                                "connected": mesh_enabled,
                                "healthy": mesh_enabled,
                            },
                            "Tor": {
                                "type": "Tor",
                                "available": false,
                                "connected": false,
                                "healthy": false,
                            }
                        })
                    })
                    .to_string(),
            )
        }
        "/api/security/circuits" | "/api/security/circuits/stats" => {
            let circuits = state
                .controller_features
                .read()
                .await
                .values_with_prefix("security/circuit/");
            if path.ends_with("/stats") {
                routing::ok_response(
                    serde_json::json!({
                        "totalCircuits": circuits.len(),
                        "totalCircuitsBuilt": circuits.len(),
                        "activeCircuits": circuits.iter().filter(|circuit| circuit.get("active").and_then(serde_json::Value::as_bool).unwrap_or(true)).count(),
                        "averageCircuitLength": 0.0,
                        "circuitLengths": {},
                        "failedCircuits": circuits.iter().filter(|circuit| circuit.get("failed").and_then(serde_json::Value::as_bool).unwrap_or(false)).count(),
                        "totalPeers": circuits.iter().filter_map(|circuit| circuit.get("peerId").and_then(serde_json::Value::as_str)).collect::<HashSet<_>>().len(),
                    })
                    .to_string(),
                )
            } else {
                routing::ok_response(serde_json::Value::Array(circuits).to_string())
            }
        }
        "/api/security/peers/stats" => {
            let users = state.users.read().await;
            routing::ok_response(
                serde_json::json!({
                    "totalPeers": users.records.len(),
                    "activePeers": users.records.iter().filter(|user| user.status.as_deref() == Some("online")).count(),
                    "onionRoutingPeers": 0,
                    "averageQualityScore": 0.0,
                    "averageLatencyMs": 0.0,
                    "onlinePeers": users.records.iter().filter(|user| user.status.as_deref() == Some("online")).count(),
                    "watchedPeers": users.records.iter().filter(|user| user.watched).count(),
                    "bannedPeers": state.security.read().await.active_bans(),
                })
                .to_string(),
            )
        }
        _ => {
            if let Some(username) = path_segment_after(path, "/api/security/reputation/") {
                let username = decoded_path_segment(username);
                return routing::ok_response(
                    security_reputation_profile_json(state, &username)
                        .await
                        .to_string(),
                );
            }
            if let Some(username) = path_segment_after(path, "/api/security/disclosure/") {
                let username = decoded_path_segment(username);
                let configured = state
                    .controller_features
                    .read()
                    .await
                    .get(&format!("security/profile/security/disclosure/{username}"))
                    .cloned();
                let settings = configured
                    .as_ref()
                    .and_then(|value| value.get("settings"))
                    .unwrap_or(&serde_json::Value::Null);
                let peer_tier = settings
                    .get("tier")
                    .or_else(|| settings.get("peerTier"))
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or("Unknown");
                return routing::ok_response(
                    serde_json::json!({
                        "peerTier": peer_tier,
                        "maxDisclosureTier": settings.get("maxDisclosureTier").and_then(serde_json::Value::as_str).unwrap_or("Public"),
                        "canSeeFileCounts": settings.get("canSeeFileCounts").and_then(serde_json::Value::as_bool).unwrap_or(false),
                        "canSeeFolderStructure": settings.get("canSeeFolderStructure").and_then(serde_json::Value::as_bool).unwrap_or(false),
                        "canSeeFullPaths": settings.get("canSeeFullPaths").and_then(serde_json::Value::as_bool).unwrap_or(false),
                        "canSeeAudioMetadata": settings.get("canSeeAudioMetadata").and_then(serde_json::Value::as_bool).unwrap_or(false),
                        "canBrowse": settings.get("canBrowse").and_then(serde_json::Value::as_bool).unwrap_or(false),
                        "canDownload": settings.get("canDownload").and_then(serde_json::Value::as_bool).unwrap_or(false),
                    })
                    .to_string(),
                );
            }
            routing::not_found_response()
        }
    }
}

async fn mediacore_extended_response(
    path: &str,
    query: Option<&str>,
    state: &AppState,
) -> HttpResponse {
    // MediaCoreStatsService owns a process-local stopwatch in the frozen
    // runtime. Keep the dashboard's uptime tied to this daemon process rather
    // than returning the old fixed zero-duration compatibility value.
    static MEDIA_CORE_STARTED_AT: std::sync::OnceLock<Instant> = std::sync::OnceLock::new();
    let media_core_uptime = MEDIA_CORE_STARTED_AT
        .get_or_init(Instant::now)
        .elapsed()
        .as_millis() as u64;
    let discovery = state.content_discovery.read().await;
    let library = state.library.read().await;
    let shares = state.shares.read().await;
    let controller_features = state.controller_features.read().await;
    let registered_mappings = controller_features
        .values_with_prefix("mediacore/contentid/")
        .into_iter()
        .filter_map(|value| {
            Some((
                value.get("externalId")?.as_str()?.to_owned(),
                value.get("contentId")?.as_str()?.to_owned(),
            ))
        })
        .collect::<Vec<_>>();
    let descriptor_records = controller_features.values_with_prefix("mediacore/descriptor/");
    // Metadata portability writes descriptor records, but the frozen
    // ContentDescriptorPublisher only counts descriptors that it itself has
    // successfully published.  Publication metadata is the durable marker
    // for that local publisher projection.
    let published_descriptors = descriptor_records
        .iter()
        .filter(|descriptor| descriptor.get("publishedAt").is_some())
        .cloned()
        .collect::<Vec<_>>();
    let cache_records = controller_features.values_with_prefix("mediacore/cache/");
    let ipld_link_records = controller_features.values_with_prefix("mediacore/ipld/");
    let mediacore_metrics = controller_features.values_with_prefix("mediacore/metrics/");
    drop(controller_features);
    let now = chrono::Utc::now();
    let metric_sum = |operation: &str, field: &str| -> u64 {
        mediacore_metrics
            .iter()
            .filter(|metric| metric["operation"].as_str() == Some(operation))
            .filter_map(|metric| metric["value"][field].as_u64())
            .sum()
    };
    let metric_count = |operation: &str| -> u64 { metric_sum(operation, "count") };
    let mappings = discovery
        .hash_entries()
        .len()
        .saturating_add(registered_mappings.len());
    let mut registered_domains = registered_mappings
        .iter()
        .filter_map(|(_, content_id)| content_id.split(':').nth(1))
        .map(str::to_ascii_lowercase)
        .collect::<HashSet<_>>();
    if discovery
        .hash_entries()
        .iter()
        .any(|entry| !entry.music_brainz_id.is_empty())
    {
        registered_domains.insert("music".to_owned());
    }
    let domains = registered_domains.len();
    let active_cache_records = cache_records
        .iter()
        .filter(|record| {
            record
                .get("expiresAt")
                .and_then(serde_json::Value::as_str)
                .and_then(|value| chrono::DateTime::parse_from_rfc3339(value).ok())
                .is_some_and(|value| value.with_timezone(&chrono::Utc) > now)
        })
        .collect::<Vec<_>>();
    let descriptors = active_cache_records.len();
    let mut mappings_by_domain = BTreeMap::<String, usize>::new();
    let mut mappings_by_type = BTreeMap::<String, usize>::new();
    for content_id in registered_mappings
        .iter()
        .map(|(_, content_id)| content_id.as_str())
        .chain(
            discovery
                .hash_entries()
                .iter()
                .filter(|entry| !entry.music_brainz_id.is_empty())
                .map(|_| "content:music:recording:musicbrainz"),
        )
    {
        let parts = content_id.split(':').collect::<Vec<_>>();
        if parts.len() == 4 && parts[0].eq_ignore_ascii_case("content") {
            *mappings_by_domain.entry(parts[1].to_owned()).or_default() += 1;
            *mappings_by_type.entry(parts[2].to_owned()).or_default() += 1;
        }
    }
    let total_retrievals = metric_sum("retrieve", "count");
    let cache_hits = metric_sum("retrieve", "hits");
    let cache_misses = metric_sum("retrieve", "misses");
    let cache_size_bytes = active_cache_records
        .iter()
        .filter_map(|record| {
            record
                .get("descriptor")
                .or(Some(*record))
                .and_then(|descriptor| serde_json::to_vec(descriptor).ok())
        })
        .map(|descriptor| descriptor.len() as u64)
        .sum::<u64>();
    let total_fuzzy_matches = metric_count("fuzzy");
    let successful_fuzzy_matches = metric_sum("fuzzy", "successes");
    let mut registered_content_ids = registered_mappings
        .iter()
        .map(|(_, content_id)| content_id.to_ascii_lowercase())
        .collect::<HashSet<_>>();
    registered_content_ids.extend(
        discovery
            .hash_entries()
            .iter()
            .filter(|entry| !entry.music_brainz_id.trim().is_empty())
            .map(|entry| {
                format!("content:music:recording:{}", entry.music_brainz_id).to_ascii_lowercase()
            }),
    );
    let mut ipld_seen_nodes = HashSet::new();
    let mut ipld_connected_nodes = HashSet::new();
    let mut total_ipld_links = 0_u64;
    let mut broken_ipld_links = 0_u64;
    for content_id in &registered_content_ids {
        ipld_seen_nodes.insert(content_id.clone());
        let Some(record) = ipld_link_records.iter().find(|record| {
            record["contentId"]
                .as_str()
                .is_some_and(|source| source.eq_ignore_ascii_case(content_id))
        }) else {
            continue;
        };
        let links = record["links"]
            .as_array()
            .map(Vec::as_slice)
            .unwrap_or_default();
        if !links.is_empty() {
            ipld_connected_nodes.insert(content_id.clone());
        }
        for link in links {
            total_ipld_links = total_ipld_links.saturating_add(1);
            let Some(target) = link["target"].as_str() else {
                continue;
            };
            let target = target.to_ascii_lowercase();
            ipld_seen_nodes.insert(target.clone());
            ipld_connected_nodes.insert(target.clone());
            if !registered_content_ids.contains(&target) {
                broken_ipld_links = broken_ipld_links.saturating_add(1);
            }
        }
    }
    let total_ipld_graphs = registered_content_ids.len() as u64;
    let total_ipld_nodes = ipld_seen_nodes.len() as u64;
    let orphaned_ipld_nodes = total_ipld_nodes.saturating_sub(ipld_connected_nodes.len() as u64);
    let total_perceptual_hashes = metric_count("perceptual-hash");
    let total_imports = metric_sum("portability", "imports");
    let successful_imports = metric_sum("portability", "successfulImports");
    let total_exports = metric_sum("portability", "exports");
    let total_data_transferred = metric_sum("portability", "dataTransferred");
    let expiring_cutoff = now + chrono::Duration::minutes(60);
    let mut active_publications = 0_u64;
    let mut expiring_publications = 0_u64;
    let mut total_storage_bytes = 0_u64;
    let mut total_remaining_ttl_hours = 0.0_f64;
    let mut publications_by_domain = BTreeMap::<String, u64>::new();
    let mut last_publish_operation = None;
    for descriptor in &published_descriptors {
        let content_id = descriptor
            .get("contentId")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default();
        let domain = content_id
            .strip_prefix("content:")
            .and_then(|value| value.split(':').next())
            .map(|domain| {
                if domain.eq_ignore_ascii_case("mb") {
                    "audio".to_owned()
                } else {
                    domain.to_owned()
                }
            })
            .unwrap_or_else(|| "unknown".to_owned());
        let published_at = descriptor
            .get("publishedAt")
            .and_then(serde_json::Value::as_str)
            .and_then(|value| chrono::DateTime::parse_from_rfc3339(value).ok())
            .map(|value| value.with_timezone(&chrono::Utc));
        let expires_at = descriptor
            .get("expiresAt")
            .and_then(serde_json::Value::as_str)
            .and_then(|value| chrono::DateTime::parse_from_rfc3339(value).ok())
            .map(|value| value.with_timezone(&chrono::Utc));
        if let Some(expires_at) = expires_at.filter(|expires_at| *expires_at > now) {
            if published_at > last_publish_operation {
                last_publish_operation = published_at;
            }
            active_publications = active_publications.saturating_add(1);
            if expires_at <= expiring_cutoff {
                expiring_publications = expiring_publications.saturating_add(1);
            }
            total_remaining_ttl_hours += (expires_at - now).num_milliseconds() as f64 / 3_600_000.0;
            *publications_by_domain.entry(domain).or_default() += 1;
            total_storage_bytes = total_storage_bytes.saturating_add(
                descriptor
                    .get("sizeBytes")
                    .or_else(|| descriptor.get("size"))
                    .and_then(serde_json::Value::as_u64)
                    .unwrap_or_default(),
            );
        }
    }
    let total_published = published_descriptors.len() as u64;
    let average_ttl_hours = if active_publications == 0 {
        0.0
    } else {
        total_remaining_ttl_hours / active_publications as f64
    };
    let successful_publishes = metric_sum("publish", "count");
    let republished_descriptors = metric_sum("publish", "republished");
    let registry = serde_json::json!({
        "totalMappings": mappings,
        "totalDomains": domains,
        "mappingsByDomain": mappings_by_domain,
        "mappingsByType": mappings_by_type,
        "lastUpdated": chrono::Utc::now().to_rfc3339(),
        "averageMappingsPerDomain": if domains == 0 { 0.0 } else { mappings as f64 / domains as f64 },
    });
    let descriptor_stats = serde_json::json!({
        "totalRetrievals": total_retrievals,
        "cacheHits": cache_hits,
        "cacheMisses": cache_misses,
        "cacheHitRatio": if total_retrievals == 0 { 0.0 } else { cache_hits as f64 / total_retrievals as f64 },
        "averageRetrievalTime": "00:00:00",
        "activeCacheEntries": descriptors,
        "cacheSizeBytes": cache_size_bytes,
        "expiredEntriesCleaned": 0,
        "lastCacheCleanup": chrono::Utc::now().to_rfc3339(),
        "retrievalsByDomain": {},
    });
    let fuzzy = serde_json::json!({
        "totalMatches": total_fuzzy_matches,
        "successfulMatches": successful_fuzzy_matches,
        "successRate": if total_fuzzy_matches == 0 { 0.0 } else { successful_fuzzy_matches as f64 / total_fuzzy_matches as f64 },
        "averageMatchingTime": "00:00:00",
        "accuracyByAlgorithm": {},
        "matchesByDomain": {},
        "averageConfidenceScore": if total_fuzzy_matches == 0 { 0.0 } else { metric_sum("fuzzy", "confidence") as f64 / total_fuzzy_matches as f64 },
    });
    let ipld = serde_json::json!({
        "totalLinks": total_ipld_links,
        "totalNodes": total_ipld_nodes,
        "totalGraphs": total_ipld_graphs,
        "linksByType": {},
        "graphsByRoot": {},
        "brokenLinksDetected": broken_ipld_links,
        "orphanedNodes": orphaned_ipld_nodes,
        "averageTraversalTime": "00:00:00",
        "graphConnectivityRatio": if total_ipld_nodes == 0 { 0.0 } else { ipld_connected_nodes.len() as f64 / total_ipld_nodes as f64 },
    });
    let perceptual = serde_json::json!({
        "totalHashesComputed": total_perceptual_hashes,
        "averageComputationTime": "00:00:00",
        "statsByAlgorithm": {},
        "overallAccuracy": 0,
        "hashesByContentType": if total_perceptual_hashes == 0 { serde_json::json!({}) } else { serde_json::json!({"audio": total_perceptual_hashes}) },
        "duplicateHashesDetected": 0,
    });
    let portability = serde_json::json!({
        "totalExports": total_exports,
        "totalImports": total_imports,
        "successfulImports": successful_imports,
        "importSuccessRate": if total_imports == 0 { 0.0 } else { successful_imports as f64 / total_imports as f64 },
        "conflictsByType": {},
        "resolutionsUsed": {"Merge": 0, "Overwrite": 0, "Skip": 0, "KeepExisting": 0},
        "averageExportTime": "00:00:00",
        "averageImportTime": "00:00:00",
        "totalDataTransferred": total_data_transferred,
    });
    let publishing = serde_json::json!({
        "totalPublished": total_published,
        "activePublications": active_publications,
        "expiredPublications": expiring_publications,
        "publicationSuccessRate": if successful_publishes == 0 { 0.0 } else { 1.0 },
        "publicationsByDomain": publications_by_domain,
        "averagePublishTime": "00:00:00",
        "republishedDescriptors": republished_descriptors,
        "failedPublications": 0,
        "recentErrors": {},
    });
    if let Some(external_id) = path_segment_after(path, "/api/mediacore/contentid/resolve/") {
        let external_id = decoded_path_segment(external_id);
        if let Some((_, content_id)) = registered_mappings
            .iter()
            .find(|(registered, _)| registered.eq_ignore_ascii_case(&external_id))
        {
            return routing::ok_response(serde_json::json!({"contentId": content_id}).to_string());
        }
        return HttpResponse {
            status: "404 Not Found",
            content_type: "application/json; charset=utf-8",
            body: serde_json::json!({"error": "External ID not found"}).to_string(),
        };
    }
    if let Some(segments) = decoded_segments_after(path, "/api/mediacore/contentid/domain/") {
        if let [domain, marker, type_name] = segments.as_slice() {
            if marker == "type" {
                let mut content_ids = discovery
                    .hash_entries()
                    .iter()
                    .filter(|entry| !entry.music_brainz_id.is_empty())
                    .map(|entry| format!("content:{domain}:{type_name}:{}", entry.music_brainz_id))
                    .collect::<Vec<_>>();
                content_ids.extend(registered_mappings.iter().filter_map(|(_, content_id)| {
                    let parts = content_id.split(':').collect::<Vec<_>>();
                    (parts.len() == 4
                        && parts[1].eq_ignore_ascii_case(domain)
                        && parts[2].eq_ignore_ascii_case(type_name))
                    .then(|| content_id.clone())
                }));
                content_ids.sort();
                content_ids.dedup();
                return routing::ok_response(
                    serde_json::json!({
                        "normalizedDomain": domain,
                        "normalizedType": type_name,
                        "contentIds": content_ids,
                    })
                    .to_string(),
                );
            }
        } else if let [domain] = segments.as_slice() {
            let mut content_ids = discovery
                .hash_entries()
                .iter()
                .filter(|entry| !entry.music_brainz_id.is_empty())
                .map(|entry| format!("content:{domain}:recording:{}", entry.music_brainz_id))
                .collect::<Vec<_>>();
            content_ids.extend(registered_mappings.iter().filter_map(|(_, content_id)| {
                let parts = content_id.split(':').collect::<Vec<_>>();
                (parts.len() == 4 && parts[1].eq_ignore_ascii_case(domain))
                    .then(|| content_id.clone())
            }));
            content_ids.sort();
            content_ids.dedup();
            return routing::ok_response(
                serde_json::json!({"normalizedDomain": domain, "contentIds": content_ids})
                    .to_string(),
            );
        }
    }
    if let Some(external_id) = path_segment_after(path, "/api/mediacore/contentid/exists/") {
        let external_id = decoded_path_segment(external_id);
        let exists = registered_mappings
            .iter()
            .any(|(registered, _)| registered.eq_ignore_ascii_case(&external_id))
            || discovery.hash_entries().iter().any(|entry| {
                entry.music_brainz_id.eq_ignore_ascii_case(&external_id)
                    || entry.flac_key.eq_ignore_ascii_case(&external_id)
                    || entry.byte_hash.eq_ignore_ascii_case(&external_id)
                    || entry.full_file_hash.eq_ignore_ascii_case(&external_id)
                    || entry.file_sha256.eq_ignore_ascii_case(&external_id)
            });
        return routing::ok_response(serde_json::json!({"exists": exists}).to_string());
    }
    if let Some(content_id) = path_segment_after(path, "/api/mediacore/contentid/external/") {
        let content_id = decoded_path_segment(content_id);
        let mut external_ids = discovery
            .hash_entries()
            .iter()
            .filter(|entry| {
                entry.music_brainz_id.eq_ignore_ascii_case(&content_id)
                    || format!("content:music:recording:{}", entry.music_brainz_id)
                        .eq_ignore_ascii_case(&content_id)
            })
            .flat_map(|entry| [entry.flac_key.clone(), entry.music_brainz_id.clone()])
            .filter(|value| !value.is_empty())
            .collect::<Vec<_>>();
        external_ids.extend(
            registered_mappings
                .iter()
                .filter(|(_, registered_content_id)| {
                    registered_content_id.eq_ignore_ascii_case(&content_id)
                })
                .map(|(external_id, _)| external_id.clone()),
        );
        external_ids.sort();
        external_ids.dedup();
        return routing::ok_response(serde_json::json!({"externalIds": external_ids}).to_string());
    }
    if let Some(raw_content_id) = path.strip_prefix("/api/mediacore/contentid/validate/") {
        let content_id = decoded_path_segment(raw_content_id);
        let parts = content_id.split(':').collect::<Vec<_>>();
        let valid = parts.len() == 4
            && parts[0].eq_ignore_ascii_case("content")
            && parts[1..].iter().all(|part| !part.trim().is_empty());
        let value = if valid {
            serde_json::json!({
                "contentId": content_id,
                "isValid": true,
                "domain": parts[1],
                "type": parts[2],
                "id": parts[3],
            })
        } else {
            serde_json::json!({
                "contentId": content_id,
                "isValid": false,
                "error": "Invalid ContentID format. Expected: content:<domain>:<type>:<id>",
            })
        };
        return routing::ok_response(value.to_string());
    }
    if let Some(raw_content_id) = path.strip_prefix("/api/mediacore/ipld/traverse/") {
        let start_content_id = decoded_path_segment(raw_content_id).trim().to_owned();
        if start_content_id.is_empty() {
            return routing::bad_request_response("Start ContentID is required");
        }
        let link_name = query_parameter(query, "linkName")
            .unwrap_or_default()
            .trim()
            .to_owned();
        if link_name.is_empty() {
            return routing::bad_request_response("Link name is required");
        }
        let max_depth = match query_parameter(query, "maxDepth") {
            None => 3,
            Some(value) => match value.parse::<usize>() {
                Ok(value) if (1..=10).contains(&value) => value,
                _ => return routing::bad_request_response("Max depth must be between 1 and 10"),
            },
        };
        let links_for = |content_id: &str| {
            ipld_link_records
                .iter()
                .find(|record| record["contentId"].as_str() == Some(content_id))
                .and_then(|record| record["links"].as_array())
                .cloned()
                .unwrap_or_default()
        };
        let incoming_for = |content_id: &str| {
            ipld_link_records
                .iter()
                .filter(|record| {
                    record["links"].as_array().is_some_and(|links| {
                        links
                            .iter()
                            .any(|link| link["target"].as_str() == Some(content_id))
                    })
                })
                .filter_map(|record| record["contentId"].as_str().map(str::to_owned))
                .collect::<Vec<_>>()
        };
        let mut visited = HashSet::new();
        let mut visited_nodes = Vec::new();
        let mut paths = Vec::new();
        let mut pending = vec![(
            start_content_id.clone(),
            0_usize,
            vec![start_content_id.clone()],
            Vec::<serde_json::Value>::new(),
        )];
        while let Some((content_id, depth, content_ids, path_links)) = pending.pop() {
            if !visited.insert(content_id.clone()) {
                continue;
            }
            let outgoing_links = links_for(&content_id);
            visited_nodes.push(serde_json::json!({
                "contentId": content_id,
                "outgoingLinks": outgoing_links,
                "incomingLinks": incoming_for(&content_id),
            }));
            if depth >= max_depth {
                continue;
            }
            for link in links_for(&content_id)
                .into_iter()
                .filter(|link| link["name"].as_str() == Some(link_name.as_str()))
            {
                let Some(target) = link["target"].as_str().map(str::to_owned) else {
                    continue;
                };
                let mut next_content_ids = content_ids.clone();
                next_content_ids.push(target.clone());
                let mut next_path_links = path_links.clone();
                next_path_links.push(link.clone());
                paths.push(serde_json::json!({
                    "contentIds": next_content_ids,
                    "links": next_path_links,
                }));
                if depth + 1 < max_depth && !visited.contains(&target) {
                    pending.push((target, depth + 1, next_content_ids, next_path_links));
                }
            }
        }
        return routing::ok_response(
            serde_json::json!({
                "startContentId": start_content_id,
                "linkName": link_name,
                "visitedNodes": visited_nodes,
                "paths": paths,
                "completedTraversal": true,
            })
            .to_string(),
        );
    }
    if let Some(raw_content_id) = path.strip_prefix("/api/mediacore/ipld/graph/") {
        let content_id = decoded_path_segment(raw_content_id);
        if content_id.trim().is_empty() {
            return routing::bad_request_response("ContentID is required");
        }
        let max_depth = match query_parameter(query, "maxDepth") {
            None => 2,
            Some(value) => match value.parse::<usize>() {
                Ok(value) if (1..=5).contains(&value) => value,
                _ => return routing::bad_request_response("Max depth must be between 1 and 5"),
            },
        };
        let links_for = |node_content_id: &str| {
            ipld_link_records
                .iter()
                .find(|record| record["contentId"].as_str() == Some(node_content_id))
                .and_then(|record| record["links"].as_array())
                .cloned()
                .unwrap_or_default()
        };
        let incoming_for = |node_content_id: &str| {
            ipld_link_records
                .iter()
                .filter(|record| {
                    record["links"].as_array().is_some_and(|links| {
                        links
                            .iter()
                            .any(|link| link["target"].as_str() == Some(node_content_id))
                    })
                })
                .filter_map(|record| record["contentId"].as_str().map(str::to_owned))
                .collect::<Vec<_>>()
        };
        let mut visited = HashSet::from([content_id.clone()]);
        let mut nodes = Vec::new();
        let mut paths = Vec::new();
        let mut pending = vec![(content_id.clone(), 0_usize)];
        while let Some((node_content_id, depth)) = pending.pop() {
            let outgoing_links = links_for(&node_content_id);
            nodes.push(serde_json::json!({
                "contentId": node_content_id.clone(),
                "outgoingLinks": outgoing_links,
                "incomingLinks": incoming_for(&node_content_id),
            }));
            if depth >= max_depth {
                continue;
            }
            for link in links_for(&node_content_id) {
                let Some(target) = link["target"].as_str().map(str::to_owned) else {
                    continue;
                };
                if !visited.insert(target.clone()) {
                    continue;
                }
                paths.push(serde_json::json!({
                    "contentIds": [node_content_id, target],
                    "links": [link],
                }));
                pending.push((target, depth + 1));
            }
        }
        return routing::ok_response(
            serde_json::json!({
                "rootContentId": content_id,
                "nodes": nodes,
                "paths": paths,
            })
            .to_string(),
        );
    }
    if let Some(raw_content_id) = path.strip_prefix("/api/mediacore/ipld/inbound/") {
        let target_content_id = decoded_path_segment(raw_content_id);
        let inbound_links = ipld_link_records
            .iter()
            .filter(|value| {
                value
                    .get("links")
                    .and_then(serde_json::Value::as_array)
                    .is_some_and(|links| {
                        links.iter().any(|link| {
                            link.get("target")
                                .or_else(|| link.get("targetContentId"))
                                .and_then(serde_json::Value::as_str)
                                .is_some_and(|link| link.eq_ignore_ascii_case(&target_content_id))
                        })
                    })
            })
            .map(|value| {
                value
                    .get("contentId")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_default()
                    .to_owned()
            })
            .collect::<Vec<_>>();
        return routing::ok_response(
            serde_json::json!({"inboundLinks": inbound_links}).to_string(),
        );
    }
    if let Some(raw_content_id) = path.strip_prefix("/api/mediacore/retrieve/descriptor/") {
        let content_id = decoded_path_segment(raw_content_id).trim().to_owned();
        if content_id.is_empty() {
            return routing::bad_request_response("ContentID is required");
        }
        let bypass_cache = query_parameter(query, "bypassCache")
            .as_deref()
            .and_then(parse_bool_value)
            .unwrap_or(false);
        return match mediacore_retrieve_descriptor(&content_id, bypass_cache, state).await {
            Ok(result) if result.found => routing::ok_response(result.value.to_string()),
            Ok(_) => HttpResponse {
                status: "404 Not Found",
                content_type: "application/json",
                body: serde_json::json!({
                    "contentId": content_id,
                    "found": false,
                    "error": "Descriptor not found",
                })
                .to_string(),
            },
            Err(error) => routing::service_unavailable_response(&error),
        };
    }
    if let Some(domain) = path_segment_after(path, "/api/mediacore/retrieve/query/domain/") {
        let domain = decoded_path_segment(domain).trim().to_ascii_lowercase();
        if domain.is_empty() {
            return routing::bad_request_response("Domain is required");
        }
        let type_filter = query_parameter(query, "type")
            .map(|value| value.trim().to_ascii_lowercase())
            .filter(|value| !value.is_empty());
        let max_results = match query_parameter(query, "maxResults") {
            None => 50,
            Some(value) => match value.parse::<usize>() {
                Ok(value) if (1..=500).contains(&value) => value,
                _ => return routing::bad_request_response("Max results must be between 1 and 500"),
            },
        };
        let mut descriptors = active_cache_records
            .iter()
            .filter_map(|record| record.get("descriptor"))
            .filter(|descriptor| {
                let content_id = descriptor
                    .get("contentId")
                    .and_then(serde_json::Value::as_str)
                    .unwrap_or_default();
                let content_parts = content_id.split(':').collect::<Vec<_>>();
                let descriptor_domain = descriptor
                    .get("domain")
                    .and_then(serde_json::Value::as_str)
                    .or_else(|| content_parts.get(1).copied())
                    .unwrap_or_default()
                    .to_ascii_lowercase();
                let descriptor_type = descriptor
                    .get("type")
                    .and_then(serde_json::Value::as_str)
                    .or_else(|| content_parts.get(2).copied())
                    .unwrap_or_default()
                    .to_ascii_lowercase();
                descriptor_domain == domain
                    && type_filter
                        .as_deref()
                        .is_none_or(|requested| descriptor_type == requested)
            })
            .cloned()
            .collect::<Vec<_>>();
        let has_more_results = descriptors.len() > max_results;
        descriptors.truncate(max_results);
        return routing::ok_response(
            serde_json::json!({
                "domain": domain,
                "type": type_filter,
                "totalFound": descriptors.len(),
                "queryDuration": "00:00:00",
                "descriptors": descriptors,
                "hasMoreResults": has_more_results,
            })
            .to_string(),
        );
    }
    let mut registered_content_ids = registered_mappings
        .iter()
        .map(|(_, content_id)| content_id.clone())
        .collect::<Vec<_>>();
    registered_content_ids.extend(
        discovery
            .hash_entries()
            .iter()
            .filter(|entry| !entry.music_brainz_id.trim().is_empty())
            .map(|entry| format!("content:music:recording:{}", entry.music_brainz_id)),
    );
    registered_content_ids.sort();
    registered_content_ids.dedup_by(|left, right| left.eq_ignore_ascii_case(right));
    let registered_lookup = registered_content_ids
        .iter()
        .map(|content_id| content_id.to_ascii_lowercase())
        .collect::<HashSet<_>>();
    let mut broken_links = Vec::new();
    let mut orphaned_links = Vec::new();
    for record in &ipld_link_records {
        let source = record
            .get("contentId")
            .and_then(serde_json::Value::as_str)
            .unwrap_or_default();
        let source_registered = registered_lookup.contains(&source.to_ascii_lowercase());
        let links = record
            .get("links")
            .and_then(serde_json::Value::as_array)
            .map(Vec::as_slice)
            .unwrap_or_default();
        for link in links {
            let target = link
                .get("target")
                .or_else(|| link.get("targetContentId"))
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default();
            if target.trim().is_empty() {
                continue;
            }
            let name = link
                .get("name")
                .and_then(serde_json::Value::as_str)
                .unwrap_or_default();
            let description = format!("{source} -> {target} ({name})");
            if !source_registered {
                orphaned_links.push(description);
            } else if !registered_lookup.contains(&target.to_ascii_lowercase()) {
                broken_links.push(description);
            }
        }
    }
    let value = match path {
        "/api/mediacore/contentid/stats" => serde_json::json!({
            "totalMappings": mappings,
            "totalDomains": domains,
            "mappingsByDomain": registry["mappingsByDomain"],
        }),
        "/api/mediacore/ipld/validate" => serde_json::json!({
            "isValid": broken_links.is_empty() && orphaned_links.is_empty(),
            "brokenLinks": broken_links,
            "orphanedLinks": orphaned_links,
            "totalLinksValidated": registered_content_ids.len(),
        }),
        "/api/mediacore/perceptualhash/algorithms" => serde_json::json!({
            "algorithms": ["Chromaprint", "PHash", "Spectral"],
            "descriptions": {
                "ChromaPrint": "Audio fingerprinting algorithm for music identification",
                "PHash": "Perceptual hash for image/video similarity detection",
                "Spectral": "Simple spectral analysis hash (fallback)",
            }
        }),
        "/api/mediacore/portability/merge-strategies" => serde_json::json!({
            "strategies": [
                {"strategy":"PreferNewer","name":"Prefer Newer","description":"Prefer metadata with newer timestamps"},
                {"strategy":"PreferHigherPriority","name":"Prefer Higher Priority","description":"Prefer metadata from higher priority sources"},
                {"strategy":"CombineAll","name":"Combine All","description":"Combine metadata fields from all sources"}
            ]
        }),
        "/api/mediacore/portability/strategies" => serde_json::json!({
            "strategies": [
                {"strategy":"Skip","name":"Skip","description":"Skip conflicting entries without importing them"},
                {"strategy":"Overwrite","name":"Overwrite","description":"Replace existing metadata with imported data"},
                {"strategy":"Merge","name":"Merge","description":"Intelligently merge existing and imported metadata"},
                {"strategy":"KeepExisting","name":"Keep Existing","description":"Keep existing metadata and ignore imported data"}
            ]
        }),
        "/api/mediacore/publish/stats" => serde_json::json!({
            "totalPublishedDescriptors": total_published,
            "activePublications": active_publications,
            "expiringSoon": expiring_publications,
            "lastPublishOperation": last_publish_operation
                .map(|value| value.to_rfc3339())
                .unwrap_or_else(|| "0001-01-01T00:00:00+00:00".to_owned()),
            "publicationsByDomain": publications_by_domain,
            "totalStorageBytes": total_storage_bytes,
            "averageTtlHours": average_ttl_hours,
        }),
        "/api/mediacore/retrieve/stats" | "/api/mediacore/stats/descriptors" => descriptor_stats,
        "/api/mediacore/stats/fuzzy" => fuzzy,
        "/api/mediacore/stats/ipld" => ipld,
        "/api/mediacore/stats/perceptual" => perceptual,
        "/api/mediacore/stats/portability" => portability,
        "/api/mediacore/stats/publishing" => publishing,
        "/api/mediacore/stats/registry" => registry,
        "/api/mediacore/stats/dashboard" => serde_json::json!({
            "timestamp": now.to_rfc3339(),
            "uptime": format_timespan_millis(media_core_uptime),
            "contentRegistry": registry,
            "descriptors": descriptor_stats,
            "fuzzyMatching": fuzzy,
            "ipldMapping": ipld,
            "perceptualHashing": perceptual,
            "metadataPortability": portability,
            "publishing": publishing,
            "contentPublishing": publishing,
            "systemResources": {
                "libraryItems": library.records.len(),
                "sharedFiles": shares.entries.len(),
                "hashEntries": discovery.hash_entries().len(),
            },
        }),
        _ => return routing::not_found_response(),
    };
    routing::ok_response(value.to_string())
}

