async fn handle_peer_transfer_negotiation_response<C>(
    peer: &mut C,
    response: PeerMessage,
    transfer: &TransferEntry,
    timeout: Duration,
) -> Result<PeerTransferNegotiation, String>
where
    C: PeerMessageSenderReceiver,
{
    let PeerMessage::TransferResponse(response) = response else {
        return Err(format!(
            "expected TransferResponse, got {}",
            peer_message_name(&response)
        ));
    };
    match response {
        TransferResponse::Allowed { token, size } => Ok(PeerTransferNegotiation::Allowed {
            token,
            size: size.or(transfer.size),
        }),
        TransferResponse::Rejected { token, reason }
            if token == transfer.token
                && transfer.direction == 0
                && is_remote_queue_response(&reason) =>
        {
            let queued = time::timeout(timeout, peer.receive_peer_message())
                .await
                .map_err(|_| "queued transfer request timed out".to_owned())?
                .map_err(|error| format!("queued transfer request failed: {error}"))?;
            let PeerMessage::TransferRequest(request) = queued else {
                return Err(format!(
                    "expected queued TransferRequest, got {}",
                    peer_message_name(&queued)
                ));
            };
            if request.direction != 1 || request.filename != transfer.filename {
                return Err("queued transfer request did not match pending download".to_owned());
            }
            peer.send_peer_message(&PeerMessage::TransferResponse(TransferResponse::Allowed {
                token: request.token,
                size: request.size.or(transfer.size),
            }))
            .await
            .map_err(|error| format!("queued transfer response failed: {error}"))?;
            Ok(PeerTransferNegotiation::QueuedInbound {
                token: request.token,
                size: request.size.or(transfer.size),
            })
        }
        TransferResponse::Rejected { token, reason } => {
            Ok(PeerTransferNegotiation::Rejected { token, reason })
        }
    }
}

trait PeerMessageSenderReceiver {
    async fn receive_peer_message(&mut self) -> Result<PeerMessage, String>;
    async fn send_peer_message(&mut self, message: &PeerMessage) -> Result<(), String>;
}

impl PeerMessageSenderReceiver for PeerMessageConnection<TcpStream> {
    async fn receive_peer_message(&mut self) -> Result<PeerMessage, String> {
        self.receive()
            .await
            .map_err(|error| format!("plain peer receive failed: {error}"))
    }

    async fn send_peer_message(&mut self, message: &PeerMessage) -> Result<(), String> {
        self.send(message)
            .await
            .map_err(|error| format!("plain peer send failed: {error}"))
    }
}

impl PeerMessageSenderReceiver for ObfuscatedPeerMessageConnection<TcpStream> {
    async fn receive_peer_message(&mut self) -> Result<PeerMessage, String> {
        self.receive()
            .await
            .map_err(|error| format!("obfuscated peer receive failed: {error}"))
    }

    async fn send_peer_message(&mut self, message: &PeerMessage) -> Result<(), String> {
        self.send(message)
            .await
            .map_err(|error| format!("obfuscated peer send failed: {error}"))
    }
}

fn browse_entries_from_peer_message(message: PeerMessage) -> Result<Vec<BrowseEntry>, String> {
    match message {
        PeerMessage::SharedFileListResponse(payload) => parse_shared_file_list_payload(&payload),
        other => Err(format!(
            "expected SharedFileListResponse, got {}",
            peer_message_name(&other)
        )),
    }
}

fn folder_entries_from_peer_message(
    message: PeerMessage,
    folder: &str,
    folder_encoding: ProtocolTextEncoding,
) -> Result<Vec<BrowseEntry>, String> {
    match message {
        PeerMessage::FolderContentsResponse(payload) => {
            parse_folder_contents_response_payload(&payload, folder, folder_encoding)
                .or_else(|_| parse_shared_file_list_payload(&payload))
                .or_else(|_| parse_folder_file_list_payload(&payload, folder, folder_encoding))
        }
        other => Err(format!(
            "expected FolderContentsResponse, got {}",
            peer_message_name(&other)
        )),
    }
}

fn parse_folder_contents_response_payload(
    payload: &[u8],
    folder: &str,
    folder_encoding: ProtocolTextEncoding,
) -> Result<Vec<BrowseEntry>, String> {
    let decompressed = decompress_zlib_payload(payload).map_err(|error| error.to_string())?;
    let mut reader = Reader::new(&decompressed);
    let _token = reader.read_u32_le().map_err(|error| error.to_string())?;
    let (_root, root_encoding) = reader
        .read_string_with_encoding()
        .map_err(|error| error.to_string())?;
    let directory_count = reader
        .read_bounded_count("folder directories", 8)
        .map_err(|error| error.to_string())?;
    let mut entries = Vec::new();
    for _ in 0..directory_count {
        let (directory, directory_encoding) = reader
            .read_string_with_encoding()
            .map_err(|error| error.to_string())?;
        let file_count = reader
            .read_bounded_count("folder files", 21)
            .map_err(|error| error.to_string())?;
        for _ in 0..file_count {
            let code = reader.read_u8().map_err(|error| error.to_string())?;
            let (filename, filename_encoding) = reader
                .read_string_with_encoding()
                .map_err(|error| error.to_string())?;
            let size = reader.read_u64_le().map_err(|error| error.to_string())?;
            let (extension, _) = reader
                .read_string_with_encoding()
                .map_err(|error| error.to_string())?;
            let attribute_count = reader
                .read_bounded_count("folder file attributes", 8)
                .map_err(|error| error.to_string())?;
            for _ in 0..attribute_count {
                let _code = reader.read_u32_le().map_err(|error| error.to_string())?;
                let _value = reader.read_u32_le().map_err(|error| error.to_string())?;
            }
            if code == 1 {
                if entries.len() >= MAX_BROWSE_ENTRIES_PER_USER {
                    return Err(format!(
                        "folder contents response exceeds {MAX_BROWSE_ENTRIES_PER_USER} entries"
                    ));
                }
                let directory = if directory.is_empty() {
                    folder
                } else {
                    directory.as_str()
                };
                entries.push(bounded_browse_entry(BrowseEntry {
                    filename: join_virtual_path(directory, &filename),
                    size,
                    extension,
                    path_encoding: if root_encoding == ProtocolTextEncoding::Utf8
                        && directory_encoding == ProtocolTextEncoding::Utf8
                    {
                        filename_encoding
                    } else if directory_encoding != ProtocolTextEncoding::Utf8 {
                        directory_encoding
                    } else {
                        folder_encoding
                    },
                }));
            }
        }
    }
    reader.finish().map_err(|error| error.to_string())?;
    Ok(entries)
}

async fn send_session_command(state: &AppState, command: SessionCommand) -> Result<(), String> {
    state
        .session_commands
        .send(command)
        .await
        .map_err(|_| "session manager is not running".to_owned())
}

async fn send_active_interest_command(
    state: &AppState,
    message: ServerMessage,
) -> Result<(), String> {
    if state.session.read().await.state != "connected" {
        return Err("Soulseek session is disconnected".to_owned());
    }
    send_session_command(state, SessionCommand::SendServerMessage(message)).await
}

fn try_send_session_command(state: &AppState, command: SessionCommand) -> Result<(), String> {
    state
        .session_commands
        .try_send(command)
        .map_err(|error| format!("session command queue rejected request: {error}"))
}

async fn update_session<F>(state: &AppState, update: F)
where
    F: FnOnce(&mut SessionSnapshot),
{
    let mut snapshot = state.session.write().await;
    let previous_error = snapshot.last_error.clone();
    update(&mut snapshot);
    if snapshot.last_error != previous_error {
        if let Some(error) = snapshot.last_error.as_deref() {
            eprintln!("[Error] session state: {error}");
        }
    }
    snapshot.updated_at = unix_timestamp();
}

async fn update_listeners<F>(state: &AppState, update: F)
where
    F: FnOnce(&mut ListenerSnapshot),
{
    let mut snapshot = state.listeners.write().await;
    update(&mut snapshot);
    snapshot.updated_at = unix_timestamp();
}

async fn record_transfer_rejection(
    state: &AppState,
    direction: u32,
    token: u32,
    filename: String,
    size: Option<u64>,
    reason: String,
) {
    let mut transfers = state.transfers.write().await;
    transfers.record_rejected_request(direction, token, filename, size, reason);
}

async fn record_event(
    state: &AppState,
    kind: impl Into<String>,
    resource: impl Into<String>,
    detail: Option<String>,
) {
    let kind = kind.into();
    let detail = if kind == "browse.failed" && detail.is_some() {
        Some("browse failed".to_owned())
    } else {
        detail
    };
    let mut events = state.events.write().await;
    let record = events.record(kind, resource, detail);
    drop(events);
    if let Err(error) = persist_event_record_checked(state, &record).await {
        eprintln!("[Error] event persistence failed: {error}");
        let session_connected = state.session.read().await.state == "connected";
        if !session_connected {
            update_session(state, |snapshot| {
                snapshot.last_error = Some(error);
            })
            .await;
        }
    }
    let _ = state.event_tx.send(record);
}

async fn record_daemon_log(
    state: &AppState,
    level: logging::LogLevel,
    category: &str,
    message: impl Into<String>,
) {
    let message = message.into();
    let configured_level = *state.log_level.read().await;
    let rendered = format!(
        "[{}] {}: {}",
        logging::LogConfig::level_name(level),
        category,
        message
    );
    if configured_level <= level {
        eprintln!("{rendered}");
    }
    if state.config.logger.disk {
        let log_dir = state.config.state_dir.join("logs");
        if tokio::fs::create_dir_all(&log_dir).await.is_ok() {
            if let Ok(mut file) = tokio::fs::OpenOptions::new()
                .create(true)
                .append(true)
                .open(log_dir.join(format!("slskr-{}.log", chrono::Utc::now().format("%Y%m%d"))))
                .await
            {
                let line = format!("{} {rendered}\n", logging::format_timestamp());
                let _ = file.write_all(line.as_bytes()).await;
            }
        }
    }
    if let Some(endpoint) = state.config.logger.loki.as_deref() {
        let endpoint = if endpoint.ends_with("/loki/api/v1/push") {
            endpoint.to_owned()
        } else {
            format!("{}/loki/api/v1/push", endpoint.trim_end_matches('/'))
        };
        let timestamp_ns = chrono::Utc::now()
            .timestamp_nanos_opt()
            .unwrap_or_default()
            .to_string();
        let payload = serde_json::json!({
            "streams": [{
                "stream": {"application": "slskr", "category": category},
                "values": [[timestamp_ns, rendered]],
            }],
        });
        let _ = time::timeout(
            Duration::from_secs(2),
            reqwest::Client::new().post(endpoint).json(&payload).send(),
        )
        .await;
    }
    let detail = serde_json::json!({
        "level": logging::LogConfig::level_name(level),
        "category": category,
        "message": message,
    })
    .to_string();
    record_event(state, "log.created", category, Some(detail)).await;
}

fn soulseek_diagnostic_level_allows(
    minimum: crate::config::SoulseekDiagnosticLevel,
    level: logging::LogLevel,
) -> bool {
    match minimum {
        crate::config::SoulseekDiagnosticLevel::None => false,
        crate::config::SoulseekDiagnosticLevel::Warning => level >= logging::LogLevel::Warn,
        crate::config::SoulseekDiagnosticLevel::Info => level >= logging::LogLevel::Info,
        crate::config::SoulseekDiagnosticLevel::Debug => level >= logging::LogLevel::Debug,
        crate::config::SoulseekDiagnosticLevel::Trace => true,
    }
}

async fn record_soulseek_diagnostic(
    state: &AppState,
    level: logging::LogLevel,
    category: &str,
    message: impl Into<String>,
) {
    if !soulseek_diagnostic_level_allows(state.config.soulseek_diagnostic_level, level) {
        return;
    }
    if category == "distributed" && !state.soulseek_distributed_settings.read().await.logging {
        return;
    }
    record_daemon_log(state, level, category, message).await;
}

async fn record_http_log(
    state: &AppState,
    request_id: &str,
    transaction: &logging::HttpTransactionLog,
) {
    if !state.config.controller_web.logging {
        return;
    }
    let level = logging::response_level(transaction.response.status_code);
    let configured_level = *state.log_level.read().await;
    let log_config = logging::LogConfig {
        level: configured_level,
        log_requests: state.config.controller_web.logging,
        log_responses: state.config.controller_web.logging,
        log_errors_only: false,
        no_color: state.config.logger.no_color,
    };
    if !log_config.should_log(level) {
        return;
    }
    let detail = serde_json::json!({
        "level": logging::LogConfig::level_name(level),
        "category": "http",
        "message": logging::transaction_summary(transaction),
        "request_id": request_id,
        "method": transaction.request.method,
        "path": logging::redacted_path(&transaction.request.path),
        "status": transaction.response.status_code,
        "duration_ms": transaction.response.duration_ms,
        "remote_addr": transaction.request.remote_addr,
    })
    .to_string();
    record_event(state, "log.created", "http", Some(detail)).await;
}

async fn persist_event_record_checked(
    state: &AppState,
    record: &EventRecord,
) -> Result<bool, String> {
    let Some(db) = state.db.as_ref() else {
        return Ok(false);
    };
    let persisted = crate::persistence::EventRecord {
        id: i64::try_from(record.id).unwrap_or(i64::MAX),
        kind: record.kind.clone(),
        resource: record.resource.clone(),
        detail: record.detail.clone(),
        created_at: i64::try_from(record.created_at).unwrap_or(i64::MAX),
    };
    db.insert_event_and_prune(&persisted, EVENT_HISTORY_LIMIT as i32)
        .await
        .map_err(|error| format!("event persistence failed: {error}"))?;
    Ok(true)
}

fn persisted_message_record(record: &MessageRecord) -> crate::persistence::MessageRecord {
    crate::persistence::MessageRecord {
        id: record.id.to_string(),
        username: record.username.clone(),
        content: record.body.clone(),
        direction: record.direction.to_owned(),
        read: record.acknowledged,
        created_at: i64::try_from(record.created_at).unwrap_or(i64::MAX),
        source_id: record.source_id.map(i64::from),
        source_timestamp: record.source_timestamp.map(i64::from),
        was_replayed: record.was_replayed,
    }
}

