    #[cfg_attr(test, test)]
    #[cfg(feature = "full-controller-tests")]
    fn controller_release_comparison_matches_frozen_slskdn_rules() {
        use super::{is_newer_controller_release_available, normalize_controller_release_version};

        assert_eq!(
            normalize_controller_release_version(" refs/tags/V1.2.3+build.4 "),
            "1.2.3"
        );
        assert_eq!(
            normalize_controller_release_version("BUILD-DEV-20260717-slskdn.2"),
            "20260717-slskdn.2"
        );
        assert!(!is_newer_controller_release_available("1.2.3", "v1.2.3"));
        assert!(is_newer_controller_release_available("1.2.3", "1.2.4"));
        assert!(!is_newer_controller_release_available("1.2.4", "1.2.3"));
        assert!(is_newer_controller_release_available(
            "20260717-slskdn.1",
            "20260717-slskdn.2"
        ));
        assert!(!is_newer_controller_release_available(
            "20260718-slskdn.1",
            "20260717-slskdn.99"
        ));
        assert!(is_newer_controller_release_available("manual", "release"));
        assert!(!is_newer_controller_release_available("manual", ""));
    }

    #[cfg_attr(test, test)]
    #[cfg(feature = "full-controller-tests")]
    fn transient_credential_stores_refuse_bursts_at_live_capacity() {
        let mut expired_oauth = super::OAuthStateStore::with_max_records(1);
        let expired_state = expired_oauth
            .issue("spotify", "http://localhost/callback", 0)
            .unwrap();
        assert!(expired_oauth.consume("spotify", &expired_state).is_none());

        let mut oauth = super::OAuthStateStore::with_max_records(1);
        let state = oauth
            .issue("spotify", "http://localhost/callback", 600)
            .unwrap();
        assert!(oauth
            .issue("spotify", "http://localhost/callback", 600)
            .is_none());
        assert!(oauth.consume("spotify", &state).is_some());
        assert!(oauth
            .issue("spotify", "http://localhost/callback", 600)
            .is_some());

        let mut expired_tickets = super::PreviewStreamTicketStore::with_max_records(1);
        let (expired_ticket, _) = expired_tickets
            .issue(
                "peer",
                "test",
                "expired".to_owned(),
                "expired.flac".to_owned(),
                None,
                0,
                "audio/flac".to_owned(),
                0,
            )
            .unwrap();
        assert!(expired_tickets.get(&expired_ticket).is_none());

        let mut tickets = super::PreviewStreamTicketStore::with_max_records(1);
        assert!(tickets
            .issue(
                "peer",
                "test",
                "content-1".to_owned(),
                "song.flac".to_owned(),
                Some("alice".to_owned()),
                123,
                "audio/flac".to_owned(),
                120,
            )
            .is_some());
        assert!(tickets
            .issue(
                "peer",
                "test",
                "content-2".to_owned(),
                "other.flac".to_owned(),
                Some("bob".to_owned()),
                456,
                "audio/flac".to_owned(),
                120,
            )
            .is_none());
    }

    #[cfg_attr(test, tokio::test)]
    #[cfg(feature = "full-controller-tests")]
    async fn spotify_oauth_callback_requires_server_issued_state() {
        let (state, _receiver) = test_state_with_env(
            MapEnv::default()
                .with("SLSKR_SPOTIFY_ENABLED", "true")
                .with("SLSKR_SPOTIFY_CLIENT_ID", "client-id")
                .with("SLSKR_HTTP_BIND", "127.0.0.1:7788"),
        );

        let authorize = super::route_http_request(
            "POST",
            "/api/v0/integrations/spotify/authorize",
            None,
            "",
            &state,
        )
        .await
        .expect("authorize response");
        assert_eq!(authorize.status, "200 OK");
        assert!(authorize
            .body
            .contains("127.0.0.1:7788/api/v0/integrations/spotify/callback"));

        let authorization: serde_json::Value = serde_json::from_str(&authorize.body).unwrap();
        let authorization_url = authorization["authorizationUrl"].as_str().unwrap();
        assert!(authorization_url.contains("code_challenge_method=S256"));
        assert!(authorization_url.contains(
            "scope=user-library-read%20user-follow-read%20playlist-read-private%20playlist-read-collaborative"
        ));

        let (issued_state, verifier) = {
            let states = state.oauth_states.read().await;
            let (issued_state, record) = states.records.iter().next().expect("issued state");
            (
                issued_state.clone(),
                record.code_verifier.clone().expect("PKCE verifier"),
            )
        };
        use base64::Engine as _;
        use sha2::Digest as _;
        let challenge = base64::engine::general_purpose::URL_SAFE_NO_PAD
            .encode(super::Sha256::digest(verifier.as_bytes()));
        assert!(authorization_url.contains(&format!("code_challenge={challenge}")));
        assert!(!authorize.body.contains(&verifier));

        let invalid = super::route_http_request(
            "GET",
            "/api/integrations/spotify/callback?code=abc&state=bogus",
            None,
            "",
            &state,
        )
        .await
        .expect("invalid callback response");
        assert_eq!(invalid.status, "400 Bad Request");
        assert!(state
            .oauth_states
            .read()
            .await
            .records
            .contains_key(&issued_state));
    }

    #[cfg_attr(test, tokio::test)]
    #[cfg(feature = "full-controller-tests")]
    async fn spotify_oauth_error_callback_returns_html_without_consuming_state() {
        let (state, _receiver) = test_state_with_env(
            MapEnv::default()
                .with("SLSKR_SPOTIFY_ENABLED", "true")
                .with("SLSKR_SPOTIFY_CLIENT_ID", "client-id"),
        );
        super::route_http_request(
            "POST",
            "/api/v0/integrations/spotify/authorize",
            None,
            "",
            &state,
        )
        .await
        .expect("authorize response");
        let issued_state = state
            .oauth_states
            .read()
            .await
            .records
            .keys()
            .next()
            .cloned()
            .expect("issued state");

        let missing = super::route_http_request(
            "GET",
            "/api/integrations/spotify/callback?error=access_denied",
            None,
            "",
            &state,
        )
        .await
        .expect("missing state response");
        assert_eq!(missing.status, "200 OK");
        assert_eq!(missing.content_type, "text/html; charset=utf-8");
        assert!(missing.body.contains("Spotify authorization failed."));

        let invalid = super::route_http_request(
            "GET",
            "/api/integrations/spotify/callback?error=access_denied&state=bogus",
            None,
            "",
            &state,
        )
        .await
        .expect("invalid state response");
        assert_eq!(invalid.status, "200 OK");

        let error_path =
            format!("/api/integrations/spotify/callback?error=access_denied&state={issued_state}");
        let denied = super::route_http_request("GET", &error_path, None, "", &state)
            .await
            .expect("valid error callback");
        assert_eq!(denied.status, "200 OK");
        assert!(denied.body.contains("Spotify authorization failed."));

        let replay = super::route_http_request("GET", &error_path, None, "", &state)
            .await
            .expect("replayed error callback");
        assert_eq!(replay.status, "200 OK");
        assert!(state
            .oauth_states
            .read()
            .await
            .records
            .contains_key(&issued_state));
    }

    #[cfg_attr(test, tokio::test)]
    #[cfg(feature = "full-controller-tests")]
    async fn spotify_authorization_exchanges_profiles_persists_and_disconnects() {
        use tokio::io::{AsyncReadExt, AsyncWriteExt};

        let listener = tokio::net::TcpListener::bind("127.0.0.1:0").await.unwrap();
        let address = listener.local_addr().unwrap();
        let server = tokio::spawn(async move {
            for (expected_path, response) in [
                (
                    "/token",
                    serde_json::json!({
                        "access_token": "access-secret",
                        "refresh_token": "refresh-secret",
                        "expires_in": 3600,
                        "scope": "user-library-read playlist-read-private"
                    })
                    .to_string(),
                ),
                (
                    "/me",
                    serde_json::json!({"id": "spotify-user", "display_name": "Fixture User"})
                        .to_string(),
                ),
            ] {
                let (mut stream, _) = listener.accept().await.unwrap();
                let mut request = Vec::new();
                let mut buffer = [0_u8; 4096];
                let header_end = loop {
                    let count = stream.read(&mut buffer).await.unwrap();
                    assert!(count > 0);
                    request.extend_from_slice(&buffer[..count]);
                    if let Some(position) = request.windows(4).position(|row| row == b"\r\n\r\n") {
                        break position + 4;
                    }
                };
                let headers = String::from_utf8_lossy(&request[..header_end]).to_string();
                let content_length = headers
                    .lines()
                    .find_map(|line| {
                        line.strip_prefix("content-length: ")
                            .or_else(|| line.strip_prefix("Content-Length: "))
                    })
                    .and_then(|value| value.trim().parse::<usize>().ok())
                    .unwrap_or_default();
                while request.len() < header_end + content_length {
                    let count = stream.read(&mut buffer).await.unwrap();
                    assert!(count > 0);
                    request.extend_from_slice(&buffer[..count]);
                }
                let request = String::from_utf8_lossy(&request).to_string();
                assert!(request.starts_with(&format!(
                    "{} {expected_path} HTTP/1.1",
                    if expected_path == "/token" {
                        "POST"
                    } else {
                        "GET"
                    }
                )));
                if expected_path == "/token" {
                    assert!(request.contains("client_id=client-id"));
                    assert!(request.contains("grant_type=authorization_code"));
                    assert!(request.contains("code=authorization-code"));
                    assert!(request.contains("code_verifier=pkce-verifier"));
                } else {
                    assert!(request
                        .to_ascii_lowercase()
                        .contains("authorization: bearer access-secret"));
                }
                let reply = format!(
                    "HTTP/1.1 200 OK\r\nContent-Type: application/json\r\nContent-Length: {}\r\nConnection: close\r\n\r\n{}",
                    response.len(),
                    response
                );
                stream.write_all(reply.as_bytes()).await.unwrap();
            }
        });

        let root = std::env::temp_dir().join(format!(
            "slskr-spotify-connection-test-{}-{}",
            std::process::id(),
            super::unix_timestamp_millis()
        ));
        super::ensure_private_state_dir(&root).unwrap();
        let (state, _receiver) = test_state_with_env(
            MapEnv::default()
                .with("SLSKR_STATE_DIR", &root.to_string_lossy())
                .with("SLSKR_SPOTIFY_ENABLED", "true")
                .with("SLSKR_SPOTIFY_CLIENT_ID", "client-id")
                .with("SLSKR_SPOTIFY_TIMEOUT", "5"),
        );
        let spotify = state.integration_settings.read().await.spotify.clone();
        let pending = super::OAuthStateRecord {
            provider: "spotify".to_owned(),
            redirect_uri: "http://127.0.0.1/callback".to_owned(),
            code_verifier: Some("pkce-verifier".to_owned()),
            created_at: super::unix_timestamp(),
            expires_at: super::unix_timestamp().saturating_add(600),
        };
        let status = super::complete_spotify_authorization(
            &state,
            &spotify,
            &pending,
            "authorization-code",
            &format!("http://{address}/token"),
            &format!("http://{address}/me"),
        )
        .await
        .unwrap();
        server.await.unwrap();

        assert_eq!(status["configured"], true);
        assert_eq!(status["connected"], true);
        assert_eq!(status["displayName"], "Fixture User");
        assert_eq!(status["spotifyUserId"], "spotify-user");
        let path = super::spotify_connection_path(&root);
        let encrypted = fs::read_to_string(&path).unwrap();
        assert!(!encrypted.contains("access-secret"));
        assert!(!encrypted.contains("refresh-secret"));
        let loaded = super::load_spotify_connection_store(&root, &state.capability_signing_key);
        assert_eq!(loaded, *state.spotify_connection.read().await);

        let response = super::route_http_request(
            "GET",
            "/api/v0/integrations/spotify/status",
            None,
            "",
            &state,
        )
        .await
        .unwrap();
        let response: serde_json::Value = serde_json::from_str(&response.body).unwrap();
        assert_eq!(response["connected"], true);
        assert!(response["expiresAt"].is_string());

        let disconnect =
            super::route_http_request("DELETE", "/api/v0/integrations/spotify", None, "", &state)
                .await
                .unwrap();
        assert_eq!(disconnect.status, "204 No Content");
        assert!(!path.exists());
        assert_eq!(
            state.spotify_connection.read().await.status_json(true)["connected"],
            false
        );
        let _ = fs::remove_dir_all(root);
    }

    #[cfg_attr(test, test)]
    #[cfg(feature = "full-controller-tests")]
    fn spotify_source_targets_match_frozen_slskdn_forms() {
        for (input, kind, id, user_token, scope) in [
            (
                "spotify:playlist:playlist-1",
                "playlist",
                "playlist-1",
                false,
                "",
            ),
            (
                "https://open.spotify.com/album/album-1?si=ignored",
                "album",
                "album-1",
                false,
                "",
            ),
            (
                "https://open.spotify.com/collection/tracks",
                "saved-tracks",
                "",
                true,
                "user-library-read",
            ),
            (
                "spotify:followed-artists",
                "followed-artists",
                "",
                true,
                "user-follow-read",
            ),
            (
                "playlists",
                "playlists",
                "",
                true,
                "playlist-read-private playlist-read-collaborative",
            ),
        ] {
            let target = super::parse_spotify_source_target(input);
            assert_eq!(target.kind, kind, "{input}");
            assert_eq!(target.id, id, "{input}");
            assert_eq!(target.requires_user_token, user_token, "{input}");
            assert_eq!(target.scope_hint, scope, "{input}");
        }
        assert!(super::looks_like_spotify_source(
            "https://open.spotify.com/track/track-1",
            "auto"
        ));
        assert!(!super::looks_like_spotify_source(
            "https://open.spotify.com.evil.example/track/track-1",
            "auto"
        ));
    }

