    #[cfg_attr(test, test)]
    #[cfg(feature = "full-controller-tests")]
    fn websocket_origin_must_match_host_when_present() {
        let headers = super::RequestSecurityHeaders {
            host: Some("127.0.0.1:5030".to_owned()),
            origin: Some("https://evil.example".to_owned()),
            referer: None,
            cookie: None,
            content_type: None,
            x_share_token: None,
            x_slskdn_api_key: None,
            x_slskdn_csrf: None,
            x_relay_agent: None,
            x_relay_credential: None,
            remote_addr: None,
            date: None,
            digest: None,
            signature: None,
        };
        assert!(!super::request_origin_matches_host(
            &headers,
            "127.0.0.1:5030"
        ));

        let headers = super::RequestSecurityHeaders {
            host: Some("127.0.0.1:5030".to_owned()),
            origin: Some("http://127.0.0.1:5030".to_owned()),
            referer: None,
            cookie: None,
            content_type: None,
            x_share_token: None,
            x_slskdn_api_key: None,
            x_slskdn_csrf: None,
            x_relay_agent: None,
            x_relay_credential: None,
            remote_addr: None,
            date: None,
            digest: None,
            signature: None,
        };
        assert!(super::request_origin_matches_host(
            &headers,
            "127.0.0.1:5030"
        ));

        let headers = super::RequestSecurityHeaders {
            host: Some("[::1]:5030".to_owned()),
            origin: Some("http://[::1]:5030".to_owned()),
            referer: None,
            cookie: None,
            content_type: None,
            x_share_token: None,
            x_slskdn_api_key: None,
            x_slskdn_csrf: None,
            x_relay_agent: None,
            x_relay_credential: None,
            remote_addr: None,
            date: None,
            digest: None,
            signature: None,
        };
        assert!(super::request_origin_matches_host(&headers, "[::1]:5030"));

        for malformed_origin in [
            "127.0.0.1:5030",
            "null",
            "ftp://127.0.0.1:5030",
            "http://user@127.0.0.1:5030",
            "http://127.0.0.1:5030@evil.example",
            "http://127.0.0.1:5030:80",
        ] {
            let headers = super::RequestSecurityHeaders {
                host: Some("127.0.0.1:5030".to_owned()),
                origin: Some(malformed_origin.to_owned()),
                referer: None,
                cookie: None,
                content_type: None,
                x_share_token: None,
                x_slskdn_api_key: None,
                x_slskdn_csrf: None,
                x_relay_agent: None,
                x_relay_credential: None,
                remote_addr: None,
                date: None,
                digest: None,
                signature: None,
            };
            assert!(!super::request_origin_matches_host(
                &headers,
                "127.0.0.1:5030"
            ));
        }
    }

