            let (symlink_state, _receiver) = test_state_with_env(
                MapEnv::default()
                    .with("SLSKR_CONTROLLER_COMPATIBILITY_TARGET", "slskd")
                    .with("SLSKR_REMOTE_FILE_MANAGEMENT", "true"),
            );
            *symlink_state
                .downloads_dir
                .write()
